import{t as e}from"./framework~index~page~page~page~page~page~layout~page~page~app-page-cache-render~app-page-ca~em9vrqol-aQei1CE8.js";import{t}from"./createLucideIcon-Dpb4c7Rd.js";var n=t(`arrow-right`,[[`path`,{d:`M5 12h14`,key:`1ays0h`}],[`path`,{d:`m12 5 7 7-7 7`,key:`xquz4c`}]]),r=t(`book-open-text`,[[`path`,{d:`M12 5v16`,key:`1f6ucr`}],[`path`,{d:`M16 13h2`,key:`weia3s`}],[`path`,{d:`M16 9h2`,key:`1n7gjm`}],[`path`,{d:`M20.001 19A2 2 0 0022 17V5a2 2 0 00-1.999-2L16 3.002A5 5 0 0012 5a5 5 0 00-4-2H4a2 2 0 00-2 2v12a2 2 0 001.999 2H8a5 5 0 014 2 5 5 0 014-2z`,key:`1fyvmf`}],[`path`,{d:`M6 13h2`,key:`1cckiz`}],[`path`,{d:`M6 9h2`,key:`1k7j9f`}]]),i=e();function a({active:e=`fe`}){return(0,i.jsx)(`header`,{className:`sticky top-0 z-50 border-b border-border/80 bg-background/95 backdrop-blur`,children:(0,i.jsxs)(`div`,{className:`mx-auto flex min-h-16 max-w-6xl items-center justify-between gap-4 px-5 py-2 sm:px-8`,children:[(0,i.jsxs)(`a`,{href:`/fe`,className:`flex min-w-0 items-center gap-3`,children:[(0,i.jsx)(`span`,{className:`grid size-10 shrink-0 place-items-center rounded-lg bg-primary text-primary-foreground`,children:(0,i.jsx)(r,{className:`size-5`,"aria-hidden":`true`})}),(0,i.jsxs)(`span`,{className:`min-w-0 leading-tight`,children:[(0,i.jsx)(`span`,{className:`block truncate font-semibold tracking-tight`,children:`FE Theory`}),(0,i.jsx)(`span`,{className:`mt-0.5 block truncate text-[11px] text-muted-foreground`,children:`基本情報技術者試験`})]})]}),(0,i.jsxs)(`nav`,{className:`flex items-center gap-1`,"aria-label":`Learning sections`,children:[(0,i.jsx)(`a`,{href:`/`,className:`rounded-md px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground`,children:`JLPT`}),(0,i.jsx)(`a`,{href:`/fe`,"aria-current":e===`fe`?`page`:void 0,className:`rounded-md bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground`,children:`基本情報`})]})]})})}var o={exam:`FE`,titleJa:`基本情報技術者試験`,titleVi:`Kỳ thi Kỹ sư Công nghệ Thông tin Cơ bản`,categories:[{id:`basic-theory`,order:1,titleJa:`基礎理論`,titleVi:`Lý thuyết cơ bản`,icon:`binary`,file:`01-basic-theory/index.json`},{id:`algorithms-and-programming`,order:2,titleJa:`アルゴリズムとプログラミング`,titleVi:`Thuật toán và lập trình`,icon:`algorithm`,file:`02-algorithm-program/index.json`}]},s={id:`basic-theory`,order:1,titleJa:`基礎理論`,titleVi:`Lý thuyết cơ bản`,chapters:[{id:`discrete-mathematics`,order:1,titleJa:`離散数学`,titleVi:`Toán rời rạc`,file:`01-discrete-mathematics.json`},{id:`applied-mathematics`,order:2,titleJa:`応用数学`,titleVi:`Toán ứng dụng`,file:`02-applied-mathematics.json`},{id:`information-theory`,order:3,titleJa:`情報に関する理論`,titleVi:`Lý thuyết về thông tin`,file:`03-information-theory.json`},{id:`communication-theory`,order:4,titleJa:`通信に関する理論`,titleVi:`Lý thuyết về truyền thông`,file:`04-communication-theory.json`},{id:`measurement-and-control-theory`,order:5,titleJa:`計測・制御に関する理論`,titleVi:`Lý thuyết về đo lường và điều khiển`,file:`05-measurement-and-control-theory.json`}]},c={id:`discrete-mathematics`,order:1,titleJa:`離散数学`,titleVi:`Toán rời rạc`,syllabus:`9.2`,lessons:[{id:`radix-and-number-systems`,order:1,titleJa:`基数と進数`,titleVi:`Cơ số và hệ đếm`,importance:`high`,summaryJa:`基数は、位取り記数法で使用する数字の種類数を表す。2進数・10進数・16進数の表現と、各桁の重みを理解することがFEの基礎となる。`,summaryVi:`Cơ số cho biết số lượng ký hiệu dùng trong một hệ đếm theo vị trí. Với FE, cần hiểu cách biểu diễn số nhị phân, thập phân, thập lục phân và trọng số của từng chữ số.`,content:[{type:`heading`,ja:`基数とは`,vi:`Cơ số là gì?`},{type:`paragraph`,ja:`基数とは、位取り記数法で一つの桁に使える数字の種類数である。基数がnなら、各桁はnの整数乗の重みをもち、桁の値と重みの積を合計して数値を表す。`,vi:`基数 (cơ số) là số lượng chữ số có thể dùng tại một vị trí trong hệ đếm theo vị trí. Với cơ số n, mỗi vị trí có trọng số là một lũy thừa nguyên của n; giá trị số được tạo bằng cách cộng các tích giữa chữ số và trọng số tương ứng.`},{type:`point`,ja:`2進数は0と1、10進数は0〜9、16進数は0〜9とA〜Fを使う。16進数1桁は2進数4桁に対応するので、2進数との相互変換がしやすい。`,vi:`Hệ nhị phân dùng 0 và 1, hệ thập phân dùng 0–9, hệ thập lục phân dùng 0–9 và A–F. Một chữ số hệ 16 tương ứng đúng 4 bit nhị phân nên việc chuyển đổi giữa hệ 2 và hệ 16 rất thuận tiện.`},{type:`example`,ja:`例：2進数1011は、1×2^3＋0×2^2＋1×2^1＋1×2^0＝11なので、10進数では11である。`,vi:`Ví dụ: 1011 ở hệ 2 có giá trị 1×2^3 + 0×2^2 + 1×2^1 + 1×2^0 = 11, nên bằng 11 ở hệ 10.`},{type:`warning`,ja:`基数変換では、数字の並びだけを見ない。各桁の重みが基数によって変わることを意識する。`,vi:`Khi đổi cơ số, không chỉ nhìn chuỗi chữ số. Hãy luôn nhớ trọng số của từng vị trí thay đổi theo cơ số.`}],terms:[{term:`基数`,reading:`きすう`,english:`Radix (Base)`,vi:`cơ số`,definitionJa:`位取り記数法で、一つの桁に使用できる数字の種類数を表す値。`,definitionVi:`Giá trị biểu thị số lượng chữ số có thể sử dụng tại một vị trí trong hệ đếm theo vị trí.`}],tags:[`discrete-mathematics`,`number-representation`,`radix`]},{id:`twos-complement`,order:2,titleJa:`2の補数と負数の表現`,titleVi:`Số bù 2 và biểu diễn số âm`,importance:`high`,summaryJa:`2の補数は、2進数で負の整数を表す代表的な方法である。正の値のビットを反転し、1を加える操作を理解する。`,summaryVi:`Số bù 2 là cách phổ biến để biểu diễn số nguyên âm bằng nhị phân. Cần nắm chắc thao tác đảo toàn bộ bit rồi cộng 1.`,content:[{type:`heading`,ja:`2の補数とは`,vi:`Số bù 2 là gì?`},{type:`paragraph`,ja:`2の補数は、固定されたビット数の2進数で負の整数を表現する方法である。加算回路を利用して正負の整数を同じ考え方で計算しやすいことが大きな利点である。`,vi:`2の補数 là phương pháp biểu diễn số nguyên âm bằng một số bit nhị phân cố định. Ưu điểm lớn là giúp phần cứng thực hiện phép tính với số dương và số âm thuận tiện bằng cùng cơ chế cộng nhị phân.`},{type:`point`,ja:`正の整数から対応する負の値を求める基本手順は「全ビットを反転する → 1を加える」である。同じビット数のまま操作することが重要である。`,vi:`Quy tắc cơ bản để lấy biểu diễn của số âm từ số dương là: đảo tất cả bit → cộng 1. Phải giữ nguyên số lượng bit trong suốt quá trình.`},{type:`example`,ja:`例：8ビットで+5は00000101。全ビットを反転すると11111010、さらに1を加えると11111011となる。したがって11111011が8ビットの2の補数表現における-5である。`,vi:`Ví dụ: với 8 bit, +5 là 00000101. Đảo tất cả bit được 11111010, cộng thêm 1 được 11111011. Vì vậy 11111011 là biểu diễn -5 theo số bù 2 trong 8 bit.`},{type:`point`,ja:`nビットの2の補数表現で表せる整数の範囲は、-2^(n-1)から2^(n-1)-1までである。8ビットなら-128〜127となる。`,vi:`Với biểu diễn bù 2 n bit, phạm vi số nguyên là từ -2^(n-1) đến 2^(n-1)-1. Với 8 bit, phạm vi là -128 đến 127.`},{type:`warning`,ja:`単に最上位ビットを1にするだけでは負数の2の補数表現にはならない。また、ビット反転だけで終わらず、必ず1を加える。`,vi:`Chỉ đổi bit cao nhất thành 1 không tạo ra biểu diễn bù 2 đúng. Sau khi đảo bit, bắt buộc phải cộng thêm 1.`}],terms:[{term:`2の補数`,reading:`にのほすう`,english:`Two's Complement`,vi:`số bù 2`,definitionJa:`固定ビット長の2進数で負の整数を表すために用いる補数表現。ある値の符号を反転した値は、全ビットを反転して1を加えることで求められる。`,definitionVi:`Cách biểu diễn bù dùng để biểu diễn số nguyên âm với độ dài bit cố định. Giá trị đổi dấu được tạo bằng cách đảo toàn bộ bit rồi cộng 1.`}],tags:[`discrete-mathematics`,`number-representation`,`binary`,`signed-integer`]},{id:`fixed-point-number`,order:3,titleJa:`固定小数点数`,titleVi:`Số dấu phẩy cố định`,importance:`medium`,summaryJa:`固定小数点数は、小数点の位置をあらかじめ固定して数値を表す方式である。ビット配分によって表現範囲と刻み幅が決まる。`,summaryVi:`Số dấu phẩy cố định là cách biểu diễn trong đó vị trí dấu chấm được xác định trước. Cách phân bổ bit quyết định phạm vi biểu diễn và độ nhỏ của bước giá trị.`,content:[{type:`heading`,ja:`固定小数点数の考え方`,vi:`Cách hiểu số dấu phẩy cố định`},{type:`paragraph`,ja:`固定小数点数は、ビット列のどこに小数点があるかをあらかじめ決めておき、その位置を変えずに数値を解釈する方式である。整数部と小数部に割り当てるビット数を固定するため、扱える範囲と精度も決まる。`,vi:`固定小数点数 là cách biểu diễn quy định trước dấu chấm nhị phân nằm ở đâu trong chuỗi bit và luôn diễn giải số theo vị trí đó. Vì số bit dành cho phần nguyên và phần lẻ được cố định, phạm vi và độ chính xác cũng được xác định trước.`},{type:`point`,ja:`小数部のビットが多いほど細かな値を表せるが、その分、同じ総ビット数では整数部に使えるビットが減り、表現できる大きな値の範囲は狭くなる。`,vi:`Càng dành nhiều bit cho phần lẻ thì biểu diễn được giá trị càng mịn, nhưng với cùng tổng số bit, số bit dành cho phần nguyên giảm nên phạm vi giá trị lớn có thể biểu diễn sẽ hẹp hơn.`},{type:`example`,ja:`例：8ビットを整数部4ビット・小数部4ビットとして扱うとする。0011.1000は、3＋1/2＝3.5を表す。`,vi:`Ví dụ: giả sử 8 bit được chia thành 4 bit phần nguyên và 4 bit phần lẻ. Khi đó 0011.1000 biểu diễn 3 + 1/2 = 3,5.`},{type:`point`,ja:`FEでは、固定された小数点位置から各ビットの重みを読み取り、表現できる範囲や最小の刻みを求める考え方を押さえる。`,vi:`Trong FE, cần biết đọc trọng số của từng bit từ vị trí dấu chấm cố định, từ đó xác định phạm vi biểu diễn và bước giá trị nhỏ nhất.`},{type:`warning`,ja:`固定小数点数と浮動小数点数を混同しない。固定小数点数では小数点位置が固定されるが、浮動小数点数では指数を使って小数点位置を実質的に移動させる。`,vi:`Không nhầm số dấu phẩy cố định với số dấu phẩy động. Ở fixed-point, vị trí dấu chấm được cố định; ở floating-point, phần số mũ làm cho vị trí dấu chấm thay đổi về mặt giá trị.`}],terms:[{term:`固定小数点数`,reading:`こていしょうすうてんすう`,english:`Fixed-point Number`,vi:`số dấu phẩy cố định`,definitionJa:`小数点の位置をあらかじめ固定して数値を表現する方式。`,definitionVi:`Phương pháp biểu diễn số với vị trí dấu chấm được quy định cố định từ trước.`}],tags:[`discrete-mathematics`,`number-representation`,`fixed-point`]},{id:`floating-point-number`,order:4,titleJa:`浮動小数点数`,titleVi:`Số dấu phẩy động`,importance:`high`,summaryJa:`浮動小数点数は、数値を仮数と指数に分けて表し、広い範囲の実数を限られたビット数で扱う方式である。単精度・倍精度、仮数部・指数部の役割を理解する。`,summaryVi:`Số dấu phẩy động biểu diễn một giá trị bằng phần định trị và số mũ, nhờ đó xử lý được phạm vi số thực rộng với số bit hữu hạn. Cần hiểu vai trò của độ chính xác đơn/kép, phần định trị và phần số mũ.`,content:[{type:`heading`,ja:`浮動小数点数の仕組み`,vi:`Cơ chế của số dấu phẩy động`},{type:`paragraph`,ja:`浮動小数点数は、数値をおおむね「符号・指数・仮数」に分けて表現する。指数を変えることで非常に大きい値から非常に小さい値まで扱いやすくする。`,vi:`Số dấu phẩy động thường chia giá trị thành ba phần: dấu, số mũ và phần định trị. Việc thay đổi số mũ giúp biểu diễn thuận tiện từ các số rất lớn đến các số rất nhỏ.`},{type:`point`,ja:`仮数部は有効数字を保持し、値の細かさや精度に強く関係する。指数部は基数の何乗を掛けるかを表し、主に表現できる数値の大きさの範囲に関係する。`,vi:`仮数部 giữ các chữ số có nghĩa và ảnh hưởng mạnh đến độ chính xác. 指数部 biểu thị lũy thừa của cơ số cần nhân vào, chủ yếu quyết định phạm vi độ lớn của số có thể biểu diễn.`},{type:`point`,ja:`一般的な浮動小数点表現では、単精度は32ビット、倍精度は64ビットで扱われる。倍精度はより多くのビットを使うため、通常は単精度より高い精度と広い表現能力をもつ。`,vi:`Trong cách biểu diễn floating-point phổ biến, độ chính xác đơn dùng 32 bit và độ chính xác kép dùng 64 bit. Do dùng nhiều bit hơn, double precision thường có độ chính xác cao hơn và khả năng biểu diễn rộng hơn single precision.`},{type:`example`,ja:`考え方の例：2進数の1.101×2^3では、1.101が有効数字を表す部分、3が指数に当たる。指数を変えると数値全体の大きさが変化する。`,vi:`Ví dụ về cách hiểu: trong 1.101 × 2^3 ở hệ nhị phân, 1.101 là phần thể hiện các chữ số có nghĩa, còn 3 là số mũ. Thay đổi số mũ sẽ làm thay đổi độ lớn của toàn bộ giá trị.`},{type:`warning`,ja:`浮動小数点数は実数を無限の精度で表せるわけではない。仮数部の桁数が有限なので、表現できない下位桁は丸められ、計算誤差の原因になる。`,vi:`Floating-point không thể biểu diễn số thực với độ chính xác vô hạn. Vì số chữ số của phần định trị là hữu hạn, các chữ số thấp không thể chứa hết sẽ bị làm tròn và có thể gây sai số.`}],terms:[{term:`単精度浮動小数点数`,reading:`たんせいどうきしょうすうてんすう`,english:`Single-precision Floating-point Number`,vi:`số dấu phẩy động độ chính xác đơn`,definitionJa:`一般に32ビットで表現される浮動小数点数。倍精度より使用ビット数が少なく、必要な記憶容量も小さい。`,definitionVi:`Số dấu phẩy động thường được biểu diễn bằng 32 bit. Nó dùng ít bit và ít bộ nhớ hơn so với độ chính xác kép.`},{term:`倍精度浮動小数点数`,reading:`ばいせいどうきしょうすうてんすう`,english:`Double-precision Floating-point Number`,vi:`số dấu phẩy động độ chính xác kép`,definitionJa:`一般に64ビットで表現される浮動小数点数。単精度より多くの有効桁を保持でき、通常は高い精度で計算できる。`,definitionVi:`Số dấu phẩy động thường được biểu diễn bằng 64 bit. Nó giữ được nhiều chữ số có nghĩa hơn single precision và thường cho độ chính xác tính toán cao hơn.`},{term:`仮数部`,reading:`かすうぶ`,english:`Significand (Mantissa)`,vi:`phần định trị`,definitionJa:`浮動小数点表現で有効数字を保持する部分。保持できる桁数が計算精度に大きく影響する。`,definitionVi:`Phần giữ các chữ số có nghĩa trong biểu diễn dấu phẩy động. Số lượng chữ số có thể giữ ảnh hưởng lớn đến độ chính xác tính toán.`},{term:`指数部`,reading:`しすうぶ`,english:`Exponent`,vi:`phần số mũ`,definitionJa:`浮動小数点表現で、基数を何乗するかを示す部分。主に表現できる数値の大きさの範囲を決める。`,definitionVi:`Phần biểu thị cơ số được nâng lên lũy thừa bao nhiêu trong biểu diễn dấu phẩy động. Nó chủ yếu quyết định phạm vi độ lớn của giá trị có thể biểu diễn.`}],tags:[`discrete-mathematics`,`number-representation`,`floating-point`]},{id:`decimal-encoding`,order:5,titleJa:`10進数の内部表現`,titleVi:`Biểu diễn số thập phân trong máy tính`,importance:`medium`,summaryJa:`BCDは10進数の各桁を4ビットずつ2進数で符号化する。パック10進数は10進数字を4ビット単位で詰めて格納し、10進数を効率よく扱う。`,summaryVi:`BCD mã hóa từng chữ số thập phân bằng 4 bit. Packed decimal đóng gói các chữ số thập phân theo từng nhóm 4 bit để lưu và xử lý dữ liệu thập phân hiệu quả.`,content:[{type:`heading`,ja:`BCD`,vi:`BCD`},{type:`paragraph`,ja:`BCDでは、10進数の各桁を独立に4ビットの2進数へ変換する。数値全体を通常の2進数へ変換する方式とは異なる。`,vi:`Trong BCD, từng chữ số thập phân được chuyển độc lập thành 4 bit nhị phân. Cách này khác với việc chuyển toàn bộ giá trị thập phân thành một số nhị phân thông thường.`},{type:`example`,ja:`例：10進数59は、5を0101、9を1001として表すので、BCDでは0101 1001となる。59そのものを通常の2進数に変換した値とは区別する。`,vi:`Ví dụ: số thập phân 59 được mã hóa bằng 5 → 0101 và 9 → 1001, nên BCD là 0101 1001. Không được nhầm với kết quả chuyển toàn bộ số 59 sang nhị phân thông thường.`},{type:`heading`,ja:`パック10進数`,vi:`Packed decimal`},{type:`paragraph`,ja:`パック10進数では、10進数字1桁を4ビットで表し、1バイトに原則として2桁を詰めて格納する。符号付きの場合は、末尾の4ビットを符号情報に使用する方式が一般的である。`,vi:`Trong packed decimal, mỗi chữ số thập phân chiếm 4 bit, vì vậy về nguyên tắc một byte chứa được hai chữ số. Với số có dấu, cách phổ biến là dùng 4 bit cuối để lưu thông tin dấu.`},{type:`point`,ja:`FEでは、BCDが「各10進桁を個別に4ビット化する」ことと、パック10進数が「4ビット単位で数字を詰める」ことを区別して覚える。`,vi:`Trong FE, cần phân biệt: BCD mã hóa từng chữ số thập phân riêng bằng 4 bit, còn packed decimal sắp các chữ số đó sát nhau theo đơn vị 4 bit để lưu trữ.`},{type:`warning`,ja:`BCDの0101 1001を、通常の2進整数1011001と同じ意味だと考えない。BCDでは4ビットごとに1桁の10進数字として読む。`,vi:`Không đọc BCD 0101 1001 như một số nguyên nhị phân thông thường. Với BCD, phải tách mỗi 4 bit và đọc chúng như từng chữ số thập phân.`}],terms:[{term:`BCD`,reading:`ビーシーディー`,english:`Binary Coded Decimal`,vi:`mã thập phân mã hóa bằng nhị phân`,definitionJa:`10進数の各桁を、それぞれ4ビットの2進数で符号化する表現方式。`,definitionVi:`Phương pháp biểu diễn trong đó từng chữ số thập phân được mã hóa riêng bằng 4 bit nhị phân.`},{term:`パック10進数`,reading:`パックじっしんすう`,english:`Packed Decimal`,vi:`số thập phân đóng gói`,definitionJa:`10進数字を4ビット単位で連続して格納し、1バイトに原則2桁を収める10進数表現。`,definitionVi:`Cách biểu diễn số thập phân bằng cách lưu liên tiếp từng chữ số theo đơn vị 4 bit, về nguyên tắc cho phép chứa hai chữ số trong một byte.`}],tags:[`discrete-mathematics`,`number-representation`,`decimal-encoding`]},{id:`shift-operation`,order:6,titleJa:`シフト演算`,titleVi:`Phép dịch bit`,importance:`high`,summaryJa:`シフト演算はビット列を左右へ移動させる演算である。論理シフトと算術シフトでは、空いたビットや符号の扱いが異なる。`,summaryVi:`Phép dịch bit di chuyển chuỗi bit sang trái hoặc phải. Logical shift và arithmetic shift khác nhau ở cách xử lý các bit trống và dấu của số.`,content:[{type:`heading`,ja:`論理シフト`,vi:`Logical shift`},{type:`paragraph`,ja:`論理シフトは、ビット列を左または右へ移動し、空いた位置を0で埋める。符号付き整数の符号を維持することは目的としない。`,vi:`論理シフト dịch chuỗi bit sang trái hoặc phải và điền 0 vào các vị trí trống. Mục đích của nó không phải là bảo toàn dấu của số nguyên có dấu.`},{type:`example`,ja:`例：8ビットの00101100を論理右シフトすると、1ビットなら00010110となる。右端からはみ出したビットは失われ、左端には0が入る。`,vi:`Ví dụ: dịch logic sang phải 1 bit cho 00101100 (8 bit) được 00010110. Bit tràn ra bên phải bị mất và bên trái được điền 0.`},{type:`heading`,ja:`算術シフト`,vi:`Arithmetic shift`},{type:`paragraph`,ja:`算術シフトは符号付き整数を意識したシフトである。特に算術右シフトでは、通常、最上位の符号を保つように空いた上位ビットを元の符号ビットで埋める。`,vi:`算術シフト là phép dịch có xét đến số nguyên có dấu. Đặc biệt khi dịch số học sang phải, các bit trống phía trên thường được điền bằng bit dấu ban đầu để giữ dấu của số.`},{type:`point`,ja:`オーバーフローなどが起きない範囲では、左にnビット移動する操作は2^n倍に対応する。符号付き整数の算術右シフトは2^nで割る操作に対応する考え方で使われる。`,vi:`Nếu không xảy ra tràn, dịch trái n bit tương ứng với nhân 2^n. Với số nguyên có dấu, dịch số học sang phải được dùng theo ý tưởng tương ứng với chia cho 2^n.`},{type:`warning`,ja:`論理右シフトと算術右シフトの違いは重要である。論理右シフトは左側を0で埋めるが、算術右シフトは符号を維持するため符号ビットを用いて埋める。`,vi:`Sự khác nhau giữa dịch logic phải và dịch số học phải rất quan trọng: logical right shift điền 0 bên trái, còn arithmetic right shift dùng bit dấu để giữ dấu của số.`}],terms:[{term:`論理シフト`,reading:`ろんりシフト`,english:`Logical Shift`,vi:`dịch logic`,definitionJa:`ビット列を左右に移動し、空いたビット位置を0で埋めるシフト演算。`,definitionVi:`Phép dịch chuỗi bit sang trái hoặc phải và điền 0 vào các vị trí bit bị trống.`},{term:`算術シフト`,reading:`さんじゅつシフト`,english:`Arithmetic Shift`,vi:`dịch số học`,definitionJa:`符号付き整数の符号を考慮して行うシフト演算。算術右シフトでは通常、符号を維持するように上位ビットを補う。`,definitionVi:`Phép dịch bit có xét đến dấu của số nguyên có dấu. Khi dịch số học sang phải, các bit phía trên thường được điền để duy trì dấu.`}],tags:[`discrete-mathematics`,`bit-operation`,`shift`]},{id:`calculation-error`,order:7,titleJa:`計算誤差`,titleVi:`Sai số tính toán`,importance:`high`,summaryJa:`有限桁の浮動小数点演算では、桁落ちや情報落ちが発生する。発生条件の違いを理解し、どちらの現象かを判別できることが重要である。`,summaryVi:`Trong phép tính floating-point với số chữ số hữu hạn có thể xảy ra 桁落ち và 情報落ち. Điều quan trọng là hiểu điều kiện phát sinh để phân biệt chính xác hai hiện tượng.`,content:[{type:`heading`,ja:`桁落ち`,vi:`桁落ち – mất chữ số có nghĩa do triệt tiêu`},{type:`paragraph`,ja:`桁落ちは、絶対値がほぼ等しい数どうしを減算したときなどに、上位の有効数字が打ち消し合い、結果として有効桁数が大きく減る現象である。`,vi:`桁落ち xảy ra chẳng hạn khi trừ hai số có trị tuyệt đối gần bằng nhau: các chữ số có nghĩa ở phần cao bị triệt tiêu, làm số chữ số có nghĩa còn lại giảm mạnh.`},{type:`example`,ja:`考え方の例：1.234567と1.234566の差を求めると、多くの上位桁が打ち消し合う。元の値に丸め誤差が含まれている場合、その誤差の影響が結果に対して相対的に大きくなる。`,vi:`Ví dụ về cách hiểu: khi tính hiệu giữa 1,234567 và 1,234566, nhiều chữ số phía trước bị triệt tiêu. Nếu hai giá trị ban đầu đã chứa sai số làm tròn, ảnh hưởng tương đối của sai số đó lên kết quả sẽ trở nên lớn.`},{type:`heading`,ja:`情報落ち`,vi:`情報落ち – mất phần thông tin nhỏ`},{type:`paragraph`,ja:`情報落ちは、絶対値が大きく異なる浮動小数点数を加減算するとき、小さい方の数の有効桁の一部または全部が仮数部で保持できる桁の範囲から押し出され、結果に反映されなくなる現象である。`,vi:`情報落ち xảy ra khi cộng hoặc trừ các số floating-point có trị tuyệt đối chênh lệch rất lớn: một phần hoặc toàn bộ chữ số có nghĩa của số nhỏ bị đẩy ra ngoài phạm vi chữ số mà phần định trị có thể giữ và không còn ảnh hưởng đến kết quả.`},{type:`example`,ja:`例：保持できる有効桁数が限られている環境では、非常に大きい数に極端に小さい数を加えても、加えた小さい値が結果に現れないことがある。`,vi:`Ví dụ: trong môi trường chỉ giữ được số chữ số có nghĩa hữu hạn, khi cộng một số cực nhỏ vào một số rất lớn, giá trị nhỏ đó có thể không xuất hiện trong kết quả.`},{type:`point`,ja:`多数の浮動小数点数を合計するとき、情報落ちを抑える基本的な考え方の一つは、絶対値の小さい値から先に加算することである。`,vi:`Khi cộng nhiều số floating-point, một cách cơ bản để giảm 情報落ち là cộng các giá trị có trị tuyệt đối nhỏ trước.`},{type:`warning`,ja:`FEでは原因を区別する。桁落ちは「近い値の差で有効桁が失われる」、情報落ちは「大きさが大きく異なる値の加減算で小さい方の情報が失われる」と整理する。`,vi:`Trong FE cần phân biệt nguyên nhân: 桁落ち là mất chữ số có nghĩa khi lấy hiệu các giá trị gần nhau; 情報落ち là mất thông tin của số nhỏ khi cộng/trừ các giá trị có độ lớn chênh lệch nhiều.`}],terms:[{term:`桁落ち`,reading:`けたおち`,english:`Cancellation`,vi:`mất chữ số có nghĩa do triệt tiêu`,definitionJa:`絶対値がほぼ等しい数の減算などで上位の有効数字が打ち消され、結果の有効桁数が大きく減少する現象。`,definitionVi:`Hiện tượng các chữ số có nghĩa ở phần cao bị triệt tiêu khi trừ các số có trị tuyệt đối gần bằng nhau, khiến số chữ số có nghĩa của kết quả giảm mạnh.`},{term:`情報落ち`,reading:`じょうほうおち`,english:`Absorption (Loss of Trailing Digits)`,vi:`mất thông tin của số nhỏ`,definitionJa:`絶対値が大きく異なる浮動小数点数の加減算で、小さい方の有効桁の一部または全部が失われる現象。`,definitionVi:`Hiện tượng một phần hoặc toàn bộ chữ số có nghĩa của số nhỏ bị mất khi cộng hoặc trừ các số floating-point có trị tuyệt đối chênh lệch rất lớn.`}],tags:[`discrete-mathematics`,`floating-point`,`numerical-error`]}]},l={id:`applied-mathematics`,order:2,titleJa:`応用数学`,titleVi:`Toán ứng dụng`,syllabus:`9.2`,lessons:[{id:`probability-basics`,order:1,titleJa:`確率の基本`,titleVi:`Cơ bản về xác suất`,importance:`high`,summaryJa:`階乗、確率の加法・乗法、同時確率、条件付き確率、ベイズの定理をまとめて学ぶ。確率問題では、事象の関係を見極めて適切な式を選ぶことが重要である。`,summaryVi:`Học chung về giai thừa, quy tắc cộng và nhân xác suất, xác suất đồng thời, xác suất có điều kiện và định lý Bayes. Khi giải bài FE, điều quan trọng là xác định đúng quan hệ giữa các biến cố trước khi chọn công thức.`,content:[{type:`heading`,ja:`確率計算の基本`,vi:`Nền tảng tính xác suất`},{type:`paragraph`,ja:`確率では、まず全事象と求めたい事象を整理する。互いに排反な事象の「AまたはB」は確率を加え、独立な事象の「AかつB」は確率を掛けるのが基本である。一般の場合は条件付き確率を用いて関係を表す。`,vi:`Trong xác suất, trước hết cần xác định không gian mẫu và biến cố cần tìm. Với các biến cố loại trừ nhau, xác suất “A hoặc B” được cộng; với các biến cố độc lập, xác suất “A và B” được nhân. Trường hợp tổng quát dùng xác suất có điều kiện để biểu diễn mối quan hệ.`},{type:`point`,ja:`加法定理の一般形は P(A∪B)=P(A)+P(B)-P(A∩B)。AとBが排反なら P(A∩B)=0 なので単純な加算になる。`,vi:`Công thức cộng tổng quát là P(A∪B)=P(A)+P(B)-P(A∩B). Nếu A và B loại trừ nhau thì P(A∩B)=0, nên chỉ cần cộng hai xác suất.`},{type:`point`,ja:`乗法定理は P(A∩B)=P(A)P(B|A)。AとBが独立なら P(B|A)=P(B) なので P(A∩B)=P(A)P(B) となる。`,vi:`Quy tắc nhân là P(A∩B)=P(A)P(B|A). Nếu A và B độc lập thì P(B|A)=P(B), nên P(A∩B)=P(A)P(B).`},{type:`example`,ja:`公平なサイコロを2回振り、両方とも6が出る確率は (1/6)×(1/6)=1/36 である。`,vi:`Tung một xúc xắc công bằng hai lần, xác suất cả hai lần đều ra 6 là (1/6)×(1/6)=1/36.`},{type:`point`,ja:`ベイズの定理は P(A|B)=P(B|A)P(A)/P(B)。原因Aを、観測結果Bから逆向きに推定するときに使う。`,vi:`Định lý Bayes: P(A|B)=P(B|A)P(A)/P(B). Nó được dùng để suy ngược xác suất của nguyên nhân A từ kết quả quan sát B.`},{type:`warning`,ja:`「排反」と「独立」は別の概念である。排反は同時に起こらないこと、独立は一方の発生が他方の確率に影響しないことを意味する。`,vi:`Không nhầm “loại trừ nhau” với “độc lập”. Loại trừ nhau nghĩa là không thể xảy ra đồng thời; độc lập nghĩa là việc một biến cố xảy ra không làm thay đổi xác suất của biến cố kia.`}],terms:[{term:`階乗`,reading:`かいじょう`,english:`Factorial`,vi:`giai thừa`,definitionJa:`自然数nについて、1からnまでの整数をすべて掛けた値。n! と表す。`,definitionVi:`Với số tự nhiên n, là tích của tất cả các số nguyên từ 1 đến n, ký hiệu n!.`},{term:`加法定理`,reading:`かほうていり`,english:`Addition Rule of Probability`,vi:`quy tắc cộng xác suất`,definitionJa:`複数の事象の和事象の確率を求める法則。重なりがある場合は共通部分を差し引く。`,definitionVi:`Quy tắc tính xác suất của hợp các biến cố; nếu các biến cố có phần giao nhau thì phải trừ phần giao.`},{term:`乗法定理`,reading:`じょうほうていり`,english:`Multiplication Rule of Probability`,vi:`quy tắc nhân xác suất`,definitionJa:`複数の事象が同時に起こる確率を、条件付き確率を用いて求める法則。`,definitionVi:`Quy tắc tính xác suất nhiều biến cố xảy ra đồng thời bằng xác suất có điều kiện.`},{term:`同時確率`,reading:`どうじかくりつ`,english:`Joint Probability`,vi:`xác suất đồng thời`,definitionJa:`二つ以上の事象が同時に起こる確率。`,definitionVi:`Xác suất hai hoặc nhiều biến cố xảy ra đồng thời.`},{term:`条件付き確率`,reading:`じょうけんつきかくりつ`,english:`Conditional Probability`,vi:`xác suất có điều kiện`,definitionJa:`事象Aが起きたという条件の下で事象Bが起こる確率。P(B|A) と表す。`,definitionVi:`Xác suất biến cố B xảy ra với điều kiện biến cố A đã xảy ra, ký hiệu P(B|A).`},{term:`ベイズの定理`,reading:`ベイズのていり`,english:`Bayes' Theorem`,vi:`định lý Bayes`,definitionJa:`条件付き確率の関係から、観測された結果を基に原因側の確率を更新する定理。`,definitionVi:`Định lý dùng quan hệ xác suất có điều kiện để cập nhật xác suất của nguyên nhân dựa trên kết quả quan sát.`}],tags:[`applied-mathematics`,`probability`]},{id:`probability-distributions`,order:2,titleJa:`確率分布`,titleVi:`Phân phối xác suất`,importance:`high`,summaryJa:`代表的な確率分布の特徴と、どのような現象をモデル化するかを理解する。`,summaryVi:`Hiểu đặc điểm của các phân phối xác suất tiêu biểu và loại hiện tượng mà mỗi phân phối dùng để mô hình hóa.`,content:[{type:`paragraph`,ja:`確率分布は、確率変数がどの値をどの程度の確率で取るかを表す。FEでは、分布名と典型的な利用場面を対応付けて覚えることが重要である。`,vi:`Phân phối xác suất biểu diễn một biến ngẫu nhiên nhận các giá trị với xác suất như thế nào. Trong FE, cần liên kết tên phân phối với tình huống điển hình mà nó mô hình hóa.`},{type:`point`,ja:`ベルヌーイ分布は1回の成功・失敗、二項分布は独立なベルヌーイ試行をn回行ったときの成功回数を表す。`,vi:`Phân phối Bernoulli mô tả một phép thử thành công/thất bại; phân phối nhị thức mô tả số lần thành công trong n phép thử Bernoulli độc lập.`},{type:`point`,ja:`ポアソン分布は一定時間・領域内の発生回数、指数分布は次の発生までの待ち時間をモデル化する代表的な分布である。`,vi:`Phân phối Poisson thường mô hình hóa số lần xảy ra trong một khoảng thời gian/khu vực; phân phối mũ thường mô hình hóa thời gian chờ đến lần xảy ra tiếp theo.`},{type:`point`,ja:`正規分布は平均を中心とする左右対称の釣鐘形分布。対数正規分布は、値の対数を取ると正規分布になる正の値の分布である。`,vi:`Phân phối chuẩn có dạng chuông đối xứng quanh trung bình. Phân phối log-chuẩn là phân phối của đại lượng dương mà log của nó tuân theo phân phối chuẩn.`},{type:`example`,ja:`平均して1時間に4件の障害が独立に発生すると仮定すると、1時間の発生件数はポアソン分布でモデル化できる。`,vi:`Nếu giả sử trung bình có 4 sự cố mỗi giờ và các sự cố xảy ra độc lập, số sự cố trong một giờ có thể được mô hình hóa bằng phân phối Poisson.`},{type:`warning`,ja:`ポアソン分布の「回数」と指数分布の「待ち時間」を取り違えない。`,vi:`Không nhầm Poisson (số lần xảy ra) với phân phối mũ (thời gian chờ).`}],terms:[{term:`ポアソン分布`,reading:`ポアソンぶんぷ`,english:`Poisson Distribution`,vi:`phân phối Poisson`,definitionJa:`一定期間や領域内で、独立に発生する事象の回数を表す離散確率分布。`,definitionVi:`Phân phối rời rạc biểu diễn số lần một biến cố độc lập xảy ra trong một khoảng thời gian hoặc khu vực.`},{term:`ベルヌーイ分布`,reading:`ベルヌーイぶんぷ`,english:`Bernoulli Distribution`,vi:`phân phối Bernoulli`,definitionJa:`成功・失敗のように二つの結果だけを取る1回の試行を表す確率分布。`,definitionVi:`Phân phối xác suất cho một phép thử chỉ có hai kết quả, chẳng hạn thành công hoặc thất bại.`},{term:`二項分布`,reading:`にこうぶんぷ`,english:`Binomial Distribution`,vi:`phân phối nhị thức`,definitionJa:`成功確率が一定の独立な試行をn回行ったときの成功回数を表す分布。`,definitionVi:`Phân phối biểu diễn số lần thành công trong n phép thử độc lập có xác suất thành công không đổi.`},{term:`正規分布`,reading:`せいきぶんぷ`,english:`Normal Distribution`,vi:`phân phối chuẩn`,definitionJa:`平均を中心に左右対称な釣鐘形をもつ連続確率分布。`,definitionVi:`Phân phối xác suất liên tục dạng chuông, đối xứng quanh giá trị trung bình.`},{term:`指数分布`,reading:`しすうぶんぷ`,english:`Exponential Distribution`,vi:`phân phối mũ`,definitionJa:`一定の発生率をもつ事象について、次の発生までの時間を表す連続確率分布。`,definitionVi:`Phân phối liên tục mô tả thời gian chờ đến lần xảy ra tiếp theo của một biến cố có tốc độ xảy ra không đổi.`},{term:`対数正規分布`,reading:`たいすうせいきぶんぷ`,english:`Log-normal Distribution`,vi:`phân phối log-chuẩn`,definitionJa:`確率変数の対数が正規分布に従う、0より大きい値を取る連続確率分布。`,definitionVi:`Phân phối liên tục nhận giá trị dương, trong đó log của biến ngẫu nhiên tuân theo phân phối chuẩn.`}],tags:[`applied-mathematics`,`probability`,`distribution`]},{id:`descriptive-statistics`,order:3,titleJa:`記述統計`,titleVi:`Thống kê mô tả`,importance:`high`,summaryJa:`代表値と散らばり、分布形状を示す基本的な統計量を理解する。`,summaryVi:`Hiểu các đại lượng thống kê cơ bản mô tả xu hướng trung tâm, độ phân tán và hình dạng phân phối.`,content:[{type:`heading`,ja:`代表値とばらつき`,vi:`Giá trị đại diện và độ phân tán`},{type:`paragraph`,ja:`平均値・中央値・最頻値はデータの中心を表す代表値である。分散と標準偏差は、データが平均からどの程度散らばっているかを表す。`,vi:`Trung bình, trung vị và mốt là các giá trị đại diện cho trung tâm dữ liệu. Phương sai và độ lệch chuẩn biểu diễn mức độ dữ liệu phân tán quanh trung bình.`},{type:`example`,ja:`データ {1,2,2,3,12} では平均値は4、中央値は2、最頻値は2である。極端な値12の影響で平均値は大きくなる。`,vi:`Với dữ liệu {1,2,2,3,12}, trung bình là 4, trung vị là 2 và mốt là 2. Giá trị cực đoan 12 làm trung bình tăng đáng kể.`},{type:`point`,ja:`分散は平均との差を二乗して平均した量、標準偏差は分散の平方根である。標準偏差は元データと同じ単位で解釈できる。`,vi:`Phương sai là trung bình của bình phương độ lệch so với trung bình; độ lệch chuẩn là căn bậc hai của phương sai. Độ lệch chuẩn có cùng đơn vị với dữ liệu gốc.`},{type:`point`,ja:`歪度は分布の左右非対称性、尖度は分布の裾の重さや極端値の出やすさに関係する形状指標である。`,vi:`Skewness biểu diễn mức bất đối xứng của phân phối; kurtosis liên quan đến độ nặng của đuôi và xu hướng xuất hiện giá trị cực đoan.`},{type:`warning`,ja:`相関係数と違い、標準偏差・分散は一つの変数の散らばりを表す。`,vi:`Khác với hệ số tương quan, độ lệch chuẩn và phương sai mô tả độ phân tán của một biến.`}],terms:[{term:`中央値`,reading:`ちゅうおうち`,english:`Median`,vi:`trung vị`,definitionJa:`データを順に並べたとき中央に位置する値。個数が偶数なら中央2値の平均を用いる。`,definitionVi:`Giá trị nằm ở giữa khi sắp dữ liệu theo thứ tự; nếu số phần tử chẵn thì lấy trung bình của hai giá trị giữa.`},{term:`最頻値`,reading:`さいひんち`,english:`Mode`,vi:`mốt`,definitionJa:`データ中で最も多く出現する値。`,definitionVi:`Giá trị xuất hiện với tần suất cao nhất trong dữ liệu.`},{term:`平均値`,reading:`へいきんち`,english:`Mean`,vi:`giá trị trung bình`,definitionJa:`数値の合計を個数で割って得る代表値。`,definitionVi:`Giá trị đại diện bằng tổng các số chia cho số lượng phần tử.`},{term:`標準偏差`,reading:`ひょうじゅんへんさ`,english:`Standard Deviation`,vi:`độ lệch chuẩn`,definitionJa:`分散の平方根で、データの散らばりの大きさを元データと同じ単位で示す。`,definitionVi:`Căn bậc hai của phương sai, biểu diễn độ phân tán bằng cùng đơn vị với dữ liệu gốc.`},{term:`分散`,reading:`ぶんさん`,english:`Variance`,vi:`phương sai`,definitionJa:`各データと平均値との差を二乗し、その平均を取った散らばりの指標。`,definitionVi:`Chỉ số độ phân tán được tính từ trung bình của bình phương độ lệch giữa từng giá trị và giá trị trung bình.`},{term:`歪度`,reading:`わいど`,english:`Skewness`,vi:`độ lệch/skewness`,definitionJa:`確率分布やデータ分布の左右の非対称性を表す指標。`,definitionVi:`Chỉ số biểu diễn mức độ bất đối xứng trái-phải của phân phối.`},{term:`尖度`,reading:`せんど`,english:`Kurtosis`,vi:`độ nhọn/kurtosis`,definitionJa:`分布の裾の重さや極端値の出やすさに関係する分布形状の指標。`,definitionVi:`Chỉ số hình dạng phân phối liên quan đến độ nặng của đuôi và khả năng xuất hiện giá trị cực đoan.`}],tags:[`applied-mathematics`,`statistics`,`descriptive-statistics`]},{id:`correlation-and-regression`,order:4,titleJa:`相関・回帰と多変量解析`,titleVi:`Tương quan, hồi quy và phân tích đa biến`,importance:`medium`,summaryJa:`変数間の関係を調べる相関・回帰と、複数変数を扱う代表的な分析手法を理解する。`,summaryVi:`Hiểu tương quan, hồi quy để khảo sát mối quan hệ giữa các biến và các phương pháp phân tích đa biến tiêu biểu.`,content:[{type:`paragraph`,ja:`相関は二つの変数が一緒に変化する傾向を示し、回帰は説明変数から目的変数を説明・予測するモデルを作る。`,vi:`Tương quan cho biết xu hướng hai biến thay đổi cùng nhau; hồi quy xây dựng mô hình dùng biến giải thích để mô tả hoặc dự đoán biến mục tiêu.`},{type:`point`,ja:`相関係数は通常 -1〜1 の範囲を取り、符号が関係の方向、絶対値が線形関係の強さを示す。`,vi:`Hệ số tương quan thường nằm trong khoảng -1 đến 1; dấu biểu thị chiều quan hệ, còn trị tuyệt đối biểu thị độ mạnh của quan hệ tuyến tính.`},{type:`warning`,ja:`相関が強くても因果関係があるとは限らない。第三の変数によって見かけ上の関係が生じる擬似相関に注意する。`,vi:`Tương quan mạnh không đồng nghĩa với quan hệ nhân quả. Cần chú ý tương quan giả do một biến thứ ba tạo ra.`},{type:`point`,ja:`主成分分析は多くの変数を、分散をできるだけ保ちながら少数の主成分へまとめる。因子分析は観測変数の背後にある共通因子を推定する。`,vi:`PCA gom nhiều biến thành một số ít thành phần chính trong khi cố giữ nhiều phương sai nhất có thể. Factor analysis ước lượng các nhân tố tiềm ẩn đứng sau các biến quan sát.`},{type:`example`,ja:`家賃を目的変数、広さ・駅からの距離・築年数を説明変数として回帰モデルを作る、という考え方が回帰分析の典型例である。`,vi:`Ví dụ điển hình của hồi quy: dùng tiền thuê nhà làm biến mục tiêu, còn diện tích, khoảng cách đến ga và tuổi tòa nhà làm các biến giải thích.`}],terms:[{term:`相関係数`,reading:`そうかんけいすう`,english:`Correlation Coefficient`,vi:`hệ số tương quan`,definitionJa:`二つの変数の線形的な関係の方向と強さを表す指標。`,definitionVi:`Chỉ số biểu diễn chiều và độ mạnh của mối quan hệ tuyến tính giữa hai biến.`},{term:`回帰分析`,reading:`かいきぶんせき`,english:`Regression Analysis`,vi:`phân tích hồi quy`,definitionJa:`説明変数と目的変数の関係をモデル化し、説明や予測に用いる統計手法。`,definitionVi:`Phương pháp thống kê mô hình hóa quan hệ giữa biến giải thích và biến mục tiêu để giải thích hoặc dự đoán.`},{term:`相関分析`,reading:`そうかんぶんせき`,english:`Correlation Analysis`,vi:`phân tích tương quan`,definitionJa:`変数間の関連の方向や強さを調べる分析。`,definitionVi:`Phân tích mức độ và chiều liên hệ giữa các biến.`},{term:`主成分分析`,reading:`しゅせいぶんぶんせき`,english:`Principal Component Analysis`,vi:`phân tích thành phần chính`,definitionJa:`多数の相関した変数を、情報をできるだけ保つ少数の主成分へ変換する次元削減手法。`,definitionVi:`Phương pháp giảm chiều biến nhiều biến tương quan thành một số ít thành phần chính, cố giữ tối đa thông tin.`},{term:`因子分析`,reading:`いんしぶんせき`,english:`Factor Analysis`,vi:`phân tích nhân tố`,definitionJa:`観測された複数変数の背後にある共通の潜在因子を推定する手法。`,definitionVi:`Phương pháp ước lượng các nhân tố tiềm ẩn chung đứng sau nhiều biến quan sát.`},{term:`相関と因果`,reading:`そうかんといんが`,english:`Correlation and Causation`,vi:`tương quan và nhân quả`,definitionJa:`変数が共に変化する相関と、一方が他方の原因となる因果関係を区別する考え方。`,definitionVi:`Khái niệm phân biệt tương quan (cùng biến đổi) với quan hệ nhân quả (một biến gây ra biến kia).`},{term:`擬似相関`,reading:`ぎじそうかん`,english:`Spurious Correlation`,vi:`tương quan giả`,definitionJa:`直接の因果関係がないのに、第三の要因などで見かけ上の相関が現れること。`,definitionVi:`Hiện tượng trông như có tương quan dù không có quan hệ nhân quả trực tiếp, thường do yếu tố thứ ba.`},{term:`説明変数`,reading:`せつめいへんすう`,english:`Explanatory Variable`,vi:`biến giải thích`,definitionJa:`回帰などで、目的変数を説明・予測する側の変数。`,definitionVi:`Biến được dùng để giải thích hoặc dự đoán biến mục tiêu trong hồi quy.`},{term:`目的変数`,reading:`もくてきへんすう`,english:`Response Variable`,vi:`biến mục tiêu`,definitionJa:`回帰などで、説明または予測の対象となる変数。`,definitionVi:`Biến cần được giải thích hoặc dự đoán trong mô hình hồi quy.`},{term:`尺度`,reading:`しゃくど`,english:`Scale of Measurement`,vi:`thang đo`,definitionJa:`データの性質を名義・順序・間隔・比例などに分類する測定上の基準。`,definitionVi:`Tiêu chuẩn phân loại tính chất dữ liệu thành các thang đo như định danh, thứ bậc, khoảng và tỷ lệ.`}],tags:[`applied-mathematics`,`statistics`,`correlation`,`regression`]},{id:`statistical-inference`,order:5,titleJa:`統計的推定と仮説検定`,titleVi:`Suy luận thống kê và kiểm định giả thuyết`,importance:`medium`,summaryJa:`標本から母集団を推定する考え方と、仮説検定における有意水準・誤り・検出力を整理する。`,summaryVi:`Hệ thống hóa cách suy luận về tổng thể từ mẫu và các khái niệm mức ý nghĩa, sai lầm và power trong kiểm định giả thuyết.`,content:[{type:`paragraph`,ja:`統計的推測では、標本データから母集団の未知の性質を推定したり、仮説がデータと整合するかを検定したりする。`,vi:`Trong suy luận thống kê, dữ liệu mẫu được dùng để ước lượng đặc tính chưa biết của tổng thể hoặc kiểm tra một giả thuyết có phù hợp với dữ liệu hay không.`},{type:`point`,ja:`尤度は、観測データを固定して、パラメータの値ごとにそのデータがどれほど起こりやすいかを見る考え方である。最尤推定では尤度が最大になるパラメータを選ぶ。`,vi:`Likelihood xem dữ liệu quan sát là cố định và đánh giá dữ liệu đó có khả năng xuất hiện đến mức nào với từng giá trị tham số. MLE chọn tham số làm likelihood lớn nhất.`},{type:`point`,ja:`有意水準αは、第1種の誤りを許容する上限として検定前に設定する基準。p値そのものとは異なる。`,vi:`Mức ý nghĩa α là ngưỡng đặt trước cho xác suất chấp nhận sai lầm loại I. Nó không phải là p-value.`},{type:`point`,ja:`第1種の誤りは正しい帰無仮説を棄却する誤り、第2種の誤りは誤った帰無仮説を棄却できない誤り。検出力は 1-β で表される。`,vi:`Sai lầm loại I là bác bỏ giả thuyết không khi nó đúng; sai lầm loại II là không bác bỏ giả thuyết không khi nó sai. Power của kiểm định là 1-β.`},{type:`warning`,ja:`仮説検定では通常、「帰無仮説を採択して真と証明した」とは言わず、「棄却できない」と表現する。`,vi:`Trong kiểm định giả thuyết, thường không nói “chấp nhận và chứng minh H0 đúng”, mà nói “không đủ bằng chứng để bác bỏ H0”.`}],terms:[{term:`推定`,reading:`すいてい`,english:`Estimation`,vi:`ước lượng`,definitionJa:`標本から母集団の未知のパラメータを推測する統計的手法。`,definitionVi:`Phương pháp thống kê dùng mẫu để suy ra tham số chưa biết của tổng thể.`},{term:`尤度`,reading:`ゆうど`,english:`Likelihood`,vi:`hàm hợp lý/likelihood`,definitionJa:`観測データを固定したとき、パラメータの値に応じてデータの起こりやすさを評価する量。`,definitionVi:`Đại lượng đánh giá mức độ dữ liệu quan sát có thể xuất hiện ứng với từng giá trị tham số.`},{term:`最尤推定`,reading:`さいゆうすいてい`,english:`Maximum Likelihood Estimation`,vi:`ước lượng hợp lý cực đại`,definitionJa:`観測データに対する尤度が最大になるようにモデルのパラメータを推定する方法。`,definitionVi:`Phương pháp ước lượng tham số mô hình sao cho likelihood của dữ liệu quan sát đạt cực đại.`},{term:`仮説検定`,reading:`かせつけんてい`,english:`Hypothesis Testing`,vi:`kiểm định giả thuyết`,definitionJa:`標本データを用いて帰無仮説を棄却できるかを統計的に判断する手法。`,definitionVi:`Phương pháp dùng dữ liệu mẫu để quyết định có thể bác bỏ giả thuyết không hay không.`},{term:`有意水準`,reading:`ゆういすいじゅん`,english:`Significance Level`,vi:`mức ý nghĩa`,definitionJa:`第1種の誤りを許容する確率の上限として、検定前に設定する値α。`,definitionVi:`Giá trị α đặt trước kiểm định, biểu thị mức xác suất tối đa chấp nhận cho sai lầm loại I.`},{term:`棄却域`,reading:`ききゃくいき`,english:`Rejection Region`,vi:`miền bác bỏ`,definitionJa:`検定統計量が入ったときに帰無仮説を棄却する値の範囲。`,definitionVi:`Miền giá trị của thống kê kiểm định mà khi rơi vào đó, giả thuyết không (H0) sẽ bị bác bỏ.`},{term:`第1種の誤り`,reading:`だいいちしゅのあやまり`,english:`Type I Error`,vi:`sai lầm loại I`,definitionJa:`実際には正しい帰無仮説を誤って棄却すること。`,definitionVi:`Bác bỏ nhầm giả thuyết không trong khi nó thực sự đúng.`},{term:`第2種の誤り`,reading:`だいにしゅのあやまり`,english:`Type II Error`,vi:`sai lầm loại II`,definitionJa:`実際には誤っている帰無仮説を棄却できないこと。`,definitionVi:`Không bác bỏ giả thuyết không trong khi nó thực sự sai.`},{term:`検出力`,reading:`けんしゅつりょく`,english:`Statistical Power`,vi:`lực kiểm định`,definitionJa:`帰無仮説が誤っているときに正しく棄却できる確率。通常1-βで表す。`,definitionVi:`Xác suất bác bỏ đúng giả thuyết không khi nó sai, thường biểu diễn bằng 1-β.`}],tags:[`applied-mathematics`,`statistics`,`hypothesis-testing`]},{id:`linear-algebra`,order:6,titleJa:`線形代数`,titleVi:`Đại số tuyến tính`,importance:`medium`,summaryJa:`スカラ、ベクトル、行列と基本的な行列操作、固有値・固有ベクトルの関係を理解する。`,summaryVi:`Hiểu scalar, vector, ma trận, các phép toán ma trận cơ bản và mối quan hệ giữa trị riêng và vector riêng.`,content:[{type:`paragraph`,ja:`線形代数は、ベクトルと行列を使って複数の量や一次関係を扱う数学である。コンピュータグラフィックス、データ解析、機械学習などの基礎にもなる。`,vi:`Đại số tuyến tính dùng vector và ma trận để xử lý nhiều đại lượng và các quan hệ tuyến tính. Đây cũng là nền tảng cho đồ họa máy tính, phân tích dữ liệu và học máy.`},{type:`point`,ja:`スカラは一つの数値、ベクトルは複数成分を並べた量、行列は数値を行と列に配置したものとして整理する。`,vi:`Có thể hiểu scalar là một giá trị, vector là một dãy nhiều thành phần, và ma trận là các giá trị sắp theo hàng và cột.`},{type:`point`,ja:`単位行列Iは AI=IA=A を満たす。逆行列A^-1が存在すれば AA^-1=A^-1A=I。`,vi:`Ma trận đơn vị I thỏa AI=IA=A. Nếu ma trận nghịch đảo A^-1 tồn tại thì AA^-1=A^-1A=I.`},{type:`example`,ja:`A=[[1,2],[3,4]] の転置行列 A^T は [[1,3],[2,4]] である。`,vi:`Với A=[[1,2],[3,4]], ma trận chuyển vị A^T là [[1,3],[2,4]].`},{type:`point`,ja:`固有ベクトルvと固有値λは Av=λv を満たす。変換後のベクトルが元のベクトルと同一直線上にあり、λ倍になる非零ベクトルが固有ベクトルである。`,vi:`Vector riêng v và trị riêng λ thỏa Av=λv. Vector riêng là vector khác 0 mà sau phép biến đổi, vector kết quả vẫn nằm trên cùng một đường thẳng với vector ban đầu và bằng λ lần vector đó.`}],terms:[{term:`線形代数`,reading:`せんけいだいすう`,english:`Linear Algebra`,vi:`đại số tuyến tính`,definitionJa:`ベクトル、行列、線形写像などを扱う数学の分野。`,definitionVi:`Lĩnh vực toán học nghiên cứu vector, ma trận, ánh xạ tuyến tính và các khái niệm liên quan.`},{term:`スカラ`,reading:`スカラ`,english:`Scalar`,vi:`đại lượng vô hướng`,definitionJa:`ベクトルや行列と区別される単一の数値。`,definitionVi:`Một giá trị số đơn lẻ, được phân biệt với vector và ma trận.`},{term:`ベクトル`,reading:`ベクトル`,english:`Vector`,vi:`vector`,definitionJa:`複数の成分を持つ量で、線形代数では数の並びとして扱う。`,definitionVi:`Đại lượng gồm nhiều thành phần, được xử lý như một dãy số trong đại số tuyến tính.`},{term:`固有値`,reading:`こゆうち`,english:`Eigenvalue`,vi:`trị riêng`,definitionJa:`行列Aと非零ベクトルvに対し Av=λv を満たすスカラλ。`,definitionVi:`Scalar λ thỏa Av=λv với ma trận A và vector khác 0 v.`},{term:`固有ベクトル`,reading:`こゆうベクトル`,english:`Eigenvector`,vi:`vector riêng`,definitionJa:`行列Aによる変換後も元のベクトルと同一直線上にあり、Av=λvを満たす非零ベクトル。`,definitionVi:`Vector khác 0 thỏa Av=λv, nên sau phép biến đổi bởi A, vector kết quả vẫn nằm trên cùng một đường thẳng với vector ban đầu.`},{term:`行列`,reading:`ぎょうれつ`,english:`Matrix`,vi:`ma trận`,definitionJa:`数や記号を行と列に長方形状に並べたもの。`,definitionVi:`Cấu trúc sắp các số hoặc ký hiệu thành các hàng và cột.`},{term:`逆行列`,reading:`ぎゃくぎょうれつ`,english:`Inverse Matrix`,vi:`ma trận nghịch đảo`,definitionJa:`正方行列Aに対して AA^-1=A^-1A=I を満たす行列A^-1。`,definitionVi:`Ma trận A^-1 thỏa AA^-1=A^-1A=I với ma trận vuông A.`},{term:`単位行列`,reading:`たんいぎょうれつ`,english:`Identity Matrix`,vi:`ma trận đơn vị`,definitionJa:`主対角成分が1、それ以外が0で、行列積の単位元となる正方行列。`,definitionVi:`Ma trận vuông có đường chéo chính bằng 1, các phần tử khác bằng 0, đóng vai trò phần tử đơn vị của phép nhân ma trận.`},{term:`転置行列`,reading:`てんちぎょうれつ`,english:`Transpose Matrix`,vi:`ma trận chuyển vị`,definitionJa:`元の行列の行と列を入れ替えて得られる行列。`,definitionVi:`Ma trận thu được bằng cách hoán đổi hàng và cột của ma trận ban đầu.`}],tags:[`applied-mathematics`,`linear-algebra`,`matrix`]},{id:`sequences`,order:7,titleJa:`数列`,titleVi:`Dãy số`,importance:`medium`,summaryJa:`等差数列、等比数列、フィボナッチ数列の規則を理解し、次項や一般項を求める基本を押さえる。`,summaryVi:`Hiểu quy luật của cấp số cộng, cấp số nhân và dãy Fibonacci, đồng thời nắm cách tìm số hạng tiếp theo hoặc số hạng tổng quát.`,content:[{type:`point`,ja:`等差数列は差が一定。一般項は a_n=a_1+(n-1)d。`,vi:`Cấp số cộng có công sai không đổi. Số hạng tổng quát: a_n=a_1+(n-1)d.`},{type:`point`,ja:`等比数列は比が一定。一般項は a_n=a_1 r^(n-1)。`,vi:`Cấp số nhân có công bội không đổi. Số hạng tổng quát: a_n=a_1 r^(n-1).`},{type:`example`,ja:`2,6,18,54,... は公比3の等比数列なので次の項は162。`,vi:`2,6,18,54,... là cấp số nhân có công bội 3 nên số tiếp theo là 162.`},{type:`point`,ja:`フィボナッチ数列は F_n=F_(n-1)+F_(n-2) のように直前2項の和で次項を定義する。`,vi:`Dãy Fibonacci định nghĩa số hạng tiếp theo bằng tổng hai số hạng ngay trước: F_n=F_(n-1)+F_(n-2).`}],terms:[{term:`等差数列`,reading:`とうさすうれつ`,english:`Arithmetic Sequence`,vi:`cấp số cộng`,definitionJa:`隣り合う項の差が一定である数列。`,definitionVi:`Dãy số trong đó hiệu giữa hai số hạng liên tiếp là hằng số.`},{term:`等比数列`,reading:`とうひすうれつ`,english:`Geometric Sequence`,vi:`cấp số nhân`,definitionJa:`各項を前の項で割った比が一定である数列。`,definitionVi:`Dãy số trong đó tỷ số giữa hai số hạng liên tiếp là hằng số.`},{term:`フィボナッチ数列`,reading:`フィボナッチすうれつ`,english:`Fibonacci Sequence`,vi:`dãy Fibonacci`,definitionJa:`各項が直前の二つの項の和で定義される数列。`,definitionVi:`Dãy số trong đó mỗi số hạng được tạo bởi tổng của hai số hạng liền trước.`}],tags:[`applied-mathematics`,`sequence`]},{id:`functions-and-calculus`,order:8,titleJa:`関数・因数分解・微積分`,titleVi:`Hàm số, phân tích nhân tử, đạo hàm và tích phân`,importance:`medium`,summaryJa:`三角関数、因数分解、微分、積分の基本的な意味と計算の考え方を理解する。`,summaryVi:`Hiểu ý nghĩa và cách tính cơ bản của hàm lượng giác, phân tích nhân tử, đạo hàm và tích phân.`,content:[{type:`point`,ja:`三角関数の基本は sin、cos、tan。直角三角形では角度と辺の比を結び付ける。`,vi:`Ba hàm lượng giác cơ bản là sin, cos và tan; trong tam giác vuông chúng liên hệ góc với tỷ lệ các cạnh.`},{type:`example`,ja:`x^2-5x+6=(x-2)(x-3)。因数分解すると方程式 x^2-5x+6=0 の解が x=2,3 と分かる。`,vi:`x^2-5x+6=(x-2)(x-3). Sau khi phân tích nhân tử, phương trình x^2-5x+6=0 có nghiệm x=2 và 3.`},{type:`point`,ja:`微分は瞬間的な変化率や接線の傾きを求める操作。積分は変化を積み上げて面積や総量を求める操作として理解する。`,vi:`Đạo hàm cho biết tốc độ thay đổi tức thời hoặc độ dốc của tiếp tuyến. Tích phân cộng dồn các đại lượng vi phân để tìm diện tích hoặc tổng lượng.`},{type:`example`,ja:`f(x)=x^2 なら f'(x)=2x。x=3での接線の傾きは6。`,vi:`Nếu f(x)=x^2 thì f'(x)=2x. Tại x=3, độ dốc tiếp tuyến bằng 6.`}],terms:[{term:`三角関数`,reading:`さんかくかんすう`,english:`Trigonometric Functions`,vi:`hàm lượng giác`,definitionJa:`角度と辺の比を関係付ける関数で、代表的なものにsin、cos、tanがある。`,definitionVi:`Các hàm liên hệ góc với tỷ lệ các cạnh, tiêu biểu là sin, cos và tan.`},{term:`因数分解`,reading:`いんすうぶんかい`,english:`Factorization`,vi:`phân tích nhân tử`,definitionJa:`数や多項式を複数の因数の積の形に変形すること。`,definitionVi:`Biến đổi một số hoặc đa thức thành tích của các nhân tử.`},{term:`微分`,reading:`びぶん`,english:`Differentiation`,vi:`đạo hàm`,definitionJa:`関数のある点での変化率や接線の傾きを求める操作。`,definitionVi:`Phép toán tìm tốc độ thay đổi hoặc độ dốc tiếp tuyến của hàm tại một điểm.`},{term:`積分`,reading:`せきぶん`,english:`Integration`,vi:`tích phân`,definitionJa:`微小な量を積み上げて面積や総量を求める数学的操作。`,definitionVi:`Phép toán cộng dồn các lượng vi phân để tìm diện tích hoặc tổng lượng.`}],tags:[`applied-mathematics`,`functions`,`calculus`]},{id:`numerical-methods-and-errors`,order:9,titleJa:`数値計算と誤差`,titleVi:`Tính toán số và sai số`,importance:`high`,summaryJa:`ニュートン法による近似解の求め方と、絶対誤差・相対誤差・丸め誤差・打切り誤差を区別する。`,summaryVi:`Hiểu cách Newton tìm nghiệm gần đúng và phân biệt sai số tuyệt đối, tương đối, làm tròn và cắt cụt.`,content:[{type:`paragraph`,ja:`コンピュータの数値計算では、真の値を厳密に扱えず近似を使う場合がある。そのため、誤差の種類と原因を区別することが重要である。`,vi:`Trong tính toán số trên máy tính, nhiều trường hợp không thể giữ giá trị chính xác và phải dùng xấp xỉ. Vì vậy cần phân biệt các loại sai số và nguyên nhân của chúng.`},{type:`point`,ja:`ニュートン法では x_(n+1)=x_n-f(x_n)/f'(x_n) を繰り返して方程式 f(x)=0 の根へ近づける。`,vi:`Phương pháp Newton lặp công thức x_(n+1)=x_n-f(x_n)/f'(x_n) để tiến gần nghiệm của f(x)=0.`},{type:`example`,ja:`f(x)=x^2-2、初期値x_0=1.5なら、x_1=1.5-(1.5^2-2)/(2×1.5)=1.416666... となり、√2に近づく。`,vi:`Với f(x)=x^2-2 và x_0=1,5, ta có x_1=1,5-(1,5^2-2)/(2×1,5)=1,416666..., tiến gần √2.`},{type:`point`,ja:`絶対誤差は |近似値-真値|、相対誤差は絶対誤差を |真値| で割ったもの。`,vi:`Sai số tuyệt đối là |giá trị xấp xỉ - giá trị thật|; sai số tương đối là sai số tuyệt đối chia cho |giá trị thật|.`},{type:`warning`,ja:`丸め誤差は有限桁へ丸めることで生じる。打切り誤差は、本来無限に続く計算過程や級数などを有限の段階で打ち切ることで生じる。`,vi:`Sai số làm tròn sinh ra khi làm tròn về số chữ số hữu hạn. Sai số cắt cụt sinh ra khi dừng một quá trình vốn cần vô hạn bước hoặc chuỗi vô hạn ở một số bước hữu hạn.`}],terms:[{term:`ニュートン法`,reading:`ニュートンほう`,english:`Newton's Method`,vi:`phương pháp Newton`,definitionJa:`関数の接線を利用し、反復計算によって方程式の根を近似する数値解法。`,definitionVi:`Phương pháp số dùng tiếp tuyến và phép lặp để xấp xỉ nghiệm của phương trình.`},{term:`絶対誤差`,reading:`ぜったいごさ`,english:`Absolute Error`,vi:`sai số tuyệt đối`,definitionJa:`近似値と真値との差の絶対値。`,definitionVi:`Trị tuyệt đối của hiệu giữa giá trị xấp xỉ và giá trị thật.`},{term:`相対誤差`,reading:`そうたいごさ`,english:`Relative Error`,vi:`sai số tương đối`,definitionJa:`絶対誤差を真値の絶対値で割った比。`,definitionVi:`Tỷ lệ giữa sai số tuyệt đối và trị tuyệt đối của giá trị thật.`},{term:`丸め誤差`,reading:`まるめごさ`,english:`Rounding Error`,vi:`sai số làm tròn`,definitionJa:`有限桁で数を表現するために丸めることで生じる誤差。`,definitionVi:`Sai số phát sinh do làm tròn số để biểu diễn bằng số chữ số hữu hạn.`},{term:`打切り誤差`,reading:`うちきりごさ`,english:`Truncation Error`,vi:`sai số cắt cụt`,definitionJa:`無限級数や反復など本来続く計算を有限の段階で打ち切って近似することで生じる誤差。`,definitionVi:`Sai số phát sinh khi cắt một quá trình tính toán, chuỗi vô hạn hoặc phép lặp ở một số bước hữu hạn để xấp xỉ.`}],tags:[`applied-mathematics`,`numerical-analysis`,`error`]},{id:`graph-theory`,order:10,titleJa:`グラフ理論`,titleVi:`Lý thuyết đồ thị`,importance:`medium`,summaryJa:`頂点と辺で関係を表現するグラフの基本と、有向グラフ・無向グラフの違いを理解する。`,summaryVi:`Hiểu nền tảng của đồ thị dùng đỉnh và cạnh để biểu diễn quan hệ, đồng thời phân biệt đồ thị có hướng và vô hướng.`,content:[{type:`paragraph`,ja:`グラフ理論では、対象を頂点、対象間の関係を辺としてモデル化する。ネットワークや経路、依存関係などの表現に使われる。`,vi:`Trong lý thuyết đồ thị, đối tượng được biểu diễn bằng đỉnh và quan hệ giữa các đối tượng bằng cạnh. Nó dùng để mô hình hóa mạng, đường đi và quan hệ phụ thuộc.`},{type:`point`,ja:`有向グラフでは辺に向きがあり、A→BとB→Aは別の関係。無向グラフでは辺に向きがない。`,vi:`Trong đồ thị có hướng, cạnh có chiều nên A→B và B→A là hai quan hệ khác nhau. Trong đồ thị vô hướng, cạnh không có chiều.`},{type:`example`,ja:`SNSの「フォロー」は一方向なので有向グラフ、相互的な「友達」関係は無向グラフで表しやすい。`,vi:`Quan hệ “follow” trên mạng xã hội là một chiều nên phù hợp với đồ thị có hướng; quan hệ “bạn bè” tương hỗ phù hợp với đồ thị vô hướng.`}],terms:[{term:`グラフ理論`,reading:`グラフりろん`,english:`Graph Theory`,vi:`lý thuyết đồ thị`,definitionJa:`頂点と辺からなる構造を用いて対象間の関係を扱う数学分野。`,definitionVi:`Lĩnh vực toán học dùng cấu trúc gồm đỉnh và cạnh để mô tả quan hệ giữa các đối tượng.`},{term:`有向グラフ`,reading:`ゆうこうグラフ`,english:`Directed Graph`,vi:`đồ thị có hướng`,definitionJa:`各辺に向きが定められているグラフ。`,definitionVi:`Đồ thị trong đó mỗi cạnh có một hướng xác định.`},{term:`無向グラフ`,reading:`むこうグラフ`,english:`Undirected Graph`,vi:`đồ thị vô hướng`,definitionJa:`辺に方向が定められていないグラフ。`,definitionVi:`Đồ thị trong đó các cạnh không có hướng.`}],tags:[`applied-mathematics`,`graph-theory`]},{id:`queueing-theory`,order:11,titleJa:`待ち行列理論`,titleVi:`Lý thuyết hàng đợi`,importance:`high`,summaryJa:`到着とサービスの関係から、システムの混雑や待ち時間を分析する基本概念を理解する。`,summaryVi:`Hiểu các khái niệm cơ bản dùng quan hệ giữa lượt đến và phục vụ để phân tích mức tải và thời gian chờ của hệ thống.`,content:[{type:`paragraph`,ja:`待ち行列モデルは、要求が到着し、サービス設備で処理され、必要なら待つという流れを数理的に表す。サーバや窓口の性能評価に使われる。`,vi:`Mô hình hàng đợi biểu diễn bằng toán học quá trình yêu cầu đến, được phục vụ và phải chờ nếu cần. Nó được dùng để đánh giá hiệu năng server hoặc quầy phục vụ.`},{type:`point`,ja:`平均到着率λは単位時間当たりの平均到着件数、平均サービス率μは単位時間当たりに1台のサービス設備が処理できる平均件数として表す。`,vi:`Tốc độ đến trung bình λ là số lượt đến trung bình trên một đơn vị thời gian; tốc độ phục vụ trung bình μ là số lượt trung bình một bộ phục vụ có thể xử lý trên một đơn vị thời gian.`},{type:`example`,ja:`平均到着率が6件/分、平均サービス率が10件/分なら、1台のサービス設備の利用率は ρ=λ/μ=0.6 と考えられる。`,vi:`Nếu tốc độ đến trung bình là 6 yêu cầu/phút và tốc độ phục vụ là 10 yêu cầu/phút, mức sử dụng của một server là ρ=λ/μ=0,6.`},{type:`warning`,ja:`待ち時間はサービス開始までの時間、サービス時間は実際の処理に要する時間であり、同じではない。`,vi:`Thời gian chờ là thời gian đến khi bắt đầu được phục vụ; thời gian phục vụ là thời gian thực tế cần để xử lý. Hai khái niệm này khác nhau.`}],terms:[{term:`待ち行列モデル`,reading:`まちぎょうれつモデル`,english:`Queueing Model`,vi:`mô hình hàng đợi`,definitionJa:`要求の到着、待ち、サービス処理を数学的に表現するモデル。`,definitionVi:`Mô hình toán học biểu diễn quá trình yêu cầu đến, chờ và được phục vụ.`},{term:`サービス時間`,reading:`サービスじかん`,english:`Service Time`,vi:`thời gian phục vụ`,definitionJa:`一つの要求を実際に処理するために要する時間。`,definitionVi:`Thời gian thực tế cần để xử lý một yêu cầu.`},{term:`待ち時間`,reading:`まちじかん`,english:`Waiting Time`,vi:`thời gian chờ`,definitionJa:`要求が到着してからサービスが開始されるまでに待つ時間。`,definitionVi:`Thời gian từ khi yêu cầu đến cho đến khi bắt đầu được phục vụ.`},{term:`到着時間`,reading:`とうちゃくじかん`,english:`Arrival Time`,vi:`thời điểm/thời gian đến`,definitionJa:`待ち行列に要求や顧客が到着する時刻または到着に関する時間情報。`,definitionVi:`Thời điểm hoặc thông tin thời gian mà yêu cầu/khách hàng đến hệ thống hàng đợi.`},{term:`平均到着率`,reading:`へいきんとうちゃくりつ`,english:`Average Arrival Rate`,vi:`tốc độ đến trung bình`,definitionJa:`単位時間当たりに到着する要求の平均件数。一般にλで表す。`,definitionVi:`Số yêu cầu đến trung bình trên một đơn vị thời gian, thường ký hiệu λ.`},{term:`平均サービス率`,reading:`へいきんサービスりつ`,english:`Average Service Rate`,vi:`tốc độ phục vụ trung bình`,definitionJa:`単位時間当たりにサービス設備が処理できる平均件数。一般にμで表す。`,definitionVi:`Số yêu cầu trung bình một bộ phục vụ xử lý được trong một đơn vị thời gian, thường ký hiệu μ.`}],tags:[`applied-mathematics`,`queueing-theory`,`performance`]},{id:`optimization`,order:12,titleJa:`最適化`,titleVi:`Tối ưu hóa`,importance:`medium`,summaryJa:`制約の下で最良の解を求める最適化問題と、部分問題の結果を再利用する動的計画法の考え方を学ぶ。`,summaryVi:`Học bài toán tối ưu tìm phương án tốt nhất dưới các ràng buộc và tư duy quy hoạch động tái sử dụng kết quả của các bài toán con.`,content:[{type:`paragraph`,ja:`最適化問題では、目的関数を最大化・最小化する変数の値を、与えられた制約の範囲内で求める。`,vi:`Trong bài toán tối ưu, ta tìm giá trị biến làm cực đại hoặc cực tiểu hàm mục tiêu trong phạm vi các ràng buộc cho trước.`},{type:`point`,ja:`動的計画法は、重複する部分問題を一度だけ解き、その結果を保存して再利用することで計算量を減らす考え方である。`,vi:`Quy hoạch động giảm lượng tính toán bằng cách chỉ giải mỗi bài toán con lặp lại một lần, lưu kết quả và tái sử dụng.`},{type:`example`,ja:`フィボナッチ数列を単純再帰で求めると同じ値を何度も計算するが、動的計画法では計算済みの値を保存して再利用できる。`,vi:`Khi tính Fibonacci bằng đệ quy đơn giản, cùng một giá trị bị tính lại nhiều lần; với quy hoạch động, các kết quả đã tính được lưu và tái sử dụng.`},{type:`warning`,ja:`動的計画法は「動的にプログラムを書く」という意味ではなく、部分問題の解を保存・再利用して全体問題を効率よく解く考え方である。`,vi:`Dynamic Programming không có nghĩa là “lập trình động”; đây là phương pháp lưu và tái sử dụng lời giải của các bài toán con để giải bài toán tổng thể một cách hiệu quả.`}],terms:[{term:`最適化問題`,reading:`さいてきかもんだい`,english:`Optimization Problem`,vi:`bài toán tối ưu`,definitionJa:`制約条件の下で目的関数を最大化または最小化する解を求める問題。`,definitionVi:`Bài toán tìm nghiệm làm cực đại hoặc cực tiểu hàm mục tiêu dưới các ràng buộc.`},{term:`動的計画法`,reading:`どうてきけいかくほう`,english:`Dynamic Programming`,vi:`quy hoạch động`,definitionJa:`問題を重複する部分問題に分け、計算結果を保存・再利用して効率的に解く手法。`,definitionVi:`Phương pháp chia bài toán thành các bài toán con lặp lại, lưu và tái sử dụng kết quả để giải hiệu quả.`}],tags:[`applied-mathematics`,`optimization`,`dynamic-programming`]}]},u={id:`information-theory`,order:3,titleJa:`情報に関する理論`,titleVi:`Lý thuyết về thông tin`,syllabus:`9.2`,lessons:[{id:`coding-and-huffman-coding`,order:1,titleJa:`通信路符号化とハフマン符号`,titleVi:`Mã hóa kênh truyền và mã Huffman`,importance:`high`,summaryJa:`通信時の誤りに備える通信路符号化と、出現頻度を利用してデータを効率よく圧縮するハフマン符号について、目的と仕組みの違いを理解する。`,summaryVi:`Tìm hiểu mã hóa kênh truyền dùng để đối phó với lỗi khi truyền dữ liệu và mã Huffman dùng tần suất xuất hiện để nén dữ liệu hiệu quả, đồng thời phân biệt rõ mục đích và cơ chế của hai phương pháp.`,content:[{type:`heading`,ja:`通信路符号化`,vi:`Mã hóa kênh truyền`},{type:`paragraph`,ja:`通信路符号化は、データを通信路で送るときに発生する可能性のある誤りに備えるための符号化である。元のデータに検査用の情報を付加し、受信側で誤りを検出したり、方式によっては訂正したりできるようにする。`,vi:`通信路符号化 (mã hóa kênh truyền) là kỹ thuật mã hóa nhằm đối phó với lỗi có thể xảy ra khi dữ liệu được truyền qua kênh truyền. Thông tin kiểm tra được bổ sung vào dữ liệu gốc để phía nhận có thể phát hiện lỗi và, tùy phương pháp, có thể sửa lỗi.`},{type:`point`,ja:`目的はデータを小さくすることではなく、通信の信頼性を高めることである。そのため、誤り検出・誤り訂正のための冗長な情報を付加する。`,vi:`Mục đích không phải làm dữ liệu nhỏ hơn mà là tăng độ tin cậy khi truyền. Vì vậy dữ liệu được bổ sung thông tin dư thừa phục vụ phát hiện hoặc sửa lỗi.`},{type:`heading`,ja:`ハフマン符号`,vi:`Mã Huffman`},{type:`paragraph`,ja:`ハフマン符号は、記号の出現頻度に応じて異なる長さのビット列を割り当てる可変長符号である。出現頻度が高い記号には短い符号、低い記号には長い符号を割り当てることで、データ全体の符号長を小さくする。`,vi:`ハフマン符号 (mã Huffman) là mã có độ dài thay đổi, trong đó chuỗi bit có độ dài khác nhau được gán theo tần suất xuất hiện của ký hiệu. Ký hiệu xuất hiện nhiều được gán mã ngắn, ký hiệu xuất hiện ít được gán mã dài, nhờ đó giảm tổng số bit cần dùng.`},{type:`point`,ja:`ハフマン符号は、出現頻度の低い記号から順にまとめて木を構成し、各枝に0と1を割り当てることで符号を作る。頻度が高い記号ほど根に近くなり、短い符号になりやすい。`,vi:`Mã Huffman được xây dựng bằng cách lần lượt ghép các ký hiệu có tần suất thấp để tạo thành cây, sau đó gán 0 và 1 cho các nhánh. Ký hiệu có tần suất cao thường nằm gần gốc hơn nên nhận mã ngắn hơn.`},{type:`example`,ja:`例えば、Aの出現頻度が高く、BやCの出現頻度が低い場合、Aには「0」、Bには「10」、Cには「11」のように、頻度の高い記号へ短い符号を割り当てることができる。`,vi:`Ví dụ, nếu A xuất hiện thường xuyên còn B và C ít xuất hiện hơn, có thể gán A = “0”, B = “10”, C = “11”, tức là ký hiệu có tần suất cao nhận mã ngắn hơn.`},{type:`warning`,ja:`通信路符号化とハフマン符号は目的が異なる。通信路符号化は誤りへの耐性を高めるために冗長性を加えるのに対し、ハフマン符号は出現頻度を利用して符号量を減らす可逆圧縮のための符号化である。`,vi:`Không được nhầm mục đích của hai khái niệm. 通信路符号化 thêm thông tin dư thừa để tăng khả năng chống lỗi, trong khi ハフマン符号 tận dụng tần suất xuất hiện để giảm lượng mã và thực hiện nén không mất dữ liệu.`}],terms:[{term:`通信路符号化`,reading:`つうしんろふごうか`,english:`Channel Coding`,vi:`mã hóa kênh truyền`,definitionJa:`通信路で生じる誤りを検出・訂正できるように、データへ冗長な情報を付加して符号化する技術。`,definitionVi:`Kỹ thuật mã hóa bổ sung thông tin dư thừa vào dữ liệu để có thể phát hiện và, tùy phương pháp, sửa lỗi phát sinh trên kênh truyền.`},{term:`ハフマン符号`,reading:`ハフマンふごう`,english:`Huffman Coding`,vi:`mã Huffman`,definitionJa:`記号の出現頻度に基づき、頻度の高い記号には短い符号、低い記号には長い符号を割り当てる可変長符号。`,definitionVi:`Mã có độ dài thay đổi, gán mã ngắn cho ký hiệu xuất hiện thường xuyên và mã dài cho ký hiệu ít xuất hiện dựa trên tần suất xuất hiện.`}],tags:[`information-theory`,`coding`,`channel-coding`,`data-compression`]},{id:`japanese-character-codes`,order:2,titleJa:`文字コードの基礎`,titleVi:`Cơ bản về mã ký tự`,importance:`high`,summaryJa:`ASCIIコードを基礎として、EUC、JISコード、シフトJISコードの特徴と違いを理解する。文字をコンピュータ内部で数値として表現する仕組みと、日本語を扱うために発展した代表的な文字コードを整理する。`,summaryVi:`Tìm hiểu ASCII cùng các mã ký tự EUC, JIS và Shift JIS. Trọng tâm là cơ chế biểu diễn ký tự bằng giá trị số trong máy tính và đặc điểm của các hệ mã được sử dụng để xử lý tiếng Nhật.`,content:[{type:`heading`,ja:`文字コードとは`,vi:`Mã ký tự là gì?`},{type:`paragraph`,ja:`コンピュータは文字そのものを直接扱うのではなく、文字に対応する数値を使って処理する。文字コードは、文字と数値の対応関係を定めたものである。異なる文字コードでデータを解釈すると、文字化けが発生することがある。`,vi:`Máy tính không trực tiếp xử lý bản thân ký tự mà xử lý các giá trị số tương ứng với ký tự. Mã ký tự quy định quan hệ giữa ký tự và giá trị số. Nếu dữ liệu được giải mã bằng một hệ mã khác với hệ mã ban đầu, hiện tượng lỗi hiển thị ký tự (文字化け) có thể xảy ra.`},{type:`heading`,ja:`ASCIIコード`,vi:`Mã ASCII`},{type:`paragraph`,ja:`ASCIIコードは、英字、数字、記号、制御文字などを表すための代表的な文字コードである。標準ASCIIは7ビットで128種類の値を表し、例えば大文字の「A」は10進数の65に対応する。`,vi:`ASCII là mã ký tự tiêu biểu dùng để biểu diễn chữ cái Latin, chữ số, ký hiệu và các ký tự điều khiển. ASCII chuẩn sử dụng 7 bit để biểu diễn 128 giá trị; ví dụ chữ hoa “A” tương ứng với số thập phân 65.`},{type:`point`,ja:`FEでは、ASCIIは7ビットで128種類を表現できることを覚えておく。2^7＝128である。`,vi:`Trong FE, cần nhớ ASCII chuẩn dùng 7 bit nên có thể biểu diễn 128 giá trị: 2^7 = 128.`},{type:`heading`,ja:`日本語を扱う文字コード`,vi:`Các mã ký tự dùng cho tiếng Nhật`},{type:`paragraph`,ja:`ASCIIだけでは漢字やひらがななどの日本語を十分に表現できない。そのため、日本語を扱うための文字コードとしてJISコード、EUC、シフトJISコードなどが利用されてきた。`,vi:`Chỉ ASCII không đủ để biểu diễn các ký tự tiếng Nhật như kanji và hiragana. Vì vậy, các hệ mã như JIS, EUC và Shift JIS đã được sử dụng để xử lý tiếng Nhật.`},{type:`point`,ja:`JISコードは日本産業規格（JIS）に基づく文字コードである。EUCはUNIX系環境で広く利用されてきた文字コード体系であり、日本語ではEUC-JPが代表的である。シフトJISコードはASCIIとの共存を考慮して日本語を扱えるようにした文字コードで、国内のパソコン環境などで広く利用されてきた。`,vi:`JIS code dựa trên tiêu chuẩn công nghiệp Nhật Bản (JIS). EUC là hệ mã từng được sử dụng rộng rãi trong môi trường UNIX, trong đó EUC-JP là dạng tiêu biểu cho tiếng Nhật. Shift JIS được thiết kế để xử lý tiếng Nhật đồng thời có thể cùng tồn tại với ASCII và từng được sử dụng rộng rãi trên các hệ thống máy tính cá nhân tại Nhật.`},{type:`warning`,ja:`ASCII、EUC、JISコード、シフトJISコードは同じものではない。特に、EUCは文字コード体系の名称であり、日本語を扱う場合にはEUC-JPが代表的である。また、文字コードが異なるデータを誤った方式で解釈すると文字化けの原因になる。`,vi:`ASCII, EUC, JIS và Shift JIS không phải cùng một hệ mã. Đặc biệt, EUC là tên của một họ mã ký tự, còn EUC-JP là dạng tiêu biểu dùng cho tiếng Nhật. Việc giải mã dữ liệu bằng sai hệ mã là một nguyên nhân phổ biến gây 文字化け.`}],terms:[{term:`ASCIIコード`,reading:`アスキーコード`,english:`ASCII Code`,vi:`mã ASCII`,definitionJa:`英字、数字、記号、制御文字などを数値に対応付ける文字コード。標準ASCIIは7ビットで128種類の値を表現する。`,definitionVi:`Mã ký tự ánh xạ chữ cái Latin, chữ số, ký hiệu và ký tự điều khiển sang các giá trị số. ASCII chuẩn sử dụng 7 bit và biểu diễn được 128 giá trị.`},{term:`EUC`,reading:`イーユーシー`,english:`Extended UNIX Code`,vi:`mã EUC`,definitionJa:`UNIX系システムで多言語の文字を扱うために利用されてきた文字コード体系。日本語用としてEUC-JPが広く使われた。`,definitionVi:`Hệ mã ký tự từng được sử dụng trong các hệ thống UNIX để xử lý nhiều loại ký tự. Đối với tiếng Nhật, EUC-JP từng được sử dụng rộng rãi.`},{term:`JISコード`,reading:`ジスコード`,english:`JIS Code`,vi:`mã JIS`,definitionJa:`日本産業規格（JIS）に基づいて日本語の文字などを扱うための文字コード。`,definitionVi:`Mã ký tự dựa trên tiêu chuẩn JIS của Nhật Bản, được dùng để biểu diễn các ký tự tiếng Nhật và các ký tự liên quan.`},{term:`シフトJISコード`,reading:`シフトジスコード`,english:`Shift JIS Code`,vi:`mã Shift JIS`,definitionJa:`ASCIIとの共存を考慮しながら、日本語の漢字、ひらがな、カタカナなどを表現できるようにした文字コード。`,definitionVi:`Mã ký tự được thiết kế để biểu diễn kanji, hiragana, katakana và các ký tự tiếng Nhật trong khi vẫn xét đến khả năng cùng tồn tại với ASCII.`}],tags:[`information-theory`,`character-code`,`ascii`,`japanese-encoding`]},{id:`unicode-and-logical-reasoning`,order:3,titleJa:`Unicode・UCSと論理的推論`,titleVi:`Unicode, UCS và suy luận logic`,importance:`high`,summaryJa:`UnicodeとUCSによる文字の統一的な表現と、述語論理・演繹推論による論理的な表現と推論の基本を理解する。`,summaryVi:`Tìm hiểu cách Unicode và UCS biểu diễn ký tự một cách thống nhất, đồng thời nắm các kiến thức cơ bản về logic vị từ và suy luận diễn dịch.`,content:[{type:`heading`,ja:`UnicodeとUCS`,vi:`Unicode và UCS`},{type:`paragraph`,ja:`Unicodeは、世界中のさまざまな文字や記号を統一的に扱うための文字コード規格である。文字ごとに一意のコードポイントを割り当てることで、異なる言語の文字を共通の体系で扱えるようにする。`,vi:`Unicode là tiêu chuẩn mã ký tự nhằm xử lý thống nhất các ký tự và ký hiệu của nhiều ngôn ngữ trên thế giới. Mỗi ký tự được gán một code point duy nhất, nhờ đó các ngôn ngữ khác nhau có thể được xử lý trong cùng một hệ thống.`},{type:`point`,ja:`Unicodeのコードポイントを実際のバイト列として表現する方式にはUTF-8やUTF-16などがある。UnicodeそのものとUTF-8を同一のものとして覚えないことが重要である。`,vi:`Các cách biểu diễn code point Unicode thành chuỗi byte thực tế gồm UTF-8, UTF-16... Cần nhớ Unicode và UTF-8 không phải là cùng một khái niệm.`},{type:`paragraph`,ja:`UCSはUniversal Character Setの略で、ISO/IEC 10646で規定される汎用文字集合である。UnicodeとISO/IEC 10646は文字の符号位置について整合が図られており、世界中の文字を共通の体系で扱うための基盤となっている。`,vi:`UCS là viết tắt của Universal Character Set, tập ký tự phổ quát được quy định bởi ISO/IEC 10646. Unicode và ISO/IEC 10646 được đồng bộ về các vị trí mã ký tự, tạo nền tảng để xử lý ký tự trên toàn thế giới trong một hệ thống chung.`},{type:`warning`,ja:`UCSは文字集合、UTF-8やUTF-16はUnicodeの符号位置をバイト列へ符号化する代表的な方式である。これらの役割を混同しない。`,vi:`UCS là tập ký tự, còn UTF-8 và UTF-16 là các cách tiêu biểu để mã hóa vị trí mã Unicode thành chuỗi byte. Không nên nhầm vai trò của các khái niệm này.`},{type:`heading`,ja:`述語論理`,vi:`Logic vị từ`},{type:`paragraph`,ja:`述語論理は、対象の性質や対象間の関係を、述語、変数、量化記号などを用いて表現する論理体系である。命題論理よりも詳細な関係を記述できる。`,vi:`Logic vị từ là hệ thống logic biểu diễn thuộc tính của đối tượng và quan hệ giữa các đối tượng bằng vị từ, biến, lượng từ... Nó có thể mô tả các quan hệ chi tiết hơn logic mệnh đề.`},{type:`example`,ja:`例えば「すべての人は有限の寿命をもつ」という内容は、「すべて」を表す全称量化を用いて表現できる。述語論理では、このように対象とその性質を分けて考える。`,vi:`Ví dụ, nội dung “mọi người đều có tuổi thọ hữu hạn” có thể được biểu diễn bằng lượng từ toàn thể mang nghĩa “mọi”. Trong logic vị từ, đối tượng và thuộc tính của đối tượng được tách ra để biểu diễn.`},{type:`heading`,ja:`演繹推論`,vi:`Suy luận diễn dịch`},{type:`paragraph`,ja:`演繹推論は、一般的な規則や前提から、個別の事例について論理的な結論を導く推論方法である。前提が正しく、推論の形式も妥当であれば、導かれる結論も正しい。`,vi:`Suy luận diễn dịch là phương pháp đi từ quy tắc hoặc tiền đề tổng quát đến kết luận logic cho một trường hợp cụ thể. Nếu các tiền đề đúng và hình thức suy luận hợp lệ thì kết luận thu được cũng đúng.`},{type:`example`,ja:`「すべての人間は死ぬ」「Aは人間である」という前提から、「Aは死ぬ」と結論するのが演繹推論の例である。`,vi:`Ví dụ của suy luận diễn dịch: từ hai tiền đề “mọi người đều chết” và “A là người”, có thể suy ra kết luận “A sẽ chết”.`},{type:`point`,ja:`FEでは、演繹推論が「一般的な前提から個別の結論へ進む」推論であることを押さえる。個別の事例から一般的な規則を導く帰納推論とは方向が異なる。`,vi:`Trong FE, cần nhớ 演繹推論 đi từ tiền đề tổng quát đến kết luận cụ thể. Hướng suy luận này khác với 帰納推論, vốn đi từ các trường hợp cụ thể để hình thành kết luận tổng quát.`}],terms:[{term:`Unicode`,reading:`ユニコード`,english:`Unicode`,vi:`Unicode`,definitionJa:`世界中の文字や記号を統一的に扱うために、それぞれの文字へコードポイントを割り当てる文字コード規格。`,definitionVi:`Tiêu chuẩn mã ký tự gán code point cho các ký tự và ký hiệu nhằm xử lý thống nhất các hệ chữ trên thế giới.`},{term:`UCS`,reading:`ユーシーエス`,english:`Universal Character Set`,vi:`tập ký tự phổ quát`,definitionJa:`ISO/IEC 10646で規定される、世界中の文字を統一的に扱うための汎用的な文字集合。`,definitionVi:`Tập ký tự phổ quát được quy định trong ISO/IEC 10646 nhằm xử lý thống nhất các ký tự trên thế giới.`},{term:`述語論理`,reading:`じゅつごろんり`,english:`Predicate Logic`,vi:`logic vị từ`,definitionJa:`述語、変数、量化記号などを用いて、対象の性質や対象間の関係を表現する論理体系。`,definitionVi:`Hệ thống logic sử dụng vị từ, biến và lượng từ để biểu diễn thuộc tính của đối tượng cũng như quan hệ giữa các đối tượng.`},{term:`演繹推論`,reading:`えんえきすいろん`,english:`Deductive Reasoning`,vi:`suy luận diễn dịch`,definitionJa:`一般的な規則や前提を個別の事例に適用し、論理的に結論を導く推論方法。`,definitionVi:`Phương pháp suy luận áp dụng quy tắc hoặc tiền đề tổng quát cho trường hợp cụ thể để rút ra kết luận logic.`}],tags:[`information-theory`,`character-code`,`unicode`,`logic`,`reasoning`]},{id:`formal-language-and-automata`,order:4,titleJa:`帰納推論・形式言語とオートマトン`,titleVi:`Suy luận quy nạp, ngôn ngữ hình thức và automaton`,importance:`high`,summaryJa:`帰納推論の考え方と、形式言語、逆ポーランド表記法、有限オートマトンの基本を理解し、論理的推論と形式的な情報表現の違いを整理する。`,summaryVi:`Tìm hiểu suy luận quy nạp cùng các kiến thức cơ bản về ngôn ngữ hình thức, ký pháp Ba Lan ngược và automaton hữu hạn; đồng thời phân biệt suy luận logic với cách biểu diễn và xử lý thông tin theo quy tắc hình thức.`,content:[{type:`heading`,ja:`帰納推論`,vi:`Suy luận quy nạp`},{type:`paragraph`,ja:`帰納推論は、複数の具体的な観察や事例から共通する特徴を見つけ、一般的な規則や結論を導く推論方法である。個別の事例から一般化するため、得られた結論が常に真であるとは限らない。`,vi:`帰納推論 là phương pháp suy luận tìm đặc điểm chung từ nhiều quan sát hoặc trường hợp cụ thể rồi khái quát thành quy luật hay kết luận chung. Vì đi từ các trường hợp riêng lẻ đến khái quát nên kết luận không nhất thiết luôn đúng tuyệt đối.`},{type:`warning`,ja:`演繹推論は一般的な前提から個別の結論を導くのに対し、帰納推論は個別の事例から一般的な結論を導く。FEではこの推論方向の違いを区別する。`,vi:`演繹推論 đi từ tiền đề tổng quát đến kết luận cụ thể, còn 帰納推論 đi từ nhiều trường hợp cụ thể đến kết luận tổng quát. Trong FE cần phân biệt rõ hướng suy luận này.`},{type:`heading`,ja:`形式言語`,vi:`Ngôn ngữ hình thức`},{type:`paragraph`,ja:`形式言語は、使用できる記号と、それらをどのように並べれば正しい表現になるかを形式的な規則によって定めた言語である。プログラミング言語や数式など、コンピュータが曖昧さなく処理する必要がある場面で重要となる。`,vi:`形式言語 là ngôn ngữ trong đó tập ký hiệu được phép sử dụng và cách kết hợp chúng thành biểu thức hợp lệ được xác định bằng các quy tắc hình thức. Khái niệm này quan trọng trong ngôn ngữ lập trình, biểu thức toán học và những trường hợp máy tính cần xử lý thông tin không mơ hồ.`},{type:`point`,ja:`自然言語には文脈による曖昧さがあるが、形式言語では構文規則を明確に定義することで、機械的な解析や処理を可能にする。`,vi:`Ngôn ngữ tự nhiên có thể mơ hồ tùy ngữ cảnh, trong khi ngôn ngữ hình thức định nghĩa rõ quy tắc cú pháp để máy tính có thể phân tích và xử lý một cách cơ học.`},{type:`heading`,ja:`逆ポーランド表記法`,vi:`Ký pháp Ba Lan ngược`},{type:`paragraph`,ja:`逆ポーランド表記法は、演算子を被演算子の後ろに置く式の表記法である。演算の優先順位を括弧に頼らず表現でき、スタックを利用して効率よく計算できる。`,vi:`逆ポーランド表記法 là cách viết biểu thức đặt toán tử sau các toán hạng. Nó có thể biểu diễn thứ tự phép tính mà không cần dựa vào dấu ngoặc và rất phù hợp để tính toán bằng stack.`},{type:`example`,ja:`例えば、中置表記の「3＋4×5」は、逆ポーランド表記法では「3 4 5 × ＋」となる。スタックでは4と5を取り出して乗算し、その結果と3を加算する。`,vi:`Ví dụ, biểu thức trung tố “3 + 4 × 5” được viết theo ký pháp Ba Lan ngược là “3 4 5 × +”. Khi dùng stack, lấy 4 và 5 ra để nhân trước, sau đó cộng kết quả với 3.`},{type:`point`,ja:`FEでは、逆ポーランド表記法とスタックの組合せが重要である。左から読み、値をスタックへ積み、演算子が現れたら必要な値を取り出して計算する。`,vi:`Trong FE, mối quan hệ giữa ký pháp Ba Lan ngược và stack là điểm quan trọng. Đọc từ trái sang phải, đưa giá trị vào stack; khi gặp toán tử thì lấy các toán hạng cần thiết ra để tính.`},{type:`heading`,ja:`有限オートマトン`,vi:`Automaton hữu hạn`},{type:`paragraph`,ja:`有限オートマトンは、有限個の状態と状態遷移規則をもち、入力された記号列に応じて状態を変化させる計算モデルである。入力を順番に処理し、最終的に受理状態へ到達したかどうかによって、その文字列を受理するかを判定できる。`,vi:`有限オートマトン là mô hình tính toán gồm một số hữu hạn trạng thái và các quy tắc chuyển trạng thái. Mô hình thay đổi trạng thái theo từng ký hiệu đầu vào và có thể quyết định chấp nhận chuỗi dựa trên trạng thái cuối cùng.`},{type:`example`,ja:`例えば、「0が偶数個含まれる文字列」を受理する場合、「0が偶数個の状態」と「0が奇数個の状態」の二つを用意し、0を読むたびに二つの状態を切り替えることで判定できる。`,vi:`Ví dụ, để chấp nhận các chuỗi chứa số lượng ký tự 0 là số chẵn, có thể dùng hai trạng thái: “số lượng 0 chẵn” và “số lượng 0 lẻ”, rồi chuyển qua lại giữa hai trạng thái mỗi khi đọc một ký tự 0.`},{type:`point`,ja:`有限オートマトンでは「状態」「入力」「状態遷移」「初期状態」「受理状態」の関係を理解することが重要である。`,vi:`Với automaton hữu hạn, cần hiểu quan hệ giữa trạng thái (状態), đầu vào (入力), chuyển trạng thái (状態遷移), trạng thái ban đầu (初期状態) và trạng thái chấp nhận (受理状態).`}],terms:[{term:`帰納推論`,reading:`きのうすいろん`,english:`Inductive Reasoning`,vi:`suy luận quy nạp`,definitionJa:`複数の具体的な観察や事例から共通点を見いだし、一般的な規則や結論を導く推論方法。`,definitionVi:`Phương pháp suy luận tìm điểm chung từ nhiều quan sát hoặc trường hợp cụ thể để hình thành quy luật hay kết luận tổng quát.`},{term:`形式言語`,reading:`けいしきげんご`,english:`Formal Language`,vi:`ngôn ngữ hình thức`,definitionJa:`使用する記号と、その記号列を構成するための規則が形式的かつ明確に定義された言語。`,definitionVi:`Ngôn ngữ có tập ký hiệu và các quy tắc cấu thành chuỗi ký hiệu được định nghĩa rõ ràng theo hình thức.`},{term:`逆ポーランド表記法`,reading:`ぎゃくポーランドひょうきほう`,english:`Reverse Polish Notation`,vi:`ký pháp Ba Lan ngược`,definitionJa:`演算子を被演算子の後ろに配置する式の表記法。括弧を使わずに演算順序を一意に表現できる。`,definitionVi:`Cách biểu diễn biểu thức đặt toán tử sau toán hạng, cho phép xác định duy nhất thứ tự tính toán mà không cần dấu ngoặc.`},{term:`有限オートマトン`,reading:`ゆうげんオートマトン`,english:`Finite Automaton`,vi:`automaton hữu hạn`,definitionJa:`有限個の状態と状態遷移規則をもち、入力記号に応じて状態を変化させ、文字列を受理するかどうかを判定する計算モデル。`,definitionVi:`Mô hình tính toán có hữu hạn trạng thái và quy tắc chuyển trạng thái, thay đổi trạng thái theo ký hiệu đầu vào để quyết định có chấp nhận chuỗi hay không.`}],tags:[`information-theory`,`reasoning`,`formal-language`,`reverse-polish-notation`,`automata`]},{id:`time-complexity-and-expert-systems`,order:5,titleJa:`時間計算量とエキスパートシステム`,titleVi:`Độ phức tạp thời gian và hệ chuyên gia`,importance:`high`,summaryJa:`アルゴリズムの効率を評価する時間計算量と、専門知識を利用して推論を行うエキスパートシステムの基本構成を理解する。特に、知識ベースと推論エンジンの役割を区別する。`,summaryVi:`Tìm hiểu độ phức tạp thời gian dùng để đánh giá hiệu quả của thuật toán và cấu trúc cơ bản của hệ chuyên gia sử dụng tri thức chuyên môn để suy luận. Đặc biệt cần phân biệt vai trò của cơ sở tri thức và bộ máy suy luận.`,content:[{type:`heading`,ja:`時間計算量`,vi:`Độ phức tạp thời gian`},{type:`paragraph`,ja:`時間計算量は、入力データの大きさに応じてアルゴリズムの処理量がどのように増えるかを表す尺度である。実際の実行秒数ではなく、入力サイズをnとしたときの処理量の増え方に着目し、O記法を用いて表すことが多い。`,vi:`時間計算量 là thước đo cho biết khối lượng xử lý của thuật toán tăng như thế nào khi kích thước dữ liệu đầu vào tăng. Thay vì biểu diễn số giây chạy thực tế, nó tập trung vào tốc độ tăng của lượng xử lý theo kích thước đầu vào n và thường được biểu diễn bằng ký hiệu Big O.`},{type:`example`,ja:`例えば、n個のデータを先頭から順番に調べる線形探索では、最悪の場合はn個すべてを調べるため、時間計算量はO(n)となる。`,vi:`Ví dụ, với tìm kiếm tuyến tính trên n phần tử, trong trường hợp xấu nhất phải kiểm tra toàn bộ n phần tử nên độ phức tạp thời gian là O(n).`},{type:`point`,ja:`FEでは、O(1)、O(log n)、O(n)、O(n log n)、O(n²)などの代表的な時間計算量について、入力サイズが大きくなったときの増加傾向を比較できるようにすることが重要である。`,vi:`Trong FE, cần có khả năng so sánh xu hướng tăng khi kích thước đầu vào lớn dần đối với các độ phức tạp tiêu biểu như O(1), O(log n), O(n), O(n log n) và O(n²).`},{type:`warning`,ja:`時間計算量は、特定のコンピュータで何秒かかるかを直接表すものではない。アルゴリズムの処理量が入力サイズに対してどのように増えるかを評価する考え方である。`,vi:`Độ phức tạp thời gian không trực tiếp cho biết thuật toán chạy bao nhiêu giây trên một máy tính cụ thể. Đây là cách đánh giá lượng xử lý tăng như thế nào theo kích thước đầu vào.`},{type:`heading`,ja:`エキスパートシステム`,vi:`Hệ chuyên gia`},{type:`paragraph`,ja:`エキスパートシステムは、特定分野の専門家がもつ知識や経験をコンピュータ上で利用し、問題解決や判断を支援するシステムである。代表的な構成要素として、専門知識を保持する知識ベースと、その知識を利用して結論を導く推論エンジンがある。`,vi:`エキスパートシステム là hệ thống sử dụng tri thức và kinh nghiệm của chuyên gia trong một lĩnh vực cụ thể trên máy tính để hỗ trợ giải quyết vấn đề hoặc đưa ra quyết định. Hai thành phần tiêu biểu là cơ sở tri thức lưu giữ kiến thức chuyên môn và bộ máy suy luận sử dụng kiến thức đó để đưa ra kết luận.`},{type:`heading`,ja:`知識ベースと推論エンジン`,vi:`Cơ sở tri thức và bộ máy suy luận`},{type:`paragraph`,ja:`知識ベースは、対象分野に関する事実や規則などの知識を蓄積する部分である。推論エンジンは、その知識を参照し、与えられた事実や条件に規則を適用して、新しい結論を導き出す部分である。`,vi:`知識ベース là phần lưu trữ các tri thức như sự kiện và quy tắc liên quan đến lĩnh vực cần xử lý. 推論エンジン là phần tham chiếu các tri thức đó, áp dụng quy tắc vào dữ kiện hoặc điều kiện được cung cấp để suy ra kết luận mới.`},{type:`example`,ja:`例えば診断支援システムでは、「ある症状と検査結果がそろった場合は特定の病気の可能性がある」といった規則を知識ベースに保持し、入力された症状や検査結果に対して推論エンジンが規則を適用して候補を導く。`,vi:`Ví dụ trong hệ thống hỗ trợ chẩn đoán, cơ sở tri thức có thể lưu quy tắc như “nếu có một nhóm triệu chứng và kết quả xét nghiệm nhất định thì có khả năng mắc bệnh X”. Bộ máy suy luận áp dụng các quy tắc đó vào dữ liệu được nhập để đưa ra các khả năng phù hợp.`},{type:`point`,ja:`FEでは、「知識ベース＝知識を蓄積する部分」「推論エンジン＝知識を利用して推論する部分」と役割を分けて覚える。`,vi:`Trong FE, nên nhớ theo cặp: “知識ベース = nơi lưu tri thức”, còn “推論エンジン = bộ phận sử dụng tri thức để suy luận”.`}],terms:[{term:`時間計算量`,reading:`じかんけいさんりょう`,english:`Time Complexity`,vi:`độ phức tạp thời gian`,definitionJa:`入力サイズの増加に応じて、アルゴリズムの処理量がどのように増えるかを表す尺度。`,definitionVi:`Thước đo biểu diễn lượng xử lý của thuật toán tăng như thế nào khi kích thước dữ liệu đầu vào tăng.`},{term:`エキスパートシステム`,reading:`エキスパートシステム`,english:`Expert System`,vi:`hệ chuyên gia`,definitionJa:`特定分野の専門知識を利用し、推論によって問題解決や意思決定を支援するシステム。`,definitionVi:`Hệ thống sử dụng tri thức chuyên môn của một lĩnh vực và thực hiện suy luận để hỗ trợ giải quyết vấn đề hoặc ra quyết định.`},{term:`知識ベース`,reading:`ちしきベース`,english:`Knowledge Base`,vi:`cơ sở tri thức`,definitionJa:`エキスパートシステムなどで利用する事実、規則、専門知識を蓄積した部分。`,definitionVi:`Bộ phận lưu trữ các sự kiện, quy tắc và tri thức chuyên môn được sử dụng trong hệ chuyên gia.`},{term:`推論エンジン`,reading:`すいろんエンジン`,english:`Inference Engine`,vi:`bộ máy suy luận`,definitionJa:`知識ベースに格納された知識や規則を適用し、与えられた情報から結論を導く処理機構。`,definitionVi:`Cơ chế xử lý áp dụng tri thức và quy tắc trong cơ sở tri thức để suy ra kết luận từ thông tin được cung cấp.`}],tags:[`information-theory`,`time-complexity`,`artificial-intelligence`,`expert-system`,`knowledge-base`]},{id:`machine-learning-fundamentals`,order:6,titleJa:`機械学習の基礎と学習方式`,titleVi:`Cơ bản về Machine Learning và các phương pháp học`,importance:`high`,summaryJa:`機械学習の基本的な考え方と汎化の意味を理解し、教師あり学習と教師なし学習の目的・利用するデータ・代表的なタスクの違いを整理する。`,summaryVi:`Tìm hiểu tư tưởng cơ bản của Machine Learning và ý nghĩa của khả năng khái quát hóa, đồng thời phân biệt học có giám sát và học không giám sát dựa trên mục đích, dữ liệu sử dụng và các bài toán tiêu biểu.`,content:[{type:`heading`,ja:`機械学習と汎化`,vi:`Machine Learning và khái quát hóa`},{type:`paragraph`,ja:`機械学習は、コンピュータがデータから規則性やパターンを学習し、その結果を予測や分類などに利用する技術である。あらかじめすべての判断規則を人間がプログラムするのではなく、データをもとにモデルを構築する点が特徴である。`,vi:`機械学習 (Machine Learning) là kỹ thuật cho phép máy tính học các quy luật và mẫu từ dữ liệu rồi sử dụng kết quả đó cho dự đoán, phân loại và các nhiệm vụ khác. Điểm đặc trưng là mô hình được xây dựng từ dữ liệu thay vì con người phải lập trình trước toàn bộ quy tắc phán đoán.`},{type:`paragraph`,ja:`汎化とは、学習に使用したデータだけでなく、学習時には見ていない新しいデータに対しても適切な予測や判断ができることである。機械学習では、学習データを単に記憶することではなく、データに共通する規則性を捉えて汎化できるモデルを作ることが重要である。`,vi:`汎化 (khái quát hóa) là khả năng mô hình đưa ra dự đoán hoặc phán đoán phù hợp không chỉ với dữ liệu đã dùng để học mà cả với dữ liệu mới chưa từng thấy trong quá trình huấn luyện. Trong Machine Learning, mục tiêu không phải đơn thuần ghi nhớ dữ liệu học mà là nắm được quy luật chung để có thể áp dụng cho dữ liệu mới.`},{type:`point`,ja:`FEでは、「学習データに対してよい結果を出すこと」と「未知のデータに対してよい結果を出すこと」を区別する。後者に関係する重要な概念が汎化である。`,vi:`Trong FE, cần phân biệt “cho kết quả tốt với dữ liệu đã học” và “cho kết quả tốt với dữ liệu chưa biết”. Khái niệm quan trọng liên quan đến trường hợp thứ hai chính là 汎化.`},{type:`heading`,ja:`教師あり学習`,vi:`Học có giám sát`},{type:`paragraph`,ja:`教師あり学習は、入力データと、それに対応する正解となるラベルや目的値の組を使ってモデルを学習させる方法である。代表的なタスクには分類と回帰がある。`,vi:`教師あり学習 (học có giám sát) là phương pháp huấn luyện mô hình bằng các cặp gồm dữ liệu đầu vào và nhãn hoặc giá trị mục tiêu tương ứng được xem là đáp án đúng. Hai dạng bài toán tiêu biểu là phân loại và hồi quy.`},{type:`example`,ja:`例えば、過去の住宅データから価格を予測する処理は回帰、メールを「スパム」「非スパム」に分ける処理は分類の例である。どちらも学習時には正解となる値やラベルを利用する。`,vi:`Ví dụ, dự đoán giá nhà từ dữ liệu nhà ở trong quá khứ là bài toán hồi quy; chia email thành “spam” và “không spam” là bài toán phân loại. Trong cả hai trường hợp, quá trình học đều sử dụng giá trị hoặc nhãn đúng.`},{type:`heading`,ja:`教師なし学習`,vi:`Học không giám sát`},{type:`paragraph`,ja:`教師なし学習は、正解ラベルが付与されていないデータから、データに潜む構造や特徴を見つける学習方法である。代表的な処理として、似たデータをグループ化するクラスタリングや、多数の特徴をより少ない特徴へまとめる次元削減がある。`,vi:`教師なし学習 (học không giám sát) là phương pháp tìm cấu trúc hoặc đặc trưng tiềm ẩn từ dữ liệu không có nhãn đáp án. Các xử lý tiêu biểu gồm clustering để nhóm những dữ liệu tương tự và giảm chiều để biểu diễn nhiều đặc trưng bằng số lượng đặc trưng ít hơn.`},{type:`warning`,ja:`教師あり学習と教師なし学習を区別するときは、単に人間が操作するかどうかではなく、学習時に正解となるラベルや目的値が与えられているかに注目する。`,vi:`Khi phân biệt học có giám sát và học không giám sát, không nên hiểu theo nghĩa có hay không có con người trực tiếp điều khiển. Điểm cần xem là trong quá trình học có dữ liệu nhãn hoặc giá trị mục tiêu đóng vai trò đáp án đúng hay không.`},{type:`point`,ja:`FEでは、教師あり学習は「正解あり → 分類・回帰」、教師なし学習は「正解ラベルなし → クラスタリング・次元削減」と整理すると区別しやすい。`,vi:`Trong FE có thể ghi nhớ: 教師あり学習 = “có đáp án → phân loại, hồi quy”; 教師なし学習 = “không có nhãn đáp án → clustering, giảm chiều”.`}],terms:[{term:`汎化`,reading:`はんか`,english:`Generalization`,vi:`khái quát hóa`,definitionJa:`学習したデータだけでなく、未知のデータに対しても適切な予測や判断を行えるようにすること。`,definitionVi:`Khả năng áp dụng những quy luật đã học để đưa ra dự đoán hoặc phán đoán phù hợp đối với cả dữ liệu mới chưa xuất hiện trong quá trình học.`},{term:`機械学習`,reading:`きかいがくしゅう`,english:`Machine Learning`,vi:`học máy`,definitionJa:`コンピュータがデータから規則性やパターンを学習し、予測、分類、判断などに利用する技術。`,definitionVi:`Kỹ thuật cho phép máy tính học quy luật hoặc mẫu từ dữ liệu và sử dụng chúng cho dự đoán, phân loại hoặc phán đoán.`},{term:`教師あり学習`,reading:`きょうしありがくしゅう`,english:`Supervised Learning`,vi:`học có giám sát`,definitionJa:`入力データと正解となるラベルや目的値の組を用いて、入力と出力の関係を学習する機械学習の方法。`,definitionVi:`Phương pháp Machine Learning sử dụng các cặp dữ liệu đầu vào và nhãn hoặc giá trị mục tiêu đúng để học mối quan hệ giữa đầu vào và đầu ra.`},{term:`教師なし学習`,reading:`きょうしなしがくしゅう`,english:`Unsupervised Learning`,vi:`học không giám sát`,definitionJa:`正解ラベルが付与されていないデータから、データの構造、特徴、グループなどを見つける機械学習の方法。`,definitionVi:`Phương pháp Machine Learning tìm cấu trúc, đặc trưng hoặc các nhóm trong dữ liệu không được gắn nhãn đáp án.`}],tags:[`information-theory`,`machine-learning`,`generalization`,`supervised-learning`,`unsupervised-learning`]},{id:`machine-learning-methods`,order:7,titleJa:`機械学習の代表的な手法`,titleVi:`Các phương pháp Machine Learning tiêu biểu`,importance:`high`,summaryJa:`強化学習の基本的な考え方と、教師あり学習で用いられる線形回帰、ロジスティック回帰、決定木の特徴を理解し、それぞれがどのような問題に適しているかを整理する。`,summaryVi:`Tìm hiểu nguyên lý cơ bản của học tăng cường và đặc điểm của hồi quy tuyến tính, hồi quy logistic, cây quyết định; đồng thời phân biệt loại bài toán phù hợp với từng phương pháp.`,content:[{type:`heading`,ja:`強化学習`,vi:`Học tăng cường`},{type:`paragraph`,ja:`強化学習は、エージェントが環境の中で行動し、その結果として得られる報酬を手掛かりに、よりよい行動の選び方を学習する方法である。教師あり学習のように各入力に対する正解ラベルが直接与えられるのではなく、行動の結果として得られる報酬を利用して学習を進める。`,vi:`強化学習 (học tăng cường) là phương pháp trong đó agent thực hiện hành động trong môi trường và học cách lựa chọn hành động tốt hơn dựa trên phần thưởng nhận được. Khác với học có giám sát, đáp án đúng cho từng đầu vào không được cung cấp trực tiếp; quá trình học dựa trên phần thưởng thu được từ kết quả của hành động.`},{type:`point`,ja:`強化学習では、エージェント、環境、行動、報酬という関係を押さえる。また、目先の報酬だけを選ぶのではなく、未知の行動を試す探索と、既に有効だと分かっている行動を選ぶ活用のバランスも重要である。`,vi:`Với học tăng cường, cần nắm quan hệ giữa agent (エージェント), môi trường (環境), hành động (行動) và phần thưởng (報酬). Ngoài ra còn phải cân bằng giữa exploration (探索) — thử hành động chưa biết — và exploitation (活用) — sử dụng hành động đã biết là hiệu quả.`},{type:`heading`,ja:`線形回帰`,vi:`Hồi quy tuyến tính`},{type:`paragraph`,ja:`線形回帰は、説明変数と目的変数の関係を直線または線形な式で表し、連続的な数値を予測するための手法である。データに適合する直線などを求め、新しい入力に対する値の予測に利用する。`,vi:`線形回帰 (hồi quy tuyến tính) là phương pháp biểu diễn quan hệ giữa biến giải thích và biến mục tiêu bằng đường thẳng hoặc biểu thức tuyến tính, chủ yếu dùng để dự đoán giá trị số liên tục. Mô hình tìm quan hệ tuyến tính phù hợp với dữ liệu rồi dùng quan hệ đó để dự đoán giá trị mới.`},{type:`example`,ja:`例えば、勉強時間xと試験得点yの関係を y=ax+b のような式で近似し、勉強時間から得点を予測することが線形回帰の例である。`,vi:`Ví dụ, có thể xấp xỉ quan hệ giữa thời gian học x và điểm thi y bằng biểu thức như y = ax + b, rồi dự đoán điểm thi từ thời gian học.`},{type:`heading`,ja:`ロジスティック回帰`,vi:`Hồi quy logistic`},{type:`paragraph`,ja:`ロジスティック回帰は、入力された特徴量から、あるクラスに属する確率を推定するために用いられる手法である。代表的には二値分類に利用され、シグモイド関数によって出力を0から1の範囲に変換し、その値を確率として扱う。`,vi:`ロジスティック回帰 (hồi quy logistic) là phương pháp dùng các đặc trưng đầu vào để ước lượng xác suất một dữ liệu thuộc về một lớp. Nó thường được dùng cho phân loại nhị phân và sử dụng hàm sigmoid để đưa đầu ra về khoảng từ 0 đến 1, từ đó có thể diễn giải như xác suất.`},{type:`warning`,ja:`名前に「回帰」とあるが、ロジスティック回帰は代表的には分類問題に利用される。線形回帰は連続値の予測、ロジスティック回帰はクラスに属する確率の推定や分類、と区別するとよい。`,vi:`Mặc dù tên có chữ “hồi quy”, logistic regression thường được sử dụng cho bài toán phân loại. Có thể phân biệt: hồi quy tuyến tính chủ yếu dự đoán giá trị liên tục, còn hồi quy logistic ước lượng xác suất thuộc lớp và dùng cho phân loại.`},{type:`heading`,ja:`決定木`,vi:`Cây quyết định`},{type:`paragraph`,ja:`決定木は、データの特徴に対する条件を順番に適用してデータを分岐させ、予測や分類を行うモデルである。木の根から条件に従って枝をたどり、最終的に到達した葉で判断結果を得る。`,vi:`決定木 (cây quyết định) là mô hình lần lượt áp dụng các điều kiện lên đặc trưng của dữ liệu để phân nhánh và thực hiện dự đoán hoặc phân loại. Bắt đầu từ nút gốc, dữ liệu đi theo các nhánh dựa trên điều kiện và kết quả cuối cùng được xác định tại nút lá.`},{type:`example`,ja:`例えば、「年齢が30歳以上か」「購入履歴があるか」のような条件で顧客を順番に分岐させ、最終的に商品を購入する可能性を分類するといった使い方ができる。`,vi:`Ví dụ, có thể lần lượt phân nhánh khách hàng theo các điều kiện như “từ 30 tuổi trở lên hay không” và “đã từng mua hàng hay chưa”, sau đó phân loại khả năng khách hàng sẽ mua sản phẩm.`},{type:`point`,ja:`FEでは、線形回帰＝連続値の予測、ロジスティック回帰＝主に分類、決定木＝条件による分岐、強化学習＝報酬を基に行動を学習、と特徴を対応付けて覚えると整理しやすい。`,vi:`Trong FE, có thể ghi nhớ theo cặp đặc trưng: 線形回帰 = dự đoán giá trị liên tục; ロジスティック回帰 = chủ yếu phân loại; 決定木 = phân nhánh theo điều kiện; 強化学習 = học hành động dựa trên phần thưởng.`}],terms:[{term:`強化学習`,reading:`きょうかがくしゅう`,english:`Reinforcement Learning`,vi:`học tăng cường`,definitionJa:`エージェントが環境内で行動し、その結果として得られる報酬を基に、よりよい行動の選択方法を学習する手法。`,definitionVi:`Phương pháp trong đó agent hành động trong môi trường và học cách lựa chọn hành động tốt hơn dựa trên phần thưởng nhận được.`},{term:`線形回帰`,reading:`せんけいかいき`,english:`Linear Regression`,vi:`hồi quy tuyến tính`,definitionJa:`説明変数と目的変数の関係を線形な式でモデル化し、主に連続的な数値を予測する手法。`,definitionVi:`Phương pháp mô hình hóa quan hệ giữa biến giải thích và biến mục tiêu bằng biểu thức tuyến tính, chủ yếu để dự đoán giá trị liên tục.`},{term:`ロジスティック回帰`,reading:`ロジスティックかいき`,english:`Logistic Regression`,vi:`hồi quy logistic`,definitionJa:`特徴量からクラスに属する確率を推定し、代表的には二値分類に利用される統計的・機械学習的手法。`,definitionVi:`Phương pháp thống kê và Machine Learning ước lượng xác suất dữ liệu thuộc một lớp, thường được sử dụng cho phân loại nhị phân.`},{term:`決定木`,reading:`けっていぎ`,english:`Decision Tree`,vi:`cây quyết định`,definitionJa:`特徴に対する条件によってデータを木構造で順次分岐させ、分類や予測を行うモデル。`,definitionVi:`Mô hình phân nhánh dữ liệu theo cấu trúc cây dựa trên các điều kiện của đặc trưng để thực hiện phân loại hoặc dự đoán.`}],tags:[`information-theory`,`machine-learning`,`reinforcement-learning`,`regression`,`classification`,`decision-tree`]},{id:`machine-learning-models-and-training-data`,order:8,titleJa:`機械学習モデルと学習データ`,titleVi:`Các mô hình Machine Learning và dữ liệu huấn luyện`,importance:`high`,summaryJa:`ランダムフォレスト、サポートベクターマシン、主成分分析の基本的な仕組みと、機械学習モデルを構築するために用いる学習データの役割を理解する。`,summaryVi:`Tìm hiểu cơ chế cơ bản của Random Forest, Support Vector Machine, Principal Component Analysis và vai trò của dữ liệu huấn luyện trong quá trình xây dựng mô hình Machine Learning.`,content:[{type:`heading`,ja:`ランダムフォレスト`,vi:`Random Forest`},{type:`paragraph`,ja:`ランダムフォレストは、複数の決定木を組み合わせて予測を行うアンサンブル学習の手法である。学習データや使用する特徴量にランダム性を持たせて複数の決定木を作り、それぞれの予測結果を統合して最終的な予測を得る。`,vi:`ランダムフォレスト (Random Forest) là phương pháp ensemble kết hợp nhiều cây quyết định để đưa ra dự đoán. Nhiều cây được xây dựng bằng cách đưa tính ngẫu nhiên vào dữ liệu huấn luyện và các đặc trưng được sử dụng, sau đó kết hợp kết quả của các cây để tạo ra dự đoán cuối cùng.`},{type:`point`,ja:`分類では複数の決定木による多数決、回帰では予測値の平均などによって結果を統合する。単一の決定木だけを使う場合に比べ、過学習を抑えて汎化性能を高める効果が期待できる。`,vi:`Trong bài toán phân loại, kết quả thường được tổng hợp bằng bỏ phiếu đa số giữa các cây; trong hồi quy có thể dùng trung bình các giá trị dự đoán. So với chỉ dùng một cây quyết định, Random Forest thường giúp giảm overfitting và cải thiện khả năng khái quát hóa.`},{type:`heading`,ja:`サポートベクターマシン`,vi:`Support Vector Machine`},{type:`paragraph`,ja:`サポートベクターマシンは、代表的には分類に利用される機械学習手法である。異なるクラスのデータを分離する境界を求めるとき、境界に近いデータ点であるサポートベクターを基準として、クラス間のマージンができるだけ大きくなるような境界を求める。`,vi:`サポートベクターマシン (SVM) là phương pháp Machine Learning thường được sử dụng cho phân loại. Khi tìm ranh giới phân chia các lớp, SVM dựa vào những điểm dữ liệu gần ranh giới gọi là support vector và tìm ranh giới sao cho margin giữa các lớp lớn nhất có thể.`},{type:`point`,ja:`FEでは、「サポートベクター」と「マージン」を関連付けて覚える。サポートベクターは分類境界の決定に強く影響するデータ点であり、SVMはマージンを大きくする境界を求めることが基本的な考え方である。`,vi:`Trong FE, nên ghi nhớ SVM cùng hai từ khóa “support vector” và “margin”. Support vector là các điểm dữ liệu có ảnh hưởng lớn đến việc xác định ranh giới phân loại, còn ý tưởng cơ bản của SVM là tìm ranh giới làm margin lớn.`},{type:`heading`,ja:`主成分分析`,vi:`Phân tích thành phần chính`},{type:`paragraph`,ja:`主成分分析は、多数の変数をもつデータから、元の情報をできるだけ保持しながら、より少数の新しい変数である主成分を作る次元削減の手法である。データの分散が大きい方向を主成分として求め、重要な情報を少ない次元にまとめる。`,vi:`主成分分析 (PCA) là phương pháp giảm chiều, tạo ra một số ít biến mới gọi là thành phần chính từ dữ liệu có nhiều biến trong khi cố gắng giữ lại càng nhiều thông tin của dữ liệu gốc càng tốt. PCA tìm các hướng có phương sai lớn và dùng chúng để biểu diễn thông tin quan trọng trong số chiều ít hơn.`},{type:`point`,ja:`主成分分析は、教師なし学習で利用される代表的な次元削減手法の一つである。変数を単純に削除するのではなく、元の変数から新しい主成分を作る点を押さえる。`,vi:`PCA là một phương pháp giảm chiều tiêu biểu thường được xếp vào học không giám sát. Điểm cần nhớ là PCA không chỉ đơn giản xóa bớt biến mà tạo ra các thành phần chính mới từ các biến ban đầu.`},{type:`heading`,ja:`学習データ`,vi:`Dữ liệu huấn luyện`},{type:`paragraph`,ja:`学習データは、機械学習モデルに規則性やパターンを学習させるために使用するデータであり、訓練データとも呼ばれる。モデルのパラメータは、このデータを用いた学習によって調整される。`,vi:`学習データ là dữ liệu được sử dụng để mô hình Machine Learning học các quy luật và mẫu, còn được gọi là training data. Các tham số của mô hình được điều chỉnh thông qua quá trình học trên dữ liệu này.`},{type:`example`,ja:`例えば、画像分類モデルでは、画像とそれに対応するラベルを学習データとして与えることで、モデルは画像の特徴とラベルの関係を学習する。`,vi:`Ví dụ, với mô hình phân loại hình ảnh, các hình ảnh cùng nhãn tương ứng được cung cấp làm dữ liệu huấn luyện để mô hình học quan hệ giữa đặc trưng hình ảnh và nhãn.`},{type:`warning`,ja:`学習データはモデルを学習させるためのデータであり、モデルの性能を公平に確認するためのデータとは役割が異なる。FEでは、学習用と評価用のデータを分けて考えることが重要である。`,vi:`Dữ liệu huấn luyện được dùng để mô hình học, nên có vai trò khác với dữ liệu dùng để đánh giá khách quan hiệu năng của mô hình. Trong FE, cần phân biệt dữ liệu dùng để học và dữ liệu dùng để đánh giá.`}],terms:[{term:`ランダムフォレスト`,reading:`ランダムフォレスト`,english:`Random Forest`,vi:`rừng ngẫu nhiên`,definitionJa:`ランダム性を取り入れて作成した複数の決定木の予測結果を統合するアンサンブル学習の手法。`,definitionVi:`Phương pháp ensemble kết hợp kết quả dự đoán của nhiều cây quyết định được xây dựng với yếu tố ngẫu nhiên.`},{term:`サポートベクターマシン`,reading:`サポートベクターマシン`,english:`Support Vector Machine`,vi:`máy vector hỗ trợ`,definitionJa:`サポートベクターを基準として、クラス間のマージンを大きくする分類境界を求める代表的な機械学習手法。`,definitionVi:`Phương pháp Machine Learning tiêu biểu sử dụng các support vector để tìm ranh giới phân loại sao cho margin giữa các lớp lớn.`},{term:`主成分分析`,reading:`しゅせいぶんぶんせき`,english:`Principal Component Analysis`,vi:`phân tích thành phần chính`,definitionJa:`多変量データの情報をできるだけ保持しながら、新しい少数の主成分にまとめる代表的な次元削減手法。`,definitionVi:`Phương pháp giảm chiều tiêu biểu chuyển dữ liệu nhiều biến thành một số ít thành phần chính mới trong khi cố gắng giữ lại thông tin quan trọng.`},{term:`学習データ`,reading:`がくしゅうデータ`,english:`Training Data`,vi:`dữ liệu huấn luyện`,definitionJa:`機械学習モデルに規則性やパターンを学習させ、モデルのパラメータを調整するために使用するデータ。`,definitionVi:`Dữ liệu được sử dụng để mô hình Machine Learning học quy luật, mẫu và điều chỉnh các tham số của mô hình.`}],tags:[`information-theory`,`machine-learning`,`random-forest`,`support-vector-machine`,`principal-component-analysis`,`training-data`]},{id:`model-validation-and-generalization`,order:9,titleJa:`モデルの検証と汎化性能`,titleVi:`Đánh giá mô hình và khả năng khái quát hóa`,importance:`high`,summaryJa:`機械学習における検証データとテストデータの役割を区別し、未知のデータに対する性能を表す汎化性能と、それを低下させる過学習について理解する。`,summaryVi:`Phân biệt vai trò của validation data và test data trong Machine Learning, đồng thời tìm hiểu khả năng khái quát hóa trên dữ liệu chưa biết và hiện tượng overfitting làm suy giảm khả năng này.`,content:[{type:`heading`,ja:`検証データとテストデータ`,vi:`Validation data và test data`},{type:`paragraph`,ja:`機械学習では、モデルを作るための学習データとは別に、モデルの調整や評価のためのデータを用意する。検証データは、学習途中のモデルを評価し、ハイパーパラメータの調整やモデルの選択などに利用するデータである。一方、テストデータは、学習や調整が完了したモデルの最終的な性能を評価するために使用する。`,vi:`Trong Machine Learning, ngoài dữ liệu huấn luyện dùng để xây dựng mô hình còn có dữ liệu dành cho điều chỉnh và đánh giá. 検証データ (validation data) được dùng trong quá trình phát triển để đánh giá mô hình, điều chỉnh hyperparameter hoặc lựa chọn mô hình. Ngược lại, テストデータ (test data) được dùng để đánh giá hiệu năng cuối cùng sau khi việc huấn luyện và điều chỉnh đã hoàn tất.`},{type:`point`,ja:`基本的な役割は、「学習データ＝モデルを学習させる」「検証データ＝モデルの調整・選択に使う」「テストデータ＝完成したモデルを最終評価する」と整理できる。`,vi:`Có thể ghi nhớ vai trò cơ bản như sau: 学習データ = huấn luyện mô hình; 検証データ = điều chỉnh/lựa chọn mô hình; テストデータ = đánh giá cuối cùng mô hình đã hoàn thiện.`},{type:`warning`,ja:`テストデータを使って繰り返しモデルを調整すると、テストデータに対しても間接的に適合してしまい、公平な最終評価ができなくなる。テストデータは原則としてモデルの最終評価まで分離しておく。`,vi:`Nếu liên tục điều chỉnh mô hình dựa trên test data, mô hình có thể gián tiếp thích nghi với chính tập test và kết quả đánh giá cuối cùng không còn khách quan. Vì vậy về nguyên tắc, test data cần được giữ riêng cho bước đánh giá cuối cùng.`},{type:`heading`,ja:`汎化性能`,vi:`Khả năng khái quát hóa`},{type:`paragraph`,ja:`汎化性能とは、学習に使用していない未知のデータに対して、モデルがどの程度適切な予測や分類を行えるかを表す性能である。機械学習では、学習データだけに対する精度ではなく、未知のデータでも高い性能を発揮できることが重要である。`,vi:`汎化性能 là khả năng mô hình đưa ra dự đoán hoặc phân loại chính xác đối với dữ liệu mới không được sử dụng trong quá trình huấn luyện. Trong Machine Learning, điều quan trọng không chỉ là đạt độ chính xác cao trên training data mà còn phải hoạt động tốt trên dữ liệu chưa biết.`},{type:`example`,ja:`例えば、学習データでは99%の正解率を示す画像分類モデルでも、未知の画像では70%しか正解できない場合、学習データへの適合度は高くても、汎化性能が十分に高いとはいえない。`,vi:`Ví dụ, một mô hình phân loại ảnh đạt độ chính xác 99% trên training data nhưng chỉ đạt 70% trên các ảnh chưa từng thấy thì dù rất phù hợp với dữ liệu huấn luyện, khả năng khái quát hóa vẫn chưa tốt.`},{type:`heading`,ja:`過学習`,vi:`Overfitting`},{type:`paragraph`,ja:`過学習は、モデルが学習データに過度に適合し、学習データに含まれる細かな特徴やノイズまで学習してしまうことで、未知のデータに対する性能が低下する現象である。学習データでの性能が高くても、検証データやテストデータで性能が大きく低下する場合は、過学習が疑われる。`,vi:`過学習 (overfitting) là hiện tượng mô hình thích nghi quá mức với training data, thậm chí học cả những đặc điểm nhỏ hoặc nhiễu riêng của tập dữ liệu đó, khiến hiệu năng trên dữ liệu mới giảm. Nếu mô hình hoạt động rất tốt trên training data nhưng giảm mạnh trên validation data hoặc test data thì có thể đang xảy ra overfitting.`},{type:`point`,ja:`FEでは、「学習データでは高性能だが、未知データでは性能が低い」という状態と過学習を結び付けて覚える。過学習は汎化性能を低下させる。`,vi:`Trong FE, nên liên hệ overfitting với trạng thái “hiệu năng cao trên dữ liệu huấn luyện nhưng thấp trên dữ liệu chưa biết”. Overfitting làm giảm 汎化性能.`},{type:`warning`,ja:`汎化と汎化性能は関連するが同じ表現ではない。汎化は未知データにも適用できる性質・考え方を指し、汎化性能はその能力がどの程度あるかというモデルの性能に着目した用語である。`,vi:`汎化 và 汎化性能 có liên quan nhưng không hoàn toàn đồng nghĩa. 汎化 nói đến khả năng/khái niệm áp dụng những gì đã học cho dữ liệu mới, còn 汎化性能 nhấn mạnh mức độ mô hình thực hiện được điều đó tốt đến đâu.`}],terms:[{term:`検証データ`,reading:`けんしょうデータ`,english:`Validation Data`,vi:`dữ liệu xác thực`,definitionJa:`機械学習において、学習途中のモデルの性能を確認し、ハイパーパラメータの調整やモデル選択などに利用するデータ。`,definitionVi:`Dữ liệu được sử dụng trong quá trình phát triển mô hình để đánh giá hiệu năng, điều chỉnh hyperparameter hoặc lựa chọn mô hình.`},{term:`テストデータ`,reading:`テストデータ`,english:`Test Data`,vi:`dữ liệu kiểm thử`,definitionJa:`学習やモデル調整に直接使用せず、完成したモデルの未知データに対する性能を最終的に評価するためのデータ。`,definitionVi:`Dữ liệu không được dùng trực tiếp để huấn luyện hay điều chỉnh mô hình, mà được dùng để đánh giá cuối cùng hiệu năng của mô hình trên dữ liệu chưa biết.`},{term:`汎化性能`,reading:`はんかせいのう`,english:`Generalization Performance`,vi:`khả năng khái quát hóa`,definitionJa:`学習に使用していない未知のデータに対して、モデルが適切な予測や判断を行える程度を表す性能。`,definitionVi:`Mức độ mô hình có thể dự đoán hoặc đưa ra phán đoán phù hợp đối với dữ liệu mới không được sử dụng trong quá trình huấn luyện.`},{term:`過学習`,reading:`かがくしゅう`,english:`Overfitting`,vi:`quá khớp`,definitionJa:`モデルが学習データに過度に適合し、学習データでは高い性能を示す一方、未知のデータに対する性能が低下する現象。`,definitionVi:`Hiện tượng mô hình thích nghi quá mức với dữ liệu huấn luyện, đạt hiệu năng cao trên dữ liệu đó nhưng giảm hiệu năng đối với dữ liệu mới.`}],tags:[`information-theory`,`machine-learning`,`validation-data`,`test-data`,`generalization`,`overfitting`]},{id:`model-evaluation-and-deep-learning`,order:10,titleJa:`モデル評価とディープラーニング`,titleVi:`Đánh giá mô hình và Deep Learning`,importance:`high`,summaryJa:`機械学習モデルの性能を評価する交差検証とホールドアウト検証、二値分類モデルを評価するROC曲線、および多層ニューラルネットワークを用いるディープラーニングの基本を理解する。`,summaryVi:`Tìm hiểu cross-validation và holdout validation dùng để đánh giá mô hình Machine Learning, đường cong ROC dùng để đánh giá mô hình phân loại nhị phân, cùng kiến thức cơ bản về Deep Learning sử dụng mạng nơ-ron nhiều lớp.`,content:[{type:`heading`,ja:`交差検証`,vi:`Cross-validation`},{type:`paragraph`,ja:`交差検証は、データを複数の部分に分け、学習に使う部分と評価に使う部分を入れ替えながら複数回評価する方法である。一度だけデータを分割する方法よりも、特定の分割結果に評価が左右されにくく、モデルの汎化性能を確認するために利用される。`,vi:`交差検証 (cross-validation) là phương pháp chia dữ liệu thành nhiều phần rồi đánh giá nhiều lần bằng cách luân phiên phần dùng để huấn luyện và phần dùng để đánh giá. So với việc chỉ chia dữ liệu một lần, kết quả ít phụ thuộc vào một cách chia cụ thể và giúp đánh giá khả năng khái quát hóa của mô hình.`},{type:`example`,ja:`代表的なk分割交差検証では、データをk個の部分に分け、そのうち1個を評価用、残りのk－1個を学習用としてモデルを評価する。評価用の部分を順番に入れ替えてk回評価し、その結果を平均する。`,vi:`Trong k-fold cross-validation, dữ liệu được chia thành k phần. Mỗi lần dùng 1 phần để đánh giá và k−1 phần còn lại để huấn luyện. Quá trình được lặp lại k lần sao cho mỗi phần đều từng được dùng để đánh giá, sau đó tổng hợp các kết quả.`},{type:`heading`,ja:`ホールドアウト検証`,vi:`Holdout validation`},{type:`paragraph`,ja:`ホールドアウト検証は、用意したデータを学習用と評価用などにあらかじめ分割し、それぞれの役割を固定してモデルを評価する方法である。交差検証と比べて処理が単純で計算量も少ないが、評価結果がデータの分け方に影響されやすい。`,vi:`ホールドアウト検証 (holdout validation) là phương pháp chia trước dữ liệu thành các tập như tập huấn luyện và tập đánh giá rồi giữ cố định vai trò của chúng để đánh giá mô hình. Phương pháp này đơn giản và ít tốn tính toán hơn cross-validation, nhưng kết quả dễ bị ảnh hưởng bởi cách chia dữ liệu.`},{type:`warning`,ja:`交差検証では複数回データの役割を入れ替えて評価するのに対し、ホールドアウト検証では基本的に一度分割したデータを用いる。この違いはFEで区別しておきたい。`,vi:`Cross-validation đánh giá nhiều lần bằng cách thay đổi phần dữ liệu giữ vai trò đánh giá, còn holdout validation về cơ bản sử dụng một lần phân chia dữ liệu. Đây là điểm cần phân biệt trong FE.`},{type:`heading`,ja:`ROC曲線`,vi:`Đường cong ROC`},{type:`paragraph`,ja:`ROC曲線は、二値分類モデルの判定しきい値を変化させたときの真陽性率と偽陽性率の関係を表すグラフである。横軸に偽陽性率（FPR）、縦軸に真陽性率（TPR）を取り、しきい値によって分類性能がどのように変化するかを確認する。`,vi:`ROC曲線 là đồ thị biểu diễn quan hệ giữa tỷ lệ dương tính thật và tỷ lệ dương tính giả khi thay đổi ngưỡng quyết định của mô hình phân loại nhị phân. Trục ngang là FPR (False Positive Rate), trục dọc là TPR (True Positive Rate), qua đó có thể quan sát hiệu năng phân loại thay đổi theo ngưỡng.`},{type:`point`,ja:`ROC曲線は左上に近いほど、偽陽性率を低く保ちながら真陽性率を高くできていることを示す。曲線下面積であるAUCも分類性能を比較する代表的な指標であり、一般にAUCが大きいほど識別性能が高い。`,vi:`Đường ROC càng gần góc trên bên trái thì mô hình càng có khả năng giữ FPR thấp trong khi đạt TPR cao. AUC, tức diện tích dưới đường ROC, cũng là chỉ số thường dùng để so sánh khả năng phân biệt; nhìn chung AUC càng lớn thì khả năng phân biệt càng tốt.`},{type:`warning`,ja:`ROC曲線の横軸は偽陽性率、縦軸は真陽性率である。軸を逆に覚えないように注意する。`,vi:`Trục ngang của ROC là tỷ lệ dương tính giả (FPR), còn trục dọc là tỷ lệ dương tính thật (TPR). Đây là điểm dễ nhầm cần ghi nhớ.`},{type:`heading`,ja:`ディープラーニング`,vi:`Deep Learning`},{type:`paragraph`,ja:`ディープラーニングは、多数の層をもつニューラルネットワークを利用して、データから特徴やパターンを学習する機械学習の手法である。画像、音声、自然言語などの複雑なデータを扱う分野で広く利用されている。`,vi:`ディープラーニング (Deep Learning) là phương pháp Machine Learning sử dụng mạng nơ-ron gồm nhiều lớp để học đặc trưng và mẫu từ dữ liệu. Nó được sử dụng rộng rãi trong các lĩnh vực xử lý dữ liệu phức tạp như hình ảnh, âm thanh và ngôn ngữ tự nhiên.`},{type:`point`,ja:`従来の機械学習では人が特徴量を設計する場合が多いのに対し、ディープラーニングでは多層ニューラルネットワークによってデータから有用な特徴表現を段階的に学習できることが大きな特徴である。`,vi:`Trong nhiều phương pháp Machine Learning truyền thống, con người thường phải thiết kế đặc trưng. Một đặc điểm quan trọng của Deep Learning là mạng nơ-ron nhiều lớp có thể học dần các biểu diễn đặc trưng hữu ích trực tiếp từ dữ liệu.`}],terms:[{term:`交差検証`,reading:`こうさけんしょう`,english:`Cross-Validation`,vi:`kiểm định chéo`,definitionJa:`データを複数の部分に分割し、学習用と評価用の役割を入れ替えながら複数回モデルを評価する方法。`,definitionVi:`Phương pháp chia dữ liệu thành nhiều phần và đánh giá mô hình nhiều lần bằng cách luân phiên các phần dùng cho huấn luyện và đánh giá.`},{term:`ホールドアウト検証`,reading:`ホールドアウトけんしょう`,english:`Holdout Validation`,vi:`kiểm định holdout`,definitionJa:`データを学習用と評価用などに分割し、分割したデータの役割を固定してモデルの性能を評価する方法。`,definitionVi:`Phương pháp chia dữ liệu thành tập huấn luyện và tập đánh giá, sau đó giữ cố định cách chia này để đánh giá hiệu năng mô hình.`},{term:`ROC曲線`,reading:`アールオーシーきょくせん`,english:`Receiver Operating Characteristic Curve`,vi:`đường cong ROC`,definitionJa:`二値分類のしきい値を変化させたときの偽陽性率を横軸、真陽性率を縦軸として、分類性能を表す曲線。`,definitionVi:`Đường cong đánh giá mô hình phân loại nhị phân bằng cách biểu diễn FPR trên trục ngang và TPR trên trục dọc khi thay đổi ngưỡng phân loại.`},{term:`ディープラーニング`,reading:`ディープラーニング`,english:`Deep Learning`,vi:`học sâu`,definitionJa:`多数の層をもつニューラルネットワークを用いて、データから特徴やパターンを学習する機械学習の手法。`,definitionVi:`Phương pháp Machine Learning sử dụng mạng nơ-ron nhiều lớp để học các đặc trưng và mẫu từ dữ liệu.`}],tags:[`information-theory`,`machine-learning`,`model-evaluation`,`cross-validation`,`roc-curve`,`deep-learning`]},{id:`neural-networks-and-backpropagation`,order:11,titleJa:`ニューラルネットワークと学習`,titleVi:`Mạng nơ-ron và quá trình học`,importance:`high`,summaryJa:`ニューラルネットワークと多層パーセプトロンの基本構造を理解し、バックプロパゲーションによる重みの学習と、深いネットワークで発生し得る勾配消失問題の関係を整理する。`,summaryVi:`Tìm hiểu cấu trúc cơ bản của mạng nơ-ron và perceptron đa tầng, cơ chế học trọng số bằng backpropagation và mối liên hệ với vấn đề tiêu biến gradient có thể xảy ra trong mạng sâu.`,content:[{type:`heading`,ja:`ニューラルネットワーク`,vi:`Mạng nơ-ron`},{type:`paragraph`,ja:`ニューラルネットワークは、生物の神経回路を参考にした計算モデルであり、多数のニューロンに相当する処理単位を接続して情報を処理する。各接続には重みがあり、入力に重みを掛けて得られた値などを基に各ニューロンの出力を計算する。`,vi:`ニューラルネットワーク (mạng nơ-ron) là mô hình tính toán lấy cảm hứng từ mạng thần kinh sinh học, xử lý thông tin bằng nhiều đơn vị tương ứng với neuron được kết nối với nhau. Mỗi kết nối có trọng số và đầu ra của neuron được tính dựa trên các giá trị đầu vào đã được nhân với trọng số cùng các xử lý liên quan.`},{type:`point`,ja:`ニューラルネットワークでは、入力をそのまま記憶するのではなく、学習によって接続の重みなどを調整し、入力と目的とする出力の関係を表現できるようにする。`,vi:`Trong mạng nơ-ron, mô hình không đơn thuần ghi nhớ đầu vào mà điều chỉnh các trọng số kết nối thông qua quá trình học để biểu diễn được quan hệ giữa đầu vào và đầu ra mong muốn.`},{type:`heading`,ja:`多層パーセプトロン`,vi:`Perceptron đa tầng`},{type:`paragraph`,ja:`多層パーセプトロンは、入力層、1層以上の中間層（隠れ層）、出力層から構成される代表的なニューラルネットワークである。複数の層を通して情報を変換することで、単純な線形モデルでは表現できない複雑な関係を学習できる。`,vi:`多層パーセプトロン (Multilayer Perceptron: MLP) là một dạng mạng nơ-ron tiêu biểu gồm lớp đầu vào, một hoặc nhiều lớp trung gian (lớp ẩn) và lớp đầu ra. Bằng cách biến đổi thông tin qua nhiều lớp, mô hình có thể học những quan hệ phức tạp mà mô hình tuyến tính đơn giản không thể biểu diễn.`},{type:`point`,ja:`基本構造は「入力層 → 中間層（隠れ層） → 出力層」である。中間層をもつことで、より複雑な特徴や非線形な関係を表現できる。`,vi:`Cấu trúc cơ bản là “lớp đầu vào → lớp trung gian (lớp ẩn) → lớp đầu ra”. Nhờ có lớp ẩn, mạng có thể biểu diễn các đặc trưng và quan hệ phi tuyến phức tạp hơn.`},{type:`heading`,ja:`バックプロパゲーション`,vi:`Lan truyền ngược`},{type:`paragraph`,ja:`バックプロパゲーションは、ニューラルネットワークの出力と正解との誤差を基に、その誤差に対する各重みの影響を出力側から入力側へ逆向きに計算していく方法である。得られた勾配を利用して重みを更新し、誤差が小さくなるように学習を進める。`,vi:`バックプロパゲーション (backpropagation) là phương pháp dựa trên sai số giữa đầu ra của mạng và giá trị mục tiêu, sau đó tính ngược từ phía đầu ra về phía đầu vào mức độ ảnh hưởng của từng trọng số đến sai số. Gradient thu được được sử dụng để cập nhật trọng số theo hướng làm giảm sai số.`},{type:`point`,ja:`大まかな流れは「順方向に出力を計算する → 誤差を求める → 誤差に関する勾配を後ろから伝える → 重みを更新する」である。`,vi:`Luồng cơ bản có thể nhớ là: “tính đầu ra theo chiều thuận → tính sai số → truyền gradient của sai số ngược trở lại → cập nhật trọng số”.`},{type:`warning`,ja:`バックプロパゲーションは、単に誤差の値そのものを各層へ配る処理ではない。連鎖律を用いて、誤差に対する各重みの勾配を効率的に計算する仕組みである。`,vi:`Backpropagation không đơn giản là phân phối trực tiếp giá trị sai số cho từng lớp. Nó sử dụng quy tắc dây chuyền để tính hiệu quả gradient của sai số đối với từng trọng số.`},{type:`heading`,ja:`勾配消失問題`,vi:`Vấn đề tiêu biến gradient`},{type:`paragraph`,ja:`勾配消失問題は、深いニューラルネットワークでバックプロパゲーションを行う際、入力側へさかのぼるにつれて勾配が非常に小さくなり、前方の層の重みがほとんど更新されなくなる問題である。その結果、ネットワークの学習が進みにくくなる。`,vi:`勾配消失問題 (vanishing gradient problem) là hiện tượng trong mạng nơ-ron sâu khi thực hiện backpropagation, gradient trở nên rất nhỏ khi truyền ngược về các lớp gần đầu vào. Vì vậy trọng số ở các lớp phía trước gần như không được cập nhật và quá trình học trở nên khó khăn.`},{type:`example`,ja:`例えば、微分値が1よりかなり小さい活性化関数を多数の層で通る場合、バックプロパゲーションではそれらの値が繰り返し掛け合わされるため、入力層に近づくほど勾配が極端に小さくなることがある。`,vi:`Ví dụ, nếu gradient phải đi qua nhiều lớp có đạo hàm nhỏ hơn 1 đáng kể, trong quá trình backpropagation các giá trị nhỏ này được nhân lặp lại với nhau, khiến gradient có thể trở nên cực kỳ nhỏ khi tiến về các lớp gần đầu vào.`},{type:`point`,ja:`勾配消失への代表的な対策には、ReLUなどの活性化関数の利用や、適切な重みの初期化、ネットワーク構造の工夫などがある。FEではまず「勾配が小さくなる → 前方の層の重みが更新されにくい → 学習が進みにくい」という関係を理解する。`,vi:`Các biện pháp tiêu biểu đối với vanishing gradient gồm sử dụng hàm kích hoạt như ReLU, khởi tạo trọng số thích hợp và cải tiến cấu trúc mạng. Ở mức FE, trước hết cần hiểu quan hệ: “gradient nhỏ dần → trọng số ở các lớp phía trước khó được cập nhật → việc học trở nên khó khăn”.`}],terms:[{term:`ニューラルネットワーク`,reading:`ニューラルネットワーク`,english:`Neural Network`,vi:`mạng nơ-ron`,definitionJa:`多数のニューロンに相当する処理単位を接続し、接続の重みなどを学習によって調整して情報を処理する計算モデル。`,definitionVi:`Mô hình tính toán gồm nhiều đơn vị tương ứng với neuron được kết nối với nhau và xử lý thông tin bằng cách điều chỉnh các trọng số kết nối thông qua quá trình học.`},{term:`多層パーセプトロン`,reading:`たそうパーセプトロン`,english:`Multilayer Perceptron`,vi:`perceptron đa tầng`,definitionJa:`入力層、中間層（隠れ層）、出力層から構成される、多層構造をもつ代表的なニューラルネットワーク。`,definitionVi:`Một dạng mạng nơ-ron nhiều tầng tiêu biểu gồm lớp đầu vào, một hoặc nhiều lớp ẩn và lớp đầu ra.`},{term:`バックプロパゲーション`,reading:`バックプロパゲーション`,english:`Backpropagation`,vi:`lan truyền ngược`,definitionJa:`ニューラルネットワークの誤差に関する勾配を出力側から入力側へ効率的に計算し、重みの学習に利用する方法。`,definitionVi:`Phương pháp tính hiệu quả gradient của sai số từ phía đầu ra ngược về phía đầu vào để sử dụng trong việc học và cập nhật trọng số của mạng nơ-ron.`},{term:`勾配消失問題`,reading:`こうばいしょうしつもんだい`,english:`Vanishing Gradient Problem`,vi:`vấn đề tiêu biến gradient`,definitionJa:`深いニューラルネットワークで勾配が入力側へ伝わるにつれて非常に小さくなり、前方の層の重みが更新されにくくなる問題。`,definitionVi:`Vấn đề trong mạng nơ-ron sâu khi gradient trở nên rất nhỏ trong quá trình truyền ngược về phía đầu vào, khiến trọng số ở các lớp phía trước khó được cập nhật.`}],tags:[`information-theory`,`machine-learning`,`neural-network`,`multilayer-perceptron`,`backpropagation`,`vanishing-gradient`]},{id:`neural-network-training-techniques`,order:12,titleJa:`ニューラルネットワークの学習技術`,titleVi:`Các kỹ thuật huấn luyện mạng nơ-ron`,importance:`high`,summaryJa:`ニューラルネットワークに非線形性を与える活性化関数と、既存の学習済み知識を活用する事前学習、ファインチューニング、転移学習の基本的な考え方と違いを理解する。`,summaryVi:`Tìm hiểu vai trò của hàm kích hoạt trong việc tạo tính phi tuyến cho mạng nơ-ron, đồng thời phân biệt pre-training, fine-tuning và transfer learning trong việc tận dụng kiến thức đã học.`,content:[{type:`heading`,ja:`活性化関数`,vi:`Hàm kích hoạt`},{type:`paragraph`,ja:`活性化関数は、ニューラルネットワークの各ニューロンで計算された値を変換し、次の層へ渡す出力を決める関数である。非線形な活性化関数を用いることで、ネットワークは単純な直線関係だけでは表現できない複雑なパターンを学習できる。`,vi:`活性化関数 (hàm kích hoạt) là hàm biến đổi giá trị được tính tại mỗi neuron để xác định đầu ra truyền sang lớp tiếp theo. Việc sử dụng hàm kích hoạt phi tuyến giúp mạng học được những mẫu phức tạp mà chỉ các quan hệ tuyến tính đơn giản không thể biểu diễn.`},{type:`point`,ja:`代表的な活性化関数にはシグモイド関数やReLUがある。特にReLUは、入力が正ならその値を出力し、負なら0を出力する単純な関数で、深いニューラルネットワークでも広く利用される。`,vi:`Các hàm kích hoạt tiêu biểu gồm sigmoid và ReLU. ReLU là hàm đơn giản: nếu đầu vào dương thì giữ nguyên giá trị, còn nếu âm thì cho đầu ra bằng 0; nó được sử dụng rộng rãi trong các mạng nơ-ron sâu.`},{type:`warning`,ja:`活性化関数の重要な役割の一つは、ネットワークに非線形性を導入することである。多くの層を重ねても、各層が線形変換だけで構成されていれば、ネットワーク全体も実質的には一つの線形変換として表せる。`,vi:`Một vai trò quan trọng của hàm kích hoạt là đưa tính phi tuyến vào mạng. Nếu các lớp chỉ thực hiện biến đổi tuyến tính thì dù xếp nhiều lớp, toàn bộ mạng về bản chất vẫn có thể biểu diễn như một phép biến đổi tuyến tính.`},{type:`heading`,ja:`事前学習`,vi:`Pre-training`},{type:`paragraph`,ja:`事前学習は、特定の最終タスクに適用する前に、大量のデータなどを用いてモデルに汎用的な特徴や知識を学習させることである。事前学習済みモデルを利用することで、個別のタスクを最初から学習する場合に比べて、必要なデータや学習時間を削減できる場合がある。`,vi:`事前学習 (pre-training) là quá trình cho mô hình học trước các đặc trưng hoặc kiến thức mang tính tổng quát, thường bằng lượng dữ liệu lớn, trước khi áp dụng vào nhiệm vụ cuối cùng cụ thể. Việc sử dụng mô hình đã pre-train có thể giúp giảm dữ liệu và thời gian cần thiết so với huấn luyện một nhiệm vụ hoàn toàn từ đầu.`},{type:`heading`,ja:`ファインチューニング`,vi:`Fine-tuning`},{type:`paragraph`,ja:`ファインチューニングは、学習済みモデルを出発点として、目的とするタスクのデータを用いて追加学習し、モデルのパラメータをそのタスクに適するよう調整する方法である。すでに獲得した知識を利用できるため、モデルを一から学習するより効率的な場合がある。`,vi:`ファインチューニング (fine-tuning) là phương pháp lấy một mô hình đã được huấn luyện làm điểm xuất phát, sau đó tiếp tục huấn luyện bằng dữ liệu của nhiệm vụ mục tiêu để điều chỉnh các tham số cho phù hợp với nhiệm vụ đó. Nhờ tận dụng kiến thức đã có, phương pháp này thường hiệu quả hơn so với huấn luyện từ đầu.`},{type:`heading`,ja:`転移学習`,vi:`Transfer learning`},{type:`paragraph`,ja:`転移学習は、あるタスクやデータで学習したモデルの知識を、別の関連するタスクの学習に活用する考え方である。新しいタスクで利用できる学習データが少ない場合でも、既存モデルが獲得した特徴を利用することで効率よく学習できる場合がある。`,vi:`転移学習 (transfer learning) là cách tiếp cận tận dụng kiến thức mà mô hình đã học từ một nhiệm vụ hoặc dữ liệu trước đó cho một nhiệm vụ khác có liên quan. Ngay cả khi nhiệm vụ mới có ít dữ liệu huấn luyện, các đặc trưng mà mô hình cũ đã học vẫn có thể giúp quá trình học hiệu quả hơn.`},{type:`point`,ja:`関係を整理すると、事前学習は「先に広い知識を学ぶこと」、転移学習は「学んだ知識を別の課題に活用する考え方」、ファインチューニングは「学習済みモデルを目的の課題に合わせて追加学習・調整する方法」と捉えると区別しやすい。`,vi:`Có thể phân biệt như sau: 事前学習 là “học trước kiến thức tổng quát”; 転移学習 là “tận dụng kiến thức đã học cho một nhiệm vụ khác”; ファインチューニング là “tiếp tục huấn luyện và điều chỉnh mô hình đã học cho phù hợp với nhiệm vụ mục tiêu”.`},{type:`example`,ja:`例えば、大量の一般画像で事前学習した画像認識モデルの特徴抽出能力を利用し、少量の犬と猫の画像を使って分類モデルを学習する場合は転移学習の例である。その際、学習済みモデルのパラメータを目的の分類に合わせて追加調整する処理はファインチューニングに当たる。`,vi:`Ví dụ, sử dụng khả năng trích xuất đặc trưng của một mô hình nhận dạng ảnh đã được pre-train trên lượng lớn ảnh tổng quát, rồi dùng một lượng nhỏ ảnh chó và mèo để xây dựng mô hình phân loại là một ví dụ về transfer learning. Nếu tiếp tục điều chỉnh các tham số của mô hình đã học để phù hợp với bài toán phân loại chó/mèo thì đó là fine-tuning.`},{type:`warning`,ja:`転移学習とファインチューニングは関連が深いが、同じ意味ではない。転移学習は既存の知識を別の課題に利用する広い考え方であり、ファインチューニングは学習済みモデルを追加学習して調整する具体的な方法である。`,vi:`Transfer learning và fine-tuning có quan hệ chặt chẽ nhưng không đồng nghĩa. Transfer learning là khái niệm rộng về việc sử dụng kiến thức đã học cho nhiệm vụ khác, còn fine-tuning là một phương pháp cụ thể trong đó mô hình đã huấn luyện được tiếp tục học để điều chỉnh cho nhiệm vụ mục tiêu.`}],terms:[{term:`活性化関数`,reading:`かっせいかかんすう`,english:`Activation Function`,vi:`hàm kích hoạt`,definitionJa:`ニューラルネットワークのニューロンで計算された値を変換し、そのニューロンの出力を決定する関数。`,definitionVi:`Hàm biến đổi giá trị được tính tại một neuron để xác định đầu ra của neuron đó.`},{term:`事前学習`,reading:`じぜんがくしゅう`,english:`Pre-training`,vi:`huấn luyện trước`,definitionJa:`目的とするタスクに適用する前に、データを用いてモデルに汎用的な特徴や知識をあらかじめ学習させること。`,definitionVi:`Quá trình cho mô hình học trước các đặc trưng hoặc kiến thức tổng quát trước khi áp dụng vào nhiệm vụ mục tiêu.`},{term:`ファインチューニング`,reading:`ファインチューニング`,english:`Fine-tuning`,vi:`tinh chỉnh mô hình`,definitionJa:`学習済みモデルに目的タスクのデータを用いて追加学習を行い、パラメータをそのタスクに適するよう調整する方法。`,definitionVi:`Phương pháp tiếp tục huấn luyện một mô hình đã học bằng dữ liệu của nhiệm vụ mục tiêu để điều chỉnh các tham số cho phù hợp.`},{term:`転移学習`,reading:`てんいがくしゅう`,english:`Transfer Learning`,vi:`học chuyển giao`,definitionJa:`あるタスクやデータで学習した知識を、別の関連するタスクの学習に活用する機械学習の方法。`,definitionVi:`Phương pháp Machine Learning tận dụng kiến thức đã học từ một nhiệm vụ hoặc tập dữ liệu cho một nhiệm vụ khác có liên quan.`}],tags:[`information-theory`,`machine-learning`,`neural-network`,`activation-function`,`pre-training`,`fine-tuning`,`transfer-learning`]},{id:`neural-network-models-and-generative-ai`,order:13,titleJa:`ニューラルネットワークのモデルと生成モデル`,titleVi:`Các mô hình mạng nơ-ron và mô hình sinh`,importance:`high`,summaryJa:`画像処理に適した畳み込みニューラルネットワーク、系列データを扱うリカレントニューラルネットワーク、データを新たに生成する生成モデル、生成器と識別器を競わせて学習する敵対的生成ネットワークの基本を理解する。`,summaryVi:`Tìm hiểu các mô hình mạng nơ-ron tiêu biểu gồm mạng nơ-ron tích chập dùng cho dữ liệu như hình ảnh, mạng nơ-ron hồi tiếp dùng cho dữ liệu chuỗi, mô hình sinh tạo dữ liệu mới và GAN học thông qua sự cạnh tranh giữa bộ sinh và bộ phân biệt.`,content:[{type:`heading`,ja:`畳み込みニューラルネットワーク`,vi:`Mạng nơ-ron tích chập`},{type:`paragraph`,ja:`畳み込みニューラルネットワークは、画像などの空間的な特徴をもつデータの処理に適したニューラルネットワークである。フィルタを入力データ上で移動させながら畳み込み演算を行い、輪郭や形などの局所的な特徴を抽出する。`,vi:`畳み込みニューラルネットワーク (CNN) là mạng nơ-ron phù hợp với việc xử lý dữ liệu có đặc trưng không gian như hình ảnh. Mạng thực hiện phép tích chập bằng cách di chuyển các bộ lọc trên dữ liệu đầu vào để trích xuất các đặc trưng cục bộ như đường viền và hình dạng.`},{type:`point`,ja:`FEでは、CNNは画像認識などに適しており、「畳み込みによって特徴を抽出する」という点を押さえる。`,vi:`Trong FE, cần nhớ CNN phù hợp với các bài toán như nhận dạng hình ảnh và đặc điểm quan trọng là sử dụng phép tích chập để trích xuất đặc trưng.`},{type:`heading`,ja:`リカレントニューラルネットワーク`,vi:`Mạng nơ-ron hồi tiếp`},{type:`paragraph`,ja:`リカレントニューラルネットワークは、時系列や文章など、順序に意味がある系列データを扱うためのニューラルネットワークである。過去の処理結果に関する情報を後続の処理に利用する構造をもち、系列の前後関係を考慮できる。`,vi:`リカレントニューラルネットワーク (RNN) là mạng nơ-ron dùng để xử lý dữ liệu chuỗi mà thứ tự có ý nghĩa, chẳng hạn như dữ liệu thời gian hoặc văn bản. Mạng có cấu trúc cho phép sử dụng thông tin từ các bước xử lý trước cho các bước sau, nhờ đó có thể xét đến quan hệ trước sau trong chuỗi.`},{type:`point`,ja:`CNNは画像などの空間的な特徴の抽出に適し、RNNは時系列や文章などの系列的な関係の処理に適する、という違いを整理しておく。`,vi:`Cần phân biệt: CNN thích hợp để trích xuất đặc trưng không gian như trong hình ảnh, còn RNN thích hợp để xử lý quan hệ theo chuỗi như dữ liệu thời gian hoặc văn bản.`},{type:`heading`,ja:`生成モデル`,vi:`Mô hình sinh`},{type:`paragraph`,ja:`生成モデルは、学習データの特徴や分布を学習し、それを基に新しいデータを生成するモデルである。画像や文章など、学習したデータと似た性質をもつ新たなデータの生成に利用される。`,vi:`生成モデル (mô hình sinh) là mô hình học các đặc trưng hoặc phân bố của dữ liệu huấn luyện rồi dựa vào đó tạo ra dữ liệu mới. Nó có thể được sử dụng để sinh hình ảnh, văn bản và các loại dữ liệu mới có đặc tính tương tự dữ liệu đã học.`},{type:`heading`,ja:`敵対的生成ネットワーク`,vi:`Mạng sinh đối kháng`},{type:`paragraph`,ja:`敵対的生成ネットワークは生成モデルの一種であり、生成器と識別器という二つのニューラルネットワークを競わせながら学習する。生成器は本物に近いデータを生成しようとし、識別器は入力されたデータが実データか生成データかを見分けようとする。`,vi:`敵対的生成ネットワーク (GAN) là một loại mô hình sinh gồm hai mạng nơ-ron được huấn luyện theo cơ chế đối kháng: bộ sinh (generator) cố gắng tạo dữ liệu giống dữ liệu thật, còn bộ phân biệt (discriminator) cố gắng xác định dữ liệu đầu vào là dữ liệu thật hay dữ liệu do bộ sinh tạo ra.`},{type:`point`,ja:`GANでは、「生成器は識別器をだませるデータを作ろうとする」「識別器は本物と生成物を正しく見分けようとする」という競争を通して学習が進む。`,vi:`Trong GAN, quá trình học diễn ra thông qua sự cạnh tranh: generator cố tạo dữ liệu có thể đánh lừa discriminator, còn discriminator cố phân biệt chính xác dữ liệu thật và dữ liệu được tạo ra.`},{type:`warning`,ja:`生成モデルとGANを同じ意味として覚えない。生成モデルは新しいデータを生成するモデルの総称であり、GANはその実現方法の一つである。`,vi:`Không được hiểu 生成モデル và GAN là cùng một khái niệm. 生成モデル là khái niệm rộng chỉ các mô hình tạo dữ liệu mới, còn GAN là một phương pháp cụ thể thuộc nhóm mô hình sinh.`},{type:`example`,ja:`FEでは、「画像の特徴抽出 → CNN」「時系列や系列データ → RNN」「新しいデータの生成 → 生成モデル」「生成器と識別器を競わせる → GAN」という対応で整理すると区別しやすい。`,vi:`Khi học FE có thể phân biệt nhanh theo cặp: “trích xuất đặc trưng ảnh → CNN”, “dữ liệu thời gian/chuỗi → RNN”, “tạo dữ liệu mới → mô hình sinh”, “generator cạnh tranh với discriminator → GAN”.`}],terms:[{term:`畳み込みニューラルネットワーク`,reading:`たたみこみニューラルネットワーク`,english:`Convolutional Neural Network`,vi:`mạng nơ-ron tích chập`,definitionJa:`畳み込み演算を用いて画像などから局所的な特徴を抽出することに適したニューラルネットワーク。`,definitionVi:`Mạng nơ-ron sử dụng phép tích chập để trích xuất các đặc trưng cục bộ từ dữ liệu như hình ảnh.`},{term:`リカレントニューラルネットワーク`,reading:`リカレントニューラルネットワーク`,english:`Recurrent Neural Network`,vi:`mạng nơ-ron hồi tiếp`,definitionJa:`過去の処理に関する情報を後続の処理に利用でき、時系列や文章などの系列データを扱うことに適したニューラルネットワーク。`,definitionVi:`Mạng nơ-ron có thể sử dụng thông tin từ các bước xử lý trước cho các bước tiếp theo, phù hợp với dữ liệu chuỗi như dữ liệu thời gian và văn bản.`},{term:`生成モデル`,reading:`せいせいモデル`,english:`Generative Model`,vi:`mô hình sinh`,definitionJa:`学習データの特徴や分布を学習し、それを基に新しいデータを生成するモデル。`,definitionVi:`Mô hình học đặc trưng hoặc phân bố của dữ liệu huấn luyện và dựa vào đó tạo ra dữ liệu mới.`},{term:`敵対的生成ネットワーク`,reading:`てきたいてきせいせいネットワーク`,english:`Generative Adversarial Network`,vi:`mạng sinh đối kháng`,definitionJa:`生成器と識別器を互いに競わせて学習させることで、実データに近いデータの生成を目指す生成モデルの一種。`,definitionVi:`Một loại mô hình sinh huấn luyện generator và discriminator theo cơ chế đối kháng nhằm tạo ra dữ liệu gần giống dữ liệu thật.`}],tags:[`information-theory`,`machine-learning`,`deep-learning`,`cnn`,`rnn`,`generative-model`,`gan`]},{id:`foundation-and-language-models`,order:14,titleJa:`基盤モデルと生成AIのモデル`,titleVi:`Mô hình nền tảng và các mô hình AI tạo sinh`,importance:`high`,summaryJa:`基盤モデル、拡散モデル、言語モデル、大規模言語モデルの基本的な役割と関係を理解する。特に、広範なタスクへ適応できる基盤モデル、生成に利用される拡散モデル、言語を扱う言語モデルと大規模言語モデルの違いを整理する。`,summaryVi:`Tìm hiểu vai trò và mối quan hệ giữa foundation model, diffusion model, language model và large language model. Trọng tâm là phân biệt mô hình nền tảng có khả năng thích ứng với nhiều nhiệm vụ, mô hình khuếch tán dùng cho sinh dữ liệu, và các mô hình xử lý ngôn ngữ.`,content:[{type:`heading`,ja:`基盤モデル`,vi:`Mô hình nền tảng`},{type:`paragraph`,ja:`基盤モデルは、大規模かつ多様なデータで学習され、さまざまな下流タスクに適応して利用できるAIモデルである。一つの特定用途だけを目的として学習するのではなく、事前学習で広範な知識や特徴を獲得し、必要に応じてファインチューニングなどを行って個別の用途に適応させる。`,vi:`基盤モデル (foundation model) là mô hình AI được huấn luyện trên lượng dữ liệu lớn và đa dạng, sau đó có thể thích ứng với nhiều tác vụ hạ nguồn. Thay vì chỉ được huấn luyện cho một mục đích duy nhất, mô hình học trước kiến thức và đặc trưng tổng quát rồi có thể được điều chỉnh bằng fine-tuning hoặc các phương pháp khác cho từng mục đích cụ thể.`},{type:`point`,ja:`FEでは、「大規模なデータで事前学習され、多様な用途へ適応できるモデル」という特徴を押さえる。基盤モデルは必ずしも言語だけを扱うモデルではない。`,vi:`Trong FE, cần nhớ đặc điểm: “được pre-train trên dữ liệu quy mô lớn và có thể thích ứng với nhiều mục đích”. Foundation model không nhất thiết chỉ là mô hình xử lý ngôn ngữ.`},{type:`heading`,ja:`拡散モデル`,vi:`Mô hình khuếch tán`},{type:`paragraph`,ja:`拡散モデルは生成モデルの一種であり、学習データに段階的にノイズを加える過程と、そのノイズを取り除いてデータを復元する過程を利用して学習する。生成時には、ランダムなノイズから段階的にノイズを除去することで、学習データの特徴をもつ新しいデータを生成する。`,vi:`拡散モデル (diffusion model) là một loại mô hình sinh. Trong quá trình học, mô hình sử dụng quá trình từng bước thêm nhiễu vào dữ liệu và học quá trình ngược lại để loại bỏ nhiễu, khôi phục dữ liệu. Khi sinh dữ liệu, mô hình bắt đầu từ nhiễu ngẫu nhiên rồi khử nhiễu dần để tạo dữ liệu mới mang đặc trưng của dữ liệu đã học.`},{type:`example`,ja:`画像生成では、最初はランダムノイズに近い状態から始め、学習したモデルによって少しずつノイズを除去し、最終的に意味のある画像へ変換していく。`,vi:`Trong sinh ảnh, quá trình có thể bắt đầu từ trạng thái gần như nhiễu ngẫu nhiên, sau đó mô hình đã học loại bỏ nhiễu từng bước cho đến khi tạo thành một hình ảnh có ý nghĩa.`},{type:`warning`,ja:`AIにおける拡散モデルの「拡散」は、SNS上で情報が広がることなどをモデル化するという意味ではない。生成AIでは、データへのノイズ付加と、その逆過程であるノイズ除去を利用する生成モデルとして理解する。`,vi:`Trong AI, “khuếch tán” của diffusion model không có nghĩa là mô hình hóa việc thông tin lan truyền trên mạng xã hội. Trong Generative AI, cần hiểu đây là mô hình sinh dựa trên quá trình thêm nhiễu vào dữ liệu và quá trình ngược để loại bỏ nhiễu.`},{type:`heading`,ja:`言語モデル`,vi:`Mô hình ngôn ngữ`},{type:`paragraph`,ja:`言語モデルは、単語やトークンなどの系列に対して確率的な関係をモデル化し、文脈に基づいて次の要素を予測するなど、言語を扱うためのモデルである。文章生成、入力補完、翻訳などの自然言語処理に利用される。`,vi:`言語モデル (language model) là mô hình biểu diễn các quan hệ xác suất trong chuỗi từ hoặc token, chẳng hạn dự đoán phần tử tiếp theo dựa trên ngữ cảnh. Nó được sử dụng trong các tác vụ xử lý ngôn ngữ tự nhiên như sinh văn bản, hoàn thành văn bản và dịch máy.`},{type:`point`,ja:`言語モデルの基本的な考え方は、文脈から単語やトークンの出現確率を扱うことである。必ずしもすべての言語モデルが大規模言語モデルであるとは限らない。`,vi:`Ý tưởng cơ bản của language model là xử lý xác suất xuất hiện của từ hoặc token dựa trên ngữ cảnh. Không phải mọi language model đều là large language model.`},{type:`heading`,ja:`大規模言語モデル`,vi:`Mô hình ngôn ngữ lớn`},{type:`paragraph`,ja:`大規模言語モデルは、大量のテキストデータなどを用いて学習された大規模な言語モデルであり、LLMとも呼ばれる。多数のパラメータをもち、文章生成、要約、翻訳、質問応答など、さまざまな言語タスクに利用できる。`,vi:`大規模言語モデル (Large Language Model: LLM) là mô hình ngôn ngữ quy mô lớn được huấn luyện bằng lượng lớn dữ liệu văn bản và các dữ liệu liên quan. Mô hình có số lượng tham số lớn và có thể được sử dụng cho nhiều tác vụ ngôn ngữ như sinh văn bản, tóm tắt, dịch và hỏi đáp.`},{type:`point`,ja:`関係を整理すると、「言語モデル」は言語を扱うモデルの広い概念であり、「大規模言語モデル」はその中でも大規模なデータとモデル規模で学習されたものを指す。一方、「基盤モデル」は言語に限定されず、多様な下流タスクへ適応可能なモデルという、より広い観点の概念である。`,vi:`Có thể phân biệt như sau: 言語モデル là khái niệm rộng về mô hình xử lý ngôn ngữ; 大規模言語モデル là language model được huấn luyện ở quy mô dữ liệu và mô hình lớn. Trong khi đó, 基盤モデル là khái niệm rộng hơn theo góc nhìn khả năng thích ứng với nhiều nhiệm vụ và không giới hạn ở ngôn ngữ.`},{type:`example`,ja:`FEでは、「多様なタスクへの基盤 → 基盤モデル」「ノイズ除去を利用した生成 → 拡散モデル」「言語の系列をモデル化 → 言語モデル」「大規模に学習された言語モデル → LLM」と整理すると区別しやすい。`,vi:`Khi học FE có thể nhớ: “nền tảng cho nhiều nhiệm vụ → foundation model”, “sinh dữ liệu thông qua quá trình khử nhiễu → diffusion model”, “mô hình hóa chuỗi ngôn ngữ → language model”, “language model được huấn luyện ở quy mô lớn → LLM”.`}],terms:[{term:`基盤モデル`,reading:`きばんモデル`,english:`Foundation Model`,vi:`mô hình nền tảng`,definitionJa:`大規模かつ多様なデータで事前学習され、さまざまな下流タスクへ適応して利用できるAIモデル。`,definitionVi:`Mô hình AI được pre-train trên dữ liệu quy mô lớn và đa dạng, có thể thích ứng để sử dụng cho nhiều tác vụ hạ nguồn.`},{term:`拡散モデル`,reading:`かくさんモデル`,english:`Diffusion Model`,vi:`mô hình khuếch tán`,definitionJa:`データへのノイズ付加と、その逆過程であるノイズ除去を学習し、ノイズから新しいデータを生成する生成モデルの一種。`,definitionVi:`Một loại mô hình sinh được huấn luyện để học quá trình thêm nhiễu và quá trình ngược nhằm loại bỏ nhiễu, từ đó có thể tạo dữ liệu mới bắt đầu từ nhiễu.`},{term:`言語モデル`,reading:`げんごモデル`,english:`Language Model`,vi:`mô hình ngôn ngữ`,definitionJa:`単語やトークンなどの系列の確率的な関係をモデル化し、予測や文章生成などに利用するモデル。`,definitionVi:`Mô hình biểu diễn quan hệ xác suất của chuỗi từ hoặc token, được sử dụng cho dự đoán, sinh văn bản và các tác vụ ngôn ngữ khác.`},{term:`大規模言語モデル`,reading:`だいきぼげんごモデル`,english:`Large Language Model`,vi:`mô hình ngôn ngữ lớn`,definitionJa:`大量のデータと多数のパラメータを用いて学習され、多様な言語処理タスクに利用できる大規模な言語モデル。LLMとも呼ばれる。`,definitionVi:`Mô hình ngôn ngữ quy mô lớn được huấn luyện với lượng dữ liệu lớn và nhiều tham số, có khả năng thực hiện nhiều tác vụ xử lý ngôn ngữ; còn gọi là LLM.`}],tags:[`information-theory`,`artificial-intelligence`,`foundation-model`,`generative-ai`,`diffusion-model`,`language-model`,`llm`]},{id:`self-supervised-learning-and-program-translation`,order:15,titleJa:`AIの学習技術とプログラム変換`,titleVi:`Kỹ thuật học AI và chuyển đổi chương trình`,importance:`medium`,summaryJa:`自己教師あり学習とプロンプトエンジニアリングの基本を理解するとともに、プログラムの変換過程で用いられる中間言語と目的プログラムの役割を整理する。`,summaryVi:`Tìm hiểu kiến thức cơ bản về self-supervised learning và prompt engineering, đồng thời nắm vai trò của ngôn ngữ trung gian và chương trình đích trong quá trình chuyển đổi chương trình.`,content:[{type:`heading`,ja:`自己教師あり学習`,vi:`Học tự giám sát`},{type:`paragraph`,ja:`自己教師あり学習は、ラベル付けされていないデータそのものから学習に必要な正解や予測対象を作り出して学習する方法である。人手で大量のラベルを用意しなくても、大量のテキスト、画像、音声などを学習に利用できる。`,vi:`自己教師あり学習 (self-supervised learning) là phương pháp tạo ra mục tiêu dự đoán hoặc tín hiệu giám sát từ chính dữ liệu chưa được gắn nhãn để tiến hành học. Nhờ đó có thể tận dụng lượng lớn văn bản, hình ảnh hoặc âm thanh mà không cần con người gắn nhãn thủ công cho toàn bộ dữ liệu.`},{type:`example`,ja:`例えば、文章の一部を隠して、その部分を周囲の文脈から予測させる学習では、元の文章自体から正解を作ることができる。このため、人手で正解ラベルを付けなくても学習データを構成できる。`,vi:`Ví dụ, có thể che một phần của câu rồi yêu cầu mô hình dự đoán phần bị che dựa trên ngữ cảnh. Đáp án được tạo từ chính câu ban đầu nên có thể xây dựng dữ liệu học mà không cần con người gắn nhãn đáp án.`},{type:`warning`,ja:`自己教師あり学習は教師なし学習と完全に同じではない。自己教師あり学習では、入力データ自身から擬似的な教師信号を作り、それを使って予測問題を学習する点が特徴である。`,vi:`自己教師あり学習 không hoàn toàn đồng nghĩa với 教師なし学習 (học không giám sát). Điểm đặc trưng của self-supervised learning là tự tạo tín hiệu giám sát từ chính dữ liệu đầu vào rồi học một bài toán dự đoán dựa trên tín hiệu đó.`},{type:`heading`,ja:`プロンプトエンジニアリング`,vi:`Kỹ thuật thiết kế prompt`},{type:`paragraph`,ja:`プロンプトエンジニアリングは、生成AIなどのモデルから目的に合った出力を得るために、入力する指示や質問の内容・構造・条件などを設計する技術である。目的、前提条件、出力形式などを明確にすることで、期待する回答を得やすくする。`,vi:`プロンプトエンジニアリング (prompt engineering) là kỹ thuật thiết kế nội dung, cấu trúc và điều kiện của chỉ thị hoặc câu hỏi đưa vào mô hình như Generative AI nhằm thu được đầu ra phù hợp với mục đích. Việc nêu rõ mục tiêu, điều kiện và định dạng đầu ra giúp mô hình dễ tạo câu trả lời mong muốn hơn.`},{type:`example`,ja:`例えば、「ネットワークについて説明して」だけでなく、「基本情報技術者試験の学習者向けに、LANとWANの違いを表で説明して」のように、対象、内容、出力形式を具体化すると目的に合った回答を得やすくなる。`,vi:`Ví dụ, thay vì chỉ yêu cầu “hãy giải thích về mạng”, có thể chỉ rõ “hãy giải thích sự khác nhau giữa LAN và WAN bằng bảng dành cho người học FE”. Việc xác định đối tượng, nội dung và định dạng giúp tăng khả năng nhận được câu trả lời phù hợp.`},{type:`heading`,ja:`中間言語`,vi:`Ngôn ngữ trung gian`},{type:`paragraph`,ja:`中間言語は、ソースプログラムを最終的な機械語などへ変換する途中で用いられる中間的な表現である。コンパイラなどがソースコードを中間表現へ変換し、その後に対象環境向けのコードへ変換することで、最適化や移植性の向上などに役立てることができる。`,vi:`中間言語 (intermediate language) là dạng biểu diễn trung gian được sử dụng trong quá trình chuyển chương trình nguồn thành dạng cuối cùng như mã máy. Compiler có thể chuyển source code sang biểu diễn trung gian rồi tiếp tục chuyển sang mã phù hợp với môi trường đích, qua đó hỗ trợ tối ưu hóa và nâng cao tính khả chuyển.`},{type:`example`,ja:`Javaでは、Javaのソースコードをコンパイルするとバイトコードが生成され、Java仮想マシン（JVM）がそれを実行する。このバイトコードは中間的なコードとして機能する。`,vi:`Trong Java, source code Java được biên dịch thành bytecode và Java Virtual Machine (JVM) thực thi bytecode đó. Bytecode đóng vai trò là một dạng mã trung gian.`},{type:`heading`,ja:`目的プログラム`,vi:`Chương trình đích`},{type:`paragraph`,ja:`目的プログラムは、コンパイラやアセンブラなどによって原始プログラムから変換されて得られるプログラムである。一般に機械語などの目的コードから構成されるが、そのまま単独で実行できるとは限らず、必要に応じてリンカによる結合などを経て実行可能なプログラムとなる。`,vi:`目的プログラム (object program) là chương trình thu được sau khi compiler hoặc assembler chuyển đổi từ chương trình nguồn. Nó thường gồm object code như mã máy, nhưng không nhất thiết có thể chạy trực tiếp; tùy trường hợp còn cần linker liên kết với các module hoặc thư viện khác để tạo chương trình thực thi.`},{type:`warning`,ja:`目的プログラムを必ず「そのまま実行できる実行ファイル」と考えない。コンパイルによって生成された目的プログラムが、リンク処理を経て実行可能プログラムになる場合がある。`,vi:`Không nên hiểu 目的プログラム lúc nào cũng là “file thực thi có thể chạy ngay”. Chương trình đích được tạo bởi quá trình biên dịch có thể còn phải trải qua bước liên kết (link) trước khi trở thành chương trình thực thi.`},{type:`point`,ja:`FEでは、プログラム変換の関係を「原始プログラム（ソース）→ コンパイラなどによる変換 → 中間言語や目的プログラム → 必要に応じてリンク → 実行可能プログラム」のように整理すると理解しやすい。`,vi:`Khi học FE, có thể hình dung luồng chuyển đổi chương trình theo dạng: “chương trình nguồn (source) → compiler và các công cụ chuyển đổi → ngôn ngữ trung gian hoặc chương trình đích → liên kết nếu cần → chương trình thực thi”.`}],terms:[{term:`自己教師あり学習`,reading:`じこきょうしありがくしゅう`,english:`Self-Supervised Learning`,vi:`học tự giám sát`,definitionJa:`ラベル付けされていない入力データ自身から学習用の教師信号を作り、それを利用して学習する機械学習の方法。`,definitionVi:`Phương pháp Machine Learning tự tạo tín hiệu giám sát từ chính dữ liệu đầu vào chưa được gắn nhãn rồi sử dụng tín hiệu đó để học.`},{term:`プロンプトエンジニアリング`,reading:`プロンプトエンジニアリング`,english:`Prompt Engineering`,vi:`kỹ thuật thiết kế prompt`,definitionJa:`生成AIなどから目的に合った出力を得るために、入力する指示や質問の内容、構造、条件などを設計する技術。`,definitionVi:`Kỹ thuật thiết kế nội dung, cấu trúc và điều kiện của prompt nhằm thu được đầu ra phù hợp với mục đích từ các mô hình như Generative AI.`},{term:`中間言語`,reading:`ちゅうかんげんご`,english:`Intermediate Language`,vi:`ngôn ngữ trung gian`,definitionJa:`ソースプログラムを最終的なコードへ変換する途中で用いられる中間的な表現。`,definitionVi:`Dạng biểu diễn trung gian được sử dụng trong quá trình chuyển chương trình nguồn thành mã đích cuối cùng.`},{term:`目的プログラム`,reading:`もくてきプログラム`,english:`Object Program`,vi:`chương trình đích`,definitionJa:`コンパイラやアセンブラなどによって原始プログラムから変換されて得られるプログラム。`,definitionVi:`Chương trình thu được sau khi chương trình nguồn được compiler, assembler hoặc công cụ tương ứng chuyển đổi.`}],tags:[`information-theory`,`artificial-intelligence`,`self-supervised-learning`,`prompt-engineering`,`compiler`,`intermediate-language`,`object-program`]},{id:`formal-language-and-programming-paradigms`,order:16,titleJa:`形式言語とプログラミング言語の基本概念`,titleVi:`Ngôn ngữ hình thức và các khái niệm cơ bản về ngôn ngữ lập trình`,importance:`medium`,summaryJa:`形式言語とオートマトンの基本的な関係、および手続型言語とオブジェクト指向言語の特徴を理解する。形式言語は規則に基づいて文字列を定義する考え方であり、オートマトンは文字列を状態遷移によって処理する計算モデルである。また、プログラムの記述方法として、処理手順を中心とする手続型と、データと操作をオブジェクトとしてまとめるオブジェクト指向の違いを整理する。`,summaryVi:`Tìm hiểu mối quan hệ cơ bản giữa ngôn ngữ hình thức và automaton, đồng thời phân biệt đặc điểm của ngôn ngữ thủ tục và ngôn ngữ hướng đối tượng. Ngôn ngữ hình thức định nghĩa các chuỗi theo những quy tắc xác định, còn automaton là mô hình tính toán xử lý chuỗi thông qua sự chuyển trạng thái. Trong lập trình, ngôn ngữ thủ tục tập trung vào trình tự xử lý, trong khi ngôn ngữ hướng đối tượng tổ chức dữ liệu và thao tác thành các đối tượng.`,content:[{type:`heading`,ja:`形式言語とオートマトン`,vi:`Ngôn ngữ hình thức và automaton`},{type:`paragraph`,ja:`形式言語は、使用できる記号と文法などの規則によって厳密に定義される言語である。自然言語とは異なり、構文を形式的に扱えるため、プログラミング言語の構文解析や計算理論などの基礎となる。`,vi:`形式言語 (formal language) là ngôn ngữ được định nghĩa chặt chẽ bằng tập ký hiệu và các quy tắc như văn phạm. Khác với ngôn ngữ tự nhiên, cú pháp của nó có thể được xử lý một cách hình thức, vì vậy đây là cơ sở của phân tích cú pháp ngôn ngữ lập trình và lý thuyết tính toán.`},{type:`paragraph`,ja:`オートマトンは、入力を受け取り、現在の状態と入力に応じて状態を遷移させる抽象的な計算モデルである。形式言語との関係では、与えられた文字列が特定の言語に属するかどうかを判定するモデルとして考えることができる。`,vi:`オートマトン (automaton) là mô hình tính toán trừu tượng nhận đầu vào và chuyển trạng thái dựa trên trạng thái hiện tại cùng dữ liệu đầu vào. Trong mối quan hệ với formal language, automaton có thể được dùng để xác định một chuỗi cho trước có thuộc một ngôn ngữ nhất định hay không.`},{type:`example`,ja:`有限オートマトンでは、有限個の状態と状態遷移規則を用いて入力文字列を順番に読み取り、最後に到達した状態などによって文字列を受理するかどうかを判定する。`,vi:`Với finite automaton, hệ thống sử dụng một số hữu hạn trạng thái và các quy tắc chuyển trạng thái để đọc lần lượt chuỗi đầu vào, sau đó dựa vào trạng thái đạt được để xác định chuỗi có được chấp nhận hay không.`},{type:`point`,ja:`FEでは、「形式言語＝規則によって定義された文字列の集合」「オートマトン＝状態遷移によって入力を処理するモデル」という対応を押さえると理解しやすい。`,vi:`Trong FE, nên ghi nhớ mối quan hệ: 「形式言語 = tập hợp các chuỗi được xác định bởi quy tắc」 và 「オートマトン = mô hình xử lý đầu vào bằng chuyển trạng thái」.`},{type:`heading`,ja:`手続型言語`,vi:`Ngôn ngữ thủ tục`},{type:`paragraph`,ja:`手続型言語は、目的の処理を実現するための手順を、命令や手続きの流れとして記述するプログラミング言語である。変数への代入、条件分岐、繰返し、関数や手続きの呼出しなどを組み合わせ、処理の順序を明確に記述する。`,vi:`手続型言語 (procedural language) là ngôn ngữ lập trình mô tả các bước cần thực hiện dưới dạng luồng lệnh và thủ tục. Chương trình kết hợp các thao tác như gán biến, rẽ nhánh điều kiện, lặp và gọi hàm hoặc thủ tục để thể hiện rõ trình tự xử lý.`},{type:`example`,ja:`例えば、入力値を読み込み、条件を判定し、必要な計算を行って結果を出力するという一連の処理を順序立てて記述する。Cなどは手続型の考え方を理解する代表的な言語である。`,vi:`Ví dụ, chương trình có thể được mô tả theo trình tự: đọc dữ liệu đầu vào → kiểm tra điều kiện → thực hiện phép tính cần thiết → xuất kết quả. C là một ngôn ngữ tiêu biểu để hiểu cách tiếp cận lập trình thủ tục.`},{type:`heading`,ja:`オブジェクト指向言語`,vi:`Ngôn ngữ hướng đối tượng`},{type:`paragraph`,ja:`オブジェクト指向言語は、データとそのデータに対する操作をオブジェクトという単位で捉えてプログラムを構成する言語である。一般に、クラスを設計し、そのクラスを基に具体的なオブジェクトであるインスタンスを生成して処理を行う。`,vi:`オブジェクト指向言語 (object-oriented language) là ngôn ngữ tổ chức chương trình dựa trên các đối tượng, trong đó dữ liệu và các thao tác liên quan đến dữ liệu được xem xét cùng nhau. Thông thường, lập trình viên định nghĩa class rồi tạo các instance cụ thể từ class để thực hiện xử lý.`},{type:`point`,ja:`手続型では「どのような手順で処理するか」に重点を置くのに対し、オブジェクト指向では「どのオブジェクトがどのデータと操作を持つか」という単位でシステムを構成する。この違いを区別して覚えることが重要である。`,vi:`Lập trình thủ tục tập trung vào “xử lý theo những bước nào”, còn lập trình hướng đối tượng tổ chức hệ thống theo “đối tượng nào sở hữu dữ liệu và thao tác nào”. Đây là điểm khác biệt quan trọng cần phân biệt.`},{type:`warning`,ja:`形式言語と手続型言語・オブジェクト指向言語は分類の観点が異なる。形式言語は記号列と規則を形式的に扱う概念であり、手続型やオブジェクト指向は主にプログラムをどのような考え方で構成するかを表す。`,vi:`形式言語 và các khái niệm 手続型言語・オブジェクト指向言語 không nằm trên cùng một tiêu chí phân loại. Formal language là khái niệm xử lý chuỗi ký hiệu và quy tắc một cách hình thức, còn procedural và object-oriented chủ yếu mô tả cách tổ chức chương trình.`}],terms:[{term:`形式言語`,reading:`けいしきげんご`,english:`Formal Language`,vi:`ngôn ngữ hình thức`,definitionJa:`有限個の記号からなる文字列について、文法などの形式的な規則によって定義される言語。`,definitionVi:`Ngôn ngữ được định nghĩa bằng các quy tắc hình thức như văn phạm đối với các chuỗi được tạo từ một tập hữu hạn ký hiệu.`},{term:`オートマトン`,reading:`オートマトン`,english:`Automaton`,vi:`automaton; máy trạng thái trừu tượng`,definitionJa:`入力と現在の状態に応じて状態を遷移させ、入力を処理する抽象的な計算モデル。`,definitionVi:`Mô hình tính toán trừu tượng xử lý đầu vào bằng cách chuyển trạng thái dựa trên đầu vào và trạng thái hiện tại.`},{term:`手続型言語`,reading:`てつづきがたげんご`,english:`Procedural Language`,vi:`ngôn ngữ thủ tục`,definitionJa:`処理の手順や命令の実行順序を中心としてプログラムを記述するプログラミング言語。`,definitionVi:`Ngôn ngữ lập trình mô tả chương trình chủ yếu dựa trên các bước xử lý và thứ tự thực hiện các lệnh.`},{term:`オブジェクト指向言語`,reading:`オブジェクトしこうげんご`,english:`Object-Oriented Language`,vi:`ngôn ngữ hướng đối tượng`,definitionJa:`データとそのデータに対する操作をオブジェクトとして捉え、それらを組み合わせてプログラムを構成する言語。`,definitionVi:`Ngôn ngữ tổ chức chương trình bằng các đối tượng, trong đó dữ liệu và các thao tác đối với dữ liệu được kết hợp và quản lý theo đơn vị đối tượng.`}],tags:[`formal-language`,`automaton`,`procedural-programming`,`object-oriented-programming`,`programming-language`]}]},d={id:`communication-theory`,order:4,titleJa:`通信に関する理論`,titleVi:`Lý thuyết về truyền thông`,syllabus:`9.2`,lessons:[{id:`communication-direction`,order:1,titleJa:`通信方向と通信方式`,titleVi:`Hướng truyền và phương thức truyền thông`,importance:`high`,summaryJa:`データ通信における情報の流れる方向について、単方向と半二重の違いを理解する。単方向は一方向にだけ情報を送る方式であり、半二重は双方向に通信できるが、同時には送受信できない方式である。`,summaryVi:`Tìm hiểu hướng truyền thông tin trong truyền dữ liệu và phân biệt 単方向 với 半二重. 単方向 chỉ cho phép truyền thông tin theo một hướng, còn 半二重 cho phép truyền theo cả hai hướng nhưng không thể gửi và nhận đồng thời.`,content:[{type:`heading`,ja:`単方向`,vi:`Truyền một chiều`},{type:`paragraph`,ja:`単方向は、情報を一方向にだけ送る通信方式である。送信側と受信側の役割が決まっており、受信側から送信側へ同じ通信路を使って情報を送り返すことはできない。`,vi:`単方向 là phương thức truyền thông trong đó thông tin chỉ được truyền theo một hướng. Vai trò bên gửi và bên nhận được xác định rõ, bên nhận không thể sử dụng cùng kênh truyền để gửi thông tin ngược lại cho bên gửi.`},{type:`point`,ja:`FEでは「一方向にのみ通信する」という特徴を押さえる。双方向通信が必要な半二重や全二重とは区別する。`,vi:`Trong FE, điểm quan trọng nhất là nhớ rằng dữ liệu chỉ truyền theo một hướng. Cần phân biệt với 半二重 và 全二重 là các phương thức cho phép truyền hai chiều.`},{type:`heading`,ja:`半二重`,vi:`Truyền bán song công`},{type:`paragraph`,ja:`半二重は、双方が送信と受信を行えるが、同時に送受信することはできない通信方式である。一方が送信している間、もう一方は受信側となり、通信方向を交互に切り替えて情報をやり取りする。`,vi:`半二重 là phương thức trong đó cả hai phía đều có thể gửi và nhận, nhưng không thể gửi và nhận đồng thời. Khi một phía đang gửi thì phía còn lại nhận, sau đó hai phía có thể đổi hướng truyền cho nhau.`},{type:`example`,ja:`トランシーバのように、一方が話している間はもう一方が聞き、交互に通信する方式は半二重のイメージとして理解しやすい。`,vi:`Có thể hình dung 半二重 giống bộ đàm: khi một người đang nói thì người kia nghe, sau đó hai bên đổi lượt cho nhau.`},{type:`warning`,ja:`半二重と全二重を混同しない。半二重は双方向通信が可能だが同時送受信はできない。全二重では双方が同時に送受信できる。`,vi:`Không nhầm 半二重 với 全二重. 半二重 cho phép truyền hai chiều nhưng không đồng thời; 全二重 cho phép hai phía gửi và nhận cùng lúc.`},{type:`point`,ja:`覚え方：単方向＝一方向だけ、半二重＝双方向だが交互、全二重＝双方向かつ同時。`,vi:`Cách nhớ: 単方向 = chỉ một hướng; 半二重 = hai hướng nhưng luân phiên; 全二重 = hai hướng và đồng thời.`}],terms:[{term:`単方向`,reading:`たんほうこう`,english:`Simplex Communication`,vi:`truyền thông một chiều`,definitionJa:`送信側から受信側への一方向にだけ情報を伝送する通信方式。`,definitionVi:`Phương thức truyền thông trong đó thông tin chỉ được truyền theo một hướng từ bên gửi đến bên nhận.`},{term:`半二重`,reading:`はんにじゅう`,english:`Half-Duplex Communication`,vi:`truyền thông bán song công`,definitionJa:`双方が送受信できるが、同時には送信と受信を行えず、通信方向を交互に切り替える方式。`,definitionVi:`Phương thức cho phép cả hai phía gửi và nhận nhưng không đồng thời; hướng truyền phải được luân phiên chuyển đổi.`}],tags:[`communication-theory`,`communication-direction`,`simplex`,`half-duplex`]},{id:`full-duplex-and-modulation`,order:2,titleJa:`全二重通信と変調方式`,titleVi:`Truyền song công và các phương thức điều chế`,importance:`high`,summaryJa:`全二重通信の特徴と、アナログ変調の基本であるAM・FM・PMを理解する。全二重では双方が同時に送受信できる。AM・FM・PMは、搬送波の振幅・周波数・位相のいずれを変化させるかによって区別される。`,summaryVi:`Tìm hiểu đặc điểm của truyền thông song công toàn phần và ba phương thức điều chế cơ bản AM, FM, PM. 全二重 cho phép hai phía gửi và nhận đồng thời. AM, FM và PM được phân biệt dựa trên đại lượng của sóng mang được thay đổi: biên độ, tần số hay pha.`,content:[{type:`heading`,ja:`全二重`,vi:`Truyền song công toàn phần`},{type:`paragraph`,ja:`全二重は、通信する双方が同時に送信と受信を行える通信方式である。一方が送信している間も、もう一方からの情報を受信できるため、双方向でリアルタイムに情報をやり取りする通信に適している。`,vi:`全二重 là phương thức truyền thông trong đó hai phía có thể gửi và nhận dữ liệu cùng lúc. Ngay cả khi một phía đang gửi, phía đó vẫn có thể nhận thông tin từ phía còn lại, vì vậy phương thức này phù hợp với truyền thông hai chiều theo thời gian thực.`},{type:`point`,ja:`通信方向は、単方向・半二重・全二重を区別して覚える。単方向は一方向のみ、半二重は双方向だが同時送受信不可、全二重は双方向かつ同時送受信可能である。`,vi:`Cần phân biệt ba kiểu hướng truyền: 単方向 chỉ truyền một chiều; 半二重 truyền được hai chiều nhưng không đồng thời; 全二重 truyền hai chiều và có thể gửi nhận đồng thời.`},{type:`heading`,ja:`AM・FM・PM`,vi:`Điều chế AM, FM và PM`},{type:`paragraph`,ja:`変調では、情報を伝送するために搬送波の性質を情報信号に応じて変化させる。AM・FM・PMの基本的な違いは、搬送波のどの要素を変化させるかにある。`,vi:`Trong điều chế, một đặc tính của sóng mang (搬送波) được thay đổi theo tín hiệu thông tin để truyền dữ liệu. Điểm khác nhau cơ bản giữa AM, FM và PM nằm ở đặc tính nào của sóng mang được thay đổi.`},{type:`point`,ja:`AMは振幅、FMは周波数、PMは位相を変化させる。この対応関係はFEで最も重要なポイントの一つである。`,vi:`AM thay đổi biên độ, FM thay đổi tần số, PM thay đổi pha. Đây là mối quan hệ quan trọng cần ghi nhớ khi học FE.`},{type:`heading`,ja:`AM`,vi:`Điều chế biên độ`},{type:`paragraph`,ja:`AM（Amplitude Modulation）は、情報信号に応じて搬送波の振幅を変化させる方式である。周波数や位相ではなく、波の大きさに相当する振幅を変えることが特徴である。`,vi:`AM (Amplitude Modulation) là phương thức thay đổi biên độ của sóng mang theo tín hiệu thông tin. Đặc trưng của AM là thay đổi độ lớn của sóng, tức biên độ, chứ không phải tần số hay pha.`},{type:`heading`,ja:`FM`,vi:`Điều chế tần số`},{type:`paragraph`,ja:`FM（Frequency Modulation）は、情報信号に応じて搬送波の周波数を変化させる方式である。AMとは異なり、基本的には振幅ではなく周波数の変化によって情報を表現する。`,vi:`FM (Frequency Modulation) là phương thức thay đổi tần số của sóng mang theo tín hiệu thông tin. Khác với AM, thông tin được biểu diễn bằng sự thay đổi tần số thay vì thay đổi biên độ.`},{type:`heading`,ja:`PM`,vi:`Điều chế pha`},{type:`paragraph`,ja:`PM（Phase Modulation）は、情報信号に応じて搬送波の位相を変化させる方式である。位相とは波の周期上の位置を表すものであり、その変化を利用して情報を伝える。`,vi:`PM (Phase Modulation) là phương thức thay đổi pha của sóng mang theo tín hiệu thông tin. Pha biểu thị vị trí của sóng trong một chu kỳ, và PM sử dụng sự thay đổi này để truyền thông tin.`},{type:`example`,ja:`覚え方：AM＝Amplitude＝振幅、FM＝Frequency＝周波数、PM＝Phase＝位相。`,vi:`Cách nhớ: AM = Amplitude = biên độ (振幅), FM = Frequency = tần số (周波数), PM = Phase = pha (位相).`},{type:`warning`,ja:`AM・FM・PMでは、変化させる量を取り違えないことが重要である。特にFMのFはFrequency（周波数）、PMのPはPhase（位相）を表す。`,vi:`Điểm dễ nhầm là đại lượng được thay đổi trong AM, FM và PM. Đặc biệt, F trong FM là Frequency (周波数), còn P trong PM là Phase (位相).`}],terms:[{term:`全二重`,reading:`ぜんにじゅう`,english:`Full-Duplex Communication`,vi:`truyền thông song công toàn phần`,definitionJa:`通信する双方が同時に送信と受信を行うことができる通信方式。`,definitionVi:`Phương thức truyền thông cho phép cả hai phía gửi và nhận dữ liệu đồng thời.`},{term:`AM`,reading:`エーエム`,english:`Amplitude Modulation`,vi:`điều chế biên độ`,definitionJa:`情報信号に応じて搬送波の振幅を変化させる変調方式。`,definitionVi:`Phương thức điều chế thay đổi biên độ của sóng mang theo tín hiệu thông tin.`},{term:`FM`,reading:`エフエム`,english:`Frequency Modulation`,vi:`điều chế tần số`,definitionJa:`情報信号に応じて搬送波の周波数を変化させる変調方式。`,definitionVi:`Phương thức điều chế thay đổi tần số của sóng mang theo tín hiệu thông tin.`},{term:`PM`,reading:`ピーエム`,english:`Phase Modulation`,vi:`điều chế pha`,definitionJa:`情報信号に応じて搬送波の位相を変化させる変調方式。`,definitionVi:`Phương thức điều chế thay đổi pha của sóng mang theo tín hiệu thông tin.`}],tags:[`communication-theory`,`full-duplex`,`modulation`,`am`,`fm`,`pm`]},{id:`digital-conversion-multiplexing-and-error-detection`,order:3,titleJa:`PCM・多重化・誤り検出`,titleVi:`PCM, ghép kênh và phát hiện lỗi`,importance:`high`,summaryJa:`通信で用いられるPCM、FDM、TDM、CRCの基本的な仕組みを理解する。PCMはアナログ信号をデジタル化する方式、FDMとTDMは一つの伝送路を複数の信号で共有する多重化方式、CRCは伝送データの誤りを検出する方式である。`,summaryVi:`Tìm hiểu cơ chế cơ bản của PCM, FDM, TDM và CRC trong truyền thông. PCM dùng để số hóa tín hiệu analog; FDM và TDM là các phương thức ghép kênh cho phép nhiều tín hiệu dùng chung một đường truyền; CRC dùng để phát hiện lỗi trong dữ liệu truyền.`,content:[{type:`heading`,ja:`PCM`,vi:`Điều chế mã xung PCM`},{type:`paragraph`,ja:`PCM（Pulse Code Modulation）は、音声などのアナログ信号をデジタルデータとして表現するための方式である。連続的なアナログ信号を一定の時間間隔で取り出し、その値を段階的な数値に対応させ、2進数などの符号として表現する。`,vi:`PCM (Pulse Code Modulation) là phương thức biểu diễn tín hiệu analog như âm thanh dưới dạng dữ liệu số. Tín hiệu analog liên tục được lấy giá trị theo các khoảng thời gian nhất định, sau đó giá trị được đưa về các mức rời rạc và biểu diễn bằng mã số như số nhị phân.`},{type:`point`,ja:`PCMの基本的な流れは「標本化（サンプリング）→量子化→符号化」である。この順序はFEで重要である。`,vi:`Quy trình cơ bản của PCM là 「標本化 (lấy mẫu) → 量子化 (lượng tử hóa) → 符号化 (mã hóa)」. Đây là thứ tự quan trọng cần nhớ trong FE.`},{type:`example`,ja:`音声をPCMでデジタル化する場合、一定時間ごとに信号の値を測定し、その値を最も近い量子化レベルに対応させ、最後にビット列として表現する。`,vi:`Khi số hóa âm thanh bằng PCM, hệ thống đo giá trị tín hiệu theo từng khoảng thời gian, đưa giá trị đó về mức lượng tử gần nhất rồi cuối cùng biểu diễn thành chuỗi bit.`},{type:`heading`,ja:`FDMとTDM`,vi:`Ghép kênh FDM và TDM`},{type:`paragraph`,ja:`多重化は、一つの伝送路を複数の信号で共有して通信効率を高めるための技術である。FDMは周波数を分割し、TDMは時間を分割することで、複数の信号を同じ伝送路で扱う。`,vi:`Ghép kênh là kỹ thuật cho phép nhiều tín hiệu dùng chung một đường truyền nhằm nâng cao hiệu quả truyền thông. FDM chia tài nguyên theo tần số, còn TDM chia theo thời gian để truyền nhiều tín hiệu trên cùng một đường truyền.`},{type:`point`,ja:`FDM＝周波数を分ける、TDM＝時間を分ける、という違いを明確に覚える。`,vi:`Cần nhớ rõ: FDM = chia theo tần số, TDM = chia theo thời gian.`},{type:`heading`,ja:`FDM`,vi:`Ghép kênh phân chia theo tần số`},{type:`paragraph`,ja:`FDM（Frequency Division Multiplexing）は、利用可能な周波数帯域を複数に分割し、それぞれに異なる信号を割り当てて同時に伝送する方式である。各信号が異なる周波数帯域を使用することで、一つの伝送路を複数の通信で共有できる。`,vi:`FDM (Frequency Division Multiplexing) chia dải tần khả dụng thành nhiều phần và gán mỗi tín hiệu vào một dải tần khác nhau để truyền đồng thời. Nhờ các tín hiệu sử dụng những vùng tần số riêng, nhiều kênh truyền có thể dùng chung một đường truyền.`},{type:`heading`,ja:`TDM`,vi:`Ghép kênh phân chia theo thời gian`},{type:`paragraph`,ja:`TDM（Time Division Multiplexing）は、伝送時間を複数の時間枠に分割し、それぞれの信号に順番に時間枠を割り当てる方式である。各信号は割り当てられた時間にデータを送ることで、一つの伝送路を共有する。`,vi:`TDM (Time Division Multiplexing) chia thời gian truyền thành nhiều khe thời gian và lần lượt phân bổ các khe này cho từng tín hiệu. Mỗi tín hiệu gửi dữ liệu trong khoảng thời gian được cấp, nhờ đó nhiều tín hiệu có thể dùng chung một đường truyền.`},{type:`example`,ja:`FDMではA・B・Cの通信に異なる周波数帯を同時に割り当てる。一方、TDMではA→B→C→A…のように時間を区切って順番に伝送するイメージで考えると分かりやすい。`,vi:`Có thể hình dung FDM là A, B, C được cấp các dải tần khác nhau và truyền đồng thời; còn TDM là chia thời gian và lần lượt truyền theo kiểu A → B → C → A…`},{type:`heading`,ja:`CRC`,vi:`Kiểm tra dư thừa tuần hoàn CRC`},{type:`paragraph`,ja:`CRC（Cyclic Redundancy Check）は、データの伝送や保存で発生した誤りを検出するための方式である。送信側ではデータを所定の生成多項式に基づいて計算し、その結果から得られる検査用の値をデータに付加する。受信側では同じ規則で検査し、誤りの有無を判断する。`,vi:`CRC (Cyclic Redundancy Check) là phương thức dùng để phát hiện lỗi xảy ra khi truyền hoặc lưu trữ dữ liệu. Phía gửi thực hiện phép tính dựa trên đa thức sinh đã quy định và thêm giá trị kiểm tra thu được vào dữ liệu. Phía nhận kiểm tra lại theo cùng quy tắc để xác định dữ liệu có lỗi hay không.`},{type:`point`,ja:`CRCの目的は基本的に誤りの「検出」であり、CRC値だけを使って誤りを訂正する方式ではない。`,vi:`Mục đích cơ bản của CRC là “phát hiện” lỗi. Chỉ riêng giá trị CRC không phải là cơ chế dùng để sửa lỗi.`},{type:`warning`,ja:`FDMとFMを混同しない。FDMは複数の信号を周波数帯域に分ける多重化方式であり、FMは搬送波の周波数を変化させる変調方式である。`,vi:`Không nhầm FDM với FM. FDM là phương thức ghép kênh bằng cách chia dải tần cho nhiều tín hiệu, còn FM là phương thức điều chế bằng cách thay đổi tần số của sóng mang.`}],terms:[{term:`PCM`,reading:`ピーシーエム`,english:`Pulse Code Modulation`,vi:`điều chế mã xung`,definitionJa:`アナログ信号を標本化・量子化・符号化してデジタルデータとして表現する方式。`,definitionVi:`Phương thức biểu diễn tín hiệu analog thành dữ liệu số thông qua lấy mẫu, lượng tử hóa và mã hóa.`},{term:`FDM`,reading:`エフディーエム`,english:`Frequency Division Multiplexing`,vi:`ghép kênh phân chia theo tần số`,definitionJa:`周波数帯域を複数に分割し、異なる信号をそれぞれの帯域に割り当てて多重化する方式。`,definitionVi:`Phương thức ghép kênh chia dải tần thành nhiều phần và gán các tín hiệu khác nhau vào từng dải tần.`},{term:`TDM`,reading:`ティーディーエム`,english:`Time Division Multiplexing`,vi:`ghép kênh phân chia theo thời gian`,definitionJa:`伝送時間を複数の時間枠に分割し、各信号に時間枠を割り当てて多重化する方式。`,definitionVi:`Phương thức ghép kênh chia thời gian truyền thành các khe thời gian và phân bổ chúng cho từng tín hiệu.`},{term:`CRC`,reading:`シーアールシー`,english:`Cyclic Redundancy Check`,vi:`kiểm tra dư thừa tuần hoàn`,definitionJa:`生成多項式を用いた計算によって検査値を求め、データの伝送や保存時に生じた誤りを検出する方式。`,definitionVi:`Phương thức tính giá trị kiểm tra dựa trên đa thức sinh để phát hiện lỗi phát sinh trong quá trình truyền hoặc lưu trữ dữ liệu.`}],tags:[`communication-theory`,`pcm`,`multiplexing`,`fdm`,`tdm`,`error-detection`,`crc`]},{id:`error-detection-and-correction`,order:4,titleJa:`誤り検出と誤り訂正`,titleVi:`Phát hiện và sửa lỗi dữ liệu`,importance:`high`,summaryJa:`通信やデータ保存で発生する誤りに対して、ハミング符号、パリティチェック、ECC、チェックサムがどのように誤りを検出・訂正するかを理解する。特に、誤りを検出するだけの方式と、誤りを訂正できる方式の違いが重要である。`,summaryVi:`Tìm hiểu cách Hamming Code, Parity Check, ECC và Checksum xử lý lỗi phát sinh trong quá trình truyền hoặc lưu trữ dữ liệu. Đặc biệt cần phân biệt phương thức chỉ phát hiện lỗi với phương thức có khả năng sửa lỗi.`,content:[{type:`heading`,ja:`誤り検出と誤り訂正`,vi:`Phát hiện lỗi và sửa lỗi`},{type:`paragraph`,ja:`通信やデータ保存では、ノイズや障害などによってデータの一部が変化することがある。そのため、元のデータに検査用の情報を付加し、受信側や読出し側で誤りを検出する仕組みが利用される。方式によっては、誤りを検出するだけでなく、その位置を特定して訂正することもできる。`,vi:`Trong truyền thông và lưu trữ dữ liệu, một phần dữ liệu có thể bị thay đổi do nhiễu hoặc sự cố. Vì vậy, thông tin kiểm tra được bổ sung vào dữ liệu gốc để phía nhận hoặc phía đọc có thể phát hiện lỗi. Một số phương thức không chỉ phát hiện mà còn có thể xác định vị trí và sửa lỗi.`},{type:`heading`,ja:`ハミング符号`,vi:`Mã Hamming`},{type:`paragraph`,ja:`ハミング符号は、データ中の特定の位置に検査用のビットを配置し、その組合せから誤りの位置を特定する誤り訂正符号である。基本的なハミング符号では、1ビットの誤りを訂正することができる。`,vi:`Mã Hamming là mã sửa lỗi đặt các bit kiểm tra tại những vị trí xác định trong dữ liệu và sử dụng tổ hợp kết quả kiểm tra để xác định vị trí lỗi. Với mã Hamming cơ bản, có thể sửa lỗi 1 bit.`},{type:`point`,ja:`ハミング符号は、単に誤りの有無を確認するだけでなく、誤ったビットの位置を特定して訂正できる点が重要である。`,vi:`Điểm quan trọng của mã Hamming là không chỉ xác định có lỗi hay không mà còn có thể xác định vị trí bit sai và sửa nó.`},{type:`heading`,ja:`パリティチェック`,vi:`Kiểm tra chẵn lẻ`},{type:`paragraph`,ja:`パリティチェックは、データにパリティビットを付加して誤りを検出する方式である。偶数パリティでは1の個数が偶数になるように、奇数パリティでは1の個数が奇数になるようにパリティビットを設定する。`,vi:`Parity Check là phương thức thêm bit chẵn lẻ vào dữ liệu để phát hiện lỗi. Với parity chẵn, bit parity được đặt sao cho tổng số bit 1 là số chẵn; với parity lẻ, tổng số bit 1 được đặt thành số lẻ.`},{type:`example`,ja:`偶数パリティでデータ部分の1の個数が3個なら、全体の1の個数を偶数にするため、パリティビットを1にする。`,vi:`Với parity chẵn, nếu phần dữ liệu có 3 bit 1 thì bit parity được đặt thành 1 để tổng số bit 1 trở thành số chẵn.`},{type:`warning`,ja:`単純なパリティチェックでは、偶数個のビットが反転すると誤りを検出できない場合がある。また、通常は誤りの位置を特定して訂正することはできない。`,vi:`Với kiểm tra parity đơn giản, nếu một số chẵn bit bị đảo thì có trường hợp không phát hiện được lỗi. Ngoài ra, phương thức này thông thường không xác định được vị trí lỗi để sửa.`},{type:`heading`,ja:`ECC`,vi:`Mã sửa lỗi ECC`},{type:`paragraph`,ja:`ECC（Error Correction Code）は、データに冗長な情報を付加し、保存や伝送の際に発生した誤りを検出・訂正するための符号の総称である。メモリやストレージなど、高い信頼性が必要なシステムで利用される。`,vi:`ECC (Error Correction Code) là tên gọi chung cho các mã bổ sung thông tin dư thừa vào dữ liệu để phát hiện và sửa lỗi phát sinh khi lưu trữ hoặc truyền dữ liệu. ECC được sử dụng trong bộ nhớ, thiết bị lưu trữ và các hệ thống yêu cầu độ tin cậy cao.`},{type:`point`,ja:`ECCは誤り訂正符号の総称であり、ハミング符号はECCを実現する代表的な方式の一つとして理解するとよい。`,vi:`ECC là khái niệm chung về mã sửa lỗi; có thể hiểu mã Hamming là một trong những phương thức tiêu biểu để thực hiện ECC.`},{type:`heading`,ja:`チェックサム`,vi:`Checksum`},{type:`paragraph`,ja:`チェックサムは、データから一定の規則で検査値を計算し、その値を利用してデータの誤りを検出する方式である。送信側で求めたチェックサムと、受信側で同じデータから求めた値を比較することで、データが変化していないかを確認する。`,vi:`Checksum là phương thức tính một giá trị kiểm tra từ dữ liệu theo quy tắc nhất định để phát hiện lỗi. Bằng cách so sánh checksum được tính ở phía gửi với giá trị tính lại từ dữ liệu nhận được, hệ thống có thể kiểm tra dữ liệu có bị thay đổi hay không.`},{type:`point`,ja:`FEでは「パリティチェック・チェックサム＝主に誤り検出」「ハミング符号・ECC＝誤り訂正が可能」という基本的な役割の違いを整理して覚える。`,vi:`Trong FE nên phân biệt vai trò cơ bản: “Parity Check và Checksum = chủ yếu phát hiện lỗi”, còn “Hamming Code và ECC = có khả năng sửa lỗi”.`}],terms:[{term:`ハミング符号`,reading:`ハミングふごう`,english:`Hamming Code`,vi:`mã Hamming`,definitionJa:`検査用の冗長ビットを付加し、誤りの位置を特定して訂正できる誤り訂正符号。`,definitionVi:`Mã sửa lỗi bổ sung các bit dư thừa để xác định vị trí lỗi và thực hiện sửa lỗi.`},{term:`パリティチェック`,reading:`パリティチェック`,english:`Parity Check`,vi:`kiểm tra chẵn lẻ`,definitionJa:`ビット列中の1の個数が偶数または奇数になるようにパリティビットを付加し、誤りを検出する方式。`,definitionVi:`Phương thức thêm bit parity để tổng số bit 1 trở thành số chẵn hoặc số lẻ, qua đó phát hiện lỗi dữ liệu.`},{term:`ECC`,reading:`イーシーシー`,english:`Error Correction Code`,vi:`mã sửa lỗi`,definitionJa:`冗長な情報を付加することで、データに発生した誤りを検出し、訂正するための符号。`,definitionVi:`Mã bổ sung thông tin dư thừa để phát hiện và sửa lỗi xảy ra trong dữ liệu.`},{term:`チェックサム`,reading:`チェックサム`,english:`Checksum`,vi:`tổng kiểm tra`,definitionJa:`データから一定の規則で検査値を計算し、その値を比較することでデータの誤りを検出する方式。`,definitionVi:`Phương thức tính giá trị kiểm tra từ dữ liệu theo quy tắc nhất định và so sánh giá trị đó để phát hiện lỗi.`}],tags:[`communication-theory`,`error-detection`,`error-correction`,`hamming-code`,`parity-check`,`ecc`,`checksum`]},{id:`data-synchronization`,order:5,titleJa:`データ通信の同期方式`,titleVi:`Các phương thức đồng bộ trong truyền dữ liệu`,importance:`high`,summaryJa:`デジタル通信で送信側と受信側のタイミングを合わせるための同期方式について学ぶ。ビット同期、キャラクター同期、フラグ同期、調歩同期の基本的な役割と違いを理解する。`,summaryVi:`Tìm hiểu các phương thức đồng bộ dùng để phối hợp thời điểm xử lý giữa phía gửi và phía nhận trong truyền thông số. Trọng tâm là vai trò và sự khác nhau cơ bản giữa đồng bộ bit, đồng bộ ký tự, đồng bộ bằng cờ và đồng bộ start-stop.`,content:[{type:`heading`,ja:`通信における同期`,vi:`Đồng bộ trong truyền thông`},{type:`paragraph`,ja:`デジタル通信では、受信側が送られてきたビットやデータ単位の境界を正しく認識する必要がある。そのため、送信側と受信側のタイミングやデータの区切りを合わせる同期の仕組みが用いられる。`,vi:`Trong truyền thông số, phía nhận cần nhận biết chính xác ranh giới của các bit và đơn vị dữ liệu được truyền tới. Vì vậy, các cơ chế đồng bộ được sử dụng để thống nhất thời điểm xử lý và ranh giới dữ liệu giữa phía gửi và phía nhận.`},{type:`heading`,ja:`ビット同期`,vi:`Đồng bộ bit`},{type:`paragraph`,ja:`ビット同期は、受信側が各ビットのタイミングや境界を正しく識別するための同期である。ビットの区切りを正しく認識することで、0と1からなるデータを正確に受信できる。`,vi:`Đồng bộ bit giúp phía nhận xác định chính xác thời điểm và ranh giới của từng bit. Khi xác định đúng vị trí phân cách giữa các bit, phía nhận có thể tiếp nhận chính xác dữ liệu gồm các bit 0 và 1.`},{type:`point`,ja:`ビット同期では「どこまでが一つのビットか」を受信側が正しく判断できることが重要である。`,vi:`Điểm quan trọng của đồng bộ bit là phía nhận phải xác định chính xác phạm vi của từng bit.`},{type:`heading`,ja:`キャラクター同期`,vi:`Đồng bộ ký tự`},{type:`paragraph`,ja:`キャラクター同期は、連続して送られるビット列の中から文字やデータ単位の区切りを識別するための同期方式である。受信側が文字の開始位置と終了位置を認識できるようにする。`,vi:`Đồng bộ ký tự là phương thức giúp xác định ranh giới của ký tự hoặc đơn vị dữ liệu trong chuỗi bit được truyền liên tục. Nhờ đó phía nhận có thể nhận biết vị trí bắt đầu và kết thúc của từng ký tự.`},{type:`heading`,ja:`フラグ同期`,vi:`Đồng bộ bằng cờ`},{type:`paragraph`,ja:`フラグ同期は、特定のビットパターンであるフラグをデータの区切りとして利用する同期方式である。受信側はフラグを検出することで、フレームなどのデータ単位の開始や終了を認識する。`,vi:`Đồng bộ bằng cờ sử dụng một mẫu bit đặc biệt gọi là flag để đánh dấu ranh giới dữ liệu. Khi phát hiện flag, phía nhận có thể xác định điểm bắt đầu hoặc kết thúc của một đơn vị dữ liệu như frame.`},{type:`point`,ja:`フラグ同期では、フラグとして使用する特定のビットパターンと実際のデータを区別する仕組みが必要になる。`,vi:`Trong đồng bộ bằng cờ, cần có cơ chế phân biệt mẫu bit được dùng làm flag với cùng mẫu bit nếu nó xuất hiện trong dữ liệu thực tế.`},{type:`heading`,ja:`調歩同期`,vi:`Đồng bộ start-stop`},{type:`paragraph`,ja:`調歩同期は、文字などのデータ単位ごとにスタートビットとストップビットを付加して送信する方式である。送信側と受信側が常に共通のクロックで同期し続ける必要がなく、データが送られるたびに受信側がスタートビットを基準としてタイミングを合わせる。`,vi:`Đồng bộ start-stop là phương thức thêm bit start và bit stop vào từng đơn vị dữ liệu như ký tự trước khi truyền. Hai phía không cần duy trì đồng bộ bằng một clock chung liên tục; mỗi khi có dữ liệu, phía nhận căn thời điểm dựa trên bit start.`},{type:`example`,ja:`調歩同期では、一般に「スタートビット → データビット → 必要に応じてパリティビット → ストップビット」という単位で送信する。`,vi:`Trong đồng bộ start-stop, dữ liệu thường được truyền theo đơn vị: “bit start → các bit dữ liệu → bit parity nếu cần → bit stop”.`},{type:`warning`,ja:`ビット同期はビットのタイミングを合わせる考え方であり、調歩同期はデータ単位ごとにスタートビットとストップビットを用いる方式である。両者を同じ意味として覚えないこと。`,vi:`Đồng bộ bit là khái niệm xác định thời điểm và ranh giới của từng bit, còn đồng bộ start-stop là phương thức dùng bit start và bit stop cho từng đơn vị dữ liệu. Không nên ghi nhớ hai khái niệm này là một.`}],terms:[{term:`ビット同期`,reading:`ビットどうき`,english:`Bit Synchronization`,vi:`đồng bộ bit`,definitionJa:`受信側が送信された各ビットのタイミングや境界を正しく識別するための同期。`,definitionVi:`Cơ chế đồng bộ giúp phía nhận xác định chính xác thời điểm và ranh giới của từng bit được truyền.`},{term:`キャラクター同期`,reading:`キャラクターどうき`,english:`Character Synchronization`,vi:`đồng bộ ký tự`,definitionJa:`連続するビット列から文字などのデータ単位の区切りを受信側が識別するための同期方式。`,definitionVi:`Phương thức đồng bộ giúp phía nhận xác định ranh giới của các đơn vị dữ liệu như ký tự trong một chuỗi bit liên tục.`},{term:`フラグ同期`,reading:`フラグどうき`,english:`Flag Synchronization`,vi:`đồng bộ bằng cờ`,definitionJa:`特定のビットパターンであるフラグを用いて、データ単位の開始や終了を識別する同期方式。`,definitionVi:`Phương thức đồng bộ sử dụng một mẫu bit đặc biệt gọi là flag để xác định điểm bắt đầu hoặc kết thúc của đơn vị dữ liệu.`},{term:`調歩同期`,reading:`ちょうほどうき`,english:`Start-Stop Synchronization`,vi:`đồng bộ start-stop`,definitionJa:`データ単位ごとにスタートビットとストップビットを付加し、それらを基準として送受信のタイミングを合わせる方式。`,definitionVi:`Phương thức thêm bit start và bit stop vào từng đơn vị dữ liệu và sử dụng chúng làm mốc để đồng bộ thời điểm gửi nhận.`}],tags:[`communication-theory`,`synchronization`,`bit-synchronization`,`character-synchronization`,`flag-synchronization`,`start-stop-synchronization`]},{id:`transmission-synchronization`,order:6,titleJa:`伝送における同期と制御ビット`,titleVi:`Đồng bộ và bit điều khiển trong truyền dữ liệu`,importance:`high`,summaryJa:`データ伝送における同期のための基本要素として、スタートビット、ストップワードビット、SYN同期、フレーム同期の役割を理解する。受信側がデータの開始・終了やデータ単位の境界を正しく認識する仕組みを整理する。`,summaryVi:`Tìm hiểu vai trò của Start Bit, Stop Word Bit, đồng bộ SYN và đồng bộ frame trong truyền dữ liệu. Trọng tâm là cách phía nhận xác định chính xác điểm bắt đầu, kết thúc và ranh giới của các đơn vị dữ liệu.`,content:[{type:`heading`,ja:`データの区切りと同期`,vi:`Ranh giới dữ liệu và đồng bộ`},{type:`paragraph`,ja:`データ通信では、受信側が送られてきたデータの開始位置や終了位置、データ単位の境界を正しく認識する必要がある。そのため、スタートビットなどの制御情報や、特定の同期用パターンを利用して送信側と受信側のタイミングを合わせる。`,vi:`Trong truyền dữ liệu, phía nhận cần xác định chính xác vị trí bắt đầu, kết thúc và ranh giới của từng đơn vị dữ liệu. Vì vậy, các thông tin điều khiển như Start Bit hoặc các mẫu đồng bộ đặc biệt được sử dụng để phối hợp phía gửi và phía nhận.`},{type:`heading`,ja:`スタートビット`,vi:`Start Bit`},{type:`paragraph`,ja:`スタートビットは、調歩同期などでデータ単位の送信開始を受信側に知らせるために付加されるビットである。受信側はスタートビットを検出すると、それを基準として後続するデータビットを読み取る。`,vi:`Start Bit là bit được thêm vào trong các phương thức như đồng bộ start-stop để báo cho phía nhận biết một đơn vị dữ liệu bắt đầu được truyền. Khi phát hiện Start Bit, phía nhận dùng nó làm mốc để đọc các bit dữ liệu tiếp theo.`},{type:`point`,ja:`調歩同期では、スタートビットがデータ単位の開始を示し、受信側がデータを読み取るタイミングを決める基準となる。`,vi:`Trong đồng bộ start-stop, Start Bit đánh dấu điểm bắt đầu của đơn vị dữ liệu và là mốc để phía nhận xác định thời điểm đọc dữ liệu.`},{type:`heading`,ja:`ストップワードビット`,vi:`Stop Word Bit`},{type:`paragraph`,ja:`ストップワードビットは、データ単位の終了側に置かれ、受信側がデータの終わりを認識するために利用される制御ビットとして扱われる。スタート側の制御ビットと組み合わせることで、データ単位の境界を明確にする。`,vi:`Stop Word Bit được đặt ở phía cuối của một đơn vị dữ liệu và được dùng như bit điều khiển giúp phía nhận nhận biết điểm kết thúc dữ liệu. Khi kết hợp với bit điều khiển ở phía bắt đầu, ranh giới của đơn vị dữ liệu được xác định rõ ràng.`},{type:`warning`,ja:`画像中のストップワードビットの説明には、不要な情報を無視するためのビットであるという記述があるが、この説明は通信同期の文脈とは整合しないため注意する。`,vi:`Phần mô tả Stop Word Bit trong ảnh cho rằng đây là bit dùng để bỏ qua thông tin không cần thiết, nhưng cách giải thích này không phù hợp với ngữ cảnh đồng bộ truyền thông, vì vậy cần thận trọng.`},{type:`heading`,ja:`SYN同期`,vi:`Đồng bộ SYN`},{type:`paragraph`,ja:`SYN同期は、同期用の特定のパターンや同期文字を利用して、受信側が連続するデータの区切りやタイミングを認識するための同期方式として扱われる。同期情報を検出した後、受信側は後続するデータを所定の単位で読み取る。`,vi:`Đồng bộ SYN sử dụng mẫu hoặc ký tự đồng bộ đặc biệt để giúp phía nhận xác định thời điểm và ranh giới trong luồng dữ liệu liên tục. Sau khi phát hiện thông tin đồng bộ, phía nhận đọc phần dữ liệu tiếp theo theo đơn vị quy định.`},{type:`warning`,ja:`ここでいうSYN同期を、TCPのコネクション確立で使用するSYNフラグと混同しないこと。画像中のSYN、SYN-ACK、ACKによる説明はTCPの3ウェイハンドシェイクの説明であり、通信データの同期方式とは別の概念である。`,vi:`Không nhầm SYN synchronization ở đây với cờ SYN dùng khi thiết lập kết nối TCP. Phần SYN → SYN-ACK → ACK trong ảnh mô tả TCP three-way handshake, là một khái niệm khác với phương thức đồng bộ dữ liệu truyền.`},{type:`heading`,ja:`フレーム同期`,vi:`Đồng bộ frame`},{type:`paragraph`,ja:`フレーム同期は、受信したビット列の中からフレームの境界を識別し、各フレームを正しい単位として取り出すための同期である。受信側がフレームの開始位置を正しく認識することで、フレーム単位のデータを適切に処理できる。`,vi:`Đồng bộ frame là cơ chế xác định ranh giới frame trong chuỗi bit nhận được để tách dữ liệu thành đúng từng frame. Khi phía nhận xác định chính xác vị trí bắt đầu frame, dữ liệu có thể được xử lý đúng theo từng đơn vị frame.`},{type:`point`,ja:`FEでは、ビット単位の同期、文字やデータ単位の同期、フレーム単位の同期というように、何の境界を認識するための同期なのかを区別して考えることが重要である。`,vi:`Trong FE, cần phân biệt đối tượng cần đồng bộ: đồng bộ ở mức bit, mức ký tự/đơn vị dữ liệu hay mức frame.`}],terms:[{term:`スタートビット`,reading:`スタートビット`,english:`Start Bit`,vi:`bit bắt đầu`,definitionJa:`調歩同期などで、データ単位の送信開始を受信側に知らせるために付加されるビット。`,definitionVi:`Bit được thêm vào trong các phương thức như đồng bộ start-stop để báo cho phía nhận biết thời điểm bắt đầu của một đơn vị dữ liệu.`},{term:`ストップワードビット`,reading:`ストップワードビット`,english:`Stop Word Bit`,vi:`bit kết thúc từ dữ liệu`,definitionJa:`データ単位の終了を受信側が認識するために、その終了側に置かれる制御ビットとして扱われる。`,definitionVi:`Bit điều khiển được đặt ở cuối đơn vị dữ liệu để phía nhận nhận biết điểm kết thúc của đơn vị đó.`},{term:`SYN同期`,reading:`シンどうき`,english:`SYN Synchronization`,vi:`đồng bộ SYN`,definitionJa:`同期用のパターンや同期文字を利用して、受信側が連続するデータの区切りやタイミングを認識する同期方式。`,definitionVi:`Phương thức sử dụng mẫu hoặc ký tự đồng bộ để phía nhận xác định thời điểm và ranh giới trong luồng dữ liệu liên tục.`},{term:`フレーム同期`,reading:`フレームどうき`,english:`Frame Synchronization`,vi:`đồng bộ frame`,definitionJa:`受信したビット列からフレームの境界を識別し、データを正しいフレーム単位で取り出すための同期。`,definitionVi:`Cơ chế xác định ranh giới frame trong chuỗi bit nhận được để tách và xử lý dữ liệu theo đúng từng frame.`}],tags:[`communication-theory`,`synchronization`,`start-bit`,`syn-synchronization`,`frame-synchronization`]}]},f={id:`measurement-and-control-theory`,order:5,titleJa:`計測・制御に関する理論`,titleVi:`Lý thuyết về đo lường và điều khiển`,syllabus:`9.2`,lessons:[{id:`filtering-and-da-conversion`,order:1,titleJa:`フィルタリングとD/A変換`,titleVi:`Lọc dữ liệu và chuyển đổi D/A`,importance:`high`,summaryJa:`計測・制御で扱う信号処理の基礎として、必要な情報を取り出すフィルタリングと、デジタル信号をアナログ信号へ変換するD/A変換の役割を理解する。`,summaryVi:`Tìm hiểu hai kiến thức cơ bản trong xử lý tín hiệu phục vụ đo lường và điều khiển: Filtering để chọn hoặc loại bỏ thành phần tín hiệu theo điều kiện, và chuyển đổi D/A để biến tín hiệu số thành tín hiệu tương tự.`,content:[{type:`heading`,ja:`フィルタリング`,vi:`Lọc`},{type:`paragraph`,ja:`フィルタリングは、データや信号から特定の条件に合う成分を取り出したり、不要な成分を除去したりする処理である。計測や信号処理では、必要な信号を残し、雑音などの不要な成分を抑えるために利用される。`,vi:`Filtering là quá trình lấy ra các thành phần phù hợp với điều kiện nhất định hoặc loại bỏ các thành phần không cần thiết khỏi dữ liệu hay tín hiệu. Trong đo lường và xử lý tín hiệu, nó được dùng để giữ lại tín hiệu cần thiết và giảm các thành phần không mong muốn như nhiễu.`},{type:`point`,ja:`FEでは、フィルタの種類によって「どの周波数成分を通し、どの周波数成分を除去するか」を判断する問題があるため、通過させる成分と遮断する成分を区別することが重要である。`,vi:`Trong FE, cần chú ý bộ lọc cho thành phần tần số nào đi qua và loại bỏ thành phần nào. Vì vậy phải phân biệt rõ dải tần được truyền qua và dải tần bị chặn.`},{type:`example`,ja:`例えば、計測した信号に不要な高周波ノイズが含まれている場合、必要な低周波成分を残しながら高周波成分を抑えるフィルタを利用できる。`,vi:`Ví dụ, nếu tín hiệu đo chứa nhiễu tần số cao không cần thiết, có thể dùng bộ lọc để giữ thành phần tần số thấp cần thiết đồng thời giảm thành phần tần số cao.`},{type:`heading`,ja:`D/A変換`,vi:`Chuyển đổi D/A`},{type:`paragraph`,ja:`D/A変換は、デジタル値を対応するアナログ信号に変換する処理である。コンピュータ内部で扱うデジタルデータを、電圧や音声などの連続的な物理量として出力するときに利用される。`,vi:`Chuyển đổi D/A là quá trình biến một giá trị số thành tín hiệu tương tự tương ứng. Nó được sử dụng khi cần xuất dữ liệu số bên trong máy tính thành đại lượng vật lý liên tục như điện áp hoặc âm thanh.`},{type:`example`,ja:`デジタル音声データをスピーカから音として出力する場合、D/A変換によってデジタル値をアナログ信号に変換し、その信号を利用して音を再生する。`,vi:`Khi phát dữ liệu âm thanh số qua loa, chuyển đổi D/A biến các giá trị số thành tín hiệu tương tự, sau đó tín hiệu này được dùng để tái tạo âm thanh.`},{type:`warning`,ja:`D/A変換はデジタルからアナログへの変換である。逆方向のアナログからデジタルへの変換と混同しないこと。`,vi:`D/A là chuyển đổi từ digital sang analog. Không nhầm với quá trình chuyển đổi theo chiều ngược lại từ analog sang digital.`}],terms:[{term:`フィルタリング`,reading:`フィルタリング`,english:`Filtering`,vi:`lọc`,definitionJa:`データや信号から特定の条件に合う成分を取り出したり、不要な成分を除去したりする処理。`,definitionVi:`Quá trình lấy ra các thành phần thỏa mãn điều kiện nhất định hoặc loại bỏ các thành phần không cần thiết khỏi dữ liệu hay tín hiệu.`},{term:`D/A変換`,reading:`ディーエーへんかん`,english:`Digital-to-Analog Conversion`,vi:`chuyển đổi số sang tương tự`,definitionJa:`デジタル値を、それに対応する連続的なアナログ信号へ変換する処理。`,definitionVi:`Quá trình chuyển đổi giá trị số thành tín hiệu tương tự liên tục tương ứng.`}],tags:[`measurement-control-theory`,`filtering`,`signal-processing`,`digital-to-analog`,`da-conversion`]},{id:`ad-conversion-and-control-systems`,order:2,titleJa:`A/D変換と制御システムの基礎`,titleVi:`Chuyển đổi A/D và cơ sở hệ thống điều khiển`,importance:`high`,summaryJa:`アナログ信号をデジタルデータとして扱うためのA/D変換と、リアルタイム処理や制御システムに関する基本概念を理解する。特に、オープンループ制御の特徴と、システムの応答特性を区別して理解する。`,summaryVi:`Tìm hiểu chuyển đổi A/D dùng để xử lý tín hiệu tương tự dưới dạng dữ liệu số, cùng các khái niệm cơ bản về xử lý thời gian thực và hệ thống điều khiển. Đặc biệt cần phân biệt đặc điểm của điều khiển vòng hở và đặc tính đáp ứng của hệ thống.`,content:[{type:`heading`,ja:`A/D変換`,vi:`Chuyển đổi A/D`},{type:`paragraph`,ja:`A/D変換は、連続的に変化するアナログ信号を、コンピュータで処理できるデジタルデータへ変換する処理である。一般に、アナログ信号を一定の時間間隔で取り出す標本化、その値を段階的な数値に対応させる量子化、数値をデジタルデータとして表す符号化という流れで変換する。`,vi:`Chuyển đổi A/D là quá trình biến tín hiệu tương tự thay đổi liên tục thành dữ liệu số mà máy tính có thể xử lý. Quá trình này thường gồm lấy mẫu tín hiệu theo những khoảng thời gian nhất định, lượng tử hóa giá trị thành các mức rời rạc và mã hóa chúng thành dữ liệu số.`},{type:`point`,ja:`A/D変換はアナログからデジタルへの変換、D/A変換はデジタルからアナログへの変換であり、変換方向を混同しないことが重要である。`,vi:`A/D chuyển từ analog sang digital, còn D/A chuyển từ digital sang analog. Trong FE cần đặc biệt chú ý không nhầm chiều chuyển đổi.`},{type:`heading`,ja:`リアルタイムOS`,vi:`Hệ điều hành thời gian thực`},{type:`paragraph`,ja:`リアルタイムOSは、要求された処理を定められた時間内に完了させることを重視するオペレーティングシステムである。機器制御など、処理結果だけでなく処理を完了する時刻にも制約があるシステムで利用される。`,vi:`Hệ điều hành thời gian thực là hệ điều hành chú trọng việc hoàn thành tác vụ trong thời hạn quy định. Nó được sử dụng trong các hệ thống như điều khiển thiết bị, nơi không chỉ kết quả mà cả thời điểm hoàn thành xử lý cũng rất quan trọng.`},{type:`point`,ja:`リアルタイム処理では、単に処理速度が速いことではなく、要求された時間制約を満たすことが重要である。`,vi:`Trong xử lý thời gian thực, điều quan trọng không đơn thuần là xử lý thật nhanh mà là đáp ứng được giới hạn thời gian đã quy định.`},{type:`heading`,ja:`オープンループ`,vi:`Vòng hở`},{type:`paragraph`,ja:`オープンループは、制御結果を入力側へフィードバックせずに制御する方式である。入力に基づいて出力を決めるが、実際の出力結果を確認して制御量を修正する仕組みを持たない。そのため構成は比較的単純だが、外乱や環境変化に応じた補正は難しい。`,vi:`Vòng hở là phương thức điều khiển không phản hồi kết quả đầu ra về phía đầu vào. Hệ thống quyết định đầu ra dựa trên đầu vào nhưng không kiểm tra kết quả thực tế để điều chỉnh lượng điều khiển. Vì vậy cấu trúc tương đối đơn giản nhưng khó tự hiệu chỉnh khi môi trường hoặc điều kiện bên ngoài thay đổi.`},{type:`example`,ja:`例えば、設定された時間だけ加熱する装置が、実際の温度を測定せずに時間だけで停止する場合は、オープンループ制御の例と考えられる。`,vi:`Ví dụ, một thiết bị chỉ gia nhiệt trong khoảng thời gian đã đặt rồi dừng mà không đo nhiệt độ thực tế là một ví dụ của điều khiển vòng hở.`},{type:`heading`,ja:`応答特性`,vi:`Đặc tính đáp ứng`},{type:`paragraph`,ja:`応答特性は、システムや装置に入力を与えたとき、出力がどのように変化するかを表す特性である。制御システムでは、入力の変化に対する出力の速さ、安定性、変化の仕方などを評価するために用いられる。`,vi:`Đặc tính đáp ứng biểu thị cách đầu ra của hệ thống hoặc thiết bị thay đổi khi có đầu vào. Trong hệ thống điều khiển, nó được dùng để đánh giá tốc độ phản ứng, độ ổn định và cách đầu ra thay đổi trước sự thay đổi của đầu vào.`},{type:`point`,ja:`オープンループは「制御の方式」、応答特性は「入力に対してシステムがどのように反応するかを表す特性」であり、同じ概念ではない。`,vi:`Open loop là một phương thức điều khiển, còn response characteristic là đặc tính thể hiện hệ thống phản ứng như thế nào trước đầu vào. Đây là hai khái niệm khác nhau.`}],terms:[{term:`A/D変換`,reading:`エーディーへんかん`,english:`Analog-to-Digital Conversion`,vi:`chuyển đổi tương tự sang số`,definitionJa:`連続的なアナログ信号を、コンピュータなどで処理できる離散的なデジタルデータへ変換する処理。`,definitionVi:`Quá trình chuyển đổi tín hiệu tương tự liên tục thành dữ liệu số rời rạc có thể được máy tính và thiết bị số xử lý.`},{term:`リアルタイムOS`,reading:`リアルタイムオーエス`,english:`Real-Time Operating System`,vi:`hệ điều hành thời gian thực`,definitionJa:`要求された処理を定められた時間内に完了させることを重視したオペレーティングシステム。`,definitionVi:`Hệ điều hành được thiết kế với trọng tâm là hoàn thành các tác vụ được yêu cầu trong thời hạn xác định.`},{term:`オープンループ`,reading:`オープンループ`,english:`Open Loop`,vi:`vòng hở`,definitionJa:`制御結果を入力側へフィードバックせず、入力に基づいて出力を決定する制御方式。`,definitionVi:`Phương thức điều khiển xác định đầu ra dựa trên đầu vào mà không phản hồi kết quả điều khiển về phía đầu vào.`},{term:`応答特性`,reading:`おうとうとくせい`,english:`Response Characteristic`,vi:`đặc tính đáp ứng`,definitionJa:`システムや装置に入力を与えたときに、出力がどのように変化するかを表す特性。`,definitionVi:`Đặc tính biểu thị cách đầu ra của hệ thống hoặc thiết bị thay đổi khi nhận một đầu vào.`}],tags:[`measurement-control-theory`,`ad-conversion`,`real-time-os`,`control-system`,`open-loop`,`response-characteristic`]},{id:`control-stability-sensors-and-actuators`,order:3,titleJa:`制御安定性とセンサー・アクチュエーター`,titleVi:`Độ ổn định điều khiển, cảm biến và cơ cấu chấp hành`,importance:`high`,summaryJa:`制御システムにおける安定性と、外部の状態を検出するセンサー、制御結果を物理的な動作に変換するアクチュエーターについて理解する。また、センサーの一種である光学センサーの役割と特徴を学ぶ。`,summaryVi:`Tìm hiểu độ ổn định trong hệ thống điều khiển, cảm biến dùng để phát hiện trạng thái bên ngoài và cơ cấu chấp hành dùng để biến tín hiệu điều khiển thành chuyển động vật lý. Đồng thời học vai trò và đặc điểm của cảm biến quang học.`,content:[{type:`heading`,ja:`制御システムの基本構成`,vi:`Cấu trúc cơ bản của hệ thống điều khiển`},{type:`paragraph`,ja:`制御システムでは、センサーによって対象や周囲の状態を検出し、その情報を基に制御を行い、アクチュエーターによって実際の動作を発生させる。制御安定性は、この一連の制御が外乱や内部状態の変化を受けても安定して行われるかを考えるための重要な概念である。`,vi:`Trong hệ thống điều khiển, cảm biến phát hiện trạng thái của đối tượng hoặc môi trường, hệ thống thực hiện điều khiển dựa trên thông tin đó và cơ cấu chấp hành tạo ra hành động thực tế. Độ ổn định điều khiển là khái niệm quan trọng để đánh giá liệu quá trình này có duy trì hoạt động ổn định khi chịu tác động bên ngoài hoặc thay đổi trạng thái bên trong hay không.`},{type:`heading`,ja:`制御安定性`,vi:`Độ ổn định điều khiển`},{type:`paragraph`,ja:`制御安定性は、制御系が外乱や内部状態の変化を受けた場合でも、出力が発散せず、目標とする状態へ適切に収束または維持できる性質を表す。制御系の設計では、目標値への応答だけでなく、安定した状態を保てるかどうかが重要となる。`,vi:`Độ ổn định điều khiển biểu thị khả năng của hệ thống điều khiển không bị mất kiểm soát khi chịu nhiễu hoặc thay đổi trạng thái bên trong, đồng thời có thể hội tụ về hoặc duy trì trạng thái mục tiêu một cách thích hợp. Khi thiết kế hệ thống điều khiển, không chỉ khả năng đáp ứng mục tiêu mà cả khả năng duy trì trạng thái ổn định đều rất quan trọng.`},{type:`heading`,ja:`センサーとアクチュエーター`,vi:`Cảm biến và cơ cấu chấp hành`},{type:`paragraph`,ja:`センサーは温度、光、圧力などの物理量や環境の状態を検出し、処理可能な信号へ変換する。一方、アクチュエーターは制御信号を受け取り、モータの回転や機構の移動などの物理的な動作へ変換する。`,vi:`Cảm biến phát hiện các đại lượng vật lý hoặc trạng thái môi trường như nhiệt độ, ánh sáng và áp suất rồi chuyển chúng thành tín hiệu có thể xử lý. Ngược lại, cơ cấu chấp hành nhận tín hiệu điều khiển và biến nó thành hành động vật lý như quay động cơ hoặc di chuyển cơ cấu.`},{type:`point`,ja:`FEでは、センサーは「検出する側」、アクチュエーターは「動作させる側」と区別すると理解しやすい。`,vi:`Trong FE, có thể ghi nhớ đơn giản: sensor là phía "phát hiện", còn actuator là phía "tạo hành động".`},{type:`heading`,ja:`光学センサー`,vi:`Cảm biến quang học`},{type:`paragraph`,ja:`光学センサーはセンサーの一種であり、光を利用して対象物や周囲の状態を検出する。光の強さ、色、反射などを利用でき、カメラ、スキャナ、物体検出、位置検出など様々な用途で使用される。`,vi:`Cảm biến quang học là một loại cảm biến sử dụng ánh sáng để phát hiện vật thể hoặc trạng thái môi trường. Nó có thể sử dụng cường độ ánh sáng, màu sắc hoặc ánh sáng phản xạ và được ứng dụng trong camera, máy quét, phát hiện vật thể, xác định vị trí và nhiều lĩnh vực khác.`},{type:`point`,ja:`関係を整理すると、「センサー」が上位概念であり、「光学センサー」は光を利用するセンサーの一種である。`,vi:`Về quan hệ khái niệm, "sensor" là khái niệm tổng quát, còn "optical sensor" là một loại sensor sử dụng ánh sáng.`}],terms:[{term:`制御安定性`,reading:`せいぎょあんていせい`,english:`Control Stability`,vi:`độ ổn định điều khiển`,definitionJa:`制御系が外乱や内部状態の変化を受けても、出力が発散せず、目標とする状態へ適切に収束または維持できる性質。`,definitionVi:`Tính chất cho biết hệ thống điều khiển có thể duy trì hoặc hội tụ thích hợp về trạng thái mục tiêu mà không bị mất ổn định khi chịu nhiễu hoặc thay đổi bên trong.`},{term:`センサー`,reading:`センサー`,english:`Sensor`,vi:`cảm biến`,definitionJa:`温度、光、圧力などの物理量や外部環境の状態を検出し、処理可能な信号に変換する装置。`,definitionVi:`Thiết bị phát hiện các đại lượng vật lý hoặc trạng thái môi trường như nhiệt độ, ánh sáng và áp suất rồi chuyển chúng thành tín hiệu có thể xử lý.`},{term:`アクチュエーター`,reading:`アクチュエーター`,english:`Actuator`,vi:`cơ cấu chấp hành`,definitionJa:`制御信号を受け取り、電気、空気圧、油圧などのエネルギーを利用して機械的な動作を発生させる装置。`,definitionVi:`Thiết bị nhận tín hiệu điều khiển và sử dụng năng lượng như điện, khí nén hoặc thủy lực để tạo ra chuyển động cơ học.`},{term:`光学センサー`,reading:`こうがくセンサー`,english:`Optical Sensor`,vi:`cảm biến quang học`,definitionJa:`光の強さ、色、反射などの性質を利用して、対象物や周囲の状態を検出するセンサー。`,definitionVi:`Loại cảm biến sử dụng các đặc tính của ánh sáng như cường độ, màu sắc hoặc phản xạ để phát hiện vật thể hoặc trạng thái môi trường.`}],tags:[`measurement-control-theory`,`control-stability`,`sensor`,`actuator`,`optical-sensor`]},{id:`infrared-magnetic-acceleration-and-gyro-sensors`,order:4,titleJa:`各種センサーと検出対象`,titleVi:`Các loại cảm biến và đối tượng đo`,importance:`high`,summaryJa:`赤外線、磁気、加速度、回転や角速度など、異なる物理量を検出する各種センサーの特徴と用途を理解する。`,summaryVi:`Tìm hiểu đặc điểm và ứng dụng của các loại cảm biến dùng để phát hiện những đại lượng vật lý khác nhau như tia hồng ngoại, từ trường, gia tốc, chuyển động quay và vận tốc góc.`,content:[{type:`heading`,ja:`センサーの種類と検出対象`,vi:`Các loại cảm biến và đối tượng phát hiện`},{type:`paragraph`,ja:`センサーには、検出する物理量に応じて様々な種類がある。赤外線センサーは赤外線、磁気センサーは磁場、加速度センサーは加速度、ジャイロセンサーは回転や角速度を検出する。それぞれの検出対象と代表的な用途を対応させて理解することが重要である。`,vi:`Cảm biến có nhiều loại khác nhau tùy theo đại lượng vật lý cần phát hiện. Cảm biến hồng ngoại phát hiện tia hồng ngoại, cảm biến từ phát hiện từ trường, cảm biến gia tốc đo gia tốc, còn cảm biến con quay hồi chuyển đo chuyển động quay hoặc vận tốc góc. Điều quan trọng là phải liên hệ đúng từng cảm biến với đối tượng đo và ứng dụng tiêu biểu của nó.`},{type:`heading`,ja:`赤外線センサーと磁気センサー`,vi:`Cảm biến hồng ngoại và cảm biến từ`},{type:`paragraph`,ja:`赤外線センサーは物体から放射される赤外線などを検出し、人や物体の検知、温度に関する測定などに利用される。磁気センサーは磁場を検出し、方位の検出や位置の検出などに利用される。`,vi:`Cảm biến hồng ngoại phát hiện tia hồng ngoại, chẳng hạn tia phát ra từ vật thể, và được sử dụng để phát hiện người, vật thể hoặc thực hiện các phép đo liên quan đến nhiệt độ. Cảm biến từ phát hiện từ trường và được sử dụng để xác định phương hướng hoặc vị trí.`},{type:`heading`,ja:`加速度センサーとジャイロセンサー`,vi:`Cảm biến gia tốc và cảm biến con quay hồi chuyển`},{type:`paragraph`,ja:`加速度センサーは物体の加速度を測定し、端末の動きや傾きなどの検出に利用される。ジャイロセンサーは物体の回転や角速度を測定し、姿勢や向きの変化を把握するために利用される。スマートフォンやドローンなどでは、両者を組み合わせてより正確に動きや姿勢を検出することがある。`,vi:`Cảm biến gia tốc đo gia tốc của vật thể và được dùng để phát hiện chuyển động hoặc độ nghiêng của thiết bị. Cảm biến con quay hồi chuyển đo chuyển động quay hoặc vận tốc góc, giúp xác định sự thay đổi tư thế và hướng. Trong các thiết bị như điện thoại thông minh và drone, hai loại cảm biến này có thể được kết hợp để phát hiện chuyển động và tư thế chính xác hơn.`},{type:`point`,ja:`FEでは、赤外線＝赤外線の検出、磁気＝磁場、加速度＝速度の変化、ジャイロ＝回転・角速度という対応を整理して覚える。`,vi:`Trong FE, nên ghi nhớ theo cặp: hồng ngoại = phát hiện tia hồng ngoại, từ = từ trường, gia tốc = sự thay đổi vận tốc, gyro = chuyển động quay/vận tốc góc.`},{type:`warning`,ja:`加速度センサーとジャイロセンサーは混同しやすい。加速度センサーは主に直線的な加速度や重力による傾きの検出に使われ、ジャイロセンサーは回転運動や角速度の検出に使われる。`,vi:`Cảm biến gia tốc và cảm biến gyro rất dễ bị nhầm. Cảm biến gia tốc chủ yếu phát hiện gia tốc tuyến tính hoặc độ nghiêng dựa trên trọng lực, trong khi cảm biến gyro dùng để phát hiện chuyển động quay và vận tốc góc.`}],terms:[{term:`赤外線センサー`,reading:`せきがいせんセンサー`,english:`Infrared Sensor`,vi:`cảm biến hồng ngoại`,definitionJa:`赤外線を検出し、人や物体の検知、温度に関する測定などに利用されるセンサー。`,definitionVi:`Cảm biến phát hiện tia hồng ngoại, được sử dụng để phát hiện người, vật thể hoặc thực hiện các phép đo liên quan đến nhiệt độ.`},{term:`磁気センサー`,reading:`じきセンサー`,english:`Magnetic Sensor`,vi:`cảm biến từ`,definitionJa:`周囲の磁場を検出し、その情報を電気信号として出力するセンサー。方位や位置の検出などに利用される。`,definitionVi:`Cảm biến phát hiện từ trường xung quanh và chuyển thông tin đó thành tín hiệu điện, thường được sử dụng để xác định phương hướng hoặc vị trí.`},{term:`加速度センサー`,reading:`かそくどセンサー`,english:`Accelerometer`,vi:`cảm biến gia tốc`,definitionJa:`物体に生じる加速度を測定するセンサー。機器の動きや傾きの検出などに利用される。`,definitionVi:`Cảm biến đo gia tốc tác động lên vật thể, được sử dụng để phát hiện chuyển động hoặc độ nghiêng của thiết bị.`},{term:`ジャイロセンサー`,reading:`ジャイロセンサー`,english:`Gyro Sensor`,vi:`cảm biến con quay hồi chuyển`,definitionJa:`物体の回転や角速度を検出するセンサー。機器の姿勢や向きの変化を把握するために利用される。`,definitionVi:`Cảm biến phát hiện chuyển động quay hoặc vận tốc góc của vật thể, được sử dụng để xác định sự thay đổi tư thế và hướng của thiết bị.`}],tags:[`measurement-control-theory`,`sensor`,`infrared-sensor`,`magnetic-sensor`,`accelerometer`,`gyro-sensor`]},{id:`ultrasonic-temperature-humidity-and-pressure-sensors`,order:5,titleJa:`距離・環境計測に用いるセンサー`,titleVi:`Cảm biến đo khoảng cách và môi trường`,importance:`high`,summaryJa:`超音波を利用して距離などを測定するセンサーと、温度、湿度、圧力を検出する代表的なセンサーについて、それぞれの測定対象、基本原理、代表的な用途を理解する。`,summaryVi:`Tìm hiểu cảm biến siêu âm dùng để đo khoảng cách và các cảm biến tiêu biểu dùng để đo nhiệt độ, độ ẩm và áp suất, bao gồm đối tượng đo, nguyên lý cơ bản và các ứng dụng điển hình.`,content:[{type:`heading`,ja:`距離や環境状態を測定するセンサー`,vi:`Cảm biến đo khoảng cách và trạng thái môi trường`},{type:`paragraph`,ja:`センサーは、目的に応じて異なる物理量を測定する。超音波センサーは超音波の反射を利用して物体までの距離などを測定し、温度センサー、湿度センサー、圧力センサーはそれぞれ温度、湿度、圧力を測定する。FEでは、各センサーが何を測定するのかを正確に対応させることが重要である。`,vi:`Tùy theo mục đích, cảm biến sẽ đo các đại lượng vật lý khác nhau. Cảm biến siêu âm sử dụng sự phản xạ của sóng siêu âm để đo khoảng cách tới vật thể, còn cảm biến nhiệt độ, độ ẩm và áp suất lần lượt đo nhiệt độ, độ ẩm và áp suất. Trong FE, điều quan trọng là phải xác định chính xác mỗi loại cảm biến dùng để đo đại lượng nào.`},{type:`heading`,ja:`超音波センサー`,vi:`Cảm biến siêu âm`},{type:`paragraph`,ja:`超音波センサーは、人間の可聴域を超える高い周波数の音波を発信し、物体で反射して戻るまでの時間などを利用して距離を測定する。障害物検知、駐車支援、ロボットの周辺認識などに利用される。`,vi:`Cảm biến siêu âm phát ra sóng âm có tần số cao hơn phạm vi nghe của con người và đo khoảng cách dựa trên thời gian sóng phản xạ từ vật thể quay trở lại. Nó được sử dụng trong phát hiện chướng ngại vật, hỗ trợ đỗ xe và nhận biết môi trường xung quanh của robot.`},{type:`heading`,ja:`温度・湿度・圧力の測定`,vi:`Đo nhiệt độ, độ ẩm và áp suất`},{type:`paragraph`,ja:`温度センサーは温度を、湿度センサーは空気中の水分量に関係する湿度を、圧力センサーは気体や液体などから受ける圧力を測定する。これらは環境監視、空調設備、工業設備、自動車、医療機器など様々なシステムで利用される。`,vi:`Cảm biến nhiệt độ đo nhiệt độ, cảm biến độ ẩm đo độ ẩm liên quan đến lượng hơi nước trong không khí, còn cảm biến áp suất đo áp suất của khí hoặc chất lỏng. Chúng được sử dụng trong nhiều hệ thống như giám sát môi trường, điều hòa không khí, thiết bị công nghiệp, ô tô và thiết bị y tế.`},{type:`point`,ja:`FEでは「超音波センサー＝反射を利用した距離測定」「温度センサー＝温度」「湿度センサー＝湿度」「圧力センサー＝圧力」という対応をまず整理して覚える。`,vi:`Trong FE, trước tiên nên ghi nhớ: cảm biến siêu âm = đo khoảng cách bằng phản xạ; cảm biến nhiệt độ = nhiệt độ; cảm biến độ ẩm = độ ẩm; cảm biến áp suất = áp suất.`},{type:`warning`,ja:`超音波センサーは音波を利用するため、光を利用する光学センサーや赤外線を検出する赤外線センサーとは検出原理が異なる。`,vi:`Cảm biến siêu âm sử dụng sóng âm nên có nguyên lý phát hiện khác với cảm biến quang học sử dụng ánh sáng và cảm biến hồng ngoại phát hiện tia hồng ngoại.`}],terms:[{term:`超音波センサー`,reading:`ちょうおんぱセンサー`,english:`Ultrasonic Sensor`,vi:`cảm biến siêu âm`,definitionJa:`超音波を発信し、物体からの反射波を受信することで、物体までの距離や存在を検出するセンサー。`,definitionVi:`Cảm biến phát sóng siêu âm và nhận sóng phản xạ từ vật thể để phát hiện sự tồn tại hoặc đo khoảng cách tới vật thể.`},{term:`温度センサー`,reading:`おんどセンサー`,english:`Temperature Sensor`,vi:`cảm biến nhiệt độ`,definitionJa:`対象物や周囲の温度を測定し、その値を電気信号などに変換して出力するセンサー。`,definitionVi:`Cảm biến đo nhiệt độ của vật thể hoặc môi trường xung quanh và chuyển giá trị đo được thành tín hiệu điện hoặc dạng tín hiệu có thể xử lý.`},{term:`湿度センサー`,reading:`しつどセンサー`,english:`Humidity Sensor`,vi:`cảm biến độ ẩm`,definitionJa:`空気中の水分量に関係する湿度を測定し、その値を信号として出力するセンサー。`,definitionVi:`Cảm biến đo độ ẩm liên quan đến lượng hơi nước trong không khí và xuất giá trị đó dưới dạng tín hiệu.`},{term:`圧力センサー`,reading:`あつりょくセンサー`,english:`Pressure Sensor`,vi:`cảm biến áp suất`,definitionJa:`気体や液体などから受ける圧力を検出し、その大きさを電気信号などに変換するセンサー。`,definitionVi:`Cảm biến phát hiện áp suất của khí hoặc chất lỏng và chuyển độ lớn của áp suất thành tín hiệu điện hoặc dạng tín hiệu có thể xử lý.`}],tags:[`measurement-control-theory`,`sensor`,`ultrasonic-sensor`,`temperature-sensor`,`humidity-sensor`,`pressure-sensor`]},{id:`measurement-elements-and-actuators`,order:6,titleJa:`計測素子と駆動装置`,titleVi:`Phần tử đo lường và thiết bị chấp hành`,importance:`high`,summaryJa:`力や温度、磁気を検出する代表的な計測素子と、電気・油圧・空気圧を利用して機械的な動作を生み出す代表的な駆動装置について理解する。`,summaryVi:`Tìm hiểu các phần tử đo lường tiêu biểu dùng để phát hiện lực, nhiệt độ và từ trường, đồng thời phân biệt các thiết bị chấp hành tạo chuyển động cơ học bằng điện, thủy lực và khí nén.`,content:[{type:`heading`,ja:`計測に用いる素子`,vi:`Các phần tử dùng trong đo lường`},{type:`paragraph`,ja:`ひずみゲージ、サーミスタ、ホール素子は、それぞれ異なる物理量を電気的な変化として検出するために利用される。ひずみゲージは物体の変形、サーミスタは温度、ホール素子は磁界を検出する。FEでは、それぞれが何を検出する素子なのかを区別することが重要である。`,vi:`Strain gauge, thermistor và phần tử Hall được sử dụng để phát hiện các đại lượng vật lý khác nhau dưới dạng biến đổi điện. Strain gauge phát hiện biến dạng của vật thể, thermistor phát hiện nhiệt độ và phần tử Hall phát hiện từ trường. Trong FE, cần phân biệt chính xác mỗi phần tử dùng để phát hiện đại lượng nào.`},{type:`point`,ja:`ひずみゲージは変形による電気抵抗の変化、サーミスタは温度による電気抵抗の変化、ホール素子は磁界によって生じるホール電圧を利用する。`,vi:`Strain gauge sử dụng sự thay đổi điện trở do biến dạng, thermistor sử dụng sự thay đổi điện trở theo nhiệt độ, còn phần tử Hall sử dụng điện áp Hall sinh ra dưới tác dụng của từ trường.`},{type:`heading`,ja:`機械的な動作を生み出す駆動装置`,vi:`Thiết bị tạo chuyển động cơ học`},{type:`paragraph`,ja:`モーター、油圧シリンダ、空気圧シリンダは、エネルギーを機械的な動作に変換する代表的な装置である。モーターは主に電気エネルギーを回転運動に変換し、油圧シリンダと空気圧シリンダは、それぞれ液体と圧縮空気の圧力を利用して主に直線運動を発生させる。`,vi:`Motor, xi lanh thủy lực và xi lanh khí nén là những thiết bị tiêu biểu biến đổi năng lượng thành chuyển động cơ học. Motor chủ yếu biến điện năng thành chuyển động quay, trong khi xi lanh thủy lực và xi lanh khí nén sử dụng áp suất của chất lỏng và khí nén để tạo ra chủ yếu là chuyển động tịnh tiến.`},{type:`point`,ja:`駆動源で整理すると、モーター＝電気、油圧シリンダ＝液体の圧力、空気圧シリンダ＝圧縮空気である。`,vi:`Nếu phân loại theo nguồn dẫn động: motor = điện, xi lanh thủy lực = áp suất chất lỏng, xi lanh khí nén = khí nén.`},{type:`warning`,ja:`油圧シリンダと空気圧シリンダはどちらも直線運動に利用されるが、作動媒体が異なる。油圧は液体を利用し、大きな力を得やすい。空気圧は圧縮空気を利用する。`,vi:`Xi lanh thủy lực và xi lanh khí nén đều có thể tạo chuyển động tịnh tiến nhưng môi chất hoạt động khác nhau. Thủy lực sử dụng chất lỏng và dễ tạo lực lớn, còn khí nén sử dụng không khí nén.`}],terms:[{term:`ひずみゲージ`,reading:`ひずみゲージ`,english:`Strain Gauge`,vi:`cảm biến biến dạng`,definitionJa:`物体に力が加わったときに生じる変形（ひずみ）を、電気抵抗の変化などを利用して測定する素子。`,definitionVi:`Phần tử đo biến dạng của vật thể khi chịu lực, thường dựa trên sự thay đổi điện trở.`},{term:`サーミスタ`,reading:`サーミスタ`,english:`Thermistor`,vi:`điện trở nhiệt`,definitionJa:`温度によって電気抵抗が大きく変化する性質を利用し、温度の検出や制御に用いられる半導体素子。`,definitionVi:`Phần tử bán dẫn có điện trở thay đổi đáng kể theo nhiệt độ, được sử dụng để phát hiện và điều khiển nhiệt độ.`},{term:`ホール素子`,reading:`ホールそし`,english:`Hall Element`,vi:`phần tử Hall`,definitionJa:`電流が流れる導体や半導体に磁界を加えたときに生じるホール電圧を利用して、磁界を検出する素子。`,definitionVi:`Phần tử phát hiện từ trường dựa trên điện áp Hall sinh ra khi từ trường tác động lên vật dẫn hoặc chất bán dẫn có dòng điện chạy qua.`},{term:`モーター`,reading:`モーター`,english:`Motor`,vi:`động cơ điện`,definitionJa:`主に電気エネルギーを機械的な回転運動に変換し、機械や装置を駆動するために用いられる装置。`,definitionVi:`Thiết bị chủ yếu biến đổi điện năng thành chuyển động quay cơ học để dẫn động máy móc và thiết bị.`},{term:`油圧シリンダ`,reading:`ゆあつシリンダ`,english:`Hydraulic Cylinder`,vi:`xi lanh thủy lực`,definitionJa:`油などの液体の圧力を利用してピストンを動かし、主に直線的な力や運動を発生させる装置。`,definitionVi:`Thiết bị sử dụng áp suất của chất lỏng như dầu để di chuyển piston và tạo lực hoặc chuyển động tịnh tiến.`},{term:`空気圧シリンダ`,reading:`くうきあつシリンダ`,english:`Pneumatic Cylinder`,vi:`xi lanh khí nén`,definitionJa:`圧縮空気の圧力を利用してピストンを動かし、主に直線的な力や運動を発生させる装置。`,definitionVi:`Thiết bị sử dụng áp suất của khí nén để di chuyển piston và tạo lực hoặc chuyển động tịnh tiến.`}],tags:[`measurement-control-theory`,`strain-gauge`,`thermistor`,`hall-element`,`motor`,`hydraulic-cylinder`,`pneumatic-cylinder`]}]},p={id:`algorithms-and-programming`,order:2,titleJa:`アルゴリズムとプログラミング`,titleVi:`Thuật toán và lập trình`,chapters:[{id:`data-structures`,order:1,titleJa:`データ構造`,titleVi:`Cấu trúc dữ liệu`,file:`01-data-structures.json`},{id:`algorithms`,order:2,titleJa:`アルゴリズム`,titleVi:`Thuật toán`,file:`02-algorithms.json`},{id:`programming`,order:3,titleJa:`プログラミング`,titleVi:`Lập trình`,file:`03-programming.json`}]},m={id:`data-structures`,order:1,titleJa:`データ構造`,titleVi:`Cấu trúc dữ liệu`,syllabus:`9.2`,lessons:[{id:`lists-and-arrays`,order:1,titleJa:`リストと配列の基本`,titleVi:`Cơ bản về List và Array`,importance:`high`,summaryJa:`代表的なデータ構造であるリストと配列の特徴を理解し、線形リストと単方向リストの構造やアクセス方法を学ぶ。特に、配列の添字による直接アクセスと、単方向リストのポインタをたどるアクセスの違いを整理する。`,summaryVi:`Tìm hiểu đặc điểm của List và Array là những cấu trúc dữ liệu cơ bản, đồng thời học cấu trúc và cách truy cập của linear list và singly linked list. Trọng tâm là phân biệt truy cập trực tiếp bằng chỉ số của mảng với việc lần theo liên kết trong danh sách liên kết đơn.`,content:[{type:`heading`,ja:`リストと配列`,vi:`List và Array`},{type:`paragraph`,ja:`リストと配列は、複数のデータをまとめて扱うための代表的なデータ構造である。どちらも複数の要素を管理するために利用されるが、データの配置方法や要素へのアクセス方法に違いがある。`,vi:`List và Array là hai cấu trúc dữ liệu tiêu biểu dùng để quản lý nhiều phần tử cùng nhau. Cả hai đều dùng để quản lý tập hợp dữ liệu, nhưng khác nhau về cách bố trí dữ liệu và cách truy cập từng phần tử.`},{type:`heading`,ja:`リスト`,vi:`List`},{type:`paragraph`,ja:`リストは、複数の要素を一定の順序で管理するデータ構造である。要素の追加、削除、検索などの処理に利用され、具体的な実装方法として連結リストなどがある。`,vi:`List là cấu trúc dữ liệu quản lý nhiều phần tử theo một thứ tự nhất định. Nó được sử dụng cho các thao tác như thêm, xóa và tìm kiếm phần tử; một cách triển khai tiêu biểu là linked list.`},{type:`heading`,ja:`配列`,vi:`Mảng`},{type:`paragraph`,ja:`配列は、複数の要素を連続した領域に並べ、各要素を添字（インデックス）によって指定できるデータ構造である。要素の位置が分かっていれば、添字を使って目的の要素へ直接アクセスできる。`,vi:`Array là cấu trúc dữ liệu sắp xếp nhiều phần tử trong vùng lưu trữ liên tiếp và xác định từng phần tử bằng chỉ số (index). Nếu biết vị trí của phần tử, có thể truy cập trực tiếp bằng chỉ số.`},{type:`example`,ja:`例えば、配列Aの3番目の要素を参照する場合、添字を指定してその位置の要素を直接取り出すことができる。`,vi:`Ví dụ, khi cần lấy phần tử thứ ba của mảng A, có thể chỉ định index tương ứng để truy cập trực tiếp phần tử ở vị trí đó.`},{type:`heading`,ja:`線形リスト`,vi:`Danh sách tuyến tính`},{type:`paragraph`,ja:`線形リストは、要素が一列の順序関係をもつリスト構造である。各要素には前後関係があり、先頭から末尾まで一定の順序で要素を並べて扱う。`,vi:`Linear list là cấu trúc danh sách trong đó các phần tử có quan hệ thứ tự theo một chuỗi tuyến tính. Các phần tử có quan hệ trước–sau và được xử lý theo thứ tự từ đầu đến cuối.`},{type:`heading`,ja:`単方向リスト`,vi:`Danh sách liên kết đơn`},{type:`paragraph`,ja:`単方向リストは、各要素がデータと次の要素への参照（ポインタ）をもち、一方向に要素を連結したリストである。先頭要素から次の要素への参照を順番にたどることで、目的の要素へアクセスする。`,vi:`Singly linked list là danh sách trong đó mỗi phần tử chứa dữ liệu và tham chiếu (pointer) đến phần tử kế tiếp, tạo thành liên kết theo một chiều. Muốn truy cập một phần tử, phải lần lượt đi từ phần tử đầu theo các liên kết tiếp theo.`},{type:`point`,ja:`単方向リストでは、要素の挿入や削除は参照先を変更することで行える。一方、任意の位置へ配列のように直接アクセスすることはできず、基本的には先頭から順にたどる必要がある。`,vi:`Trong singly linked list, có thể chèn hoặc xóa phần tử bằng cách thay đổi các liên kết. Tuy nhiên không thể truy cập trực tiếp một vị trí tùy ý như Array mà về cơ bản phải lần từ đầu danh sách.`},{type:`warning`,ja:`配列と単方向リストのアクセス方法を混同しない。配列は添字による直接アクセスが可能だが、単方向リストはポインタを先頭から順にたどってアクセスする。`,vi:`Không nhầm cách truy cập của Array và singly linked list. Array cho phép truy cập trực tiếp bằng index, còn singly linked list phải lần theo pointer từ đầu danh sách.`},{type:`point`,ja:`FEでは、「配列＝添字で直接アクセス」「単方向リスト＝次要素へのポインタをたどる」という対応を覚えるとよい。`,vi:`Trong FE, nên nhớ: “Array = truy cập trực tiếp bằng index”, “singly linked list = lần theo pointer đến phần tử kế tiếp”.`}],terms:[{term:`リスト`,reading:`リスト`,english:`List`,vi:`danh sách`,definitionJa:`複数の要素を一定の順序で管理し、追加、削除、検索などの操作を行うためのデータ構造。`,definitionVi:`Cấu trúc dữ liệu quản lý nhiều phần tử theo một thứ tự nhất định và hỗ trợ các thao tác như thêm, xóa và tìm kiếm.`},{term:`配列`,reading:`はいれつ`,english:`Array`,vi:`mảng`,definitionJa:`複数の要素を並べて保持し、添字を指定することで各要素へ直接アクセスできるデータ構造。`,definitionVi:`Cấu trúc dữ liệu lưu nhiều phần tử theo thứ tự và cho phép truy cập trực tiếp từng phần tử bằng chỉ số.`},{term:`線形リスト`,reading:`せんけいリスト`,english:`Linear List`,vi:`danh sách tuyến tính`,definitionJa:`要素が一列の順序関係をもち、先頭から末尾まで線形に並ぶリスト構造。`,definitionVi:`Cấu trúc danh sách trong đó các phần tử có quan hệ thứ tự tuyến tính từ đầu đến cuối.`},{term:`単方向リスト`,reading:`たんほうこうリスト`,english:`Singly Linked List`,vi:`danh sách liên kết đơn`,definitionJa:`各要素が次の要素への参照をもち、一方向に連結されたリスト構造。`,definitionVi:`Cấu trúc danh sách liên kết trong đó mỗi phần tử giữ tham chiếu đến phần tử kế tiếp theo một chiều.`}],tags:[`data-structures`,`list`,`array`,`linear-list`,`linked-list`]},{id:`linked-lists-stack-and-queue`,order:2,titleJa:`双方向リスト・環状リスト・スタック・キュー`,titleVi:`Danh sách liên kết đôi, danh sách vòng, Stack và Queue`,importance:`high`,summaryJa:`双方向リストと環状リストの構造を理解し、スタックのLIFOとキューのFIFOという基本的なデータ処理方式を学ぶ。それぞれのデータ構造における要素の参照方法や取り出し順序の違いを整理する。`,summaryVi:`Tìm hiểu cấu trúc của danh sách liên kết đôi và danh sách vòng, đồng thời nắm vững hai phương thức xử lý dữ liệu cơ bản: LIFO của Stack và FIFO của Queue. Phân biệt cách liên kết phần tử và thứ tự lấy dữ liệu của từng cấu trúc.`,content:[{type:`heading`,ja:`双方向リスト`,vi:`Danh sách liên kết đôi`},{type:`paragraph`,ja:`双方向リストは、各要素が前の要素と次の要素の両方への参照（ポインタ）をもつリスト構造である。そのため、先頭から末尾へ進むだけでなく、末尾から先頭へ逆方向にたどることもできる。`,vi:`Doubly linked list là cấu trúc danh sách trong đó mỗi phần tử có tham chiếu (pointer) đến cả phần tử trước và phần tử sau. Vì vậy, ngoài việc đi từ đầu đến cuối, còn có thể duyệt ngược từ cuối về đầu.`},{type:`point`,ja:`単方向リストが次の要素への参照だけをもつのに対し、双方向リストは前後両方の要素への参照をもつ。`,vi:`Singly linked list chỉ giữ tham chiếu đến phần tử tiếp theo, trong khi doubly linked list giữ tham chiếu đến cả phần tử trước và phần tử sau.`},{type:`heading`,ja:`環状リスト`,vi:`Danh sách vòng`},{type:`paragraph`,ja:`環状リストは、最後の要素が最初の要素へ接続され、要素が環状につながったリスト構造である。終端がなく、要素を繰り返し順番に処理する場合に適している。`,vi:`Circular list là cấu trúc danh sách trong đó phần tử cuối được nối với phần tử đầu, tạo thành một vòng khép kín. Do không có điểm kết thúc cố định, cấu trúc này phù hợp với các xử lý cần lặp tuần tự qua các phần tử.`},{type:`example`,ja:`タスクを順番に繰り返し処理するスケジューリングや、曲の最後まで再生した後に最初の曲へ戻る音楽プレイヤーなどに利用できる。`,vi:`Có thể sử dụng cho việc lập lịch xử lý các tác vụ tuần tự lặp lại hoặc trình phát nhạc quay về bài đầu tiên sau khi phát hết bài cuối.`},{type:`heading`,ja:`スタック`,vi:`Stack`},{type:`paragraph`,ja:`スタックは、最後に格納したデータを最初に取り出すLIFO（Last In First Out：後入れ先出し）方式のデータ構造である。本を積み重ねた場合に、一番上に置いた本から順に取り出すイメージで理解できる。`,vi:`Stack là cấu trúc dữ liệu hoạt động theo nguyên tắc LIFO (Last In First Out – vào sau ra trước). Có thể hình dung như một chồng sách: cuốn được đặt lên trên cùng sau cùng sẽ được lấy ra trước.`},{type:`point`,ja:`スタックへのデータの追加をPUSH、データの取り出しをPOPという。`,vi:`Thao tác thêm dữ liệu vào Stack được gọi là PUSH, còn thao tác lấy dữ liệu ra được gọi là POP.`},{type:`example`,ja:`関数の呼出しや戻り先の管理、処理を直前の状態へ戻すバックトラッキングなどでスタックが利用される。`,vi:`Stack được sử dụng để quản lý lời gọi hàm và địa chỉ quay về, cũng như trong các xử lý backtracking để quay lại trạng thái trước đó.`},{type:`heading`,ja:`キュー`,vi:`Queue`},{type:`paragraph`,ja:`キューは、最初に格納したデータを最初に取り出すFIFO（First In First Out：先入れ先出し）方式のデータ構造である。先に並んだ人から順番に処理される行列と同じ考え方である。`,vi:`Queue là cấu trúc dữ liệu hoạt động theo nguyên tắc FIFO (First In First Out – vào trước ra trước). Có thể hình dung như một hàng người chờ, người đến trước sẽ được xử lý trước.`},{type:`point`,ja:`キューでは、データを末尾に追加する操作をエンキュー（enqueue）、先頭から取り出す操作をデキュー（dequeue）という。`,vi:`Trong Queue, thao tác thêm dữ liệu vào cuối hàng đợi gọi là enqueue, còn thao tác lấy dữ liệu từ đầu hàng đợi gọi là dequeue.`},{type:`example`,ja:`複数のタスクを到着順に処理する場合や、データの送受信、印刷待ちジョブの管理などにキューが利用される。`,vi:`Queue được sử dụng khi xử lý nhiều tác vụ theo thứ tự đến, truyền nhận dữ liệu hoặc quản lý các job đang chờ in.`},{type:`warning`,ja:`スタックとキューの取り出し順序を混同しない。スタックはLIFO（後入れ先出し）、キューはFIFO（先入れ先出し）である。`,vi:`Không nhầm thứ tự lấy dữ liệu của Stack và Queue. Stack là LIFO (vào sau ra trước), còn Queue là FIFO (vào trước ra trước).`},{type:`point`,ja:`FEでは、「スタック＝LIFO＝PUSH/POP」「キュー＝FIFO＝enqueue/dequeue」の対応が重要である。`,vi:`Trong FE, cần đặc biệt nhớ: “Stack = LIFO = PUSH/POP” và “Queue = FIFO = enqueue/dequeue”.`}],terms:[{term:`双方向リスト`,reading:`そうほうこうリスト`,english:`Doubly Linked List`,vi:`danh sách liên kết đôi`,definitionJa:`各要素が前の要素と次の要素の両方への参照をもち、双方向にたどることができるリスト構造。`,definitionVi:`Cấu trúc danh sách trong đó mỗi phần tử có tham chiếu đến cả phần tử trước và phần tử sau, cho phép duyệt theo hai chiều.`},{term:`環状リスト`,reading:`かんじょうリスト`,english:`Circular List`,vi:`danh sách vòng`,definitionJa:`最後の要素が最初の要素に接続され、全体が環状につながったリスト構造。`,definitionVi:`Cấu trúc danh sách trong đó phần tử cuối liên kết với phần tử đầu, tạo thành một vòng khép kín.`},{term:`スタック`,reading:`スタック`,english:`Stack`,vi:`ngăn xếp`,definitionJa:`最後に格納したデータを最初に取り出すLIFO方式のデータ構造。`,definitionVi:`Cấu trúc dữ liệu theo nguyên tắc LIFO, dữ liệu được đưa vào sau cùng sẽ được lấy ra đầu tiên.`},{term:`キュー`,reading:`キュー`,english:`Queue`,vi:`hàng đợi`,definitionJa:`最初に格納したデータを最初に取り出すFIFO方式のデータ構造。`,definitionVi:`Cấu trúc dữ liệu theo nguyên tắc FIFO, dữ liệu được đưa vào đầu tiên sẽ được lấy ra đầu tiên.`}],tags:[`data-structures`,`linked-list`,`doubly-linked-list`,`circular-list`,`stack`,`queue`,`lifo`,`fifo`]},{id:`stack-operations-and-tree-structure`,order:3,titleJa:`スタック操作と木構造`,titleVi:`Thao tác Stack và cấu trúc cây`,importance:`high`,summaryJa:`スタックにおけるプッシュとポップの基本操作、およびデータを階層的に表現する木構造について理解する。また、rootという用語について確認する。`,summaryVi:`Tìm hiểu hai thao tác cơ bản của Stack là Push và Pop, cùng với cấu trúc cây dùng để biểu diễn dữ liệu theo dạng phân cấp. Đồng thời tìm hiểu thuật ngữ root.`,content:[{type:`heading`,ja:`プッシュ`,vi:`Push`},{type:`paragraph`,ja:`プッシュ（push）は、スタックにデータを追加する操作である。スタックでは新しいデータを一番上に追加し、最後に追加されたデータが最初に取り出される。`,vi:`Push là thao tác thêm dữ liệu vào Stack. Dữ liệu mới được thêm vào đỉnh Stack và dữ liệu được thêm sau cùng sẽ được lấy ra đầu tiên.`},{type:`heading`,ja:`ポップ`,vi:`Pop`},{type:`paragraph`,ja:`ポップ（pop）は、スタックの最上部にあるデータを取り出す操作である。プッシュによって追加されたデータは、追加された順序とは逆の順序でポップされる。`,vi:`Pop là thao tác lấy dữ liệu ở đỉnh Stack ra. Dữ liệu được thêm bằng Push sẽ được Pop theo thứ tự ngược với thứ tự đã thêm.`},{type:`example`,ja:`A、B、Cの順にプッシュした場合、ポップするとC、B、Aの順に取り出される。`,vi:`Nếu Push lần lượt A, B, C thì khi Pop, dữ liệu sẽ được lấy ra theo thứ tự C, B, A.`},{type:`point`,ja:`スタックでは、データを追加する操作がプッシュ、最上部のデータを取り出す操作がポップである。`,vi:`Trong Stack, thao tác thêm dữ liệu là Push và thao tác lấy dữ liệu trên đỉnh ra là Pop.`},{type:`heading`,ja:`木構造`,vi:`Cấu trúc cây`},{type:`paragraph`,ja:`木構造は、データを階層的に整理するためのデータ構造である。親子関係をもつノード（節）から構成され、根と呼ばれる頂点から枝分かれする形をとる。`,vi:`Cấu trúc cây là cấu trúc dữ liệu dùng để tổ chức dữ liệu theo dạng phân cấp. Nó gồm các node có quan hệ cha-con và phân nhánh từ đỉnh được gọi là root.`},{type:`example`,ja:`組織図やファイルシステムなどは、木構造で表現できる代表的な例である。`,vi:`Sơ đồ tổ chức và hệ thống tệp là những ví dụ tiêu biểu có thể được biểu diễn bằng cấu trúc cây.`},{type:`point`,ja:`木構造には、二分木や平衡木などの種類があり、データの検索、挿入、削除などに利用される。`,vi:`Cấu trúc cây có các loại như cây nhị phân và cây cân bằng, được sử dụng trong tìm kiếm, chèn và xóa dữ liệu.`},{type:`heading`,ja:`根`,vi:`Root`},{type:`paragraph`,ja:`木構造における根（root）は、親ノードを持たない最上位のノードであり、木の走査を始める基点となる。根以外の各ノードは、親ノードを一つ持つ。`,vi:`Trong cấu trúc cây, gốc (root) là node cao nhất không có node cha và là điểm bắt đầu khi duyệt cây. Mỗi node khác gốc có một node cha.`},{type:`warning`,ja:`木構造の根（root node）と、LinuxやUnix系システムの最高権限アカウントであるrootは、同じ語を使うが別の概念である。`,vi:`Root node trong cấu trúc cây và tài khoản root có quyền cao nhất trong Linux/Unix dùng cùng một từ nhưng là hai khái niệm khác nhau.`},{type:`point`,ja:`FEでは、スタックについて「PUSH＝追加」「POP＝取り出し」「LIFO＝後入れ先出し」の関係を確実に覚える。`,vi:`Trong FE, cần nhớ chắc quan hệ: “PUSH = thêm”, “POP = lấy ra”, “LIFO = vào sau ra trước”.`}],terms:[{term:`プッシュ`,reading:`プッシュ`,english:`Push`,vi:`thao tác Push`,definitionJa:`スタックにデータを追加する操作。`,definitionVi:`Thao tác thêm dữ liệu vào Stack.`},{term:`ポップ`,reading:`ポップ`,english:`Pop`,vi:`thao tác Pop`,definitionJa:`スタックの最上部にあるデータを取り出す操作。`,definitionVi:`Thao tác lấy dữ liệu ở đỉnh Stack ra.`},{term:`木構造`,reading:`きこうぞう`,english:`Tree Structure`,vi:`cấu trúc cây`,definitionJa:`親子関係をもつノードを用いて、データを階層的に表現するデータ構造。`,definitionVi:`Cấu trúc dữ liệu biểu diễn dữ liệu theo dạng phân cấp bằng các node có quan hệ cha-con.`},{term:`根`,reading:`ね`,english:`Root`,vi:`root`,definitionJa:`木構造において親ノードを持たない最上位のノード。`,definitionVi:`Node cao nhất trong cấu trúc cây, không có node cha.`}],tags:[`data-structures`,`stack`,`push`,`pop`,`tree`,`root`]},{id:`tree-nodes-and-binary-trees`,order:4,titleJa:`葉・枝と2分木`,titleVi:`Lá, nhánh và cây nhị phân`,importance:`high`,summaryJa:`木構造を構成する葉と枝の役割、および各ノードが最大2つの子ノードを持つ2分木と完全2分木の特徴を理解する。`,summaryVi:`Tìm hiểu vai trò của lá và nhánh trong cấu trúc cây, đồng thời nắm được đặc điểm của cây nhị phân và cây nhị phân hoàn chỉnh.`,content:[{type:`heading`,ja:`葉`,vi:`Lá`},{type:`paragraph`,ja:`葉（leaf）は、木構造において子ノードを持たない終端ノードである。木構造ではデータを階層的に扱い、葉はそれぞれの経路の終端として機能する。`,vi:`Lá (leaf) là node cuối trong cấu trúc cây và không có node con. Trong cấu trúc cây phân cấp, mỗi lá là điểm kết thúc của một đường đi.`},{type:`example`,ja:`ファイルシステムを木構造で表した場合、ディレクトリを親ノード、各ファイルを葉として考えることができる。`,vi:`Khi biểu diễn hệ thống tệp bằng cấu trúc cây, có thể xem thư mục là node cha và các tệp là lá.`},{type:`point`,ja:`葉は子ノードを持たない終端ノードである。`,vi:`Lá là node cuối và không có node con.`},{type:`heading`,ja:`枝`,vi:`Nhánh`},{type:`paragraph`,ja:`枝（branch）は、木構造においてノード同士を結ぶ部分を指す。親ノードと子ノードの関係や、木構造内の経路を表すために用いられる。`,vi:`Nhánh (branch) là phần nối các node với nhau trong cấu trúc cây. Nó được dùng để biểu diễn quan hệ giữa node cha và node con cũng như đường đi trong cây.`},{type:`point`,ja:`木構造では、ノードがデータや要素を表し、枝がノード間の関係を表す。`,vi:`Trong cấu trúc cây, node biểu diễn dữ liệu hoặc phần tử, còn nhánh biểu diễn mối quan hệ giữa các node.`},{type:`heading`,ja:`2分木`,vi:`Cây nhị phân`},{type:`paragraph`,ja:`2分木（binary tree）は、各ノードが最大2つの子ノードを持つ木構造である。各ノードはデータを保持し、親ノードと子ノードの関係によって階層的な構造を形成する。`,vi:`Cây nhị phân (binary tree) là cấu trúc cây mà mỗi node có tối đa hai node con. Mỗi node giữ dữ liệu và tạo thành cấu trúc phân cấp thông qua quan hệ cha-con.`},{type:`paragraph`,ja:`2分木は、データを効率的に格納したり検索したりするために、さまざまなアルゴリズムで利用される。`,vi:`Cây nhị phân được sử dụng trong nhiều thuật toán nhằm lưu trữ và tìm kiếm dữ liệu hiệu quả.`},{type:`point`,ja:`2分木では、一つのノードが持つことのできる子ノードは最大2つである。`,vi:`Trong cây nhị phân, một node có thể có tối đa 2 node con.`},{type:`heading`,ja:`完全2分木`,vi:`Cây nhị phân hoàn chỉnh`},{type:`paragraph`,ja:`完全2分木（complete binary tree）は、最後のレベルを除くすべてのレベルがノードで満たされ、最後のレベルではノードが左側から順に配置される2分木である。`,vi:`Cây nhị phân hoàn chỉnh (complete binary tree) là cây nhị phân mà tất cả các tầng trừ tầng cuối đều được lấp đầy, còn các node ở tầng cuối được bố trí lần lượt từ bên trái.`},{type:`point`,ja:`完全2分木はヒープなどのデータ構造で利用される重要な木構造である。`,vi:`Cây nhị phân hoàn chỉnh là cấu trúc cây quan trọng được sử dụng trong các cấu trúc dữ liệu như heap.`}],terms:[{term:`葉`,reading:`は`,english:`Leaf`,vi:`lá`,definitionJa:`木構造において子ノードを持たない終端のノード。`,definitionVi:`Node cuối trong cấu trúc cây, không có node con.`},{term:`枝`,reading:`えだ`,english:`Branch`,vi:`nhánh`,definitionJa:`木構造においてノード同士を結び、その関係や経路を表す部分。`,definitionVi:`Phần nối các node trong cấu trúc cây, biểu diễn quan hệ hoặc đường đi giữa chúng.`},{term:`2分木`,reading:`にぶんき`,english:`Binary Tree`,vi:`cây nhị phân`,definitionJa:`各ノードが最大2つの子ノードを持つ木構造。`,definitionVi:`Cấu trúc cây mà mỗi node có tối đa hai node con.`},{term:`完全2分木`,reading:`かんぜんにぶんぎ`,english:`Complete Binary Tree`,vi:`cây nhị phân hoàn chỉnh`,definitionJa:`最後のレベルを除いて各レベルが満たされ、最後のレベルのノードが左側から配置される2分木。`,definitionVi:`Cây nhị phân có các tầng ngoài tầng cuối được lấp đầy và các node ở tầng cuối được bố trí từ trái sang phải.`}],tags:[`data-structures`,`tree`,`leaf`,`branch`,`binary-tree`,`complete-binary-tree`]},{id:`tree-types`,order:5,titleJa:`バランス木・順序木・多分木・探索木`,titleVi:`Cây cân bằng, cây có thứ tự, cây đa nhánh và cây tìm kiếm`,importance:`high`,summaryJa:`木構造の代表的な種類であるバランス木、順序木、多分木、探索木について、それぞれの構造と用途の違いを理解する。`,summaryVi:`Tìm hiểu các loại cấu trúc cây tiêu biểu gồm cây cân bằng, cây có thứ tự, cây đa nhánh và cây tìm kiếm, đồng thời phân biệt cấu trúc và mục đích sử dụng của chúng.`,content:[{type:`heading`,ja:`バランス木`,vi:`Cây cân bằng`},{type:`paragraph`,ja:`バランス木（balanced tree）は、木の高さが極端に偏らないように一定の条件を保つ木構造である。主に二分探索木で用いられ、木の高さを抑えることで、データの検索、挿入、削除を効率よく行うことができる。`,vi:`Cây cân bằng (balanced tree) là cấu trúc cây duy trì các điều kiện nhất định để chiều cao của cây không bị lệch quá mức. Nó thường được sử dụng với cây tìm kiếm nhị phân và giúp thực hiện tìm kiếm, chèn và xóa dữ liệu hiệu quả bằng cách hạn chế chiều cao của cây.`},{type:`example`,ja:`AVL木や赤黒木は代表的なバランス木であり、データの挿入や削除によって木が偏った場合に構造を調整する。`,vi:`Cây AVL và cây đỏ-đen là những cây cân bằng tiêu biểu. Khi việc chèn hoặc xóa dữ liệu làm cây bị lệch, cấu trúc của cây sẽ được điều chỉnh.`},{type:`point`,ja:`バランス木は木の高さを抑えることで、検索・挿入・削除の効率低下を防ぐ。`,vi:`Cây cân bằng hạn chế chiều cao của cây để tránh làm giảm hiệu suất tìm kiếm, chèn và xóa.`},{type:`heading`,ja:`順序木`,vi:`Cây có thứ tự`},{type:`paragraph`,ja:`順序木（ordered tree）は、各ノードの子ノードに順序が定められている木構造である。通常の木では子ノードの並び順を区別しない場合があるが、順序木では子ノードの位置や順番に意味がある。`,vi:`Cây có thứ tự (ordered tree) là cấu trúc cây trong đó thứ tự của các node con được xác định. Trong cây thông thường có thể không phân biệt thứ tự các node con, nhưng trong cây có thứ tự, vị trí và thứ tự của chúng có ý nghĩa.`},{type:`example`,ja:`HTMLのDOMツリーでは、要素の並び順が文書の構造や表示に影響するため、子ノードの順序が重要になる。`,vi:`Trong cây DOM của HTML, thứ tự các phần tử ảnh hưởng đến cấu trúc và cách hiển thị tài liệu, vì vậy thứ tự của các node con rất quan trọng.`},{type:`point`,ja:`順序木では、同じ子ノードを持っていても、その並び順が異なれば異なる木として扱われる。`,vi:`Trong cây có thứ tự, ngay cả khi có cùng các node con, nếu thứ tự của chúng khác nhau thì cây cũng được xem là khác nhau.`},{type:`heading`,ja:`多分木`,vi:`Cây đa nhánh`},{type:`paragraph`,ja:`多分木（N-ary tree）は、一つのノードが複数の子ノードを持つことができる木構造である。二分木では一つのノードが持てる子ノードは最大2つであるが、多分木ではより多くの子ノードを持つことができる。`,vi:`Cây đa nhánh (N-ary tree) là cấu trúc cây trong đó một node có thể có nhiều node con. Trong khi cây nhị phân giới hạn tối đa hai node con cho mỗi node, cây đa nhánh có thể có nhiều node con hơn.`},{type:`example`,ja:`ファイルシステムのディレクトリ構造では、一つのディレクトリの下に複数のファイルやサブディレクトリを配置できるため、多分木として表現できる。`,vi:`Trong cấu trúc thư mục của hệ thống tệp, một thư mục có thể chứa nhiều tệp và thư mục con, vì vậy có thể biểu diễn bằng cây đa nhánh.`},{type:`point`,ja:`二分木は子ノードが最大2つであるのに対し、多分木では一つのノードが複数の子ノードを持つことができる。`,vi:`Cây nhị phân có tối đa 2 node con, trong khi cây đa nhánh cho phép một node có nhiều node con.`},{type:`heading`,ja:`探索木`,vi:`Cây tìm kiếm`},{type:`paragraph`,ja:`探索木（search tree）は、データを効率よく探索できるように、一定の規則に従ってデータを配置する木構造である。代表例である二分探索木では、各ノードについて、左部分木にはそのノードより小さい値、右部分木にはそのノードより大きい値を配置する。`,vi:`Cây tìm kiếm (search tree) là cấu trúc cây sắp xếp dữ liệu theo một quy tắc nhất định để có thể tìm kiếm hiệu quả. Trong cây tìm kiếm nhị phân tiêu biểu, các giá trị nhỏ hơn một node được đặt ở cây con bên trái và các giá trị lớn hơn được đặt ở cây con bên phải.`},{type:`point`,ja:`探索木では、データを一定の規則で配置することで、目的のデータを効率よく探索できる。`,vi:`Trong cây tìm kiếm, dữ liệu được bố trí theo quy tắc nhất định để có thể tìm kiếm dữ liệu cần thiết một cách hiệu quả.`}],terms:[{term:`バランス木`,reading:`ばらんすき`,english:`Balanced Tree`,vi:`cây cân bằng`,definitionJa:`木の高さが極端に偏らないように構造を保つ木。`,definitionVi:`Cây duy trì cấu trúc để chiều cao không bị lệch quá mức.`},{term:`順序木`,reading:`じゅんじょぎ`,english:`Ordered Tree`,vi:`cây có thứ tự`,definitionJa:`各ノードの子ノードの順序が定められている木。`,definitionVi:`Cây trong đó thứ tự của các node con được xác định.`},{term:`多分木`,reading:`たぶんき`,english:`N-ary Tree`,vi:`cây đa nhánh`,definitionJa:`一つのノードが複数の子ノードを持つことができる木。`,definitionVi:`Cây trong đó một node có thể có nhiều node con.`},{term:`探索木`,reading:`たんさくぎ`,english:`Search Tree`,vi:`cây tìm kiếm`,definitionJa:`データを効率よく探索できるように一定の規則でデータを配置した木。`,definitionVi:`Cây bố trí dữ liệu theo quy tắc nhất định để tìm kiếm hiệu quả.`}],tags:[`data-structures`,`tree`,`balanced-tree`,`ordered-tree`,`n-ary-tree`,`search-tree`]},{id:`search-trees-and-depth-first-search`,order:6,titleJa:`2分探索木・B木・AVL木・深さ優先探索`,titleVi:`Cây tìm kiếm nhị phân, cây B, cây AVL và tìm kiếm theo chiều sâu`,importance:`high`,summaryJa:`探索に用いられる代表的な木構造である2分探索木、B木、AVL木と、木やグラフを探索する基本手法である深さ優先探索について理解する。`,summaryVi:`Tìm hiểu cây tìm kiếm nhị phân, cây B và cây AVL là những cấu trúc cây tiêu biểu dùng cho tìm kiếm, cùng với tìm kiếm theo chiều sâu là một phương pháp cơ bản để duyệt cây và đồ thị.`,content:[{type:`heading`,ja:`2分探索木`,vi:`Cây tìm kiếm nhị phân`},{type:`paragraph`,ja:`2分探索木（Binary Search Tree）は、各ノードについて、左部分木にそのノードより小さいキー、右部分木にそのノードより大きいキーを配置する木構造である。この規則を利用することで、目的のキーとノードのキーを比較しながら探索範囲を絞り込むことができる。`,vi:`Cây tìm kiếm nhị phân (Binary Search Tree) là cấu trúc cây trong đó, đối với mỗi node, các khóa nhỏ hơn node đó được đặt ở cây con bên trái và các khóa lớn hơn được đặt ở cây con bên phải. Nhờ quy tắc này, có thể thu hẹp phạm vi tìm kiếm bằng cách so sánh khóa cần tìm với khóa của từng node.`},{type:`example`,ja:`例えば、キー50を持つノードに対して30を探索する場合、30は50より小さいため左部分木を探索する。この比較を繰り返して目的のデータを探す。`,vi:`Ví dụ, khi tìm khóa 30 tại node có khóa 50, vì 30 nhỏ hơn 50 nên tiếp tục tìm trong cây con bên trái. Quá trình so sánh này được lặp lại cho đến khi tìm thấy dữ liệu cần thiết.`},{type:`point`,ja:`2分探索木の探索時間は、木が適切に分散していれば平均的にO(log n)であるが、木が一方向に偏ると最悪の場合O(n)になる。`,vi:`Thời gian tìm kiếm của cây tìm kiếm nhị phân trung bình là O(log n) nếu cây được phân bố hợp lý, nhưng nếu cây bị lệch về một phía thì trường hợp xấu nhất có thể là O(n).`},{type:`heading`,ja:`B木`,vi:`Cây B`},{type:`paragraph`,ja:`B木（B-tree）は、一つのノードに複数のキーと複数の子ノードを持たせることができる平衡多分木である。木の高さを低く保ちながら大量のデータを管理できるため、外部記憶装置へのアクセス回数を減らすことができる。`,vi:`Cây B (B-tree) là một cây đa nhánh cân bằng, trong đó một node có thể chứa nhiều khóa và có nhiều node con. Do có thể quản lý lượng lớn dữ liệu trong khi giữ chiều cao của cây thấp, nó giúp giảm số lần truy cập vào bộ nhớ ngoài.`},{type:`example`,ja:`B木はデータベースのインデックスやファイルシステムなど、大量のデータを扱う場面で利用される。`,vi:`Cây B được sử dụng trong các trường hợp xử lý lượng dữ liệu lớn, chẳng hạn như chỉ mục của cơ sở dữ liệu và hệ thống tệp.`},{type:`point`,ja:`B木は一つのノードに複数のキーを格納できる平衡多分木であり、ディスクなどの外部記憶装置を利用するシステムに適している。`,vi:`Cây B là cây đa nhánh cân bằng có thể lưu nhiều khóa trong một node và phù hợp với các hệ thống sử dụng bộ nhớ ngoài như đĩa.`},{type:`heading`,ja:`AVL木`,vi:`Cây AVL`},{type:`paragraph`,ja:`AVL木（AVL Tree）は、左右の部分木の高さの差が1以下になるように保たれる平衡2分探索木である。データの挿入や削除によってバランスが崩れた場合は、回転操作によって木の構造を調整する。`,vi:`Cây AVL (AVL Tree) là một cây tìm kiếm nhị phân cân bằng, trong đó chênh lệch chiều cao giữa cây con bên trái và bên phải được giữ không quá 1. Khi việc chèn hoặc xóa dữ liệu làm mất cân bằng, cấu trúc cây được điều chỉnh bằng phép xoay.`},{type:`example`,ja:`例えば、ノードを追加した結果、一方の部分木だけが深くなった場合、単回転や二重回転を行って木の高さのバランスを回復する。`,vi:`Ví dụ, nếu sau khi thêm một node mà chỉ một phía của cây trở nên quá sâu, phép xoay đơn hoặc xoay kép được thực hiện để khôi phục sự cân bằng về chiều cao.`},{type:`point`,ja:`AVL木では木の高さがO(log n)に保たれるため、探索を最悪の場合でもO(log n)で行うことができる。`,vi:`Do chiều cao của cây AVL được duy trì ở O(log n), việc tìm kiếm có thể được thực hiện trong O(log n) ngay cả trong trường hợp xấu nhất.`},{type:`heading`,ja:`深さ優先探索`,vi:`Tìm kiếm theo chiều sâu`},{type:`paragraph`,ja:`深さ優先探索（Depth-First Search：DFS）は、木やグラフを探索する際に、一つの経路を可能な限り深く進み、行き止まりになったら直前の分岐点まで戻って別の経路を探索する方法である。`,vi:`Tìm kiếm theo chiều sâu (Depth-First Search: DFS) là phương pháp duyệt cây hoặc đồ thị bằng cách đi sâu nhất có thể theo một đường đi, sau đó khi gặp ngõ cụt thì quay lại điểm phân nhánh trước đó để tiếp tục duyệt đường khác.`},{type:`example`,ja:`迷路を探索する場合、一つの道を行けるところまで進み、行き止まりになったら戻って別の道を試す方法は、深さ優先探索の考え方に相当する。`,vi:`Khi tìm đường trong mê cung, việc đi theo một con đường đến khi không thể đi tiếp, sau đó quay lại và thử đường khác chính là cách suy nghĩ của tìm kiếm theo chiều sâu.`},{type:`point`,ja:`深さ優先探索はスタックを利用して実現できる。再帰呼出しを用いる場合も、内部ではコールスタックが利用される。`,vi:`Tìm kiếm theo chiều sâu có thể được thực hiện bằng stack. Khi sử dụng lời gọi đệ quy, call stack cũng được sử dụng ở bên trong.`}],terms:[{term:`2分探索木`,reading:`にぶんたんさくぎ`,english:`Binary Search Tree`,vi:`cây tìm kiếm nhị phân`,definitionJa:`左部分木に小さいキー、右部分木に大きいキーを配置する2分木。`,definitionVi:`Cây nhị phân đặt các khóa nhỏ hơn ở cây con trái và các khóa lớn hơn ở cây con phải.`},{term:`B木`,reading:`びーき`,english:`B-tree`,vi:`cây B`,definitionJa:`一つのノードに複数のキーと子ノードを持つことができる平衡多分木。`,definitionVi:`Cây đa nhánh cân bằng trong đó một node có thể chứa nhiều khóa và nhiều node con.`},{term:`AVL木`,reading:`えーぶいえるき`,english:`AVL Tree`,vi:`cây AVL`,definitionJa:`左右の部分木の高さの差を1以下に保つ平衡2分探索木。`,definitionVi:`Cây tìm kiếm nhị phân cân bằng giữ chênh lệch chiều cao giữa hai cây con không quá 1.`},{term:`深さ優先探索`,reading:`ふかさゆうせんたんさく`,english:`Depth-First Search`,vi:`tìm kiếm theo chiều sâu`,definitionJa:`一つの経路を可能な限り深く探索し、行き止まりになると戻って別の経路を探索する方法。`,definitionVi:`Phương pháp đi sâu nhất có thể theo một đường đi rồi quay lại để duyệt đường khác khi gặp ngõ cụt.`}],tags:[`data-structures`,`binary-search-tree`,`b-tree`,`avl-tree`,`depth-first-search`,`tree-search`]},{id:`tree-traversal-and-breadth-first-search`,order:7,titleJa:`幅優先探索と木の走査`,titleVi:`Tìm kiếm theo chiều rộng và duyệt cây`,importance:`high`,summaryJa:`幅優先探索の仕組みと、木構造を走査する代表的な方法である先行順・中間順・後行順について理解する。`,summaryVi:`Tìm hiểu cơ chế của tìm kiếm theo chiều rộng và ba phương pháp duyệt cây tiêu biểu: thứ tự trước, thứ tự giữa và thứ tự sau.`,content:[{type:`heading`,ja:`幅優先探索`,vi:`Tìm kiếm theo chiều rộng`},{type:`paragraph`,ja:`幅優先探索（Breadth-First Search：BFS）は、木やグラフを探索する際に、現在のノードに隣接するノードを先に調べ、その後で次の階層へ進む探索方法である。探索予定のノードをキューに格納し、先に追加されたノードから順番に処理する。`,vi:`Tìm kiếm theo chiều rộng (Breadth-First Search: BFS) là phương pháp duyệt cây hoặc đồ thị bằng cách kiểm tra trước các node liền kề với node hiện tại, sau đó mới chuyển sang tầng tiếp theo. Các node chờ được duyệt được lưu trong queue và xử lý theo thứ tự được thêm vào.`},{type:`example`,ja:`重みのないグラフで二つのノード間の最短経路を求める場合、幅優先探索を利用することで、始点から近いノードから順番に探索できる。`,vi:`Khi tìm đường đi ngắn nhất giữa hai node trong đồ thị không có trọng số, BFS cho phép duyệt lần lượt từ những node gần điểm bắt đầu nhất.`},{type:`point`,ja:`幅優先探索はキュー（FIFO）を利用する。深さ優先探索がスタックを利用することとの違いを覚える。`,vi:`BFS sử dụng queue (FIFO). Cần phân biệt với DFS sử dụng stack.`},{type:`heading`,ja:`先行順`,vi:`Duyệt thứ tự trước`},{type:`paragraph`,ja:`先行順（Preorder Traversal）は、2分木を「根 → 左部分木 → 右部分木」の順に走査する方法である。各部分木についても同じ順序を再帰的に適用する。`,vi:`Duyệt thứ tự trước (Preorder Traversal) là phương pháp duyệt cây nhị phân theo thứ tự "gốc → cây con trái → cây con phải". Quy tắc tương tự được áp dụng đệ quy cho từng cây con.`},{type:`example`,ja:`根がA、左の子がB、右の子がCの場合、先行順では A → B → C の順に訪問する。`,vi:`Nếu A là node gốc, B là node con trái và C là node con phải, thứ tự duyệt trước là A → B → C.`},{type:`point`,ja:`先行順：根 → 左 → 右。`,vi:`Preorder: Gốc → Trái → Phải.`},{type:`heading`,ja:`中間順`,vi:`Duyệt thứ tự giữa`},{type:`paragraph`,ja:`中間順（Inorder Traversal）は、2分木を「左部分木 → 根 → 右部分木」の順に走査する方法である。2分探索木を中間順で走査すると、キーを昇順に取り出すことができる。`,vi:`Duyệt thứ tự giữa (Inorder Traversal) là phương pháp duyệt cây nhị phân theo thứ tự "cây con trái → gốc → cây con phải". Khi duyệt cây tìm kiếm nhị phân theo thứ tự giữa, có thể lấy các khóa theo thứ tự tăng dần.`},{type:`example`,ja:`根がB、左の子がA、右の子がCの場合、中間順では A → B → C の順に訪問する。`,vi:`Nếu B là node gốc, A là node con trái và C là node con phải, thứ tự duyệt giữa là A → B → C.`},{type:`point`,ja:`中間順：左 → 根 → 右。2分探索木では昇順にデータを取り出せる。`,vi:`Inorder: Trái → Gốc → Phải. Với cây tìm kiếm nhị phân, kết quả được lấy theo thứ tự tăng dần.`},{type:`heading`,ja:`後行順`,vi:`Duyệt thứ tự sau`},{type:`paragraph`,ja:`後行順（Postorder Traversal）は、2分木を「左部分木 → 右部分木 → 根」の順に走査する方法である。子ノードを先に処理してから親ノードを処理する。`,vi:`Duyệt thứ tự sau (Postorder Traversal) là phương pháp duyệt cây nhị phân theo thứ tự "cây con trái → cây con phải → gốc". Các node con được xử lý trước node cha.`},{type:`example`,ja:`根がA、左の子がB、右の子がCの場合、後行順では B → C → A の順に訪問する。`,vi:`Nếu A là node gốc, B là node con trái và C là node con phải, thứ tự duyệt sau là B → C → A.`},{type:`point`,ja:`後行順：左 → 右 → 根。数式を構文木で表した場合、後行順で走査すると逆ポーランド記法（後置記法）に対応する。`,vi:`Postorder: Trái → Phải → Gốc. Khi biểu diễn biểu thức bằng cây cú pháp, duyệt postorder tương ứng với ký pháp hậu tố (Reverse Polish Notation).`}],terms:[{term:`幅優先探索`,reading:`はばゆうせんたんさく`,english:`Breadth-First Search`,vi:`tìm kiếm theo chiều rộng`,definitionJa:`開始ノードに近いノードから、階層ごとに順番に探索する方法。`,definitionVi:`Phương pháp tìm kiếm lần lượt theo từng tầng, bắt đầu từ các node gần node xuất phát.`},{term:`先行順`,reading:`せんこうじゅん`,english:`Preorder Traversal`,vi:`duyệt thứ tự trước`,definitionJa:`根、左部分木、右部分木の順に木を走査する方法。`,definitionVi:`Phương pháp duyệt cây theo thứ tự gốc, trái, phải.`},{term:`中間順`,reading:`ちゅうかんじゅん`,english:`Inorder Traversal`,vi:`duyệt thứ tự giữa`,definitionJa:`左部分木、根、右部分木の順に木を走査する方法。`,definitionVi:`Phương pháp duyệt cây theo thứ tự trái, gốc, phải.`},{term:`後行順`,reading:`こうこうじゅん`,english:`Postorder Traversal`,vi:`duyệt thứ tự sau`,definitionJa:`左部分木、右部分木、根の順に木を走査する方法。`,definitionVi:`Phương pháp duyệt cây theo thứ tự trái, phải, gốc.`}],tags:[`data-structures`,`breadth-first-search`,`bfs`,`tree-traversal`,`preorder`,`inorder`,`postorder`]}]},h={id:`algorithms`,order:2,titleJa:`アルゴリズム`,titleVi:`Thuật toán`,syllabus:`9.2`,lessons:[{id:`flowchart-and-basic-sorting`,order:1,titleJa:`流れ図と基本的なソート`,titleVi:`Lưu đồ và các thuật toán sắp xếp cơ bản`,importance:`high`,summaryJa:`アルゴリズムを図で表現する流れ図の基本と、代表的なソートアルゴリズムである選択ソート、バブルソート、マージソートの仕組みと特徴を理解する。`,summaryVi:`Tìm hiểu kiến thức cơ bản về lưu đồ dùng để biểu diễn thuật toán và cơ chế, đặc điểm của các thuật toán sắp xếp tiêu biểu gồm selection sort, bubble sort và merge sort.`,content:[{type:`heading`,ja:`流れ図`,vi:`Lưu đồ`},{type:`paragraph`,ja:`流れ図（フローチャート）は、処理やアルゴリズムの手順を図で表現したものである。処理の流れや条件による分岐、繰返しなどを視覚的に表すことができ、プログラムや業務手順を整理するときに利用される。`,vi:`Lưu đồ (flowchart) là sơ đồ biểu diễn các bước xử lý hoặc trình tự của một thuật toán. Nó cho phép thể hiện trực quan luồng xử lý, rẽ nhánh theo điều kiện và các thao tác lặp, vì vậy thường được sử dụng khi tổ chức chương trình hoặc quy trình nghiệp vụ.`},{type:`point`,ja:`流れ図では、端子、処理、判断、データ、流れ線などの記号を使って処理の流れを表す。`,vi:`Trong lưu đồ, các ký hiệu như bắt đầu/kết thúc, xử lý, điều kiện, dữ liệu và đường luồng được sử dụng để biểu diễn quá trình xử lý.`},{type:`example`,ja:`条件によって処理Aまたは処理Bを実行する場合は、判断を表す記号から二つの経路に分岐させて表現する。`,vi:`Ví dụ, nếu tùy theo điều kiện mà thực hiện xử lý A hoặc xử lý B, lưu đồ sẽ dùng ký hiệu điều kiện và chia thành hai nhánh xử lý.`},{type:`heading`,ja:`選択ソート`,vi:`Sắp xếp chọn`},{type:`paragraph`,ja:`選択ソート（Selection Sort）は、未整列部分から最小値または最大値を探し、それを未整列部分の先頭の要素と交換する操作を繰り返すソートアルゴリズムである。操作を繰り返すたびに、整列済みの範囲が一つずつ広がっていく。`,vi:`Sắp xếp chọn (Selection Sort) là thuật toán tìm phần tử nhỏ nhất hoặc lớn nhất trong vùng chưa được sắp xếp rồi đổi chỗ nó với phần tử đầu tiên của vùng đó. Sau mỗi lần thực hiện, vùng đã được sắp xếp tăng thêm một phần tử.`},{type:`example`,ja:`配列［3, 1, 4, 2］を昇順に並べる場合、まず最小値1を選び、先頭の3と交換して［1, 3, 4, 2］とする。次に残りの部分から最小値2を選び、3と交換する。`,vi:`Ví dụ, khi sắp xếp mảng [3, 1, 4, 2] theo thứ tự tăng dần, trước tiên chọn giá trị nhỏ nhất là 1 và đổi chỗ với 3 để được [1, 3, 4, 2]. Sau đó chọn 2 là giá trị nhỏ nhất trong phần còn lại và đổi chỗ với 3.`},{type:`point`,ja:`選択ソートは実装が単純であるが、平均・最悪の場合ともに比較回数はO(n²)となる。`,vi:`Selection Sort đơn giản để triển khai nhưng số phép so sánh ở cả trường hợp trung bình và xấu nhất đều có độ phức tạp O(n²).`},{type:`heading`,ja:`バブルソート`,vi:`Sắp xếp nổi bọt`},{type:`paragraph`,ja:`バブルソート（Bubble Sort）は、隣り合う要素を比較し、順序が逆であれば交換する操作を繰り返すソートアルゴリズムである。昇順に並べる場合、一方向に比較を繰り返すことで、大きな値が配列の端へ順次移動していく。`,vi:`Sắp xếp nổi bọt (Bubble Sort) là thuật toán liên tục so sánh hai phần tử liền kề và đổi chỗ nếu chúng đang ở sai thứ tự. Khi sắp xếp tăng dần, việc lặp lại các phép so sánh theo một hướng sẽ làm các giá trị lớn dần di chuyển về cuối mảng.`},{type:`example`,ja:`［3, 1, 4, 2］では、3と1を比較して交換し、次に3と4を比較し、さらに4と2を比較して交換する。この一巡によって大きな値4が末尾へ移動する。`,vi:`Với [3, 1, 4, 2], đầu tiên so sánh 3 và 1 rồi đổi chỗ, tiếp theo so sánh 3 và 4, sau đó so sánh 4 và 2 rồi đổi chỗ. Sau một lượt, giá trị lớn 4 sẽ được đưa về cuối.`},{type:`point`,ja:`バブルソートは隣接する要素を比較・交換する。基本的な時間計算量はO(n²)である。`,vi:`Bubble Sort so sánh và đổi chỗ các phần tử liền kề. Độ phức tạp thời gian cơ bản là O(n²).`},{type:`heading`,ja:`マージソート`,vi:`Sắp xếp trộn`},{type:`paragraph`,ja:`マージソート（Merge Sort）は、データ列を分割し、それぞれを整列した後で併合する分割統治法に基づくソートアルゴリズムである。データを繰り返し分割して小さな単位にし、それらを順序を保ちながら併合していく。`,vi:`Sắp xếp trộn (Merge Sort) là thuật toán sắp xếp dựa trên phương pháp chia để trị: chia dãy dữ liệu thành các phần nhỏ, sắp xếp từng phần rồi trộn chúng lại. Dữ liệu được chia liên tục thành các đơn vị nhỏ và sau đó được hợp nhất lại trong khi vẫn duy trì đúng thứ tự.`},{type:`example`,ja:`［4, 1, 3, 2］を［4, 1］と［3, 2］に分割し、さらに一要素ずつに分割する。その後、［1, 4］と［2, 3］に併合し、最後に［1, 2, 3, 4］へ併合する。`,vi:`Ví dụ, [4, 1, 3, 2] được chia thành [4, 1] và [3, 2], sau đó tiếp tục chia thành từng phần tử. Tiếp theo chúng được trộn thành [1, 4] và [2, 3], cuối cùng hợp nhất thành [1, 2, 3, 4].`},{type:`point`,ja:`マージソートの時間計算量は最悪の場合でもO(n log n)である。一方、併合処理のための追加領域が必要になる。`,vi:`Merge Sort có độ phức tạp thời gian O(n log n) ngay cả trong trường hợp xấu nhất. Tuy nhiên, thuật toán cần thêm vùng nhớ để thực hiện quá trình trộn.`},{type:`point`,ja:`FEでは、選択ソート・バブルソート・マージソートについて、どのように要素が移動するかと時間計算量の違いを区別できるようにする。`,vi:`Trong FE, cần phân biệt cách các phần tử được di chuyển và sự khác nhau về độ phức tạp thời gian giữa Selection Sort, Bubble Sort và Merge Sort.`}],terms:[{term:`流れ図`,reading:`ながれず`,english:`Flowchart`,vi:`lưu đồ`,definitionJa:`処理やアルゴリズムの手順を記号と線を用いて図で表したもの。`,definitionVi:`Sơ đồ biểu diễn trình tự xử lý hoặc thuật toán bằng các ký hiệu và đường nối.`},{term:`選択ソート`,reading:`せんたくそーと`,english:`Selection Sort`,vi:`sắp xếp chọn`,definitionJa:`未整列部分から最小値または最大値を選び、所定の位置へ移動する操作を繰り返すソート方法。`,definitionVi:`Phương pháp sắp xếp bằng cách liên tục chọn giá trị nhỏ nhất hoặc lớn nhất từ vùng chưa sắp xếp và đưa nó về vị trí thích hợp.`},{term:`バブルソート`,reading:`ばぶるそーと`,english:`Bubble Sort`,vi:`sắp xếp nổi bọt`,definitionJa:`隣接する要素を比較し、必要に応じて交換する操作を繰り返すソート方法。`,definitionVi:`Phương pháp sắp xếp bằng cách liên tục so sánh các phần tử liền kề và đổi chỗ khi cần thiết.`},{term:`マージソート`,reading:`まーじそーと`,english:`Merge Sort`,vi:`sắp xếp trộn`,definitionJa:`データを分割し、整列された部分列を順次併合するソート方法。`,definitionVi:`Phương pháp sắp xếp bằng cách chia dữ liệu rồi lần lượt trộn các dãy con đã được sắp xếp.`}],tags:[`algorithms`,`flowchart`,`sorting`,`selection-sort`,`bubble-sort`,`merge-sort`]},{id:`advanced-sorting-algorithms`,order:2,titleJa:`挿入ソートと高速なソート`,titleVi:`Sắp xếp chèn và các thuật toán sắp xếp hiệu quả`,importance:`high`,summaryJa:`代表的なソートアルゴリズムである挿入ソート、シェルソート、クイックソート、ヒープソートについて、基本的な仕組みと特徴を理解する。`,summaryVi:`Tìm hiểu cơ chế cơ bản và đặc điểm của các thuật toán sắp xếp tiêu biểu gồm Insertion Sort, Shell Sort, Quick Sort và Heap Sort.`,content:[{type:`heading`,ja:`挿入ソート`,vi:`Sắp xếp chèn`},{type:`paragraph`,ja:`挿入ソート（Insertion Sort）は、未整列の要素を一つずつ取り出し、既に整列されている部分の適切な位置に挿入していくソートアルゴリズムである。先頭の要素を整列済みと考え、次の要素から順番に正しい位置へ挿入することで、整列済みの範囲を広げていく。`,vi:`Sắp xếp chèn (Insertion Sort) là thuật toán lần lượt lấy từng phần tử chưa được sắp xếp và chèn nó vào vị trí thích hợp trong phần đã được sắp xếp. Phần tử đầu tiên được xem là đã sắp xếp, sau đó từng phần tử tiếp theo được chèn vào đúng vị trí để mở rộng dần vùng đã sắp xếp.`},{type:`example`,ja:`［3, 1, 4, 2］を昇順に整列する場合、まず3を整列済みとし、1を3の前に挿入して［1, 3, 4, 2］とする。次に4を適切な位置に置き、最後に2を1と3の間に挿入して［1, 2, 3, 4］とする。`,vi:`Ví dụ, khi sắp xếp [3, 1, 4, 2] theo thứ tự tăng dần, trước tiên coi 3 là phần đã sắp xếp, sau đó chèn 1 vào trước 3 để được [1, 3, 4, 2]. Tiếp theo đặt 4 vào vị trí thích hợp và cuối cùng chèn 2 vào giữa 1 và 3 để được [1, 2, 3, 4].`},{type:`point`,ja:`挿入ソートは、データ数が少ない場合や、あらかじめほぼ整列されているデータに対して効率がよい。平均・最悪時間計算量はO(n²)である。`,vi:`Insertion Sort hoạt động hiệu quả khi số lượng dữ liệu nhỏ hoặc dữ liệu ban đầu gần như đã được sắp xếp. Độ phức tạp thời gian trung bình và trường hợp xấu nhất là O(n²).`},{type:`heading`,ja:`シェルソート`,vi:`Sắp xếp Shell`},{type:`paragraph`,ja:`シェルソート（Shell Sort）は、挿入ソートを改良したソートアルゴリズムである。一定の間隔（ギャップ）ごとに離れた要素をグループ化して整列し、その間隔を段階的に小さくしながら整列を繰り返す。最後に間隔を1として挿入ソートを行う。`,vi:`Shell Sort là thuật toán cải tiến từ Insertion Sort. Các phần tử cách nhau một khoảng nhất định (gap) được nhóm lại và sắp xếp, sau đó khoảng cách này được giảm dần. Cuối cùng, thuật toán thực hiện sắp xếp với khoảng cách bằng 1 giống như Insertion Sort.`},{type:`point`,ja:`離れた位置にある要素を先に移動させて全体をおおまかに整列してから挿入ソートを行うため、通常の挿入ソートより効率を高めることができる。`,vi:`Do các phần tử ở xa nhau được di chuyển trước để toàn bộ dữ liệu trở nên gần với trạng thái đã sắp xếp rồi mới thực hiện Insertion Sort, Shell Sort có thể hiệu quả hơn Insertion Sort thông thường.`},{type:`heading`,ja:`クイックソート`,vi:`Sắp xếp nhanh`},{type:`paragraph`,ja:`クイックソート（Quick Sort）は、基準となる値（ピボット）を選び、ピボットより小さい要素と大きい要素にデータを分割し、それぞれの部分に対して同じ処理を再帰的に行うソートアルゴリズムである。分割統治法を利用する代表的なアルゴリズムである。`,vi:`Quick Sort là thuật toán chọn một giá trị làm mốc (pivot), chia dữ liệu thành các phần tử nhỏ hơn và lớn hơn pivot, rồi tiếp tục thực hiện cùng quá trình một cách đệ quy trên từng phần. Đây là thuật toán tiêu biểu sử dụng phương pháp chia để trị.`},{type:`example`,ja:`例えば5をピボットとした場合、5より小さい要素を一方に、5より大きい要素をもう一方に分ける。その後、それぞれの部分でもピボットを選んで同じ処理を繰り返す。`,vi:`Ví dụ, nếu chọn 5 làm pivot, các phần tử nhỏ hơn 5 được đưa về một phía và các phần tử lớn hơn 5 về phía còn lại. Sau đó tiếp tục chọn pivot và thực hiện tương tự trên từng phần.`},{type:`point`,ja:`クイックソートの平均時間計算量はO(n log n)であるが、分割が極端に偏る場合には最悪O(n²)となる。`,vi:`Độ phức tạp thời gian trung bình của Quick Sort là O(n log n), nhưng nếu việc phân chia bị lệch nghiêm trọng thì trường hợp xấu nhất có thể là O(n²).`},{type:`heading`,ja:`ヒープソート`,vi:`Sắp xếp vun đống`},{type:`paragraph`,ja:`ヒープソート（Heap Sort）は、データをヒープと呼ばれる木構造として構成し、最大値または最小値を順番に取り出して整列するアルゴリズムである。最大ヒープを利用する場合、根にある最大値を取り出し、残った要素から再びヒープを構成する操作を繰り返す。`,vi:`Heap Sort là thuật toán tổ chức dữ liệu thành cấu trúc cây gọi là heap rồi lần lượt lấy ra giá trị lớn nhất hoặc nhỏ nhất để sắp xếp. Khi sử dụng max heap, giá trị lớn nhất ở gốc được lấy ra, sau đó heap được xây dựng lại từ các phần tử còn lại và quá trình này được lặp lại.`},{type:`point`,ja:`ヒープソートの時間計算量は平均・最悪の場合ともにO(n log n)であり、入力データの並び方による性能の悪化が比較的小さい。`,vi:`Heap Sort có độ phức tạp thời gian O(n log n) ở cả trường hợp trung bình và xấu nhất, nên hiệu năng ít bị suy giảm do thứ tự ban đầu của dữ liệu.`},{type:`point`,ja:`FEでは、挿入ソートは「整列済み部分の適切な位置へ挿入」、シェルソートは「間隔を空けて整列」、クイックソートは「ピボットによる分割」、ヒープソートは「ヒープから最大値・最小値を取り出す」という特徴を区別することが重要である。`,vi:`Trong FE, cần phân biệt: Insertion Sort là 'chèn vào vị trí thích hợp trong phần đã sắp xếp', Shell Sort là 'sắp xếp theo khoảng cách', Quick Sort là 'phân chia dựa trên pivot', còn Heap Sort là 'lấy giá trị lớn nhất/nhỏ nhất từ heap'.`}],terms:[{term:`挿入ソート`,reading:`そうにゅうそーと`,english:`Insertion Sort`,vi:`sắp xếp chèn`,definitionJa:`未整列の要素を、整列済み部分の適切な位置へ順次挿入するソート方法。`,definitionVi:`Phương pháp sắp xếp bằng cách lần lượt chèn các phần tử chưa sắp xếp vào vị trí thích hợp trong phần đã sắp xếp.`},{term:`シェルソート`,reading:`しぇるそーと`,english:`Shell Sort`,vi:`sắp xếp Shell`,definitionJa:`一定間隔の要素を整列し、その間隔を徐々に小さくしていくソート方法。`,definitionVi:`Phương pháp sắp xếp các phần tử theo một khoảng cách nhất định rồi giảm dần khoảng cách đó.`},{term:`クイックソート`,reading:`くいっくそーと`,english:`Quick Sort`,vi:`sắp xếp nhanh`,definitionJa:`ピボットを基準にデータを分割し、それぞれを再帰的に整列するソート方法。`,definitionVi:`Phương pháp sắp xếp bằng cách chia dữ liệu dựa trên pivot rồi sắp xếp đệ quy từng phần.`},{term:`ヒープソート`,reading:`ひーぷそーと`,english:`Heap Sort`,vi:`sắp xếp vun đống`,definitionJa:`ヒープ構造を利用して最大値または最小値を順次取り出すソート方法。`,definitionVi:`Phương pháp sắp xếp sử dụng cấu trúc heap để lần lượt lấy ra giá trị lớn nhất hoặc nhỏ nhất.`}],tags:[`algorithms`,`sorting`,`insertion-sort`,`shell-sort`,`quick-sort`,`heap-sort`]},{id:`search-and-recursive-algorithms`,order:3,titleJa:`探索法と再帰的アルゴリズム`,titleVi:`Thuật toán tìm kiếm và đệ quy`,importance:`high`,summaryJa:`代表的な探索アルゴリズムである線形探索法、2分探索法、ハッシュ表探索法の仕組みと特徴、および再帰的アルゴリズムの基本的な考え方を理解する。`,summaryVi:`Tìm hiểu cơ chế và đặc điểm của các thuật toán tìm kiếm tiêu biểu gồm tìm kiếm tuyến tính, tìm kiếm nhị phân, tìm kiếm bằng bảng băm, đồng thời nắm được tư duy cơ bản của thuật toán đệ quy.`,content:[{type:`heading`,ja:`線形探索法`,vi:`Tìm kiếm tuyến tính`},{type:`paragraph`,ja:`線形探索法（Linear Search）は、データ列の先頭から順番に要素を調べ、目的の値と一致するかを一つずつ比較する探索方法である。データが整列されていなくても利用でき、仕組みが単純で実装しやすい。`,vi:`Tìm kiếm tuyến tính (Linear Search) là phương pháp lần lượt kiểm tra từng phần tử từ đầu dãy dữ liệu và so sánh với giá trị cần tìm. Phương pháp này có thể sử dụng ngay cả khi dữ liệu chưa được sắp xếp, đồng thời có cơ chế đơn giản và dễ triển khai.`},{type:`example`,ja:`［8, 3, 6, 2, 9］から2を探す場合、8、3、6、2の順に比較し、4回目の比較で目的の値を発見する。`,vi:`Ví dụ, khi tìm giá trị 2 trong [8, 3, 6, 2, 9], lần lượt so sánh với 8, 3, 6 và 2. Giá trị cần tìm được phát hiện ở lần so sánh thứ 4.`},{type:`point`,ja:`線形探索法では、最悪の場合は全ての要素を調べる必要があるため、時間計算量はO(n)である。`,vi:`Trong trường hợp xấu nhất, Linear Search phải kiểm tra toàn bộ phần tử nên có độ phức tạp thời gian O(n).`},{type:`heading`,ja:`2分探索法`,vi:`Tìm kiếm nhị phân`},{type:`paragraph`,ja:`2分探索法（Binary Search）は、整列済みのデータを対象として、探索範囲の中央の要素と目的の値を比較し、探索範囲を半分ずつ絞り込んでいく方法である。中央の値より目的の値が小さければ左側、大きければ右側を次の探索対象とする。`,vi:`Tìm kiếm nhị phân (Binary Search) là phương pháp áp dụng cho dữ liệu đã được sắp xếp. Thuật toán so sánh giá trị cần tìm với phần tử ở giữa và thu hẹp phạm vi tìm kiếm xuống còn một nửa. Nếu giá trị cần tìm nhỏ hơn phần tử giữa thì tiếp tục tìm bên trái, nếu lớn hơn thì tìm bên phải.`},{type:`example`,ja:`昇順に並んだ［1, 3, 5, 7, 9, 11, 13］から11を探す場合、まず中央の7と比較する。11は7より大きいため右半分に絞り込み、次に11と比較して発見する。`,vi:`Ví dụ, khi tìm 11 trong dãy đã sắp xếp [1, 3, 5, 7, 9, 11, 13], trước tiên so sánh với giá trị giữa là 7. Vì 11 lớn hơn 7 nên chỉ tìm ở nửa bên phải, sau đó so sánh với 11 và tìm thấy kết quả.`},{type:`point`,ja:`2分探索法を利用するためには、原則として探索対象のデータがあらかじめ整列されている必要がある。時間計算量はO(log n)である。`,vi:`Để sử dụng Binary Search, về nguyên tắc dữ liệu cần tìm phải được sắp xếp trước. Độ phức tạp thời gian là O(log n).`},{type:`heading`,ja:`ハッシュ表探索法`,vi:`Tìm kiếm bằng bảng băm`},{type:`paragraph`,ja:`ハッシュ表探索法（Hash Table Search Method）は、キーにハッシュ関数を適用して得られた値を基に格納位置を決定し、その位置を利用してデータを探索する方法である。適切なハッシュ関数と十分な表領域を用いることで、高速な検索が可能になる。`,vi:`Tìm kiếm bằng bảng băm (Hash Table Search Method) là phương pháp áp dụng hàm băm lên khóa để xác định vị trí lưu trữ và sử dụng vị trí đó để tìm dữ liệu. Với hàm băm thích hợp và vùng bảng đủ lớn, việc tìm kiếm có thể được thực hiện rất nhanh.`},{type:`example`,ja:`社員番号をキーとしてハッシュ関数で格納位置を求め、その位置に社員情報を保存しておけば、社員番号から対応する情報を効率よく検索できる。`,vi:`Ví dụ, nếu sử dụng mã nhân viên làm khóa, tính vị trí lưu bằng hàm băm rồi lưu thông tin nhân viên tại đó, ta có thể tìm thông tin tương ứng một cách hiệu quả từ mã nhân viên.`},{type:`point`,ja:`異なるキーから同じハッシュ値が得られることを衝突（シノニム）という。衝突が発生した場合には、チェイン法やオープンアドレス法などで処理する。`,vi:`Hiện tượng các khóa khác nhau tạo ra cùng một giá trị băm được gọi là xung đột (collision/synonym). Khi xảy ra xung đột, có thể xử lý bằng phương pháp chaining hoặc open addressing.`},{type:`point`,ja:`ハッシュ表では、適切に設計されていれば探索・挿入・削除を平均O(1)で行うことができる。`,vi:`Nếu bảng băm được thiết kế phù hợp, thao tác tìm kiếm, chèn và xóa có thể thực hiện với độ phức tạp trung bình O(1).`},{type:`heading`,ja:`再帰的アルゴリズム`,vi:`Thuật toán đệ quy`},{type:`paragraph`,ja:`再帰的アルゴリズム（Recursive Algorithm）は、ある処理の中から同じ処理自身を呼び出すことで問題を解決するアルゴリズムである。大きな問題を同じ性質を持つより小さな問題に分解し、基本となる条件に到達するまで処理を繰り返す。`,vi:`Thuật toán đệ quy (Recursive Algorithm) là thuật toán giải quyết vấn đề bằng cách gọi lại chính xử lý đó từ bên trong nó. Một vấn đề lớn được chia thành các vấn đề nhỏ hơn có cùng tính chất và quá trình được lặp lại cho đến khi đạt điều kiện cơ sở.`},{type:`example`,ja:`階乗n!は、n!＝n×(n－1)!として再帰的に定義できる。例えば、4!＝4×3!、3!＝3×2!というように処理を続け、1!に到達したところで結果を順に戻していく。`,vi:`Ví dụ, giai thừa n! có thể được định nghĩa đệ quy là n! = n × (n−1)!. Chẳng hạn 4! = 4 × 3!, 3! = 3 × 2!, tiếp tục cho đến 1!, sau đó lần lượt trả kết quả ngược trở lại.`},{type:`point`,ja:`再帰処理では、再帰を終了するための条件（基底条件）が必要である。終了条件がない場合、再帰呼出しが続き、スタック領域を使い切る可能性がある。`,vi:`Xử lý đệ quy cần có điều kiện kết thúc (base case). Nếu không có điều kiện kết thúc, lời gọi đệ quy sẽ tiếp tục và có thể làm cạn kiệt vùng nhớ stack.`},{type:`point`,ja:`FEでは、線形探索は「先頭から順に探索」、2分探索は「整列済みデータを半分ずつ探索」、ハッシュ表探索は「ハッシュ関数で格納位置を求める」、再帰は「処理自身を呼び出す」と区別することが重要である。`,vi:`Trong FE, cần phân biệt: Linear Search là 'tìm lần lượt từ đầu', Binary Search là 'chia đôi phạm vi trên dữ liệu đã sắp xếp', Hash Search là 'xác định vị trí bằng hàm băm', còn đệ quy là 'xử lý tự gọi lại chính nó'.`}],terms:[{term:`線形探索法`,reading:`せんけいたんさくほう`,english:`Linear Search`,vi:`tìm kiếm tuyến tính`,definitionJa:`データを先頭から順番に比較して目的の値を探す方法。`,definitionVi:`Phương pháp tìm giá trị bằng cách lần lượt so sánh dữ liệu từ đầu.`},{term:`2分探索法`,reading:`にぶんたんさくほう`,english:`Binary Search Method`,vi:`tìm kiếm nhị phân`,definitionJa:`整列済みデータの探索範囲を半分ずつ絞り込んで目的の値を探す方法。`,definitionVi:`Phương pháp tìm kiếm bằng cách liên tục thu hẹp một nửa phạm vi trên dữ liệu đã sắp xếp.`},{term:`ハッシュ表探索法`,reading:`はっしゅひょうたんさくほう`,english:`Hash Table Search Method`,vi:`tìm kiếm bằng bảng băm`,definitionJa:`ハッシュ関数によってキーから格納位置を求め、データを探索する方法。`,definitionVi:`Phương pháp sử dụng hàm băm để xác định vị trí lưu trữ từ khóa và tìm dữ liệu.`},{term:`再帰的アルゴリズム`,reading:`さいきてきあるごりずむ`,english:`Recursive Algorithm`,vi:`thuật toán đệ quy`,definitionJa:`処理の中から同じ処理自身を呼び出して問題を解くアルゴリズム。`,definitionVi:`Thuật toán giải quyết vấn đề bằng cách gọi lại chính nó trong quá trình xử lý.`}],tags:[`algorithms`,`search`,`linear-search`,`binary-search`,`hash-table`,`recursion`]},{id:`graph-search-and-shortest-path`,order:4,titleJa:`グラフ探索と最短経路`,titleVi:`Tìm kiếm trên đồ thị và đường đi ngắn nhất`,importance:`high`,summaryJa:`グラフや木構造を探索する代表的な手法である深さ優先探索と幅優先探索、および最短経路探索とダイクストラ法の基本的な仕組みと特徴を理解する。`,summaryVi:`Tìm hiểu cơ chế và đặc điểm cơ bản của tìm kiếm theo chiều sâu, tìm kiếm theo chiều rộng, bài toán tìm đường đi ngắn nhất và thuật toán Dijkstra.`,content:[{type:`heading`,ja:`深さ優先探索`,vi:`Tìm kiếm theo chiều sâu`},{type:`paragraph`,ja:`深さ優先探索（Depth-First Search：DFS）は、グラフや木構造において、一つの経路を可能な限り深く探索し、行き止まりに達したら戻って別の経路を探索する方法である。未訪問の隣接ノードを順にたどり、探索できるノードがなくなったところで直前のノードへ戻る。`,vi:`Tìm kiếm theo chiều sâu (Depth-First Search: DFS) là phương pháp đi sâu nhất có thể theo một đường trong đồ thị hoặc cây. Khi không thể đi tiếp, thuật toán quay lại và thử một đường khác. Các nút kề chưa được thăm được duyệt liên tục cho đến khi không còn nút nào để đi tiếp.`},{type:`point`,ja:`深さ優先探索は、スタックまたは再帰処理を利用して実装できる。`,vi:`DFS có thể được triển khai bằng stack hoặc bằng xử lý đệ quy.`},{type:`example`,ja:`迷路を探索する場合、一つの道を行けるところまで進み、行き止まりになったら直前の分岐点まで戻って別の道を試す方法が深さ優先探索に相当する。`,vi:`Ví dụ khi giải mê cung, ta đi theo một đường xa nhất có thể. Nếu gặp ngõ cụt thì quay lại điểm rẽ trước đó và thử đường khác. Đây là cách hoạt động của DFS.`},{type:`heading`,ja:`幅優先探索`,vi:`Tìm kiếm theo chiều rộng`},{type:`paragraph`,ja:`幅優先探索（Breadth-First Search：BFS）は、開始ノードに近いノードから順番に探索し、同じ深さのノードを調べた後で次の深さへ進む探索方法である。探索予定のノードをキューに格納し、先に登録されたノードから順に処理していく。`,vi:`Tìm kiếm theo chiều rộng (Breadth-First Search: BFS) là phương pháp tìm kiếm lần lượt từ các nút gần nút bắt đầu nhất. Sau khi duyệt các nút ở cùng một mức, thuật toán mới chuyển sang mức tiếp theo. Các nút chờ duyệt được lưu trong queue và xử lý theo thứ tự được đưa vào.`},{type:`point`,ja:`幅優先探索ではキューを利用する。辺に重みがないグラフでは、開始点から各ノードまでの最短経路を求めることができる。`,vi:`BFS sử dụng queue. Trong đồ thị không có trọng số, BFS có thể tìm đường đi ngắn nhất từ điểm bắt đầu đến các nút khác.`},{type:`example`,ja:`開始ノードAからB、Cが隣接している場合、まずBとCを探索し、その後でBやCから接続されている次の階層のノードを探索する。`,vi:`Ví dụ, nếu B và C kề với nút bắt đầu A, BFS sẽ duyệt B và C trước, sau đó mới duyệt các nút ở tầng tiếp theo được nối từ B và C.`},{type:`heading`,ja:`最短経路探索`,vi:`Tìm đường đi ngắn nhất`},{type:`paragraph`,ja:`最短経路探索（Shortest Path Search）は、グラフ上のある地点から別の地点までの経路のうち、距離や時間、コストなどが最小となる経路を求める処理である。交通ネットワーク、通信ネットワーク、経路案内などで利用される。`,vi:`Tìm đường đi ngắn nhất (Shortest Path Search) là quá trình tìm đường có tổng khoảng cách, thời gian hoặc chi phí nhỏ nhất giữa các điểm trên đồ thị. Nó được sử dụng trong mạng giao thông, mạng truyền thông và các hệ thống chỉ đường.`},{type:`point`,ja:`最短経路では、辺に設定された距離・時間・料金などを重みとして扱い、その合計が最小となる経路を求める。`,vi:`Trong bài toán đường đi ngắn nhất, khoảng cách, thời gian hoặc chi phí của các cạnh có thể được xem là trọng số và mục tiêu là tìm đường có tổng trọng số nhỏ nhất.`},{type:`heading`,ja:`ダイクストラ法`,vi:`Thuật toán Dijkstra`},{type:`paragraph`,ja:`ダイクストラ法（Dijkstra's Algorithm）は、始点から各頂点までの最短経路を求める代表的なアルゴリズムである。始点の距離を0とし、その他の頂点の距離を未確定として、現在最も距離が小さい頂点を順に確定しながら、隣接する頂点までの距離を更新していく。`,vi:`Thuật toán Dijkstra là thuật toán tiêu biểu để tìm đường đi ngắn nhất từ một đỉnh bắt đầu đến các đỉnh khác. Khoảng cách của đỉnh bắt đầu được đặt bằng 0, sau đó thuật toán lần lượt xác định đỉnh có khoảng cách nhỏ nhất hiện tại và cập nhật khoảng cách đến các đỉnh kề.`},{type:`example`,ja:`始点AからBまでの距離が4、AからCまでが2、CからBまでが1の場合、AからBへ直接進む距離4より、A→C→Bの距離3の方が短いため、Bまでの最短距離は3となる。`,vi:`Ví dụ, nếu A→B có trọng số 4, A→C là 2 và C→B là 1, thì đường A→C→B có tổng trọng số 3, nhỏ hơn đường trực tiếp A→B là 4. Vì vậy khoảng cách ngắn nhất đến B là 3.`},{type:`point`,ja:`基本的なダイクストラ法は、負の重みを持つ辺が存在するグラフには適用できない。`,vi:`Thuật toán Dijkstra cơ bản không áp dụng được cho đồ thị có cạnh mang trọng số âm.`},{type:`point`,ja:`FEでは、深さ優先探索は「深く進んでから戻る・スタック」、幅優先探索は「近いノードから順に探索・キュー」、ダイクストラ法は「最短距離が確定できる頂点から順に処理する」という違いを押さえることが重要である。`,vi:`Trong FE, cần nhớ: DFS là 'đi sâu rồi quay lại, dùng stack'; BFS là 'duyệt các nút gần trước, dùng queue'; Dijkstra là 'lần lượt xử lý các đỉnh có thể xác định được khoảng cách ngắn nhất'.`}],terms:[{term:`深さ優先探索`,reading:`ふかさゆうせんたんさく`,english:`Depth-First Search`,vi:`tìm kiếm theo chiều sâu`,definitionJa:`一つの経路を可能な限り深く探索し、行き止まりになったら戻って別の経路を探索する方法。`,definitionVi:`Phương pháp đi sâu nhất có thể theo một đường, sau đó quay lại để tìm đường khác khi gặp ngõ cụt.`},{term:`幅優先探索`,reading:`はばゆうせんたんさく`,english:`Breadth-First Search`,vi:`tìm kiếm theo chiều rộng`,definitionJa:`開始点に近いノードから階層ごとに順番に探索する方法。`,definitionVi:`Phương pháp tìm kiếm lần lượt theo từng tầng, bắt đầu từ các nút gần điểm xuất phát.`},{term:`最短経路探索`,reading:`さいたんけいろたんさく`,english:`Shortest Path Search`,vi:`tìm đường đi ngắn nhất`,definitionJa:`二つの地点間で距離やコストなどが最小となる経路を求める処理。`,definitionVi:`Quá trình tìm đường có khoảng cách hoặc chi phí nhỏ nhất giữa các điểm.`},{term:`ダイクストラ法`,reading:`だいくすとらほう`,english:`Dijkstra's Algorithm`,vi:`thuật toán Dijkstra`,definitionJa:`負の重みを持たないグラフで、始点から各頂点への最短経路を求めるアルゴリズム。`,definitionVi:`Thuật toán tìm đường đi ngắn nhất từ một đỉnh bắt đầu đến các đỉnh khác trong đồ thị không có trọng số âm.`}],tags:[`algorithms`,`graph-search`,`dfs`,`bfs`,`shortest-path`,`dijkstra`]},{id:`bellman-ford-algorithm`,order:5,titleJa:`ベルマンフォード法`,titleVi:`Thuật toán Bellman-Ford`,importance:`high`,summaryJa:`負の重みを持つ辺を含むグラフに適用できるベルマンフォード法について、辺の緩和を繰り返す仕組みと負閉路の検出方法を理解する。`,summaryVi:`Tìm hiểu thuật toán Bellman-Ford có thể áp dụng cho đồ thị chứa cạnh trọng số âm, bao gồm cơ chế lặp việc cập nhật khoảng cách và cách phát hiện chu trình âm.`,content:[{type:`heading`,ja:`ベルマンフォード法`,vi:`Thuật toán Bellman-Ford`},{type:`paragraph`,ja:`ベルマンフォード法（Bellman-Ford Algorithm）は、単一の始点から他の頂点までの最短経路を求めるアルゴリズムである。ダイクストラ法とは異なり、負の重みを持つ辺が存在するグラフにも適用できる。ただし、始点から到達可能な負閉路がある場合、最短経路は定まらない。`,vi:`Bellman-Ford là thuật toán tìm đường đi ngắn nhất từ một đỉnh bắt đầu đến các đỉnh khác. Khác với Dijkstra, thuật toán này có thể áp dụng cho đồ thị có cạnh mang trọng số âm. Tuy nhiên, nếu có chu trình âm có thể đi tới từ đỉnh bắt đầu thì đường đi ngắn nhất không xác định.`},{type:`point`,ja:`始点の距離を0、その他の頂点を未確定として初期化し、すべての辺について、より短い経路が見つかれば距離を更新する。この処理を頂点数−1回まで繰り返す。`,vi:`Khoảng cách của đỉnh bắt đầu được đặt bằng 0, các đỉnh khác ở trạng thái chưa xác định. Sau đó kiểm tra tất cả các cạnh và cập nhật khoảng cách nếu tìm thấy đường ngắn hơn. Quá trình này được lặp tối đa số đỉnh − 1 lần.`},{type:`heading`,ja:`負の重み`,vi:`Trọng số âm`},{type:`paragraph`,ja:`ベルマンフォード法の重要な特徴は、負の重みを持つ辺を扱えることである。到達可能な負閉路がなければ、コストの減少などを負の値で表現するグラフでも最短経路を計算できる。`,vi:`Đặc điểm quan trọng của Bellman-Ford là có thể xử lý cạnh có trọng số âm. Nếu không có chu trình âm có thể đi tới, thuật toán vẫn có thể tìm đường đi ngắn nhất trong đồ thị biểu diễn việc giảm chi phí bằng giá trị âm.`},{type:`heading`,ja:`負閉路の検出`,vi:`Phát hiện chu trình âm`},{type:`paragraph`,ja:`頂点数−1回の更新を行った後でも、さらに距離を小さくできる辺が存在する場合、始点から到達可能な負閉路が存在すると判断できる。負閉路を繰り返し通ると経路のコストを際限なく小さくできるため、通常の意味での最短経路を定めることができない。`,vi:`Nếu sau số đỉnh − 1 lần cập nhật mà vẫn còn cạnh có thể làm khoảng cách nhỏ hơn, có thể xác định rằng tồn tại chu trình âm có thể đi tới từ đỉnh bắt đầu. Vì đi qua chu trình này nhiều lần có thể làm tổng chi phí giảm không giới hạn nên không thể xác định đường đi ngắn nhất theo nghĩa thông thường.`},{type:`point`,ja:`FEでは、ダイクストラ法は負の重みを扱えないのに対し、ベルマンフォード法は負の重みを扱え、負閉路も検出できるという違いが重要である。到達可能な負閉路がある場合、最短経路は定まらない。`,vi:`Trong FE, điểm cần nhớ là Dijkstra không xử lý được trọng số âm, trong khi Bellman-Ford có thể xử lý trọng số âm và còn có thể phát hiện chu trình âm. Nếu có chu trình âm có thể đi tới thì đường đi ngắn nhất không xác định.`}],terms:[{term:`ベルマンフォード法`,reading:`べるまんふぉーどほう`,english:`Bellman-Ford Algorithm`,vi:`thuật toán Bellman-Ford`,definitionJa:`到達可能な負閉路がない場合に、負の重みを持つ辺を含むグラフでも単一始点からの最短経路を求められ、負閉路も検出できるアルゴリズム。`,definitionVi:`Thuật toán tìm đường đi ngắn nhất từ một đỉnh bắt đầu trong đồ thị có cạnh trọng số âm khi không có chu trình âm có thể đi tới từ đỉnh đó, đồng thời có thể phát hiện chu trình âm.`},{term:`負閉路`,reading:`ふへいろ`,english:`Negative Cycle`,vi:`chu trình âm`,definitionJa:`辺の重みの合計が負になる閉路。`,definitionVi:`Chu trình có tổng trọng số của các cạnh là số âm.`}],tags:[`algorithms`,`graph`,`shortest-path`,`bellman-ford`,`negative-weight`]},{id:`semantic-and-language-analysis`,order:7,titleJa:`意味解析と自然言語処理`,titleVi:`Phân tích ngữ nghĩa và xử lý ngôn ngữ tự nhiên`,importance:`medium`,summaryJa:`意味解析、文脈解析、係り受け解析、n-gramについて、それぞれが言語データの何を解析する技術なのか、その違いと基本的な仕組みを理解する。`,summaryVi:`Tìm hiểu phân tích ngữ nghĩa, phân tích ngữ cảnh, phân tích quan hệ phụ thuộc và n-gram, đồng thời phân biệt đối tượng và cơ chế xử lý cơ bản của từng kỹ thuật.`,content:[{type:`heading`,ja:`意味解析`,vi:`Phân tích ngữ nghĩa`},{type:`paragraph`,ja:`意味解析（Semantic Analysis）は、文や語句が表す意味を解析する処理である。単に単語や文の構造を調べるだけではなく、語の意味や文全体が何を表しているのかを判断する。`,vi:`Phân tích ngữ nghĩa (Semantic Analysis) là quá trình phân tích ý nghĩa mà câu hoặc cụm từ biểu đạt. Nó không chỉ xem xét từ và cấu trúc câu mà còn xác định ý nghĩa của từ và nội dung mà toàn bộ câu muốn truyền đạt.`},{type:`point`,ja:`自然言語処理では、単語の多義性や文の構造などを考慮して意味を判断する。検索エンジン、機械翻訳、質問応答などに利用される。`,vi:`Trong xử lý ngôn ngữ tự nhiên, ý nghĩa được xác định bằng cách xem xét nhiều yếu tố như tính đa nghĩa của từ và cấu trúc câu. Kỹ thuật này được sử dụng trong công cụ tìm kiếm, dịch máy và hệ thống hỏi đáp.`},{type:`heading`,ja:`文脈解析`,vi:`Phân tích ngữ cảnh`},{type:`paragraph`,ja:`文脈解析（Context Analysis）は、ある単語や文だけを見るのではなく、その前後の文章や周囲の情報を考慮して意味を判断する処理である。同じ単語でも文脈によって意味が異なる場合があるため、自然言語を正しく理解するために重要である。`,vi:`Phân tích ngữ cảnh (Context Analysis) là quá trình xác định ý nghĩa bằng cách xem xét không chỉ một từ hay một câu riêng lẻ mà cả các câu trước sau và thông tin xung quanh. Do cùng một từ có thể mang ý nghĩa khác nhau tùy ngữ cảnh, kỹ thuật này rất quan trọng để hiểu chính xác ngôn ngữ tự nhiên.`},{type:`point`,ja:`文脈解析では、前後の情報を利用することで、単語の意味や発言者の意図などをより適切に判断できる。`,vi:`Phân tích ngữ cảnh sử dụng thông tin trước và sau để xác định chính xác hơn ý nghĩa của từ cũng như ý định của người nói.`},{type:`heading`,ja:`係り受け解析`,vi:`Phân tích quan hệ phụ thuộc`},{type:`paragraph`,ja:`係り受け解析（Dependency Parsing）は、文の中で、どの語や文節がどの語や文節に係っているかという関係を解析する処理である。文の構造や語同士の関係を把握するために用いられる。`,vi:`Phân tích quan hệ phụ thuộc (Dependency Parsing) là quá trình xác định từ hoặc cụm từ nào trong câu phụ thuộc hay liên hệ với từ hoặc cụm từ nào khác. Nó được sử dụng để nắm bắt cấu trúc câu và mối quan hệ giữa các thành phần.`},{type:`example`,ja:`例えば「犬が公園で遊んでいる」という文では、「犬が」や「公園で」が「遊んでいる」に係るという関係を解析する。`,vi:`Ví dụ, trong câu 「犬が公園で遊んでいる」, có thể phân tích rằng 「犬が」 và 「公園で」 có quan hệ phụ thuộc với 「遊んでいる」.`},{type:`heading`,ja:`n-gram`,vi:`n-gram`},{type:`paragraph`,ja:`n-gramは、文章や文字列を連続するn個の文字や単語の単位に分割する手法である。nが1の場合をuni-gram、2の場合をbi-gram、3の場合をtri-gramという。`,vi:`n-gram là phương pháp chia văn bản hoặc chuỗi thành các nhóm gồm n ký tự hoặc n từ liên tiếp. Khi n = 1 gọi là uni-gram, n = 2 là bi-gram và n = 3 là tri-gram.`},{type:`example`,ja:`例えば「私は猫が好きです」を単語単位で「私／は／猫／が／好き／です」と分割して2-gramにすると、「私／は」「は／猫」「猫／が」「が／好き」「好き／です」のように、隣接する二つの単語の組として扱う。`,vi:`Ví dụ, nếu tách 「私は猫が好きです」 thành các đơn vị từ 「私／は／猫／が／好き／です」 rồi tạo 2-gram, ta được các cặp từ liền nhau như 「私／は」, 「は／猫」, 「猫／が」, 「が／好き」 và 「好き／です」.`},{type:`point`,ja:`n-gramは、文字列検索、自然言語処理、入力予測などで利用される。文字単位のn-gramと単語単位のn-gramがあることを押さえる。`,vi:`n-gram được sử dụng trong tìm kiếm chuỗi, xử lý ngôn ngữ tự nhiên và dự đoán đầu vào. Cần nhớ rằng n-gram có thể được tạo theo đơn vị ký tự hoặc đơn vị từ.`},{type:`point`,ja:`形態素解析は語を分割して品詞などを調べ、構文解析・係り受け解析は文の構造や語の関係を調べ、意味解析・文脈解析はその意味を理解するための処理である。`,vi:`Cần phân biệt: phân tích hình thái tách câu thành các đơn vị từ và xác định từ loại; phân tích cú pháp và quan hệ phụ thuộc xem xét cấu trúc câu và quan hệ giữa các thành phần; còn phân tích ngữ nghĩa và ngữ cảnh hướng tới việc hiểu ý nghĩa.`}],terms:[{term:`意味解析`,reading:`いみかいせき`,english:`Semantic Analysis`,vi:`phân tích ngữ nghĩa`,definitionJa:`文や語句が表す意味を解析する処理。`,definitionVi:`Quá trình phân tích ý nghĩa được biểu đạt bởi câu hoặc cụm từ.`},{term:`文脈解析`,reading:`ぶんみゃくかいせき`,english:`Context Analysis`,vi:`phân tích ngữ cảnh`,definitionJa:`前後の文章や周囲の情報を考慮して、語や文の意味を解析する処理。`,definitionVi:`Quá trình phân tích ý nghĩa của từ hoặc câu dựa trên thông tin và văn bản xung quanh.`},{term:`係り受け解析`,reading:`かかりうけかいせき`,english:`Dependency Parsing`,vi:`phân tích quan hệ phụ thuộc`,definitionJa:`文中の語や文節の係り受け関係を解析する処理。`,definitionVi:`Quá trình phân tích quan hệ phụ thuộc giữa các từ hoặc cụm từ trong câu.`},{term:`n-gram`,reading:`えぬぐらむ`,english:`n-gram`,vi:`n-gram`,definitionJa:`文字列や文章を連続するn個の文字または単語の単位に分割する手法。`,definitionVi:`Phương pháp chia chuỗi hoặc văn bản thành các nhóm gồm n ký tự hoặc n từ liên tiếp.`}],tags:[`algorithms`,`natural-language-processing`,`semantic-analysis`,`context-analysis`,`dependency-parsing`,`n-gram`]},{id:`textual-similarity`,order:8,titleJa:`文章間類似度`,titleVi:`Độ tương đồng giữa các văn bản`,importance:`medium`,summaryJa:`二つの文章がどの程度似ているかを数値で表す文章間類似度について、基本的な考え方と代表的な類似度指標を理解する。`,summaryVi:`Tìm hiểu độ tương đồng giữa hai văn bản, cách biểu diễn mức độ giống nhau bằng giá trị số và các chỉ số tương đồng tiêu biểu.`,content:[{type:`heading`,ja:`文章間類似度`,vi:`Độ tương đồng giữa các văn bản`},{type:`paragraph`,ja:`文章間類似度（Textual Similarity）は、二つの文章がどの程度似ているかを数値で表す指標である。文章に含まれる単語や特徴などを利用して比較し、内容や表現の類似性を評価する。`,vi:`Độ tương đồng giữa các văn bản (Textual Similarity) là chỉ số biểu diễn bằng số mức độ giống nhau giữa hai văn bản. Các từ và đặc trưng có trong văn bản được sử dụng để so sánh và đánh giá sự tương đồng về nội dung hoặc cách biểu đạt.`},{type:`heading`,ja:`利用例`,vi:`Ví dụ ứng dụng`},{type:`paragraph`,ja:`文章間類似度は、自然言語処理における文章分類、情報検索、類似文書の検索などに利用される。例えば、検索エンジンでは、入力された検索語や文章と各文書との類似性を評価し、関連性の高い情報を探すために利用できる。`,vi:`Độ tương đồng văn bản được sử dụng trong xử lý ngôn ngữ tự nhiên như phân loại văn bản, truy xuất thông tin và tìm kiếm tài liệu tương tự. Ví dụ, công cụ tìm kiếm có thể đánh giá mức độ tương đồng giữa truy vấn hoặc văn bản đầu vào với các tài liệu để tìm thông tin có liên quan cao.`},{type:`heading`,ja:`代表的な類似度`,vi:`Các chỉ số tương đồng tiêu biểu`},{type:`paragraph`,ja:`文章やデータの類似性を数値化する方法として、コサイン類似度やJaccard係数などがある。コサイン類似度はベクトル化したデータの向きの近さを利用し、Jaccard係数は二つの集合に共通する要素の割合を利用して類似性を求める。`,vi:`Các phương pháp số hóa mức độ tương đồng của văn bản hoặc dữ liệu gồm cosine similarity và hệ số Jaccard. Cosine similarity đánh giá độ gần nhau về hướng của các vector, còn hệ số Jaccard dựa trên tỷ lệ các phần tử chung giữa hai tập hợp.`},{type:`point`,ja:`FEでは、類似度は「どの程度似ているか」を数値化した指標であることと、コサイン類似度やJaccard係数などの代表的な方法を押さえる。`,vi:`Trong FE, cần nhớ similarity là chỉ số số hóa 'mức độ giống nhau', cùng các phương pháp tiêu biểu như cosine similarity và hệ số Jaccard.`}],terms:[{term:`文章間類似度`,reading:`ぶんしょうかんるいじど`,english:`Textual Similarity`,vi:`độ tương đồng giữa các văn bản`,definitionJa:`二つの文章がどの程度似ているかを数値で表した指標。`,definitionVi:`Chỉ số biểu diễn bằng số mức độ giống nhau giữa hai văn bản.`},{term:`コサイン類似度`,reading:`こさいんるいじど`,english:`Cosine Similarity`,vi:`độ tương đồng cosine`,definitionJa:`二つのベクトルが示す方向の近さを基に類似度を求める方法。`,definitionVi:`Phương pháp tính độ tương đồng dựa trên độ gần nhau về hướng của hai vector.`},{term:`Jaccard係数`,reading:`じゃっかーどけいすう`,english:`Jaccard Index`,vi:`hệ số Jaccard`,definitionJa:`二つの集合の和集合に対する共通部分の割合によって類似度を表す指標。`,definitionVi:`Chỉ số biểu diễn độ tương đồng bằng tỷ lệ giữa phần giao và phần hợp của hai tập hợp.`}],tags:[`algorithms`,`textual-similarity`,`cosine-similarity`,`jaccard-index`,`natural-language-processing`]}]},g={id:`programming`,order:3,titleJa:`プログラミング`,titleVi:`Lập trình`,syllabus:`9.2`,lessons:[{id:`programming-basics`,order:1,titleJa:`プログラミング`,titleVi:`Lập trình`,importance:`high`,summaryJa:`コンピュータに処理を実行させるためのプログラミングについて、プログラム、プログラミング言語、コーディングとの関係を理解する。`,summaryVi:`Tìm hiểu về lập trình để yêu cầu máy tính thực hiện các xử lý, đồng thời hiểu mối quan hệ giữa chương trình, ngôn ngữ lập trình và coding.`,content:[{type:`heading`,ja:`プログラミングとは`,vi:`Lập trình là gì?`},{type:`paragraph`,ja:`プログラミング（Programming）とは、コンピュータに特定の処理を実行させるために、処理の手順や命令をプログラミング言語を用いて記述することである。記述された一連の命令をプログラムという。`,vi:`Lập trình (Programming) là việc sử dụng ngôn ngữ lập trình để mô tả các bước xử lý và lệnh nhằm yêu cầu máy tính thực hiện một công việc cụ thể. Tập hợp các lệnh được viết ra được gọi là chương trình.`},{type:`heading`,ja:`プログラミングの目的`,vi:`Mục đích của lập trình`},{type:`paragraph`,ja:`プログラミングでは、目的とする処理をどのような手順で実現するかを考え、それをコンピュータが処理できる形で記述する。計算処理、データ処理、Webアプリケーションなど、様々なシステムやソフトウェアの実現に利用される。`,vi:`Trong lập trình, người lập trình xác định các bước cần thiết để thực hiện một xử lý mong muốn rồi mô tả chúng dưới dạng mà máy tính có thể xử lý. Lập trình được sử dụng để xây dựng nhiều loại hệ thống và phần mềm như xử lý tính toán, xử lý dữ liệu và ứng dụng Web.`},{type:`heading`,ja:`プログラミング言語`,vi:`Ngôn ngữ lập trình`},{type:`paragraph`,ja:`コンピュータに処理内容を指示するためには、一定の文法や規則を持つプログラミング言語を使用する。代表的なプログラミング言語には、C、Java、Pythonなどがある。`,vi:`Để chỉ thị nội dung xử lý cho máy tính, người ta sử dụng ngôn ngữ lập trình có các quy tắc và cú pháp nhất định. Một số ngôn ngữ lập trình tiêu biểu là C, Java và Python.`},{type:`heading`,ja:`プログラミングとコーディング`,vi:`Programming và coding`},{type:`paragraph`,ja:`コーディングは、設計された処理内容をプログラミング言語で実際に記述する作業を指す。プログラミングは、問題の分析、処理手順の検討、コーディング、テストなどを含む、より広い意味で使われることがある。`,vi:`Coding là công việc thực tế viết nội dung xử lý đã được thiết kế bằng ngôn ngữ lập trình. Programming có thể được dùng với nghĩa rộng hơn, bao gồm phân tích vấn đề, xem xét trình tự xử lý, coding và kiểm thử.`},{type:`point`,ja:`「プログラム」はコンピュータに実行させる命令の集まり、「プログラミング」はそのプログラムを作成するための活動である。`,vi:`Cần phân biệt: 'program' là tập hợp các lệnh để máy tính thực hiện, còn 'programming' là hoạt động tạo ra chương trình đó.`}],terms:[{term:`プログラミング`,reading:`ぷろぐらみんぐ`,english:`Programming`,vi:`lập trình`,definitionJa:`コンピュータに処理を実行させるための手順や命令をプログラミング言語で記述すること。`,definitionVi:`Việc mô tả các bước và lệnh bằng ngôn ngữ lập trình để máy tính thực hiện xử lý.`},{term:`プログラム`,reading:`ぷろぐらむ`,english:`Program`,vi:`chương trình`,definitionJa:`コンピュータに特定の処理を実行させるために記述された一連の命令。`,definitionVi:`Tập hợp các lệnh được viết để máy tính thực hiện một xử lý cụ thể.`},{term:`プログラミング言語`,reading:`ぷろぐらみんぐげんご`,english:`Programming Language`,vi:`ngôn ngữ lập trình`,definitionJa:`コンピュータに処理内容を指示するために使用する、文法や規則を持つ人工言語。`,definitionVi:`Ngôn ngữ nhân tạo có cú pháp và quy tắc dùng để chỉ thị nội dung xử lý cho máy tính.`},{term:`コーディング`,reading:`こーでぃんぐ`,english:`Coding`,vi:`viết mã`,definitionJa:`設計された処理内容をプログラミング言語を用いてソースコードとして記述する作業。`,definitionVi:`Công việc viết nội dung xử lý đã thiết kế thành mã nguồn bằng ngôn ngữ lập trình.`}],tags:[`programming`,`program`,`programming-language`,`coding`]},{id:`naming-convention`,order:3,titleJa:`命名規則`,titleVi:`Quy tắc đặt tên`,importance:`high`,summaryJa:`プログラムやデータベースの要素に名前を付ける際の命名規則について、目的と代表的な命名スタイルを理解する。`,summaryVi:`Tìm hiểu quy tắc đặt tên cho các thành phần trong chương trình và cơ sở dữ liệu, mục đích của chúng và các kiểu đặt tên phổ biến.`,content:[{type:`heading`,ja:`命名規則とは`,vi:`Quy tắc đặt tên là gì?`},{type:`paragraph`,ja:`命名規則（Naming Convention）とは、プログラムやデータベース内の変数、関数、クラス、テーブルなどに名前を付ける際のルールである。一定の規則に従って名前を付けることで、コードやデータの可読性や整合性を高めることができる。`,vi:`Quy tắc đặt tên (Naming Convention) là các quy tắc được sử dụng khi đặt tên cho biến, hàm, lớp, bảng và các thành phần khác trong chương trình hoặc cơ sở dữ liệu. Việc đặt tên theo một quy tắc thống nhất giúp nâng cao tính dễ đọc và tính nhất quán của code và dữ liệu.`},{type:`heading`,ja:`代表的な命名スタイル`,vi:`Các kiểu đặt tên phổ biến`},{type:`paragraph`,ja:`代表的な命名スタイルには、単語をアンダースコアで区切るsnake_caseや、複数の単語をつなぎ、各単語の先頭文字を大文字にするPascalCaseなどがある。また、先頭の単語を小文字で始め、それ以降の単語の先頭を大文字にするcamelCaseも広く利用されている。`,vi:`Các kiểu đặt tên phổ biến gồm snake_case, trong đó các từ được nối bằng dấu gạch dưới; PascalCase, trong đó chữ cái đầu của mỗi từ được viết hoa; và camelCase, trong đó từ đầu tiên viết thường còn chữ cái đầu của các từ tiếp theo được viết hoa.`},{type:`heading`,ja:`命名規則を統一する利点`,vi:`Lợi ích của việc thống nhất quy tắc đặt tên`},{type:`paragraph`,ja:`命名規則を統一することで、変数や関数などの役割を理解しやすくなり、複数人での開発や保守を効率的に行える。また、コードレビューやバグの発見、修正も容易になる。`,vi:`Thống nhất quy tắc đặt tên giúp dễ hiểu vai trò của biến, hàm và các thành phần khác, từ đó nâng cao hiệu quả phát triển và bảo trì khi làm việc theo nhóm. Việc review code, phát hiện và sửa lỗi cũng trở nên dễ dàng hơn.`},{type:`point`,ja:`命名規則は、名前そのものを統一するのではなく、「名前の付け方」を統一するためのルールである。`,vi:`Quy tắc đặt tên không phải là thống nhất chính các tên được sử dụng, mà là thống nhất cách đặt tên.`}],terms:[{term:`命名規則`,reading:`めいめいきそく`,english:`Naming Convention`,vi:`quy tắc đặt tên`,definitionJa:`変数や関数などの名前の付け方を統一するための規則。`,definitionVi:`Quy tắc dùng để thống nhất cách đặt tên biến, hàm và các thành phần khác.`},{term:`snake_case`,reading:`すねーくけーす`,english:`snake_case`,vi:`kiểu snake_case`,definitionJa:`複数の単語をアンダースコアで区切って表す命名形式。`,definitionVi:`Kiểu đặt tên phân tách nhiều từ bằng dấu gạch dưới.`},{term:`camelCase`,reading:`きゃめるけーす`,english:`camelCase`,vi:`kiểu camelCase`,definitionJa:`先頭の単語を小文字で始め、以降の単語の先頭文字を大文字にしてつなぐ命名形式。`,definitionVi:`Kiểu đặt tên bắt đầu từ đầu tiên bằng chữ thường và viết hoa chữ cái đầu của các từ tiếp theo.`},{term:`PascalCase`,reading:`ぱすかるけーす`,english:`PascalCase`,vi:`kiểu PascalCase`,definitionJa:`各単語の先頭文字を大文字にしてつなぐ命名形式。`,definitionVi:`Kiểu đặt tên viết hoa chữ cái đầu của mỗi từ rồi nối các từ lại với nhau.`}],tags:[`programming`,`naming-convention`,`snake-case`,`camel-case`,`pascal-case`]},{id:`disallow-directive`,order:4,titleJa:`使用禁止命令`,titleVi:`Lệnh bị cấm sử dụng`,importance:`medium`,summaryJa:`コーディング標準で使用を禁止する命令や機能について、その目的と、禁止事項を定めることで安全性や保守性を高める考え方を理解する。`,summaryVi:`Tìm hiểu các lệnh hoặc chức năng bị cấm sử dụng theo tiêu chuẩn coding và mục đích nâng cao độ an toàn, khả năng bảo trì bằng cách quy định những thành phần không được dùng.`,content:[{type:`heading`,ja:`使用禁止命令とは`,vi:`Lệnh bị cấm sử dụng là gì?`},{type:`paragraph`,ja:`使用禁止命令とは、コーディング標準において、プログラム中で使用しないよう定められた命令や機能である。誤りを起こしやすい命令、動作が処理系に依存する機能、安全性や可読性を損なう書き方などを禁止対象として定めることがある。`,vi:`Lệnh bị cấm sử dụng là lệnh hoặc chức năng được tiêu chuẩn coding quy định không được dùng trong chương trình. Những lệnh dễ gây lỗi, chức năng phụ thuộc vào môi trường xử lý hoặc cách viết làm giảm độ an toàn và khả năng đọc có thể được đưa vào danh sách cấm.`},{type:`heading`,ja:`使用禁止命令の目的`,vi:`Mục đích`},{type:`paragraph`,ja:`使用禁止命令をコーディング標準で定めることで、バグやセキュリティ上の問題を招きやすい記述を避け、プログラムの安全性、移植性、可読性、保守性を高める。禁止対象は、使用する言語や開発組織の標準によって異なる。`,vi:`Việc quy định các lệnh bị cấm trong tiêu chuẩn coding giúp tránh những cách viết dễ gây lỗi hoặc vấn đề bảo mật, qua đó nâng cao độ an toàn, tính khả chuyển, khả năng đọc và bảo trì. Thành phần bị cấm phụ thuộc vào ngôn ngữ và tiêu chuẩn của tổ chức phát triển.`},{type:`point`,ja:`使用禁止命令はアクセス制御の命令ではなく、コーディング標準で使用しないと定めた命令や機能である。`,vi:`Lệnh bị cấm sử dụng không phải là lệnh kiểm soát truy cập; đó là lệnh hoặc chức năng mà tiêu chuẩn coding quy định không được dùng.`}],terms:[{term:`使用禁止命令`,reading:`しようきんしめいれい`,english:`Prohibited Statement`,vi:`lệnh bị cấm sử dụng`,definitionJa:`コーディング標準によって、プログラム中で使用しないよう定められた命令や機能。`,definitionVi:`Lệnh hoặc chức năng được tiêu chuẩn coding quy định không được sử dụng trong chương trình.`}],tags:[`programming`,`disallow-directive`,`coding-standards`]},{id:`program-quality-improvement`,order:5,titleJa:`プログラムの機能適合性・性能効率性・使用性・保守性の向上`,titleVi:`Nâng cao tính phù hợp chức năng, hiệu quả hiệu năng, khả năng sử dụng và khả năng bảo trì`,importance:`high`,summaryJa:`プログラム品質を評価する重要な観点である機能適合性、性能効率性、使用性、保守性について、それぞれの意味と改善の目的を理解する。`,summaryVi:`Tìm hiểu tính phù hợp chức năng, hiệu quả hiệu năng, khả năng sử dụng và khả năng bảo trì — những khía cạnh quan trọng để đánh giá và cải thiện chất lượng chương trình.`,content:[{type:`heading`,ja:`プログラム品質の向上`,vi:`Nâng cao chất lượng chương trình`},{type:`paragraph`,ja:`ソフトウェア開発では、要求された機能を実現するだけでなく、性能、使いやすさ、修正のしやすさなどを考慮してプログラムの品質を高めることが重要である。その代表的な観点として、機能適合性、性能効率性、使用性、保守性がある。`,vi:`Trong phát triển phần mềm, ngoài việc thực hiện đúng các chức năng được yêu cầu, còn cần nâng cao chất lượng chương trình bằng cách xem xét hiệu năng, mức độ dễ sử dụng và khả năng sửa đổi. Các khía cạnh tiêu biểu gồm tính phù hợp chức năng, hiệu quả hiệu năng, khả năng sử dụng và khả năng bảo trì.`},{type:`heading`,ja:`機能適合性`,vi:`Tính phù hợp chức năng`},{type:`paragraph`,ja:`機能適合性は、利用者やシステムから要求された機能を、プログラムが適切かつ正確に実現しているかを示す。`,vi:`Tính phù hợp chức năng thể hiện chương trình có thực hiện thích hợp và chính xác các chức năng mà người dùng hoặc hệ thống yêu cầu hay không.`},{type:`heading`,ja:`性能効率性`,vi:`Hiệu quả hiệu năng`},{type:`paragraph`,ja:`性能効率性は、処理時間、メモリ、CPUなどの資源を適切に使用しながら、必要な性能を実現できるかを示す。`,vi:`Hiệu quả hiệu năng thể hiện chương trình có đạt được hiệu năng cần thiết trong khi sử dụng hợp lý các tài nguyên như thời gian xử lý, bộ nhớ và CPU hay không.`},{type:`heading`,ja:`使用性と保守性`,vi:`Khả năng sử dụng và khả năng bảo trì`},{type:`paragraph`,ja:`使用性は、利用者がプログラムを理解し、操作しやすいかを示す。保守性は、障害の修正や機能追加、仕様変更などを容易に行えるかを示す。これらを改善することで、利用者の満足度向上や長期的な運用コストの削減につながる。`,vi:`Khả năng sử dụng thể hiện người dùng có thể hiểu và thao tác chương trình dễ dàng hay không. Khả năng bảo trì thể hiện mức độ dễ dàng khi sửa lỗi, bổ sung chức năng hoặc thay đổi đặc tả. Cải thiện các yếu tố này giúp tăng mức độ hài lòng của người dùng và giảm chi phí vận hành lâu dài.`},{type:`point`,ja:`機能適合性＝要求された機能、性能効率性＝性能と資源、使用性＝使いやすさ、保守性＝修正・変更のしやすさ、と整理する。`,vi:`Có thể ghi nhớ: tính phù hợp chức năng = chức năng được yêu cầu; hiệu quả hiệu năng = hiệu năng và tài nguyên; khả năng sử dụng = dễ sử dụng; khả năng bảo trì = dễ sửa đổi và thay đổi.`}],terms:[{term:`機能適合性`,reading:`きのうてきごうせい`,english:`Functional Suitability`,vi:`tính phù hợp chức năng`,definitionJa:`要求された機能を適切に実現できているかを表す品質特性。`,definitionVi:`Đặc tính chất lượng thể hiện mức độ thực hiện phù hợp các chức năng được yêu cầu.`},{term:`性能効率性`,reading:`せいのうこうりつせい`,english:`Performance Efficiency`,vi:`hiệu quả hiệu năng`,definitionJa:`使用する資源に対して適切な性能を実現できているかを表す品質特性。`,definitionVi:`Đặc tính chất lượng thể hiện khả năng đạt hiệu năng phù hợp so với tài nguyên được sử dụng.`},{term:`使用性`,reading:`しようせい`,english:`Usability`,vi:`khả năng sử dụng`,definitionJa:`利用者にとって理解や操作がしやすいかを表す品質特性。`,definitionVi:`Đặc tính chất lượng thể hiện mức độ dễ hiểu và dễ thao tác đối với người dùng.`},{term:`保守性`,reading:`ほしゅせい`,english:`Maintainability`,vi:`khả năng bảo trì`,definitionJa:`プログラムの修正や変更を容易に行えるかを表す品質特性。`,definitionVi:`Đặc tính chất lượng thể hiện mức độ dễ dàng sửa đổi hoặc thay đổi chương trình.`}],tags:[`programming`,`software-quality`,`functional-suitability`,`performance-efficiency`,`usability`,`maintainability`]},{id:`module-decomposition`,order:6,titleJa:`モジュール分割`,titleVi:`Phân chia mô-đun`,importance:`high`,summaryJa:`大きなプログラムを機能ごとの小さなモジュールに分割する考え方と、その利点を理解する。`,summaryVi:`Tìm hiểu phương pháp chia một chương trình lớn thành các mô-đun nhỏ theo chức năng và những lợi ích của việc phân chia mô-đun.`,content:[{type:`heading`,ja:`モジュール分割とは`,vi:`Phân chia mô-đun là gì?`},{type:`paragraph`,ja:`モジュール分割（Module Decomposition）とは、大きなプログラムを機能や役割ごとの小さな単位であるモジュールに分割することである。各モジュールに明確な役割を持たせることで、プログラム全体の構造を整理できる。`,vi:`Phân chia mô-đun (Module Decomposition) là việc chia một chương trình lớn thành các đơn vị nhỏ gọi là mô-đun theo từng chức năng hoặc vai trò. Việc quy định vai trò rõ ràng cho từng mô-đun giúp tổ chức cấu trúc tổng thể của chương trình.`},{type:`heading`,ja:`モジュール分割の利点`,vi:`Lợi ích của phân chia mô-đun`},{type:`paragraph`,ja:`適切にモジュールを分割することで、プログラムの可読性や保守性が向上する。また、特定の機能を独立して開発、テスト、修正できるため、開発作業を効率化できる。`,vi:`Việc phân chia mô-đun hợp lý giúp nâng cao tính dễ đọc và khả năng bảo trì của chương trình. Ngoài ra, từng chức năng có thể được phát triển, kiểm thử và sửa đổi độc lập, nhờ đó nâng cao hiệu quả phát triển.`},{type:`heading`,ja:`再利用性`,vi:`Khả năng tái sử dụng`},{type:`paragraph`,ja:`汎用的な処理を独立したモジュールとして作成することで、同じ機能を別のプログラムや別の部分から再利用できる。これにより、同じ処理を何度も作成する必要がなくなる。`,vi:`Khi các xử lý có tính dùng chung được tạo thành mô-đun độc lập, cùng một chức năng có thể được tái sử dụng ở chương trình hoặc phần khác. Nhờ đó không cần viết lại cùng một xử lý nhiều lần.`},{type:`point`,ja:`モジュール分割の主な利点は、可読性、保守性、再利用性、テストのしやすさを向上させることである。`,vi:`Lợi ích chính của phân chia mô-đun là nâng cao tính dễ đọc, khả năng bảo trì, khả năng tái sử dụng và khả năng kiểm thử.`}],terms:[{term:`モジュール分割`,reading:`もじゅーるぶんかつ`,english:`Module Decomposition`,vi:`phân chia mô-đun`,definitionJa:`大きなプログラムを機能や役割ごとの小さなモジュールに分割すること。`,definitionVi:`Việc chia một chương trình lớn thành các mô-đun nhỏ theo chức năng hoặc vai trò.`},{term:`モジュール`,reading:`もじゅーる`,english:`Module`,vi:`mô-đun`,definitionJa:`特定の機能や役割を担当する、プログラムを構成する単位。`,definitionVi:`Đơn vị cấu thành chương trình đảm nhiệm một chức năng hoặc vai trò cụ thể.`},{term:`再利用性`,reading:`さいりようせい`,english:`Reusability`,vi:`khả năng tái sử dụng`,definitionJa:`作成したプログラム部品を他の処理やシステムでも利用できる性質。`,definitionVi:`Tính chất cho phép các thành phần chương trình đã tạo được sử dụng lại trong xử lý hoặc hệ thống khác.`}],tags:[`programming`,`module`,`module-decomposition`,`maintainability`,`reusability`]},{id:`module-independence`,order:7,titleJa:`モジュール独立性`,titleVi:`Tính độc lập của mô-đun`,importance:`high`,summaryJa:`モジュール独立性の意味と、モジュール間の依存関係を小さくすることで得られる保守性や再利用性の向上について理解する。`,summaryVi:`Tìm hiểu tính độc lập của mô-đun và cách giảm sự phụ thuộc giữa các mô-đun giúp nâng cao khả năng bảo trì và tái sử dụng.`,content:[{type:`heading`,ja:`モジュール独立性とは`,vi:`Tính độc lập của mô-đun là gì?`},{type:`paragraph`,ja:`モジュール独立性（Module Independence）とは、ソフトウェアを構成する各モジュールが、他のモジュールにできるだけ依存せずに機能できる度合いを表す。モジュールの独立性を高めることは、プログラムの設計において重要である。`,vi:`Tính độc lập của mô-đun (Module Independence) biểu thị mức độ mà mỗi mô-đun cấu thành phần mềm có thể hoạt động mà ít phụ thuộc nhất có thể vào các mô-đun khác. Nâng cao tính độc lập của mô-đun là một yếu tố quan trọng trong thiết kế chương trình.`},{type:`heading`,ja:`モジュール間の依存関係`,vi:`Quan hệ phụ thuộc giữa các mô-đun`},{type:`paragraph`,ja:`モジュール間の依存関係が強いと、一つのモジュールを変更したときに他のモジュールにも影響が及びやすくなる。反対に、必要な情報だけを明確なインタフェースを通して受け渡すように設計することで、モジュール間の依存関係を小さくできる。`,vi:`Nếu sự phụ thuộc giữa các mô-đun quá mạnh, việc thay đổi một mô-đun có thể dễ dàng ảnh hưởng đến các mô-đun khác. Ngược lại, nếu thiết kế để chỉ trao đổi thông tin cần thiết thông qua interface rõ ràng thì có thể giảm sự phụ thuộc giữa các mô-đun.`},{type:`heading`,ja:`独立性を高める利点`,vi:`Lợi ích của việc nâng cao tính độc lập`},{type:`paragraph`,ja:`モジュール独立性が高いと、あるモジュールを変更しても他の部分への影響を小さくできる。そのため、保守、テスト、デバッグが容易になり、モジュールの再利用もしやすくなる。`,vi:`Khi tính độc lập của mô-đun cao, việc thay đổi một mô-đun ít ảnh hưởng đến các phần khác. Vì vậy, việc bảo trì, kiểm thử và debug trở nên dễ dàng hơn, đồng thời mô-đun cũng dễ được tái sử dụng.`},{type:`point`,ja:`モジュール独立性を高める基本は、モジュール間の依存関係を小さくし、それぞれのモジュールの役割を明確にすることである。`,vi:`Điểm quan trọng: để tăng tính độc lập của mô-đun, cần giảm sự phụ thuộc giữa các mô-đun và làm rõ trách nhiệm của từng mô-đun.`}],terms:[{term:`モジュール独立性`,reading:`もじゅーるどくりつせい`,english:`Module Independence`,vi:`tính độc lập của mô-đun`,definitionJa:`各モジュールが他のモジュールに依存せずに機能できる度合い。`,definitionVi:`Mức độ mà mỗi mô-đun có thể hoạt động mà không phụ thuộc vào các mô-đun khác.`},{term:`依存関係`,reading:`いぞんかんけい`,english:`Dependency`,vi:`quan hệ phụ thuộc`,definitionJa:`あるモジュールの処理や変更が、別のモジュールに影響する関係。`,definitionVi:`Quan hệ trong đó xử lý hoặc thay đổi của một mô-đun ảnh hưởng đến mô-đun khác.`},{term:`インタフェース`,reading:`いんたふぇーす`,english:`Interface`,vi:`giao diện kết nối`,definitionJa:`モジュール間で情報を受け渡すための接点や規約。`,definitionVi:`Điểm kết nối hoặc quy tắc dùng để trao đổi thông tin giữa các mô-đun.`}],tags:[`programming`,`module-independence`,`module`,`dependency`,`interface`]},{id:`main-routine`,order:8,titleJa:`メインルーチン`,titleVi:`Chương trình chính`,importance:`high`,summaryJa:`プログラム全体の実行を制御する中心的な処理であるメインルーチンの役割を理解する。`,summaryVi:`Tìm hiểu vai trò của main routine, phần xử lý trung tâm điều khiển quá trình thực thi của toàn bộ chương trình.`,content:[{type:`heading`,ja:`メインルーチンとは`,vi:`Main routine là gì?`},{type:`paragraph`,ja:`メインルーチン（Main Routine）とは、プログラム全体の実行を制御する中心的なルーチンである。プログラムの開始時に実行され、必要に応じて他のルーチンや関数を呼び出しながら処理を進める。`,vi:`Main routine là routine trung tâm điều khiển quá trình thực thi của toàn bộ chương trình. Nó được thực thi khi chương trình bắt đầu và tiến hành xử lý bằng cách gọi các routine hoặc hàm khác khi cần.`},{type:`heading`,ja:`メインルーチンの役割`,vi:`Vai trò của main routine`},{type:`paragraph`,ja:`メインルーチンでは、処理の順序を制御したり、必要なデータを管理したり、サブルーチンを呼び出したりする。これにより、プログラム全体の処理の流れを管理できる。`,vi:`Main routine điều khiển thứ tự xử lý, quản lý dữ liệu cần thiết và gọi các subroutine. Nhờ đó có thể quản lý luồng xử lý của toàn bộ chương trình.`},{type:`heading`,ja:`プログラムの開始点`,vi:`Điểm bắt đầu của chương trình`},{type:`paragraph`,ja:`プログラミング言語によって形式は異なるが、プログラムの実行を開始するための入口が定められている場合がある。例えば、C言語ではmain関数がプログラムのエントリーポイントとして機能する。`,vi:`Hình thức khác nhau tùy ngôn ngữ lập trình, nhưng chương trình thường có một điểm vào để bắt đầu thực thi. Ví dụ, trong C, hàm main đóng vai trò là entry point của chương trình.`},{type:`point`,ja:`メインルーチンはプログラム全体の流れを制御し、必要に応じてサブルーチンなどを呼び出す。`,vi:`Main routine điều khiển luồng tổng thể của chương trình và gọi các subroutine khi cần.`}],terms:[{term:`メインルーチン`,reading:`めいんるーちん`,english:`Main Routine`,vi:`chương trình chính`,definitionJa:`プログラム全体の実行を制御する中心的なルーチン。`,definitionVi:`Routine trung tâm điều khiển quá trình thực thi của toàn bộ chương trình.`},{term:`エントリーポイント`,reading:`えんとりーぽいんと`,english:`Entry Point`,vi:`điểm vào chương trình`,definitionJa:`プログラムの実行が開始される位置。`,definitionVi:`Vị trí mà việc thực thi chương trình bắt đầu.`}],tags:[`programming`,`main-routine`,`entry-point`]},{id:`subroutine`,order:9,titleJa:`サブルーチン`,titleVi:`Chương trình con`,importance:`high`,summaryJa:`特定の処理をまとめ、必要なときに呼び出して利用するサブルーチンの仕組みと利点を理解する。`,summaryVi:`Tìm hiểu cơ chế và lợi ích của subroutine, phần chương trình tập hợp một xử lý cụ thể và được gọi khi cần.`,content:[{type:`heading`,ja:`サブルーチンとは`,vi:`Subroutine là gì?`},{type:`paragraph`,ja:`サブルーチン（Subroutine）とは、プログラム内の特定の処理をひとまとまりにしたものである。必要なときにメインルーチンなどから呼び出して実行することができる。`,vi:`Subroutine là một phần chương trình tập hợp một xử lý cụ thể thành một đơn vị. Khi cần, nó có thể được gọi từ main routine hoặc các phần khác để thực thi.`},{type:`heading`,ja:`サブルーチンの利点`,vi:`Lợi ích của subroutine`},{type:`paragraph`,ja:`同じ処理を複数の場所で必要とする場合、その処理をサブルーチンとして定義しておけば、必要な場所から呼び出すだけで利用できる。同じコードを繰り返し記述する必要がなくなり、プログラムを簡潔にできる。`,vi:`Khi cùng một xử lý được sử dụng ở nhiều nơi, có thể định nghĩa nó thành subroutine và chỉ cần gọi khi cần. Nhờ đó không phải viết lặp lại cùng một đoạn code và chương trình trở nên gọn hơn.`},{type:`heading`,ja:`保守性と再利用性`,vi:`Khả năng bảo trì và tái sử dụng`},{type:`paragraph`,ja:`共通処理をサブルーチンとしてまとめることで、処理内容を変更する場合も一か所を修正すればよく、保守性が向上する。また、汎用的なサブルーチンは他のプログラムでも再利用できる。`,vi:`Khi gom xử lý dùng chung thành subroutine, nếu cần thay đổi xử lý thì chỉ cần sửa tại một nơi, giúp nâng cao khả năng bảo trì. Các subroutine có tính dùng chung cũng có thể được tái sử dụng trong chương trình khác.`},{type:`point`,ja:`サブルーチンを利用すると、処理の重複を減らし、プログラムの保守性と再利用性を高めることができる。`,vi:`Sử dụng subroutine giúp giảm xử lý trùng lặp và nâng cao khả năng bảo trì cũng như tái sử dụng của chương trình.`}],terms:[{term:`サブルーチン`,reading:`さぶるーちん`,english:`Subroutine`,vi:`chương trình con`,definitionJa:`特定の処理をまとめ、必要なときに呼び出して実行するプログラムの一部分。`,definitionVi:`Một phần của chương trình tập hợp một xử lý cụ thể và được gọi để thực thi khi cần.`}],tags:[`programming`,`subroutine`,`reusability`,`maintainability`]},{id:`integer-type`,order:10,titleJa:`整数型`,titleVi:`Kiểu số nguyên`,importance:`high`,summaryJa:`小数部を持たない整数を扱う整数型について、その用途とデータ型による表現範囲の違いを理解する。`,summaryVi:`Tìm hiểu kiểu số nguyên dùng để biểu diễn các số không có phần thập phân, mục đích sử dụng và sự khác nhau về phạm vi biểu diễn.`,content:[{type:`heading`,ja:`整数型とは`,vi:`Kiểu số nguyên là gì?`},{type:`paragraph`,ja:`整数型（Integer Type）とは、小数部を持たない整数を扱うためのデータ型である。個数、回数、番号など、整数で表現できる値をプログラム内で扱うために使用される。`,vi:`Kiểu số nguyên (Integer Type) là kiểu dữ liệu dùng để xử lý các số nguyên không có phần thập phân. Nó được sử dụng cho các giá trị có thể biểu diễn bằng số nguyên như số lượng, số lần hoặc số thứ tự.`},{type:`heading`,ja:`整数型と演算`,vi:`Kiểu số nguyên và phép tính`},{type:`paragraph`,ja:`整数型の値に対しては、加算、減算、乗算などの基本的な算術演算を行うことができる。プログラムでは、繰返し回数の管理や配列の添字などにも整数型が利用される。`,vi:`Có thể thực hiện các phép toán số học cơ bản như cộng, trừ và nhân với các giá trị kiểu số nguyên. Trong chương trình, kiểu số nguyên còn được dùng để quản lý số lần lặp hoặc chỉ số của mảng.`},{type:`heading`,ja:`表現できる値の範囲`,vi:`Phạm vi giá trị có thể biểu diễn`},{type:`paragraph`,ja:`整数型で表現できる値の範囲は、使用するビット数や符号の有無によって異なる。限られたビット数で表現できる範囲を超えた値を扱うと、オーバーフローが発生する場合がある。`,vi:`Phạm vi giá trị mà kiểu số nguyên có thể biểu diễn phụ thuộc vào số bit được sử dụng và việc có dấu hay không. Nếu xử lý giá trị vượt quá phạm vi biểu diễn của số bit giới hạn, có thể xảy ra overflow.`},{type:`point`,ja:`整数型は小数部を持たない値を扱う。表現できる範囲はビット数や符号の有無によって決まる。`,vi:`Kiểu số nguyên dùng cho giá trị không có phần thập phân. Phạm vi biểu diễn phụ thuộc vào số bit và việc kiểu dữ liệu có dấu hay không.`}],terms:[{term:`整数型`,reading:`せいすうがた`,english:`Integer Type`,vi:`kiểu số nguyên`,definitionJa:`小数部を持たない整数を扱うためのデータ型。`,definitionVi:`Kiểu dữ liệu dùng để xử lý các số nguyên không có phần thập phân.`},{term:`オーバーフロー`,reading:`おーばーふろー`,english:`Overflow`,vi:`tràn số`,definitionJa:`データ型で表現できる値の範囲を超えること。`,definitionVi:`Hiện tượng giá trị vượt quá phạm vi mà kiểu dữ liệu có thể biểu diễn.`}],tags:[`programming`,`data-type`,`integer`,`overflow`]},{id:`real-number-type`,order:11,titleJa:`実数型`,titleVi:`Kiểu số thực`,importance:`high`,summaryJa:`整数だけでなく小数を含む数値を扱う実数型について、その用途と浮動小数点数による表現を理解する。`,summaryVi:`Tìm hiểu kiểu số thực dùng để xử lý các giá trị số có phần thập phân và cách biểu diễn chúng bằng số dấu phẩy động.`,content:[{type:`heading`,ja:`実数型とは`,vi:`Kiểu số thực là gì?`},{type:`paragraph`,ja:`実数型（Real Number Type）とは、整数だけでなく小数を含む数値を扱うためのデータ型である。温度、距離、割合など、小数部分を必要とする値をプログラム内で表現するときに使用される。`,vi:`Kiểu số thực (Real Number Type) là kiểu dữ liệu dùng để xử lý không chỉ số nguyên mà cả các giá trị có phần thập phân. Nó được sử dụng để biểu diễn các giá trị như nhiệt độ, khoảng cách và tỷ lệ.`},{type:`heading`,ja:`浮動小数点数`,vi:`Số dấu phẩy động`},{type:`paragraph`,ja:`多くのプログラミング言語では、実数を浮動小数点数として表現する。浮動小数点数では、非常に大きな値や小さな値まで幅広く表現できる一方、有限のビット数で表現するため、値によっては誤差が生じることがある。`,vi:`Trong nhiều ngôn ngữ lập trình, số thực được biểu diễn dưới dạng số dấu phẩy động. Cách biểu diễn này cho phép xử lý phạm vi giá trị rất lớn hoặc rất nhỏ, nhưng do sử dụng số bit hữu hạn nên một số giá trị có thể phát sinh sai số.`},{type:`heading`,ja:`実数型の利用`,vi:`Ứng dụng của kiểu số thực`},{type:`paragraph`,ja:`実数型は、科学技術計算、測定値の処理、シミュレーションなど、小数を含む計算が必要な場面で広く利用される。整数型とは異なり、小数部分を扱えることが大きな特徴である。`,vi:`Kiểu số thực được sử dụng rộng rãi trong tính toán khoa học kỹ thuật, xử lý giá trị đo và mô phỏng, nơi cần thực hiện các phép tính có phần thập phân. Điểm khác biệt lớn so với kiểu số nguyên là khả năng xử lý phần thập phân.`},{type:`point`,ja:`実数型は小数を含む数値を扱える。多くの場合は浮動小数点数として表現され、計算時に誤差が生じる場合がある。`,vi:`Kiểu số thực có thể xử lý giá trị có phần thập phân. Thông thường nó được biểu diễn bằng số dấu phẩy động và có thể phát sinh sai số khi tính toán.`}],terms:[{term:`実数型`,reading:`じっすうがた`,english:`Real Number Type`,vi:`kiểu số thực`,definitionJa:`整数や小数を含む数値を扱うためのデータ型。`,definitionVi:`Kiểu dữ liệu dùng để xử lý các giá trị số bao gồm cả số nguyên và số thập phân.`},{term:`浮動小数点数`,reading:`ふどうしょうすうてんすう`,english:`Floating-Point Number`,vi:`số dấu phẩy động`,definitionJa:`実数をコンピュータ上で近似的に表現するための数値表現方式。`,definitionVi:`Phương pháp biểu diễn gần đúng số thực trên máy tính.`}],tags:[`programming`,`data-type`,`real-number`,`floating-point`]},{id:`logical-type`,order:12,titleJa:`論理型`,titleVi:`Kiểu logic`,importance:`high`,summaryJa:`真と偽の二つの状態を表現し、条件判定やフラグに利用される論理型について理解する。`,summaryVi:`Tìm hiểu kiểu logic biểu diễn hai trạng thái đúng và sai, được sử dụng trong điều kiện và cờ trạng thái.`,content:[{type:`heading`,ja:`論理型とは`,vi:`Kiểu logic là gì?`},{type:`paragraph`,ja:`論理型（Logical Type）とは、真（true）と偽（false）の二つの状態を表すためのデータ型である。プログラムにおける条件判定や、ある状態が成立しているかどうかを表すために使用される。`,vi:`Kiểu logic (Logical Type) là kiểu dữ liệu biểu diễn hai trạng thái đúng (true) và sai (false). Nó được sử dụng để đánh giá điều kiện hoặc biểu diễn việc một trạng thái nào đó có đang được thỏa mãn hay không.`},{type:`heading`,ja:`条件判定での利用`,vi:`Sử dụng trong đánh giá điều kiện`},{type:`paragraph`,ja:`例えば、ユーザーがログインしているかどうかを論理型で表す場合、ログインしていればtrue、していなければfalseとすることができる。この値を条件分岐に利用することで、状態に応じた処理を実行できる。`,vi:`Ví dụ, khi biểu diễn trạng thái đăng nhập của người dùng bằng kiểu logic, có thể dùng true nếu đã đăng nhập và false nếu chưa đăng nhập. Giá trị này có thể được sử dụng trong câu lệnh rẽ nhánh để thực hiện xử lý phù hợp với trạng thái.`},{type:`heading`,ja:`フラグとしての利用`,vi:`Sử dụng làm cờ trạng thái`},{type:`paragraph`,ja:`論理型の値は、処理済みかどうか、エラーが発生したかどうかなどを表すフラグとしても利用される。二つの状態を明確に表現できるため、プログラムの条件処理を簡潔に記述できる。`,vi:`Giá trị logic cũng được sử dụng làm cờ để biểu diễn các trạng thái như đã xử lý hay chưa hoặc có xảy ra lỗi hay không. Vì có thể biểu diễn rõ ràng hai trạng thái nên giúp viết các xử lý điều kiện ngắn gọn hơn.`},{type:`point`,ja:`論理型はtrueとfalseの二つの値を扱い、条件判定や状態を表すフラグに利用される。`,vi:`Kiểu logic xử lý hai giá trị true và false, chủ yếu được dùng cho điều kiện và cờ biểu diễn trạng thái.`}],terms:[{term:`論理型`,reading:`ろんりがた`,english:`Logical Type`,vi:`kiểu logic`,definitionJa:`真と偽の二つの状態を表すデータ型。`,definitionVi:`Kiểu dữ liệu biểu diễn hai trạng thái đúng và sai.`},{term:`フラグ`,reading:`ふらぐ`,english:`Flag`,vi:`cờ trạng thái`,definitionJa:`ある状態が成立しているかどうかを示すための値。`,definitionVi:`Giá trị dùng để biểu thị một trạng thái có đang được thỏa mãn hay không.`}],tags:[`programming`,`data-type`,`logical-type`,`boolean`,`flag`]},{id:`character-type`,order:13,titleJa:`文字型`,titleVi:`Kiểu ký tự`,importance:`high`,summaryJa:`一つの文字を扱うための文字型と、文字列型との違いを理解する。`,summaryVi:`Tìm hiểu kiểu ký tự dùng để biểu diễn một ký tự và phân biệt nó với kiểu chuỗi.`,content:[{type:`heading`,ja:`文字型とは`,vi:`Kiểu ký tự là gì?`},{type:`paragraph`,ja:`文字型（Character Type）とは、一つの文字を扱うためのデータ型である。アルファベット、数字、記号などの文字を一文字単位で格納するときに使用される。`,vi:`Kiểu ký tự (Character Type) là kiểu dữ liệu dùng để xử lý một ký tự. Nó được sử dụng để lưu một ký tự như chữ cái, chữ số hoặc ký hiệu.`},{type:`heading`,ja:`文字の表現`,vi:`Biểu diễn ký tự`},{type:`paragraph`,ja:`コンピュータ内部では、文字は文字コードによって数値として表現される。代表的な文字コードにはASCIIやUnicodeなどがあり、文字と数値の対応関係を定めている。`,vi:`Bên trong máy tính, ký tự được biểu diễn dưới dạng giá trị số thông qua mã ký tự. ASCII và Unicode là những hệ thống mã ký tự tiêu biểu, quy định quan hệ tương ứng giữa ký tự và giá trị số.`},{type:`heading`,ja:`文字型と文字列型`,vi:`Kiểu ký tự và kiểu chuỗi`},{type:`paragraph`,ja:`文字型が基本的に一つの文字を扱うのに対し、文字列型は複数の文字を連続して扱うために使用される。この違いは、プログラミングにおける基本的なデータ型の理解として重要である。`,vi:`Trong khi kiểu ký tự về cơ bản xử lý một ký tự, kiểu chuỗi được sử dụng để xử lý nhiều ký tự liên tiếp. Phân biệt hai kiểu này là kiến thức cơ bản quan trọng về kiểu dữ liệu trong lập trình.`},{type:`point`,ja:`文字型は基本的に一文字を扱う。複数の文字の集まりを扱うものは文字列型である。`,vi:`Kiểu ký tự về cơ bản xử lý một ký tự; tập hợp nhiều ký tự được xử lý bằng kiểu chuỗi.`}],terms:[{term:`文字型`,reading:`もじがた`,english:`Character Type`,vi:`kiểu ký tự`,definitionJa:`一つの文字を扱うためのデータ型。`,definitionVi:`Kiểu dữ liệu dùng để xử lý một ký tự.`},{term:`文字コード`,reading:`もじこーど`,english:`Character Code`,vi:`mã ký tự`,definitionJa:`文字とコンピュータ内部の数値を対応付けるための規則。`,definitionVi:`Quy tắc ánh xạ ký tự với giá trị số bên trong máy tính.`}],tags:[`programming`,`data-type`,`character`,`character-code`]},{id:`string-type`,order:14,titleJa:`文字列型`,titleVi:`Kiểu chuỗi`,importance:`high`,summaryJa:`複数の文字を連続したデータとして扱う文字列型と、その基本的な操作について理解する。`,summaryVi:`Tìm hiểu kiểu chuỗi dùng để xử lý nhiều ký tự liên tiếp và các thao tác cơ bản với chuỗi.`,content:[{type:`heading`,ja:`文字列型とは`,vi:`Kiểu chuỗi là gì?`},{type:`paragraph`,ja:`文字列型（String Type）とは、複数の文字を連続した一つのデータとして扱うためのデータ型である。名前、住所、文章などのテキストデータをプログラム内で扱うときに使用される。`,vi:`Kiểu chuỗi (String Type) là kiểu dữ liệu dùng để xử lý nhiều ký tự liên tiếp như một dữ liệu duy nhất. Nó được sử dụng cho dữ liệu văn bản như tên, địa chỉ hoặc câu văn.`},{type:`heading`,ja:`文字列の操作`,vi:`Thao tác với chuỗi`},{type:`paragraph`,ja:`文字列に対しては、複数の文字列をつなぐ結合、必要な部分を取り出す部分文字列の取得、特定の文字列を探す検索など、さまざまな操作を行うことができる。`,vi:`Có thể thực hiện nhiều thao tác với chuỗi như nối nhiều chuỗi với nhau, lấy một phần của chuỗi hoặc tìm kiếm một chuỗi cụ thể.`},{type:`heading`,ja:`文字列型の利用`,vi:`Ứng dụng của kiểu chuỗi`},{type:`paragraph`,ja:`文字列型は、Webサイトのユーザー名やメッセージ、データベースに保存する名称など、さまざまなテキスト情報の処理に利用される。多くのプログラミング言語では、文字列を扱うための機能が用意されている。`,vi:`Kiểu chuỗi được sử dụng để xử lý nhiều loại thông tin văn bản như tên người dùng và tin nhắn trên website hoặc tên được lưu trong cơ sở dữ liệu. Nhiều ngôn ngữ lập trình cung cấp sẵn các chức năng để xử lý chuỗi.`},{type:`point`,ja:`文字列型は複数の文字の集まりを扱うデータ型であり、結合、検索、部分文字列の取得などの操作が行われる。`,vi:`Kiểu chuỗi xử lý một tập hợp nhiều ký tự và hỗ trợ các thao tác như nối, tìm kiếm và lấy chuỗi con.`}],terms:[{term:`文字列型`,reading:`もじれつがた`,english:`String Type`,vi:`kiểu chuỗi`,definitionJa:`複数の文字を連続したデータとして扱うためのデータ型。`,definitionVi:`Kiểu dữ liệu dùng để xử lý nhiều ký tự liên tiếp.`},{term:`文字列`,reading:`もじれつ`,english:`String`,vi:`chuỗi ký tự`,definitionJa:`複数の文字を順番に並べたもの。`,definitionVi:`Một dãy gồm nhiều ký tự được sắp xếp theo thứ tự.`}],tags:[`programming`,`data-type`,`string`,`character`]},{id:`abstract-data-type`,order:15,titleJa:`抽象データ型`,titleVi:`Kiểu dữ liệu trừu tượng`,importance:`high`,summaryJa:`データの具体的な実装方法ではなく、データの構造とそれに対して行える操作を定義する抽象データ型について理解する。`,summaryVi:`Tìm hiểu kiểu dữ liệu trừu tượng, trong đó cấu trúc dữ liệu và các thao tác có thể thực hiện được định nghĩa độc lập với cách triển khai cụ thể.`,content:[{type:`heading`,ja:`抽象データ型とは`,vi:`Kiểu dữ liệu trừu tượng là gì?`},{type:`paragraph`,ja:`抽象データ型（Abstract Data Type：ADT）とは、データの具体的な実装方法とは独立して、データの構造やそれに対して行える操作を定義する概念である。データを内部でどのように保持するかではなく、どのような操作が可能であるかに着目する。`,vi:`Kiểu dữ liệu trừu tượng (Abstract Data Type: ADT) là khái niệm định nghĩa cấu trúc dữ liệu và các thao tác có thể thực hiện trên dữ liệu một cách độc lập với cách triển khai cụ thể. Nó tập trung vào những thao tác có thể thực hiện thay vì cách dữ liệu được lưu trữ bên trong.`},{type:`heading`,ja:`代表的な抽象データ型`,vi:`Các kiểu dữ liệu trừu tượng tiêu biểu`},{type:`paragraph`,ja:`代表的な抽象データ型には、スタックやキューなどがある。例えば、スタックではデータの追加を行うプッシュと、データを取り出すポップなどの操作が定義される。内部で配列を使うかリストを使うかといった実装方法は、抽象データ型そのものとは分離して考えることができる。`,vi:`Các kiểu dữ liệu trừu tượng tiêu biểu gồm stack và queue. Ví dụ, stack định nghĩa các thao tác như push để thêm dữ liệu và pop để lấy dữ liệu ra. Việc triển khai bên trong bằng mảng hay danh sách có thể được xem xét riêng với bản thân kiểu dữ liệu trừu tượng.`},{type:`heading`,ja:`抽象化の利点`,vi:`Lợi ích của tính trừu tượng`},{type:`paragraph`,ja:`実装の詳細を隠すことで、利用者はデータが持つ性質や操作に集中できる。また、内部の実装を変更しても、外部から利用する操作が同じであれば影響を小さくできるため、保守性や再利用性の向上にもつながる。`,vi:`Bằng cách che giấu chi tiết triển khai, người sử dụng có thể tập trung vào đặc tính và thao tác của dữ liệu. Ngoài ra, ngay cả khi cách triển khai bên trong thay đổi, ảnh hưởng ra bên ngoài có thể được hạn chế nếu các thao tác cung cấp vẫn giữ nguyên, từ đó cải thiện khả năng bảo trì và tái sử dụng.`},{type:`point`,ja:`抽象データ型では「どのように実装するか」ではなく「どのようなデータと操作を提供するか」を定義する。スタックやキューが代表例である。`,vi:`Kiểu dữ liệu trừu tượng định nghĩa "dữ liệu và thao tác nào được cung cấp" thay vì "triển khai như thế nào". Stack và queue là các ví dụ tiêu biểu.`}],terms:[{term:`抽象データ型`,reading:`ちゅうしょうでーたがた`,english:`Abstract Data Type`,vi:`kiểu dữ liệu trừu tượng`,definitionJa:`データの具体的な実装方法から独立して、データの構造や操作を定義する概念。`,definitionVi:`Khái niệm định nghĩa cấu trúc và thao tác của dữ liệu độc lập với phương pháp triển khai cụ thể.`}],tags:[`programming`,`data-type`,`abstract-data-type`,`adt`]},{id:`structured-type`,order:16,titleJa:`構造型`,titleVi:`Kiểu cấu trúc`,importance:`high`,summaryJa:`異なる種類のデータを一つのまとまりとして扱うための構造型について、その特徴と用途を理解する。`,summaryVi:`Tìm hiểu kiểu cấu trúc dùng để tổ chức và quản lý nhiều loại dữ liệu khác nhau như một đơn vị.`,content:[{type:`heading`,ja:`構造型とは`,vi:`Kiểu cấu trúc là gì?`},{type:`paragraph`,ja:`構造型（Structured Type）とは、複数のデータを特定の形式でまとめて扱うためのデータ型である。異なる種類のデータを一つのまとまりとして管理できる。`,vi:`Kiểu cấu trúc (Structured Type) là kiểu dữ liệu dùng để tập hợp nhiều dữ liệu theo một cấu trúc nhất định. Nó cho phép quản lý nhiều loại dữ liệu khác nhau như một đơn vị.`},{type:`heading`,ja:`構造型の例`,vi:`Ví dụ về kiểu cấu trúc`},{type:`paragraph`,ja:`例えば、人を表すデータとして名前、年齢、住所を一つの構造としてまとめることができる。それぞれ異なる種類のデータであっても、関連する情報として一括して扱えるため、複雑なデータを整理しやすくなる。`,vi:`Ví dụ, dữ liệu về một người có thể được tập hợp thành một cấu trúc gồm tên, tuổi và địa chỉ. Mặc dù các dữ liệu có thể thuộc những kiểu khác nhau, chúng vẫn có thể được xử lý chung như những thông tin có liên quan.`},{type:`heading`,ja:`構造型の利点`,vi:`Lợi ích của kiểu cấu trúc`},{type:`paragraph`,ja:`関連する複数の情報を一つにまとめることで、データの意味や関係が分かりやすくなり、プログラムの可読性や保守性が向上する。複雑なデータを意味のある単位で管理するために重要な考え方である。`,vi:`Việc tập hợp nhiều thông tin liên quan giúp quan hệ và ý nghĩa của dữ liệu trở nên rõ ràng hơn, từ đó cải thiện khả năng đọc và bảo trì chương trình. Đây là một khái niệm quan trọng để quản lý dữ liệu phức tạp theo các đơn vị có ý nghĩa.`},{type:`point`,ja:`構造型では、異なる種類のデータを一つのまとまりとして管理できる。`,vi:`Kiểu cấu trúc cho phép quản lý nhiều loại dữ liệu khác nhau như một đơn vị.`}],terms:[{term:`構造型`,reading:`こうぞうがた`,english:`Structured Type`,vi:`kiểu cấu trúc`,definitionJa:`複数のデータを特定の構造にまとめて扱うためのデータ型。`,definitionVi:`Kiểu dữ liệu dùng để tập hợp và xử lý nhiều dữ liệu theo một cấu trúc nhất định.`}],tags:[`programming`,`data-type`,`structured-type`]},{id:`assignment`,order:17,titleJa:`代入`,titleVi:`Phép gán`,importance:`high`,summaryJa:`値を変数に記憶させる基本操作である代入について、その役割とプログラムでの使い方を理解する。`,summaryVi:`Tìm hiểu phép gán, thao tác cơ bản dùng để lưu một giá trị vào biến trong chương trình.`,content:[{type:`heading`,ja:`代入とは`,vi:`Phép gán là gì?`},{type:`paragraph`,ja:`代入（Assignment）とは、プログラミングにおいて値を変数に記憶させる操作である。変数に数値や文字列などの値を設定することで、その値を後の処理から利用できるようになる。`,vi:`Phép gán (Assignment) là thao tác lưu một giá trị vào biến trong lập trình. Khi gán một giá trị như số hoặc chuỗi cho biến, giá trị đó có thể được sử dụng trong các xử lý tiếp theo.`},{type:`heading`,ja:`代入の例`,vi:`Ví dụ về phép gán`},{type:`paragraph`,ja:`例えば「x = 5」と記述した場合、変数xに値5を代入することを表す。その後の処理では、xを使用することで記憶された値5を参照できる。`,vi:`Ví dụ, khi viết "x = 5", giá trị 5 được gán cho biến x. Trong các xử lý tiếp theo, có thể sử dụng x để tham chiếu đến giá trị 5 đã được lưu.`},{type:`heading`,ja:`代入と等号`,vi:`Phép gán và dấu bằng`},{type:`paragraph`,ja:`多くのプログラミング言語では「=」が代入演算子として使用されるが、数学の等号とは意味が異なる。代入では、右辺の値や式を評価し、その結果を左辺の変数に格納する。`,vi:`Trong nhiều ngôn ngữ lập trình, dấu "=" được sử dụng làm toán tử gán nhưng có ý nghĩa khác với dấu bằng trong toán học. Trong phép gán, giá trị hoặc biểu thức ở vế phải được tính trước rồi kết quả được lưu vào biến ở vế trái.`},{type:`point`,ja:`代入は値を変数に記憶させる操作である。「=」を使う言語では、数学の等号との違いに注意する。`,vi:`Phép gán là thao tác lưu giá trị vào biến. Với các ngôn ngữ sử dụng "=", cần phân biệt nó với dấu bằng trong toán học.`}],terms:[{term:`代入`,reading:`だいにゅう`,english:`Assignment`,vi:`phép gán`,definitionJa:`値や式の結果を変数に格納する操作。`,definitionVi:`Thao tác lưu một giá trị hoặc kết quả của biểu thức vào biến.`},{term:`代入演算子`,reading:`だいにゅうえんざんし`,english:`Assignment Operator`,vi:`toán tử gán`,definitionJa:`値を変数に代入するために使用する演算子。`,definitionVi:`Toán tử được sử dụng để gán giá trị cho biến.`}],tags:[`programming`,`assignment`,`variable`,`operator`]},{id:`arithmetic-operation`,order:18,titleJa:`算術演算`,titleVi:`Phép toán số học`,importance:`high`,summaryJa:`加算、減算、乗算、除算など、数値に対して行う基本的な算術演算について理解する。`,summaryVi:`Tìm hiểu các phép toán số học cơ bản được thực hiện trên dữ liệu số như cộng, trừ, nhân và chia.`,content:[{type:`heading`,ja:`算術演算とは`,vi:`Phép toán số học là gì?`},{type:`paragraph`,ja:`算術演算（Arithmetic Operation）とは、数値に対して行う基本的な計算である。代表的なものとして、加算、減算、乗算、除算がある。`,vi:`Phép toán số học (Arithmetic Operation) là các phép tính cơ bản thực hiện trên giá trị số. Những phép toán tiêu biểu gồm cộng, trừ, nhân và chia.`},{type:`heading`,ja:`四則演算`,vi:`Bốn phép tính cơ bản`},{type:`paragraph`,ja:`加算は二つの値を足し合わせる演算、減算はある値から別の値を引く演算、乗算は値を掛け合わせる演算、除算はある値を別の値で割る演算である。これらをまとめて四則演算という。`,vi:`Phép cộng dùng để cộng hai giá trị, phép trừ lấy một giá trị trừ đi giá trị khác, phép nhân nhân các giá trị với nhau và phép chia chia một giá trị cho giá trị khác. Bốn phép này được gọi chung là bốn phép tính cơ bản.`},{type:`heading`,ja:`プログラムでの算術演算`,vi:`Phép toán số học trong chương trình`},{type:`paragraph`,ja:`プログラミングでは、一般に「+」「-」「*」「/」などの算術演算子を使用して計算を記述する。複数の演算を組み合わせる場合には演算子の優先順位があり、必要に応じて括弧を使用して計算順序を明確にする。`,vi:`Trong lập trình, các toán tử số học như "+", "-", "*" và "/" thường được sử dụng để mô tả phép tính. Khi kết hợp nhiều phép toán, cần chú ý đến thứ tự ưu tiên của toán tử và có thể sử dụng dấu ngoặc để xác định rõ thứ tự tính.`},{type:`point`,ja:`算術演算の基本は加算・減算・乗算・除算である。プログラムでは演算子の優先順位にも注意する。`,vi:`Các phép toán số học cơ bản là cộng, trừ, nhân và chia. Trong chương trình cũng cần chú ý đến thứ tự ưu tiên của toán tử.`}],terms:[{term:`算術演算`,reading:`さんじゅつえんざん`,english:`Arithmetic Operation`,vi:`phép toán số học`,definitionJa:`数値に対して加算、減算、乗算、除算などを行う演算。`,definitionVi:`Phép toán thực hiện cộng, trừ, nhân, chia và các tính toán khác trên giá trị số.`},{term:`四則演算`,reading:`しそくえんざん`,english:`Four Arithmetic Operations`,vi:`bốn phép tính cơ bản`,definitionJa:`加算、減算、乗算、除算の四つの基本的な算術演算。`,definitionVi:`Bốn phép toán số học cơ bản gồm cộng, trừ, nhân và chia.`}],tags:[`programming`,`arithmetic`,`operation`,`operator`]},{id:`comparison-operation`,order:19,titleJa:`比較演算`,titleVi:`Phép toán so sánh`,importance:`high`,summaryJa:`二つの値を比較して真偽値を得る比較演算と、条件分岐やループで使用される代表的な比較演算子を理解する。`,summaryVi:`Tìm hiểu phép toán so sánh dùng để so sánh hai giá trị và trả về giá trị đúng hoặc sai, cùng các toán tử so sánh thường dùng trong rẽ nhánh và vòng lặp.`,content:[{type:`heading`,ja:`比較演算とは`,vi:`Phép toán so sánh là gì?`},{type:`paragraph`,ja:`比較演算（Comparison Operation）とは、二つの値や変数を比較し、その結果を真または偽として得る演算である。プログラミングでは、条件分岐やループ処理など、条件に応じて処理を制御するときに利用される。`,vi:`Phép toán so sánh (Comparison Operation) là phép toán so sánh hai giá trị hoặc biến và trả về kết quả đúng hoặc sai. Trong lập trình, nó được sử dụng để điều khiển xử lý theo điều kiện, chẳng hạn trong rẽ nhánh và vòng lặp.`},{type:`heading`,ja:`代表的な比較演算子`,vi:`Các toán tử so sánh tiêu biểu`},{type:`paragraph`,ja:`代表的な比較演算子には、「==」（等しい）、「!=」（等しくない）、「>」（より大きい）、「<」（より小さい）、「>=」（以上）、「<=」（以下）などがある。例えば「A > B」は、AがBより大きい場合に真となる。`,vi:`Các toán tử so sánh tiêu biểu gồm "==" (bằng), "!=" (khác), ">" (lớn hơn), "<" (nhỏ hơn), ">=" (lớn hơn hoặc bằng) và "<=" (nhỏ hơn hoặc bằng). Ví dụ, "A > B" trả về đúng nếu A lớn hơn B.`},{type:`heading`,ja:`条件判定での利用`,vi:`Sử dụng trong đánh giá điều kiện`},{type:`paragraph`,ja:`比較演算の結果は真偽値となるため、その結果に基づいて特定の処理を実行するかどうかを判断できる。このため、プログラムの流れを制御するための基本的な演算として広く利用される。`,vi:`Do kết quả của phép so sánh là giá trị đúng hoặc sai, chương trình có thể dựa vào đó để quyết định có thực hiện một xử lý nhất định hay không. Vì vậy, đây là phép toán cơ bản để điều khiển luồng chương trình.`},{type:`point`,ja:`比較演算は二つの値を比較して真または偽を返す。「==」「!=」「>」「<」「>=」「<=」などの比較演算子を覚える。`,vi:`Phép so sánh so sánh hai giá trị và trả về đúng hoặc sai. Cần nhớ các toán tử như ==, !=, >, <, >= và <=.`}],terms:[{term:`比較演算`,reading:`ひかくえんざん`,english:`Comparison Operation`,vi:`phép toán so sánh`,definitionJa:`二つの値を比較し、その結果を真偽値として得る演算。`,definitionVi:`Phép toán so sánh hai giá trị và trả về kết quả đúng hoặc sai.`},{term:`比較演算子`,reading:`ひかくえんざんし`,english:`Comparison Operator`,vi:`toán tử so sánh`,definitionJa:`値の大小や等しさなどを比較するための演算子。`,definitionVi:`Toán tử dùng để so sánh độ lớn hoặc sự bằng nhau giữa các giá trị.`}],tags:[`programming`,`comparison`,`operator`,`condition`]},{id:`logical-operation`,order:20,titleJa:`論理演算`,titleVi:`Phép toán logic`,importance:`high`,summaryJa:`真偽値に対してAND、OR、NOTなどを適用する論理演算について、それぞれの基本的な動作を理解する。`,summaryVi:`Tìm hiểu các phép toán logic AND, OR và NOT được thực hiện trên các giá trị đúng/sai và cách hoạt động cơ bản của chúng.`,content:[{type:`heading`,ja:`論理演算とは`,vi:`Phép toán logic là gì?`},{type:`paragraph`,ja:`論理演算（Logical Operation）とは、真（True）または偽（False）の真偽値に対して行う演算である。プログラミングでは、複数の条件を組み合わせたり、条件を反転したりするときに利用される。`,vi:`Phép toán logic (Logical Operation) là phép toán thực hiện trên các giá trị đúng (True) hoặc sai (False). Trong lập trình, nó được sử dụng để kết hợp nhiều điều kiện hoặc đảo ngược một điều kiện.`},{type:`heading`,ja:`AND・OR・NOT`,vi:`AND, OR và NOT`},{type:`paragraph`,ja:`AND演算は両方の条件が真の場合だけ真となる。OR演算は少なくとも一方の条件が真であれば真となる。NOT演算は真を偽に、偽を真に反転させる。`,vi:`Phép AND chỉ trả về đúng khi cả hai điều kiện đều đúng. Phép OR trả về đúng nếu ít nhất một điều kiện đúng. Phép NOT đảo giá trị đúng thành sai và sai thành đúng.`},{type:`heading`,ja:`プログラムでの利用`,vi:`Ứng dụng trong chương trình`},{type:`paragraph`,ja:`論理演算は条件分岐やループなどで頻繁に使用される。複数の条件を組み合わせることで、より複雑な条件を表現し、プログラムの判断や処理を制御することができる。`,vi:`Phép toán logic thường được sử dụng trong rẽ nhánh và vòng lặp. Bằng cách kết hợp nhiều điều kiện, chương trình có thể biểu diễn các điều kiện phức tạp hơn và kiểm soát quá trình xử lý.`},{type:`point`,ja:`ANDは「両方が真」、ORは「少なくとも一方が真」、NOTは「真偽を反転」と覚える。`,vi:`Hãy nhớ: AND = cả hai đều đúng, OR = ít nhất một bên đúng, NOT = đảo ngược đúng/sai.`}],terms:[{term:`論理演算`,reading:`ろんりえんざん`,english:`Logical Operation`,vi:`phép toán logic`,definitionJa:`真偽値に対してAND、OR、NOTなどを行う演算。`,definitionVi:`Phép toán thực hiện AND, OR, NOT và các thao tác tương tự trên giá trị logic.`},{term:`真偽値`,reading:`しんぎち`,english:`Boolean Value`,vi:`giá trị logic`,definitionJa:`真または偽のいずれかを表す値。`,definitionVi:`Giá trị biểu diễn một trong hai trạng thái đúng hoặc sai.`}],tags:[`programming`,`logical-operation`,`and`,`or`,`not`]},{id:`bitwise-operation`,order:21,titleJa:`ビット演算`,titleVi:`Phép toán bit`,importance:`high`,summaryJa:`2進数の各ビットに対して直接処理を行うビット演算と、AND、OR、NOT、XOR、シフトなどの基本操作を理解する。`,summaryVi:`Tìm hiểu phép toán bit tác động trực tiếp lên từng bit của dữ liệu nhị phân và các thao tác cơ bản như AND, OR, NOT, XOR và dịch bit.`,content:[{type:`heading`,ja:`ビット演算とは`,vi:`Phép toán bit là gì?`},{type:`paragraph`,ja:`ビット演算（Bitwise Operation）とは、データを2進数として扱い、それぞれのビット（0または1）に対して直接操作を行う演算である。データの特定のビットだけを操作したい場合などに利用される。`,vi:`Phép toán bit (Bitwise Operation) là phép toán xử lý dữ liệu dưới dạng nhị phân và thao tác trực tiếp trên từng bit 0 hoặc 1. Nó được sử dụng khi cần xử lý riêng các bit cụ thể của dữ liệu.`},{type:`heading`,ja:`基本的なビット演算`,vi:`Các phép toán bit cơ bản`},{type:`paragraph`,ja:`代表的なビット演算にはAND、OR、NOT、XORなどがある。ANDでは対応する両方のビットが1の場合だけ1となり、ORでは少なくとも一方が1であれば1となる。XORでは二つのビットが異なる場合に1となる。`,vi:`Các phép toán bit tiêu biểu gồm AND, OR, NOT và XOR. Với AND, kết quả là 1 chỉ khi cả hai bit tương ứng đều là 1. Với OR, kết quả là 1 nếu ít nhất một bit là 1. Với XOR, kết quả là 1 khi hai bit khác nhau.`},{type:`heading`,ja:`シフト演算`,vi:`Phép dịch bit`},{type:`paragraph`,ja:`ビット列を左または右へ移動させる操作をシフト演算という。ビット演算やシフト演算は、ビットマスク、フラグの設定、高速なデータ処理などで利用される。`,vi:`Thao tác di chuyển dãy bit sang trái hoặc phải được gọi là phép dịch bit. Phép toán bit và dịch bit được sử dụng trong bit mask, thiết lập cờ trạng thái và xử lý dữ liệu hiệu quả.`},{type:`point`,ja:`ビット演算は0と1の各ビットを直接操作する。論理演算と似たAND・OR・NOTなどがあるが、真偽値ではなくビット単位で処理する点が重要である。`,vi:`Phép toán bit thao tác trực tiếp trên từng bit 0 và 1. Tuy có AND, OR, NOT giống phép toán logic, điểm quan trọng là chúng xử lý từng bit chứ không phải toàn bộ giá trị đúng/sai.`}],terms:[{term:`ビット演算`,reading:`びっとえんざん`,english:`Bitwise Operation`,vi:`phép toán bit`,definitionJa:`2進数の各ビットに対して直接操作を行う演算。`,definitionVi:`Phép toán tác động trực tiếp lên từng bit của dữ liệu nhị phân.`},{term:`シフト演算`,reading:`しふとえんざん`,english:`Shift Operation`,vi:`phép dịch bit`,definitionJa:`ビット列を左または右へ移動させる演算。`,definitionVi:`Phép toán dịch một dãy bit sang trái hoặc sang phải.`}],tags:[`programming`,`bitwise-operation`,`bit`,`binary`,`shift`]},{id:`selection-processing`,order:22,titleJa:`選択処理`,titleVi:`Xử lý lựa chọn`,importance:`high`,summaryJa:`条件の真偽によって実行する処理を選択する選択処理と、if文やswitch文などの代表的な実現方法を理解する。`,summaryVi:`Tìm hiểu xử lý lựa chọn, trong đó chương trình chọn xử lý cần thực hiện dựa trên điều kiện, cùng các cấu trúc tiêu biểu như if và switch.`,content:[{type:`heading`,ja:`選択処理とは`,vi:`Xử lý lựa chọn là gì?`},{type:`paragraph`,ja:`選択処理（Selection Processing）とは、特定の条件に応じて実行する処理を選択する制御構造である。例えば、条件が真の場合は処理A、偽の場合は処理Bを実行するといった制御を行う。`,vi:`Xử lý lựa chọn (Selection Processing) là cấu trúc điều khiển lựa chọn xử lý cần thực hiện dựa trên một điều kiện nhất định. Ví dụ, nếu điều kiện đúng thì thực hiện xử lý A, còn nếu sai thì thực hiện xử lý B.`},{type:`heading`,ja:`if文`,vi:`Câu lệnh if`},{type:`paragraph`,ja:`if文は、条件の真偽によって処理を分岐させる代表的な方法である。例えば、「晴れていれば公園へ行く、雨であれば家にいる」のように、条件によって異なる処理を実行できる。`,vi:`Câu lệnh if là phương pháp tiêu biểu để phân nhánh xử lý dựa trên việc điều kiện đúng hay sai. Ví dụ, có thể thực hiện xử lý khác nhau như "nếu trời nắng thì đi công viên, nếu trời mưa thì ở nhà".`},{type:`heading`,ja:`switch文`,vi:`Câu lệnh switch`},{type:`paragraph`,ja:`複数の候補から値に応じて処理を選択する場合には、switch文などが使用される。多数の条件を整理して記述できるため、状況に応じた処理を分かりやすく表現できる。`,vi:`Khi cần lựa chọn một xử lý dựa trên một giá trị trong nhiều trường hợp, có thể sử dụng câu lệnh switch. Cấu trúc này giúp tổ chức nhiều trường hợp một cách rõ ràng.`},{type:`point`,ja:`選択処理は条件によって実行する処理を切り替える。代表的なものはif文やswitch文である。`,vi:`Xử lý lựa chọn thay đổi xử lý được thực hiện tùy theo điều kiện. Các cấu trúc tiêu biểu là if và switch.`}],terms:[{term:`選択処理`,reading:`せんたくしょり`,english:`Selection Processing`,vi:`xử lý lựa chọn`,definitionJa:`条件に応じて実行する処理を選択する制御構造。`,definitionVi:`Cấu trúc điều khiển lựa chọn xử lý cần thực hiện dựa trên điều kiện.`},{term:`条件分岐`,reading:`じょうけんぶんき`,english:`Conditional Branch`,vi:`rẽ nhánh có điều kiện`,definitionJa:`条件の真偽や値によって処理の流れを分岐させること。`,definitionVi:`Việc phân nhánh luồng xử lý dựa trên giá trị hoặc kết quả đúng/sai của điều kiện.`}],tags:[`programming`,`selection-processing`,`conditional-branch`,`if`,`switch`]},{id:`repetitive-processing`,order:23,titleJa:`繰返し処理`,titleVi:`Xử lý lặp`,importance:`high`,summaryJa:`同じ処理を繰り返し実行する繰返し処理と、ループを利用した効率的なプログラム制御について理解する。`,summaryVi:`Tìm hiểu xử lý lặp dùng để thực hiện cùng một thao tác nhiều lần và cách sử dụng vòng lặp để điều khiển chương trình hiệu quả.`,content:[{type:`heading`,ja:`繰返し処理とは`,vi:`Xử lý lặp là gì?`},{type:`paragraph`,ja:`繰返し処理（Repetitive Processing）とは、プログラムやアルゴリズムにおいて同じ操作を何度も実行するための処理である。例えば、リストの各要素に対して同じ計算を行う場合などに利用される。`,vi:`Xử lý lặp (Repetitive Processing) là phương pháp thực hiện cùng một thao tác nhiều lần trong chương trình hoặc thuật toán. Ví dụ, nó được sử dụng khi cần thực hiện cùng một phép tính cho từng phần tử trong danh sách.`},{type:`heading`,ja:`ループ`,vi:`Vòng lặp`},{type:`paragraph`,ja:`同じ処理を繰り返すために用いられる制御構造をループという。一定の回数だけ処理を繰り返したり、特定の条件を満たしている間だけ処理を続けたりすることができる。`,vi:`Cấu trúc điều khiển dùng để lặp lại cùng một xử lý được gọi là vòng lặp. Có thể lặp một số lần xác định hoặc tiếp tục xử lý trong khi một điều kiện nhất định vẫn được thỏa mãn.`},{type:`heading`,ja:`繰返し処理の利用`,vi:`Ứng dụng của xử lý lặp`},{type:`paragraph`,ja:`例えば、購入した商品の合計金額を求める場合、各商品の価格を順番に加算する処理を繰り返すことで計算できる。繰返し処理は、条件分岐や入出力処理などと組み合わせて利用されることも多い。`,vi:`Ví dụ, để tính tổng giá trị của các sản phẩm đã mua, có thể lặp lại thao tác cộng lần lượt giá của từng sản phẩm. Xử lý lặp cũng thường được kết hợp với rẽ nhánh điều kiện và xử lý nhập/xuất.`},{type:`point`,ja:`繰返し処理は同じ処理を何度も実行するための基本的な制御構造である。回数や条件に応じてループを制御する。`,vi:`Xử lý lặp là cấu trúc điều khiển cơ bản để thực hiện cùng một xử lý nhiều lần. Vòng lặp được điều khiển dựa trên số lần hoặc điều kiện.`}],terms:[{term:`繰返し処理`,reading:`くりかえししょり`,english:`Repetitive Processing`,vi:`xử lý lặp`,definitionJa:`同じ処理を一定回数または条件に応じて繰り返し実行する処理。`,definitionVi:`Xử lý thực hiện lặp lại cùng một thao tác theo số lần hoặc điều kiện nhất định.`},{term:`ループ`,reading:`るーぷ`,english:`Loop`,vi:`vòng lặp`,definitionJa:`同じ処理を繰り返して実行するための制御構造。`,definitionVi:`Cấu trúc điều khiển dùng để thực hiện lặp lại một xử lý.`}],tags:[`programming`,`repetitive-processing`,`loop`,`control-structure`]},{id:`argument`,order:24,titleJa:`引数`,titleVi:`Đối số`,importance:`high`,summaryJa:`関数やメソッドに処理に必要なデータを渡す引数の役割と、引数を利用した処理の再利用について理解する。`,summaryVi:`Tìm hiểu vai trò của đối số trong việc truyền dữ liệu cần thiết cho hàm hoặc phương thức và cách sử dụng đối số để tái sử dụng xử lý.`,content:[{type:`heading`,ja:`引数とは`,vi:`Đối số là gì?`},{type:`paragraph`,ja:`引数（Argument）とは、プログラムにおいて関数やメソッドに渡すデータのことである。関数が特定の処理を行うために必要となる情報を、呼び出し側から渡す役割を持つ。`,vi:`Đối số (Argument) là dữ liệu được truyền cho một hàm hoặc phương thức trong chương trình. Nó có vai trò cung cấp từ phía gọi hàm những thông tin cần thiết để hàm thực hiện một xử lý nhất định.`},{type:`heading`,ja:`引数の例`,vi:`Ví dụ về đối số`},{type:`paragraph`,ja:`例えば、二つの数値を加算する関数では、計算対象となる二つの数値を引数として渡すことができる。引数として渡せるデータには、数値だけでなく、文字列やその他のデータ型もある。`,vi:`Ví dụ, với một hàm cộng hai số, hai giá trị cần tính có thể được truyền vào dưới dạng đối số. Đối số không chỉ có thể là số mà còn có thể là chuỗi và các kiểu dữ liệu khác.`},{type:`heading`,ja:`引数を使う利点`,vi:`Lợi ích của việc sử dụng đối số`},{type:`paragraph`,ja:`引数を利用すると、同じ関数に異なるデータを渡して処理できるため、一つの関数を様々な条件で再利用できる。これにより、コードの重複を減らし、可読性や保守性を高めることができる。`,vi:`Khi sử dụng đối số, có thể truyền các dữ liệu khác nhau vào cùng một hàm, nhờ đó một hàm có thể được tái sử dụng trong nhiều trường hợp. Điều này giúp giảm mã trùng lặp và cải thiện khả năng đọc cũng như bảo trì.`},{type:`point`,ja:`引数は関数やメソッドへ渡すデータである。関数を呼び出す側から、処理に必要な情報を与える。`,vi:`Đối số là dữ liệu được truyền vào hàm hoặc phương thức. Nó cung cấp thông tin cần thiết từ phía gọi hàm.`}],terms:[{term:`引数`,reading:`ひきすう`,english:`Argument`,vi:`đối số`,definitionJa:`関数やメソッドを呼び出すときに渡すデータ。`,definitionVi:`Dữ liệu được truyền vào khi gọi một hàm hoặc phương thức.`}],tags:[`programming`,`argument`,`function`,`method`]},{id:`return-value`,order:25,titleJa:`戻り値`,titleVi:`Giá trị trả về`,importance:`high`,summaryJa:`関数が処理結果として呼び出し元へ返す戻り値の役割と、戻り値を利用したプログラム処理について理解する。`,summaryVi:`Tìm hiểu vai trò của giá trị trả về mà hàm gửi lại cho nơi gọi sau khi xử lý và cách sử dụng giá trị đó trong chương trình.`,content:[{type:`heading`,ja:`戻り値とは`,vi:`Giá trị trả về là gì?`},{type:`paragraph`,ja:`戻り値（Return Value）とは、関数が処理を実行した後に呼び出し元へ返す情報のことである。関数で計算や処理を行った結果を、プログラムの別の部分で利用するために使用される。`,vi:`Giá trị trả về (Return Value) là thông tin mà hàm trả lại cho nơi gọi sau khi thực hiện xử lý. Nó được sử dụng để kết quả tính toán hoặc xử lý của hàm có thể được dùng ở phần khác của chương trình.`},{type:`heading`,ja:`戻り値の利用`,vi:`Sử dụng giá trị trả về`},{type:`paragraph`,ja:`例えば、二つの数値を加算する関数では、計算結果を戻り値として呼び出し元へ返すことができる。呼び出し元はその戻り値を変数に代入したり、別の計算に使用したりすることができる。`,vi:`Ví dụ, một hàm cộng hai số có thể trả kết quả tính toán về nơi gọi dưới dạng giá trị trả về. Nơi gọi có thể gán giá trị này cho một biến hoặc sử dụng nó trong phép tính khác.`},{type:`heading`,ja:`様々な戻り値`,vi:`Các loại giá trị trả về`},{type:`paragraph`,ja:`戻り値は数値だけとは限らず、文字列や真偽値など、関数の目的やデータ型に応じて様々な形式を取ることができる。戻り値を適切に利用することで、処理を機能ごとに分割しやすくなる。`,vi:`Giá trị trả về không chỉ giới hạn ở số mà có thể là chuỗi, giá trị logic hoặc nhiều dạng khác tùy theo mục đích và kiểu dữ liệu của hàm. Việc sử dụng giá trị trả về thích hợp giúp chia chương trình thành các chức năng rõ ràng hơn.`},{type:`point`,ja:`引数は「関数へ渡す値」、戻り値は「関数から返される値」である。この違いを区別する。`,vi:`Cần phân biệt: đối số là "giá trị truyền vào hàm", còn giá trị trả về là "giá trị được hàm trả lại".`}],terms:[{term:`戻り値`,reading:`もどりち`,english:`Return Value`,vi:`giá trị trả về`,definitionJa:`関数やメソッドが処理結果として呼び出し元へ返す値。`,definitionVi:`Giá trị mà hàm hoặc phương thức trả về cho nơi gọi sau khi xử lý.`}],tags:[`programming`,`return-value`,`function`]},{id:`local-variable`,order:26,titleJa:`局所変数`,titleVi:`Biến cục bộ`,importance:`high`,summaryJa:`特定のブロックや関数の内部だけで使用できる局所変数と、その有効範囲であるスコープについて理解する。`,summaryVi:`Tìm hiểu biến cục bộ chỉ có thể được sử dụng bên trong một khối hoặc hàm nhất định và phạm vi hiệu lực (scope) của biến.`,content:[{type:`heading`,ja:`局所変数とは`,vi:`Biến cục bộ là gì?`},{type:`paragraph`,ja:`局所変数（Local Variable）とは、プログラム内の特定のブロックや関数の中だけで使用できる変数である。定義された範囲を超えると、通常はその変数へアクセスすることができない。`,vi:`Biến cục bộ (Local Variable) là biến chỉ có thể được sử dụng bên trong một khối hoặc hàm nhất định của chương trình. Thông thường không thể truy cập biến đó từ bên ngoài phạm vi nơi nó được định nghĩa.`},{type:`heading`,ja:`スコープ`,vi:`Phạm vi (scope)`},{type:`paragraph`,ja:`変数を参照できる範囲をスコープという。局所変数はスコープが限定されているため、他の処理から意図せず値を変更されることを防ぎやすく、プログラムの独立性や可読性を高めることができる。`,vi:`Phạm vi mà một biến có thể được tham chiếu được gọi là scope. Vì biến cục bộ có phạm vi giới hạn nên có thể hạn chế việc giá trị bị thay đổi ngoài ý muốn từ các xử lý khác, giúp tăng tính độc lập và khả năng đọc của chương trình.`},{type:`heading`,ja:`局所変数の利用`,vi:`Sử dụng biến cục bộ`},{type:`paragraph`,ja:`例えば、関数内で計算にだけ使用する一時的な値は局所変数として定義できる。必要な処理が終了すると不要になるため、局所変数を適切に利用することでメモリを効率的に扱いやすくなる。`,vi:`Ví dụ, một giá trị tạm thời chỉ dùng cho phép tính bên trong hàm có thể được định nghĩa là biến cục bộ. Vì nó không còn cần thiết sau khi xử lý kết thúc, việc sử dụng biến cục bộ thích hợp giúp quản lý bộ nhớ hiệu quả hơn.`},{type:`point`,ja:`局所変数は定義されたブロックや関数内で有効な変数である。変数を参照できる範囲をスコープという。`,vi:`Biến cục bộ chỉ có hiệu lực trong khối hoặc hàm nơi nó được định nghĩa. Phạm vi mà biến có thể được truy cập được gọi là scope.`}],terms:[{term:`局所変数`,reading:`きょくしょへんすう`,english:`Local Variable`,vi:`biến cục bộ`,definitionJa:`特定のブロックや関数など、限定された範囲内で使用できる変数。`,definitionVi:`Biến chỉ có thể được sử dụng trong một phạm vi giới hạn như một khối hoặc hàm.`},{term:`スコープ`,reading:`すこーぷ`,english:`Scope`,vi:`phạm vi`,definitionJa:`変数や関数などを参照できる有効範囲。`,definitionVi:`Phạm vi mà biến, hàm hoặc thành phần khác có thể được tham chiếu.`}],tags:[`programming`,`local-variable`,`variable`,`scope`]},{id:`object-oriented-programming`,order:27,titleJa:`オブジェクト指向プログラミング`,titleVi:`Lập trình hướng đối tượng`,importance:`high`,summaryJa:`データと機能をオブジェクトとしてまとめて扱うオブジェクト指向プログラミングの基本的な考え方と、その利点について理解する。`,summaryVi:`Tìm hiểu tư tưởng cơ bản của lập trình hướng đối tượng, trong đó dữ liệu và chức năng được tổ chức thành các đối tượng, cùng những lợi ích của phương pháp này.`,content:[{type:`heading`,ja:`オブジェクト指向プログラミングとは`,vi:`Lập trình hướng đối tượng là gì?`},{type:`paragraph`,ja:`オブジェクト指向プログラミング（Object-Oriented Programming）とは、現実世界の物や概念を「オブジェクト」として捉え、データとそれを操作する機能を一つにまとめてプログラムを構成する考え方である。`,vi:`Lập trình hướng đối tượng (Object-Oriented Programming) là cách xây dựng chương trình bằng cách xem các sự vật hoặc khái niệm trong thế giới thực như những "đối tượng", đồng thời kết hợp dữ liệu và các chức năng xử lý dữ liệu đó thành một đơn vị.`},{type:`heading`,ja:`オブジェクトの例`,vi:`Ví dụ về đối tượng`},{type:`paragraph`,ja:`例えば、車をオブジェクトとして考えると、「色」や「モデル」などをデータとして持ち、「走る」「止まる」などを機能として持たせることができる。このように、対象の状態と振る舞いをまとめて表現する。`,vi:`Ví dụ, nếu coi một chiếc xe là một đối tượng, nó có thể có dữ liệu như "màu sắc", "mẫu xe" và các chức năng như "chạy", "dừng". Theo cách này, trạng thái và hành vi của một đối tượng được biểu diễn cùng nhau.`},{type:`heading`,ja:`オブジェクト指向の利点`,vi:`Lợi ích của hướng đối tượng`},{type:`paragraph`,ja:`オブジェクト指向では、機能をオブジェクト単位で整理できるため、再利用性や柔軟性が高まり、プログラムの保守や拡張が容易になる。また、継承やポリモーフィズムなどを利用することで、複雑なシステムを整理して管理しやすくなる。`,vi:`Trong lập trình hướng đối tượng, các chức năng có thể được tổ chức theo từng đối tượng, giúp tăng khả năng tái sử dụng và tính linh hoạt, đồng thời giúp chương trình dễ bảo trì và mở rộng hơn. Các cơ chế như kế thừa và đa hình cũng giúp quản lý những hệ thống phức tạp dễ dàng hơn.`},{type:`point`,ja:`オブジェクトは、データ（属性）とそのデータを操作する機能（振る舞い）をまとめたものである。`,vi:`Đối tượng là một đơn vị kết hợp dữ liệu (thuộc tính) và chức năng xử lý dữ liệu đó (hành vi).`}],terms:[{term:`オブジェクト指向プログラミング`,reading:`おぶじぇくとしこうぷろぐらみんぐ`,english:`Object-Oriented Programming`,vi:`lập trình hướng đối tượng`,definitionJa:`データと機能をオブジェクトとしてまとめてプログラムを構成する考え方。`,definitionVi:`Phương pháp xây dựng chương trình bằng cách tổ chức dữ liệu và chức năng thành các đối tượng.`},{term:`オブジェクト`,reading:`おぶじぇくと`,english:`Object`,vi:`đối tượng`,definitionJa:`データと、そのデータに対する操作をまとめたもの。`,definitionVi:`Một đơn vị kết hợp dữ liệu và các thao tác đối với dữ liệu đó.`}],tags:[`programming`,`object-oriented-programming`,`oop`,`object`]},{id:`constructor`,order:28,titleJa:`コンストラクタ`,titleVi:`Hàm khởi tạo`,importance:`high`,summaryJa:`オブジェクトを生成するときに呼び出され、必要な初期設定を行うコンストラクタの役割について理解する。`,summaryVi:`Tìm hiểu vai trò của constructor được gọi khi tạo đối tượng và dùng để thực hiện các thiết lập ban đầu cần thiết.`,content:[{type:`heading`,ja:`コンストラクタとは`,vi:`Constructor là gì?`},{type:`paragraph`,ja:`コンストラクタ（Constructor）とは、オブジェクト指向プログラミングにおいて、クラスからオブジェクトを生成する際に呼び出される特別なメソッドである。主に、オブジェクトが初期化されるタイミングで必要なプロパティや値を設定するために使用される。`,vi:`Constructor (hàm khởi tạo) là một phương thức đặc biệt được gọi khi tạo đối tượng từ một lớp trong lập trình hướng đối tượng. Nó chủ yếu được sử dụng để thiết lập các thuộc tính và giá trị cần thiết khi đối tượng được khởi tạo.`},{type:`heading`,ja:`初期化`,vi:`Khởi tạo`},{type:`paragraph`,ja:`例えば、車を表すクラスでは、オブジェクトを生成するときにコンストラクタを使って車の色やモデルなどの初期値を設定できる。これにより、生成されたオブジェクトを最初から適切な状態にすることができる。`,vi:`Ví dụ, với một lớp biểu diễn xe ô tô, khi tạo đối tượng có thể sử dụng constructor để thiết lập các giá trị ban đầu như màu sắc hoặc mẫu xe. Nhờ đó, đối tượng vừa được tạo có thể ở trạng thái thích hợp ngay từ đầu.`},{type:`heading`,ja:`コンストラクタの特徴`,vi:`Đặc điểm của constructor`},{type:`paragraph`,ja:`コンストラクタの具体的な記述方法はプログラミング言語によって異なるが、オブジェクト生成時の初期化を一か所にまとめられるため、プログラムを整理しやすく、保守性を高めることができる。`,vi:`Cách viết constructor cụ thể khác nhau tùy ngôn ngữ lập trình, nhưng vì có thể tập trung việc khởi tạo đối tượng tại một nơi nên chương trình dễ tổ chức và bảo trì hơn.`},{type:`point`,ja:`コンストラクタは、オブジェクト生成時に初期化処理を行うための特別なメソッドである。`,vi:`Constructor là phương thức đặc biệt dùng để thực hiện xử lý khởi tạo khi một đối tượng được tạo.`}],terms:[{term:`コンストラクタ`,reading:`こんすとらくた`,english:`Constructor`,vi:`hàm khởi tạo`,definitionJa:`オブジェクトを生成するときに呼び出され、初期化を行うための特別なメソッド。`,definitionVi:`Phương thức đặc biệt được gọi khi tạo đối tượng để thực hiện việc khởi tạo.`}],tags:[`programming`,`object-oriented-programming`,`constructor`,`initialization`]},{id:`member-variable`,order:29,titleJa:`メンバ変数`,titleVi:`Biến thành viên`,importance:`high`,summaryJa:`クラスに属し、オブジェクトの状態や属性を保持するメンバ変数の役割について理解する。`,summaryVi:`Tìm hiểu vai trò của biến thành viên thuộc về lớp và dùng để lưu giữ trạng thái hoặc thuộc tính của đối tượng.`,content:[{type:`heading`,ja:`メンバ変数とは`,vi:`Biến thành viên là gì?`},{type:`paragraph`,ja:`メンバ変数（Member Variable）とは、クラスに属する変数であり、オブジェクトの状態や属性を保持するために使用される。`,vi:`Biến thành viên (Member Variable) là biến thuộc về một lớp và được sử dụng để lưu giữ trạng thái hoặc thuộc tính của đối tượng.`},{type:`heading`,ja:`メンバ変数の例`,vi:`Ví dụ về biến thành viên`},{type:`paragraph`,ja:`例えば、「車」というクラスでは、「色」や「速度」などをメンバ変数として定義できる。それぞれの車のオブジェクトは、これらのメンバ変数に異なる値を保持することで、個別の状態を表現できる。`,vi:`Ví dụ, trong lớp "Xe", có thể định nghĩa "màu sắc" và "tốc độ" làm các biến thành viên. Mỗi đối tượng xe có thể lưu các giá trị khác nhau trong những biến này để biểu diễn trạng thái riêng của mình.`},{type:`heading`,ja:`オブジェクト指向における役割`,vi:`Vai trò trong lập trình hướng đối tượng`},{type:`paragraph`,ja:`メンバ変数はオブジェクトのデータを表す重要な要素であり、メソッドから参照したり変更したりできる。また、アクセス方法を適切に制御することで、データの隠蔽やカプセル化にもつながる。`,vi:`Biến thành viên là thành phần quan trọng biểu diễn dữ liệu của đối tượng và có thể được các phương thức tham chiếu hoặc thay đổi. Việc kiểm soát cách truy cập thích hợp cũng góp phần vào che giấu dữ liệu và đóng gói.`},{type:`point`,ja:`メンバ変数はクラスに属する変数であり、各オブジェクトの状態や属性を保持する。`,vi:`Biến thành viên là biến thuộc về lớp, dùng để lưu trạng thái hoặc thuộc tính của từng đối tượng.`}],terms:[{term:`メンバ変数`,reading:`めんばへんすう`,english:`Member Variable`,vi:`biến thành viên`,definitionJa:`クラスに属し、オブジェクトの状態や属性を保持する変数。`,definitionVi:`Biến thuộc về lớp và lưu giữ trạng thái hoặc thuộc tính của đối tượng.`}],tags:[`programming`,`object-oriented-programming`,`member-variable`,`class`,`object`]},{id:`override`,order:30,titleJa:`オーバーライド`,titleVi:`Ghi đè`,importance:`high`,summaryJa:`親クラスで定義されたメソッドを子クラスで再定義するオーバーライドの仕組みと、その目的について理解する。`,summaryVi:`Tìm hiểu cơ chế override, trong đó phương thức được định nghĩa ở lớp cha được định nghĩa lại trong lớp con, cùng mục đích của cơ chế này.`,content:[{type:`heading`,ja:`オーバーライドとは`,vi:`Override là gì?`},{type:`paragraph`,ja:`オーバーライド（Override）とは、スーパークラス（親クラス）で定義されたメソッドを、サブクラス（子クラス）で再定義することである。これにより、親クラスの基本的な構造を利用しながら、子クラス固有の処理を実装できる。`,vi:`Override (ghi đè) là việc định nghĩa lại trong lớp con (subclass) một phương thức đã được định nghĩa ở lớp cha (superclass). Nhờ đó có thể sử dụng cấu trúc cơ bản của lớp cha đồng thời triển khai xử lý riêng cho lớp con.`},{type:`heading`,ja:`オーバーライドの例`,vi:`Ví dụ về override`},{type:`paragraph`,ja:`例えば、動物を表す親クラスに「鳴く」というメソッドがある場合、犬のサブクラスではそのメソッドをオーバーライドして「ワンワン」と鳴く処理を定義できる。このように、同じメソッドでもオブジェクトの種類に応じて異なる動作を実現できる。`,vi:`Ví dụ, nếu lớp cha biểu diễn động vật có phương thức "kêu", lớp con biểu diễn chó có thể ghi đè phương thức đó để định nghĩa hành vi kêu "gâu gâu". Nhờ vậy, cùng một phương thức có thể thực hiện hành vi khác nhau tùy loại đối tượng.`},{type:`heading`,ja:`オーバーライドの利点`,vi:`Lợi ích của override`},{type:`paragraph`,ja:`オーバーライドを利用することで、既存のクラスの仕組みを再利用しながら、必要な部分だけを変更できる。そのため、プログラムの柔軟性や再利用性を高めることができる。`,vi:`Sử dụng override cho phép tái sử dụng cơ chế của lớp hiện có và chỉ thay đổi những phần cần thiết. Vì vậy, nó giúp tăng tính linh hoạt và khả năng tái sử dụng của chương trình.`},{type:`point`,ja:`オーバーライドは、親クラスのメソッドを子クラスで再定義することである。オーバーロードとは異なるため区別する。`,vi:`Override là định nghĩa lại phương thức của lớp cha trong lớp con. Cần phân biệt với overload (nạp chồng).`}],terms:[{term:`オーバーライド`,reading:`おーばーらいど`,english:`Override`,vi:`ghi đè`,definitionJa:`親クラスで定義されたメソッドを子クラスで再定義すること。`,definitionVi:`Việc định nghĩa lại trong lớp con một phương thức đã được định nghĩa ở lớp cha.`},{term:`スーパークラス`,reading:`すーぱーくらす`,english:`Superclass`,vi:`lớp cha`,definitionJa:`継承関係において、他のクラスに機能や属性を継承させる側のクラス。`,definitionVi:`Lớp cung cấp thuộc tính và chức năng cho lớp khác thông qua quan hệ kế thừa.`},{term:`サブクラス`,reading:`さぶくらす`,english:`Subclass`,vi:`lớp con`,definitionJa:`継承関係において、親クラスの機能や属性を引き継ぐクラス。`,definitionVi:`Lớp kế thừa thuộc tính và chức năng từ lớp cha.`}],tags:[`programming`,`object-oriented-programming`,`override`,`inheritance`,`polymorphism`]},{id:`overload`,order:31,titleJa:`オーバーロード`,titleVi:`Nạp chồng`,importance:`high`,summaryJa:`同じ名前の関数やメソッドを、引数の型や数を変えて複数定義するオーバーロードの仕組みについて理解する。`,summaryVi:`Tìm hiểu cơ chế overload, cho phép định nghĩa nhiều hàm hoặc phương thức cùng tên nhưng khác kiểu hoặc số lượng tham số.`,content:[{type:`heading`,ja:`オーバーロードとは`,vi:`Overload là gì?`},{type:`paragraph`,ja:`オーバーロード（Overload）とは、プログラミングにおいて、同じ名前の関数やメソッドを異なる引数の型や数で複数定義することである。呼び出し時に与えられた引数に応じて、適切な処理が選択される。`,vi:`Overload (nạp chồng) là việc định nghĩa nhiều hàm hoặc phương thức có cùng tên nhưng khác kiểu hoặc số lượng tham số. Khi gọi, xử lý phù hợp sẽ được lựa chọn dựa trên các tham số được truyền vào.`},{type:`heading`,ja:`オーバーロードの例`,vi:`Ví dụ về overload`},{type:`paragraph`,ja:`例えば、「足す」という同じ名前のメソッドについて、整数を二つ受け取るものと、小数を二つ受け取るものをそれぞれ定義することができる。利用する側は同じ名前で呼び出し、引数の型などに応じて適切な処理を利用できる。`,vi:`Ví dụ, với cùng một phương thức tên là "cộng", có thể định nghĩa một phiên bản nhận hai số nguyên và một phiên bản nhận hai số thực. Người sử dụng vẫn gọi cùng một tên, còn xử lý phù hợp được chọn tùy theo kiểu tham số.`},{type:`heading`,ja:`オーバーライドとの違い`,vi:`Khác biệt với override`},{type:`paragraph`,ja:`オーバーロードは、同じ名前で引数の異なる関数やメソッドを複数定義する仕組みである。一方、オーバーライドは、親クラスで定義されたメソッドを子クラスで再定義することである。`,vi:`Overload là cơ chế định nghĩa nhiều hàm hoặc phương thức cùng tên nhưng khác tham số. Trong khi đó, override là việc lớp con định nghĩa lại phương thức đã được định nghĩa ở lớp cha.`},{type:`point`,ja:`オーバーロードは「同じ名前・異なる引数」、オーバーライドは「親クラスのメソッドを子クラスで再定義」と覚える。`,vi:`Hãy nhớ: overload = "cùng tên, khác tham số"; override = "lớp con định nghĩa lại phương thức của lớp cha".`}],terms:[{term:`オーバーロード`,reading:`おーばーろーど`,english:`Overload`,vi:`nạp chồng`,definitionJa:`同じ名前の関数やメソッドを、異なる引数の型や数で複数定義すること。`,definitionVi:`Định nghĩa nhiều hàm hoặc phương thức cùng tên nhưng khác kiểu hoặc số lượng tham số.`}],tags:[`programming`,`object-oriented-programming`,`overload`,`method`]},{id:`web-programming`,order:32,titleJa:`Webプログラミング`,titleVi:`Lập trình Web`,importance:`high`,summaryJa:`WebサイトやWebアプリケーションを構築するWebプログラミングと、フロントエンド・バックエンドの基本的な役割について理解する。`,summaryVi:`Tìm hiểu lập trình Web để xây dựng website và ứng dụng Web, cùng vai trò cơ bản của frontend và backend.`,content:[{type:`heading`,ja:`Webプログラミングとは`,vi:`Lập trình Web là gì?`},{type:`paragraph`,ja:`Webプログラミング（Web Programming）とは、インターネット上で動作するWebサイトやWebアプリケーションを構築するための技術や手法である。一般に、ユーザーが操作するフロントエンドと、データ処理や管理を行うバックエンドに分けて考えることができる。`,vi:`Lập trình Web (Web Programming) là các kỹ thuật và phương pháp dùng để xây dựng website và ứng dụng Web hoạt động trên Internet. Thông thường có thể chia thành frontend, nơi người dùng thao tác, và backend, nơi thực hiện xử lý và quản lý dữ liệu.`},{type:`heading`,ja:`フロントエンド`,vi:`Frontend`},{type:`paragraph`,ja:`フロントエンドは、Webブラウザ上でユーザーに表示され、ユーザーが直接操作する部分である。HTMLでページの構造を作り、CSSで表示を整え、JavaScriptなどを使って動的な処理を実現する。`,vi:`Frontend là phần được hiển thị trên trình duyệt Web và được người dùng trực tiếp thao tác. HTML tạo cấu trúc trang, CSS điều chỉnh cách hiển thị, còn JavaScript và các công nghệ tương tự được dùng để thực hiện các xử lý động.`},{type:`heading`,ja:`バックエンド`,vi:`Backend`},{type:`paragraph`,ja:`バックエンドはサーバ側で動作し、ユーザーからの要求に応じて処理を行ったり、データベースの情報を取得・更新したりする。Webアプリケーションでは、フロントエンドとバックエンドが連携してサービスを提供する。`,vi:`Backend hoạt động ở phía máy chủ, thực hiện xử lý theo yêu cầu của người dùng và truy xuất hoặc cập nhật thông tin trong cơ sở dữ liệu. Trong ứng dụng Web, frontend và backend phối hợp với nhau để cung cấp dịch vụ.`},{type:`point`,ja:`フロントエンドは主にユーザー側の表示・操作、バックエンドは主にサーバ側の処理・データ管理を担当する。`,vi:`Frontend chủ yếu phụ trách hiển thị và thao tác phía người dùng; backend chủ yếu phụ trách xử lý phía máy chủ và quản lý dữ liệu.`}],terms:[{term:`Webプログラミング`,reading:`うぇぶぷろぐらみんぐ`,english:`Web Programming`,vi:`lập trình Web`,definitionJa:`WebサイトやWebアプリケーションを構築するためのプログラミング技術。`,definitionVi:`Kỹ thuật lập trình dùng để xây dựng website và ứng dụng Web.`},{term:`フロントエンド`,reading:`ふろんとえんど`,english:`Front End`,vi:`frontend`,definitionJa:`ユーザーがWebブラウザなどを通して直接操作する側。`,definitionVi:`Phần mà người dùng trực tiếp nhìn thấy và thao tác thông qua trình duyệt Web.`},{term:`バックエンド`,reading:`ばっくえんど`,english:`Back End`,vi:`backend`,definitionJa:`サーバ側でデータ処理やデータ管理などを行う部分。`,definitionVi:`Phần phía máy chủ thực hiện xử lý và quản lý dữ liệu.`}],tags:[`programming`,`web-programming`,`frontend`,`backend`]},{id:`server-side-programming`,order:33,titleJa:`サーバサイドプログラミング`,titleVi:`Lập trình phía máy chủ`,importance:`high`,summaryJa:`Webアプリケーションにおいてサーバ側で実行され、要求の処理やデータベースとの連携を行うサーバサイドプログラミングについて理解する。`,summaryVi:`Tìm hiểu lập trình phía máy chủ, nơi chương trình chạy trên server để xử lý yêu cầu và làm việc với cơ sở dữ liệu trong ứng dụng Web.`,content:[{type:`heading`,ja:`サーバサイドプログラミングとは`,vi:`Lập trình phía máy chủ là gì?`},{type:`paragraph`,ja:`サーバサイドプログラミング（Server-Side Programming）とは、Webアプリケーションにおいてサーバ上で実行されるプログラムを作成することである。ユーザーからのリクエストを受け取り、必要な処理を行って結果をクライアントへ返す役割を持つ。`,vi:`Lập trình phía máy chủ (Server-Side Programming) là việc tạo các chương trình chạy trên server trong ứng dụng Web. Nó nhận yêu cầu từ người dùng, thực hiện xử lý cần thiết và trả kết quả về phía client.`},{type:`heading`,ja:`データベースとの連携`,vi:`Liên kết với cơ sở dữ liệu`},{type:`paragraph`,ja:`サーバサイドでは、データベースから情報を取得したり、登録・更新・削除したりする処理が行われる。これにより、ユーザーごとに異なる情報を表示するなど、動的なWebページを生成できる。`,vi:`Ở phía server, chương trình có thể lấy thông tin từ cơ sở dữ liệu hoặc thực hiện đăng ký, cập nhật và xóa dữ liệu. Nhờ đó có thể tạo các trang Web động, chẳng hạn hiển thị thông tin khác nhau cho từng người dùng.`},{type:`heading`,ja:`利用される言語`,vi:`Các ngôn ngữ được sử dụng`},{type:`paragraph`,ja:`サーバサイドプログラミングには、PHP、Python、Rubyなど様々なプログラミング言語が利用される。Webサービスでは、データ処理や認証などの重要な処理をサーバ側で行う。`,vi:`Nhiều ngôn ngữ như PHP, Python và Ruby được sử dụng cho lập trình phía máy chủ. Trong dịch vụ Web, các xử lý quan trọng như xử lý dữ liệu và xác thực thường được thực hiện phía server.`},{type:`point`,ja:`サーバサイドは、ユーザーのリクエストを処理し、必要に応じてデータベースと連携して結果を返す。`,vi:`Server-side xử lý yêu cầu của người dùng, làm việc với cơ sở dữ liệu khi cần và trả về kết quả.`}],terms:[{term:`サーバサイドプログラミング`,reading:`さーばさいどぷろぐらみんぐ`,english:`Server-Side Programming`,vi:`lập trình phía máy chủ`,definitionJa:`Webアプリケーションにおいて、サーバ上で実行される処理を作成するプログラミング。`,definitionVi:`Lập trình các xử lý được thực thi trên máy chủ trong ứng dụng Web.`}],tags:[`programming`,`web-programming`,`server-side`,`backend`,`database`]},{id:`rich-client`,order:34,titleJa:`リッチクライアント`,titleVi:`Rich Client`,importance:`medium`,summaryJa:`クライアント側で多くの処理を行い、豊富なユーザーインタフェースや高い操作性を提供するリッチクライアントについて理解する。`,summaryVi:`Tìm hiểu Rich Client, ứng dụng thực hiện nhiều xử lý ở phía client và cung cấp giao diện phong phú cùng khả năng tương tác cao.`,content:[{type:`heading`,ja:`リッチクライアントとは`,vi:`Rich Client là gì?`},{type:`paragraph`,ja:`リッチクライアント（Rich Client）とは、ユーザーの端末上で動作し、多くの処理をクライアント側で行うことで、豊富なユーザーインタフェースや高い操作性を提供するアプリケーションである。`,vi:`Rich Client là ứng dụng chạy trên thiết bị của người dùng và thực hiện nhiều xử lý ở phía client, nhờ đó cung cấp giao diện người dùng phong phú và khả năng thao tác cao.`},{type:`heading`,ja:`特徴`,vi:`Đặc điểm`},{type:`paragraph`,ja:`リッチクライアントは、サーバから必要なデータを受け取り、表示や一部の処理をローカル環境で実行できる。そのため、画面を動的に変化させたり、ユーザーの操作に素早く反応したりすることができる。`,vi:`Rich Client nhận dữ liệu cần thiết từ server và có thể thực hiện việc hiển thị cũng như một phần xử lý ngay trên môi trường cục bộ. Vì vậy, giao diện có thể thay đổi động và phản hồi nhanh với thao tác của người dùng.`},{type:`heading`,ja:`利用例`,vi:`Ví dụ sử dụng`},{type:`paragraph`,ja:`デスクトップアプリケーションや、一部の高機能なWebアプリケーションなどがリッチクライアントの例として挙げられる。オンラインとオフラインの両方で利用できるものもあり、ネットワークの状況に応じて柔軟に動作できる。`,vi:`Ứng dụng desktop và một số ứng dụng Web có chức năng cao là những ví dụ về Rich Client. Một số có thể hoạt động cả online lẫn offline, cho phép vận hành linh hoạt tùy theo tình trạng kết nối mạng.`},{type:`point`,ja:`リッチクライアントは、クライアント側でも多くの処理を行うことで、高い操作性や豊富なユーザーインタフェースを実現する。`,vi:`Rich Client thực hiện nhiều xử lý ở phía client để cung cấp khả năng thao tác cao và giao diện người dùng phong phú.`}],terms:[{term:`リッチクライアント`,reading:`りっちくらいあんと`,english:`Rich Client`,vi:`Rich Client`,definitionJa:`クライアント側で多くの処理を行い、豊富なユーザーインタフェースや高い操作性を提供するアプリケーション。`,definitionVi:`Ứng dụng thực hiện nhiều xử lý ở phía client và cung cấp giao diện phong phú cùng khả năng thao tác cao.`}],tags:[`programming`,`web-programming`,`rich-client`,`client`]},{id:`ajax`,order:35,titleJa:`Ajax`,titleVi:`Ajax`,importance:`high`,summaryJa:`WebブラウザとWebサーバの間で非同期通信を行い、Webページ全体を再読み込みせずに必要な部分だけを更新するAjaxについて理解する。`,summaryVi:`Tìm hiểu Ajax, kỹ thuật giao tiếp bất đồng bộ giữa trình duyệt Web và Web server, cho phép chỉ cập nhật phần cần thiết mà không phải tải lại toàn bộ trang.`,content:[{type:`heading`,ja:`Ajaxとは`,vi:`Ajax là gì?`},{type:`paragraph`,ja:`Ajax（Asynchronous JavaScript and XML）とは、WebブラウザとWebサーバの間で非同期通信を行い、Webページ全体を再読み込みすることなく、必要な部分だけを更新するための技術である。`,vi:`Ajax (Asynchronous JavaScript and XML) là kỹ thuật thực hiện giao tiếp bất đồng bộ giữa trình duyệt Web và Web server, cho phép cập nhật riêng phần cần thiết mà không phải tải lại toàn bộ trang Web.`},{type:`heading`,ja:`非同期通信`,vi:`Giao tiếp bất đồng bộ`},{type:`paragraph`,ja:`非同期通信では、サーバからの応答を待っている間も、ユーザーはWebページ上で別の操作を続けることができる。サーバからデータを受信すると、必要な部分だけを更新できるため、操作性を向上させることができる。`,vi:`Trong giao tiếp bất đồng bộ, người dùng vẫn có thể tiếp tục các thao tác khác trên trang Web trong khi chờ phản hồi từ server. Khi nhận được dữ liệu, chỉ phần cần thiết được cập nhật, nhờ đó cải thiện khả năng thao tác.`},{type:`heading`,ja:`Ajaxの利用例`,vi:`Ví dụ sử dụng Ajax`},{type:`paragraph`,ja:`チャットアプリケーションや地図サービスなどで利用される。例えば、地図を移動したときにページ全体を読み込み直さず、必要な地図データだけを取得して画面を更新する処理などが代表的な例である。`,vi:`Ajax được sử dụng trong các ứng dụng chat, dịch vụ bản đồ và nhiều ứng dụng Web khác. Ví dụ, khi di chuyển bản đồ, hệ thống chỉ lấy dữ liệu bản đồ cần thiết và cập nhật màn hình thay vì tải lại toàn bộ trang.`},{type:`point`,ja:`Ajaxの重要ポイントは「非同期通信」と「ページ全体を再読み込みせずに必要な部分だけを更新する」ことである。`,vi:`Điểm quan trọng của Ajax là "giao tiếp bất đồng bộ" và "chỉ cập nhật phần cần thiết mà không tải lại toàn bộ trang".`}],terms:[{term:`Ajax`,reading:`あじゃっくす、えいじゃっくす`,english:`Asynchronous JavaScript and XML`,vi:`Ajax`,definitionJa:`WebブラウザとWebサーバの間で非同期通信を行い、ページの一部を動的に更新する技術。`,definitionVi:`Kỹ thuật giao tiếp bất đồng bộ giữa trình duyệt và Web server để cập nhật động một phần của trang.`}],tags:[`programming`,`web-programming`,`ajax`,`asynchronous`]},{id:`apache`,order:36,titleJa:`Apache`,titleVi:`Apache`,importance:`medium`,summaryJa:`Webサイトのコンテンツをクライアントに提供する代表的なオープンソースのWebサーバソフトウェアであるApacheについて理解する。`,summaryVi:`Tìm hiểu Apache, một phần mềm Web server mã nguồn mở tiêu biểu dùng để cung cấp nội dung Web cho client.`,content:[{type:`heading`,ja:`Apacheとは`,vi:`Apache là gì?`},{type:`paragraph`,ja:`Apacheは、WebサイトやWebアプリケーションのコンテンツをクライアントに提供するために使用される代表的なWebサーバソフトウェアである。オープンソースとして提供されており、様々な環境で利用されている。`,vi:`Apache là một phần mềm Web server tiêu biểu được sử dụng để cung cấp nội dung của website và ứng dụng Web cho client. Đây là phần mềm mã nguồn mở và được sử dụng trong nhiều môi trường khác nhau.`},{type:`heading`,ja:`Webサーバの役割`,vi:`Vai trò của Web server`},{type:`paragraph`,ja:`WebブラウザなどのクライアントからHTTPなどによるリクエストを受け取り、要求されたWebページなどのコンテンツを返す。これにより、ユーザーはネットワークを通してWebサイトを閲覧できる。`,vi:`Web server nhận request từ client như trình duyệt Web thông qua HTTP và trả về nội dung được yêu cầu như trang Web. Nhờ đó, người dùng có thể truy cập website thông qua mạng.`},{type:`heading`,ja:`他の技術との連携`,vi:`Kết hợp với các công nghệ khác`},{type:`paragraph`,ja:`Apacheは、PHPなどのサーバサイド技術やデータベースと組み合わせて利用されることがあり、動的なWebアプリケーションを構築するためのWebサーバとして使用される。`,vi:`Apache có thể được sử dụng kết hợp với các công nghệ server-side như PHP và cơ sở dữ liệu để làm Web server cho các ứng dụng Web động.`},{type:`point`,ja:`Apacheはプログラミング言語ではなく、クライアントからの要求を受けてWebコンテンツを提供するWebサーバソフトウェアである。`,vi:`Apache không phải là ngôn ngữ lập trình mà là phần mềm Web server nhận yêu cầu từ client và cung cấp nội dung Web.`}],terms:[{term:`Apache`,reading:`あぱっち`,english:`Apache HTTP Server`,vi:`Apache`,definitionJa:`Webコンテンツをクライアントに提供する代表的なオープンソースのWebサーバソフトウェア。`,definitionVi:`Phần mềm Web server mã nguồn mở tiêu biểu dùng để cung cấp nội dung Web cho client.`}],tags:[`programming`,`web-programming`,`apache`,`web-server`]},{id:`front-end-framework`,order:37,titleJa:`フロントエンドフレームワーク`,titleVi:`Framework Frontend`,importance:`medium`,summaryJa:`WebサイトやWebアプリケーションのユーザーインタフェースを効率よく構築するためのフロントエンドフレームワークについて理解する。`,summaryVi:`Tìm hiểu framework frontend dùng để xây dựng giao diện người dùng của website và ứng dụng Web một cách hiệu quả.`,content:[{type:`heading`,ja:`フロントエンドフレームワークとは`,vi:`Framework Frontend là gì?`},{type:`paragraph`,ja:`フロントエンドフレームワークは、WebサイトやWebアプリケーションのユーザーインタフェースを効率よく構築するためのソフトウェアのひな型である。共通する機能や仕組みを利用することで、開発者は一からすべてを実装する必要がなくなる。`,vi:`Framework frontend là bộ khung phần mềm dùng để xây dựng giao diện người dùng của website và ứng dụng Web một cách hiệu quả. Nhờ sử dụng các chức năng và cơ chế có sẵn, lập trình viên không cần xây dựng mọi thứ từ đầu.`},{type:`heading`,ja:`主な特徴`,vi:`Đặc điểm chính`},{type:`paragraph`,ja:`フロントエンドフレームワークを利用すると、画面を部品単位で構築したり、ユーザーの操作に応じて表示内容を動的に変更したりしやすくなる。また、共通の仕組みを利用することで、開発の効率化や保守性の向上にもつながる。`,vi:`Khi sử dụng framework frontend, việc xây dựng giao diện theo từng thành phần và thay đổi nội dung hiển thị động theo thao tác của người dùng trở nên dễ dàng hơn. Việc dùng chung các cơ chế có sẵn cũng giúp tăng hiệu quả phát triển và khả năng bảo trì.`},{type:`heading`,ja:`代表例`,vi:`Ví dụ tiêu biểu`},{type:`paragraph`,ja:`代表的なフロントエンド技術としてReactやVue.jsなどがある。これらを利用することで、インタラクティブなユーザーインタフェースを効率よく構築できる。`,vi:`Các công nghệ frontend tiêu biểu gồm React và Vue.js. Chúng giúp xây dựng giao diện người dùng có tính tương tác một cách hiệu quả.`},{type:`point`,ja:`フレームワークは、開発に必要な共通の仕組みを提供する「ひな型」であり、開発効率や保守性の向上に役立つ。`,vi:`Framework là một "bộ khung" cung cấp các cơ chế chung cần thiết cho phát triển, giúp tăng hiệu quả phát triển và khả năng bảo trì.`}],terms:[{term:`フロントエンドフレームワーク`,reading:`ふろんとえんどふれーむわーく`,english:`Front-End Framework`,vi:`framework frontend`,definitionJa:`Webアプリケーションのユーザーインタフェースを効率よく構築するためのソフトウェアのひな型。`,definitionVi:`Bộ khung phần mềm dùng để xây dựng giao diện người dùng của ứng dụng Web một cách hiệu quả.`}],tags:[`programming`,`web-programming`,`frontend`,`framework`]}]},_=o,v=s,y={id:v.id,order:v.order,titleJa:v.titleJa,titleVi:v.titleVi,chapters:[c,l,u,d,f]},b=p,x=[y,{id:b.id,order:b.order,titleJa:b.titleJa,titleVi:b.titleVi,chapters:[m,h,g]}],S=new Map(x.map(e=>[e.id,e]));function C(){return _}function w(){return[..._.categories].sort((e,t)=>e.order-t.order).map(e=>{let t=S.get(e.id);return{...e,chapterCount:t?.chapters.length??0,lessonCount:t?.chapters.reduce((e,t)=>e+t.lessons.length,0)??0}})}function T(e){return S.get(e)}function E(e,t){let n=T(e);if(!n)return;let r=n.chapters.find(e=>e.id===t);if(r)return{category:n,chapter:r}}function D(e){for(let t of x)for(let n of t.chapters){let r=n.lessons.find(t=>t.id===e);if(r)return{category:t,chapter:n,lesson:r}}}function O(e){let t=[],n=[...x].sort((e,t)=>e.order-t.order);for(let e of n){let n=[...e.chapters].sort((e,t)=>e.order-t.order);for(let r of n){let n=[...r.lessons].sort((e,t)=>e.order-t.order);for(let i of n)t.push({category:e,chapter:r,lesson:i})}}let r=t.findIndex(t=>t.lesson.id===e);return r===-1?{}:{previous:r>0?t[r-1]:void 0,next:r<t.length-1?t[r+1]:void 0}}export{O as a,n as c,D as i,C as n,w as o,E as r,a as s,T as t};